(** * Section index.

    This public library re-exports [solver_qcp_tactics], [solver_qcp_model],
    and [solver_qcp_model_tactics], in that order. The model file contains the
    mathematical dependency closure of the model tactics; manual-only tactics
    live in [solver_qcp_proof_common]. The index below describes the combined
    library vocabulary.

    Every top-level division of the library source opens with a
    [(* ===...=== SECTION <name> ===...=== *)] rule line followed by a header
    paragraph.  This index follows the conceptual layers and names their host
    files; it does not prescribe source or import order.  Inside a section, each group of lemmas
    written for one C function opens with a
    [(** ===== group: <function> ===== *)] banner.

    Layers -- the mathematics, bottom up.  (There is no S3 section: the
    [cdcl_view] algebra S3 names is re-exported from [cdcl_shared_lib] and
    [CDCLLib], not restated here.)
      - [msat_s1_semantics]          re-export of the shared SAT/CDCL algebra
        in [solver_qcp_model.v]
      - [msat_s2_bridge]             MiniSat's packed literal encoding
        in [solver_qcp_model.v]
      - [msat_s4_trail]              the concrete trail and its view projection
        in [solver_qcp_model.v]
      - [msat_s5_watch]              the watched-literal layer
        in [solver_qcp_model.v]
      - [msat_s6_learn]              resolution carrier and minimization
        in [solver_qcp_lib.v]
      - [msat_s7_heur]               variable-order heap and random seed
        in [solver_qcp_lib.v]
      - [msat_s8_rep]                the separation-logic predicates
        in [solver_qcp_model.v]
      - [msat_s9_contract]           contract vocabulary and the endgames
        in [solver_qcp_model.v]
      - [msat_problem_clause_install] clause installation over the learnt flag
        in [solver_qcp_model.v]
      - [msat_s10_witness]           concrete pure-state consistency witnesses
        in [solver_qcp_lib.v]

    Per-goal-group helpers -- lemmas written because one proof obligation of
    one C function needed them, ordered by first need rather than by topic.
      - [msat_api_goal_helpers]      clause, vector, order and record API
        in [solver_qcp_lib.v]
      - [msat_conflict_goal_helpers] [solver_lit_removable], [solver_analyze]
        in [solver_qcp_lib.v]
      - [msat_search_goal_helpers]   the search-loop functions
        in [solver_qcp_lib.v]
      - [msat_propagate_db_update]   the propagation database-update path
        in [solver_qcp_model.v]
      - [msat_propagate_scan_steps]  shared scan steps and the frame folds
        in [solver_qcp_lib.v]
      - [msat_variable_count_growth] raising the variable count
        in [solver_qcp_lib.v]
      - [msat_clause_new_generic]    clause install over the learnt selector
        in [solver_qcp_model.v]
      - [msat_addclause_model]       the [solver_addclause] model layer
        in [solver_qcp_lib.v]
      - [msat_addclause_wl_lane]     the same, with [wl] kept visible
        in [solver_qcp_lib.v]
      - [msat_hoisted_helpers]       facts hoisted out of the proof files
        in [solver_qcp_lib.v] *)


Module MiniSatTarget.

Definition two31 : Z := 2147483648.
Definition two32 : Z := 4294967296.
Definition two64 : Z := 18446744073709551616.
Definition lo64 (x : Z) : Z := x mod two64.
Definition lo32 (x : Z) : Z := x mod two32.
Definition signed_low32 (x : Z) : Z :=
  let y := lo32 x in
  if y <? two31 then y else y - two32.
Definition uint64_sum_to_int (left right : Z) : Z :=
  signed_low32 (lo64 (left + right)).

End MiniSatTarget.

(** Type-only carrier for opaque or intentionally abstracted double results.
    Unlike IEEE equality, this remains true for NaNs as well as ordinary values. *)
Definition msat_fp64_value (_ : fp64) : Prop := True.

(** Structural identity for binary32 values.  IEEE [fp32_eq] is deliberately
    not used here: it is false when both operands are the same NaN payload. *)
Definition msat_fp32_same (x y : fp32) : Prop := x = y.

Definition double_Znth (i : Z) (values : list fp64) : fp64 :=
  Znth i values msat_fp64_zero.

(** The part of a concrete double array left after focusing two distinct
    live indices.  The two omitted cells remain explicit in C annotations so
    symbolic execution can read them; this predicate owns every other cell. *)
Definition double_array_missing2
    (base i j n : Z) (values : list fp64) : Assertion :=
  “ Zlength values = n ” &&
  (if i <? j then
     DoubleArray.seg base 0 i (sublist 0 i values) **
     DoubleArray.seg base (i + 1) j (sublist (i + 1) j values) **
     DoubleArray.seg base (j + 1) n (sublist (j + 1) n values)
   else
     DoubleArray.seg base 0 j (sublist 0 j values) **
     DoubleArray.seg base (j + 1) i (sublist (j + 1) i values) **
     DoubleArray.seg base (i + 1) n (sublist (i + 1) n values)).

Definition lit_encode (l : literal) : Z :=
  match l with
  | Pos x => 2 * x
  | Neg x => 2 * x + 1
  end.

Definition lit_sign_c (l : Z) : Z := if Z.odd l then 1 else 0.

(** ----- parity toolbox for [lit_neg_c] ----- *)

Lemma land_1_mod2 : forall l, Z.land l 1 = l mod 2.
Proof.
  intros l.
  assert (H : Z.land l (Z.ones 1) = l mod 2 ^ 1) by (apply Z.land_ones; lia).
  replace (Z.ones 1) with 1 in H by reflexivity.
  replace (2 ^ 1) with 2 in H by reflexivity.
  exact H.
Qed.

Lemma one_div_two : 1 / 2 = 0.
Proof. reflexivity. Qed.

Lemma lit_neg_c_even : forall l, Z.even l = true -> lit_neg_c l = l + 1.
Proof.
  intros l Hev. unfold lit_neg_c. symmetry.
  apply Z.add_nocarry_lxor.
  rewrite land_1_mod2.
  apply Z.even_spec in Hev. destruct Hev as [k ->].
  rewrite Z.mul_comm. apply Z_mod_mult.
Qed.

Lemma lit_neg_c_odd : forall l, Z.odd l = true -> lit_neg_c l = l - 1.
Proof.
  intros l Hod.
  assert (Hev : Z.even (l - 1) = true).
  { apply Z.odd_spec in Hod. destruct Hod as [k ->].
    apply Z.even_spec. exists k. lia. }
  apply lit_neg_c_even in Hev.
  unfold lit_neg_c in *.
  assert (Hrw : Z.lxor (Z.lxor (l - 1) 1) 1 = l - 1).
  { rewrite Z.lxor_assoc, Z.lxor_nilpotent, Z.lxor_0_r. reflexivity. }
  rewrite Hev in Hrw.
  replace (l - 1 + 1) with l in Hrw by lia.
  exact Hrw.
Qed.

Lemma lit_neg_c_involutive : forall l, lit_neg_c (lit_neg_c l) = l.
Proof.
  intros l. unfold lit_neg_c.
  rewrite Z.lxor_assoc, Z.lxor_nilpotent, Z.lxor_0_r. reflexivity.
Qed.

Lemma lit_neg_c_odd_parity : forall l,
  Z.odd (lit_neg_c l) = negb (Z.odd l).
Proof.
  intros l. destruct (Z.odd l) eqn:Hod.
  - rewrite lit_neg_c_odd by assumption. simpl.
    apply Z.odd_spec in Hod. destruct Hod as [k ->].
    replace (2 * k + 1 - 1) with (0 + 2 * k) by lia.
    rewrite Z.odd_add_mul_2. reflexivity.
  - assert (Hev : Z.even l = true).
    { rewrite <- Z.negb_odd, Hod. reflexivity. }
    rewrite lit_neg_c_even by assumption. simpl.
    apply Z.even_spec in Hev. destruct Hev as [k ->].
    replace (2 * k + 1) with (1 + 2 * k) by lia.
    rewrite Z.odd_add_mul_2. reflexivity.
Qed.

Lemma lit_var_c_neg : forall l, lit_var_c (lit_neg_c l) = lit_var_c l.
Proof.
  intros l. unfold lit_var_c. destruct (Z.odd l) eqn:Hod.
  - rewrite lit_neg_c_odd by assumption.
    apply Z.odd_spec in Hod. destruct Hod as [k ->].
    replace (2 * k + 1 - 1) with (k * 2) by lia.
    replace (2 * k + 1) with (k * 2 + 1) by lia.
    rewrite Z.div_add_l by lia. rewrite Z_div_mult_full by lia.
    rewrite one_div_two. lia.
  - assert (Hev : Z.even l = true).
    { rewrite <- Z.negb_odd, Hod. reflexivity. }
    rewrite lit_neg_c_even by assumption.
    apply Z.even_spec in Hev. destruct Hev as [k ->].
    replace (2 * k) with (k * 2) by lia.
    replace (k * 2 + 1) with (k * 2 + 1) by lia.
    rewrite Z.div_add_l by lia. rewrite Z_div_mult_full by lia.
    rewrite one_div_two. lia.
Qed.

Lemma lit_denote_neg : forall l,
  0 <= l -> lit_denote (lit_neg_c l) = literal_neg (lit_denote l).
Proof.
  intros l _. unfold lit_denote, literal_neg.
  rewrite lit_neg_c_odd_parity.
  assert (Hv : lit_var_c (lit_neg_c l) = lit_var_c l) by apply lit_var_c_neg.
  unfold lit_var_c in Hv.
  destruct (Z.odd l); simpl; rewrite Hv; reflexivity.
Qed.

Lemma lit_var_c_denote : forall l, literal_var (lit_denote l) = lit_var_c l.
Proof.
  intros l. unfold lit_denote, lit_var_c, literal_var.
  destruct (Z.odd l); reflexivity.
Qed.

Lemma lit_denote_wf : forall n l, lit_wf_c n l -> literal_wf n (lit_denote l).
Proof.
  intros n l [Hlo Hhi].
  unfold literal_wf, var_in_range. rewrite lit_var_c_denote.
  unfold lit_var_c. split.
  - apply Z.div_pos; lia.
  - apply Z.div_lt_upper_bound; lia.
Qed.

Lemma lit_encode_wf : forall n l,
  literal_wf n l -> lit_wf_c n (lit_encode l).
Proof.
  intros n [x|x] Hwf;
    unfold literal_wf, var_in_range, literal_var in Hwf;
    unfold lit_wf_c, lit_encode;
    lia.
Qed.

Lemma lit_denote_encode : forall n l,
  literal_wf n l -> lit_denote (lit_encode l) = l.
Proof.
  intros n [x|x] Hwf;
    unfold literal_wf, var_in_range, literal_var in Hwf.
  - unfold lit_encode, lit_denote.
    assert (Ho : Z.odd (2 * x) = false)
      by (rewrite Z.odd_mul; reflexivity).
    assert (Hd : (2 * x) / 2 = x).
    { replace (2 * x) with (x * 2) by lia.
      apply Z_div_mult_full. lia. }
    rewrite Ho, Hd. reflexivity.
  - unfold lit_encode, lit_denote.
    assert (Ho : Z.odd (2 * x + 1) = true).
    { replace (2 * x + 1) with (Z.succ (2 * x)) by lia.
      rewrite Z.odd_succ, Z.even_mul. reflexivity. }
    assert (Hd : (2 * x + 1) / 2 = x).
    { replace (2 * x + 1) with (1 + x * 2) by lia.
      rewrite Z.div_add by lia. rewrite Z.div_small by lia. lia. }
    rewrite Ho, Hd. reflexivity.
Qed.

Lemma lit_encode_denote : forall n l,
  lit_wf_c n l -> lit_encode (lit_denote l) = l.
Proof.
  intros n l Hwf. unfold lit_encode, lit_denote.
  destruct (Z.odd l) eqn:Hodd.
  - apply Z.odd_spec in Hodd. destruct Hodd as [k Hk]. subst l.
    replace ((2 * k + 1) / 2) with k.
    + lia.
    + replace (2 * k + 1) with (1 + k * 2) by lia.
      rewrite Z.div_add by lia. rewrite Z.div_small by lia. lia.
  - assert (Heven : Z.even l = true).
    { rewrite <- Z.negb_odd, Hodd. reflexivity. }
    apply Z.even_spec in Heven. destruct Heven as [k Hk]. subst l.
    replace ((2 * k) / 2) with k.
    + lia.
    + replace (2 * k) with (k * 2) by lia.
      symmetry. apply Z_div_mult_full. lia.
Qed.

Lemma lit_neg_c_wf : forall n l, lit_wf_c n l -> lit_wf_c n (lit_neg_c l).
Proof.
  intros n l [Hlo Hhi]. unfold lit_wf_c. destruct (Z.odd l) eqn:Hod.
  - rewrite lit_neg_c_odd by assumption.
    apply Z.odd_spec in Hod. destruct Hod as [k Hk]. lia.
  - assert (Hev : Z.even l = true).
    { rewrite <- Z.negb_odd, Hod. reflexivity. }
    rewrite lit_neg_c_even by assumption.
    apply Z.even_spec in Hev. destruct Hev as [k Hk]. lia.
Qed.

Lemma lit_sign_c_range : forall l, 0 <= lit_sign_c l <= 1.
Proof. intros l. unfold lit_sign_c. destruct (Z.odd l); lia. Qed.

Lemma lit_pack_unpack : forall l,
  0 <= l -> 2 * lit_var_c l + lit_sign_c l = l.
Proof.
  intros l _. unfold lit_var_c, lit_sign_c.
  destruct (Z.odd l) eqn:Hod.
  - apply Z.odd_spec in Hod. destruct Hod as [k ->].
    replace (2 * k + 1) with (k * 2 + 1) by lia.
    rewrite Z.div_add_l by lia. rewrite one_div_two. lia.
  - assert (Hev : Z.even l = true).
    { rewrite <- Z.negb_odd, Hod. reflexivity. }
    apply Z.even_spec in Hev. destruct Hev as [k ->].
    replace (2 * k) with (k * 2) by lia.
    rewrite Z_div_mult_full by lia. lia.
Qed.

Lemma lbool_val_true : forall v, lbool_val v = Some true <-> v = 1.
Proof.
  intros v. unfold lbool_val. split; intros H.
  - destruct (v =? 1) eqn:H1; [ apply Z.eqb_eq in H1; assumption |].
    destruct (v =? -1); discriminate.
  - subst. reflexivity.
Qed.

Lemma lbool_val_false : forall v, lbool_val v = Some false <-> v = -1.
Proof.
  intros v. unfold lbool_val. split; intros H.
  - destruct (v =? 1) eqn:H1; [discriminate|].
    destruct (v =? -1) eqn:H2; [ apply Z.eqb_eq in H2; assumption | discriminate].
  - subst. reflexivity.
Qed.

Lemma eval_denote : forall assigns l, 0 <= l ->
  eval_partial_literal (assigns_pv assigns) (lit_denote l)
  = match lbool_val (Znth (lit_var_c l) assigns 0) with
    | None => None
    | Some b => Some (if Z.odd l then negb b else b)
    end.
Proof.
  intros assigns l _.
  unfold eval_partial_literal, assigns_pv, assigns_val, lit_denote, lit_var_c.
  destruct (Z.odd l); simpl;
    destruct (lbool_val (Znth (l / 2) assigns 0)) as [b|]; reflexivity.
Qed.

Lemma lit_true_iff : forall assigns l, 0 <= l ->
  Znth (lit_var_c l) assigns 0 = lit_sig l
  <-> eval_partial_literal (assigns_pv assigns) (lit_denote l) = Some true.
Proof.
  intros assigns l Hl. rewrite eval_denote by assumption.
  unfold lit_sig. split; intros H.
  - rewrite H. destruct (Z.odd l).
    + rewrite (proj2 (lbool_val_false _) eq_refl). reflexivity.
    + rewrite (proj2 (lbool_val_true _) eq_refl). reflexivity.
  - destruct (lbool_val (Znth (lit_var_c l) assigns 0)) as [b|] eqn:Hb;
      [|discriminate].
    destruct (Z.odd l).
    + destruct b; simpl in H; [discriminate|].
      apply lbool_val_false. exact Hb.
    + destruct b; simpl in H; [|discriminate].
      apply lbool_val_true. exact Hb.
Qed.

Lemma lit_false_iff : forall assigns l, 0 <= l ->
  Znth (lit_var_c l) assigns 0 = - lit_sig l
  <-> eval_partial_literal (assigns_pv assigns) (lit_denote l) = Some false.
Proof.
  intros assigns l Hl. rewrite eval_denote by assumption.
  unfold lit_sig. split; intros H.
  - destruct (Z.odd l).
    + assert (Hv : Znth (lit_var_c l) assigns 0 = 1) by lia.
      rewrite Hv. reflexivity.
    + assert (Hv : Znth (lit_var_c l) assigns 0 = -1) by lia.
      rewrite Hv. reflexivity.
  - destruct (lbool_val (Znth (lit_var_c l) assigns 0)) as [b|] eqn:Hb;
      [|discriminate].
    destruct (Z.odd l).
    + destruct b; simpl in H; [|discriminate].
      apply lbool_val_true in Hb. lia.
    + destruct b; simpl in H; [discriminate|].
      apply lbool_val_false in Hb. lia.
Qed.

(** the negation of a literal is false exactly when the literal is true *)
Lemma lit_neg_true_iff_false : forall assigns l, 0 <= l ->
  eval_partial_literal (assigns_pv assigns) (lit_denote (lit_neg_c l)) = Some true
  <-> eval_partial_literal (assigns_pv assigns) (lit_denote l) = Some false.
Proof.
  intros assigns l Hl.
  rewrite lit_denote_neg by assumption.
  rewrite eval_partial_literal_neg.
  destruct (eval_partial_literal (assigns_pv assigns) (lit_denote l)) as [b|];
    simpl.
  - destruct b; simpl; split; intros H; try reflexivity; discriminate.
  - split; intros H; discriminate.
Qed.

(** ----- watcher tag codec ----- *)

Lemma tag_lit_of : forall l, tag_lit (tag_of_lit l) = l.
Proof.
  intros l. unfold tag_lit, tag_of_lit.
  replace (2 * l + 1) with (l * 2 + 1) by lia.
  rewrite Z.div_add_l by lia. rewrite one_div_two. lia.
Qed.

Lemma tag_of_lit_odd : forall l, Z.odd (tag_of_lit l) = true.
Proof.
  intros l. unfold tag_of_lit.
  replace (2 * l + 1) with (1 + 2 * l) by lia.
  rewrite Z.odd_add_mul_2. reflexivity.
Qed.

Lemma is_tag_of : forall l, is_tag (tag_of_lit l) = true.
Proof. intros l. unfold is_tag. apply tag_of_lit_odd. Qed.

Lemma even_not_tag : forall p, Z.even p = true -> is_tag p = false.
Proof.
  intros p H. unfold is_tag.
  rewrite <- Z.negb_even, H. reflexivity.
Qed.

Lemma is_tag_odd_inv : forall w, is_tag w = true -> tag_of_lit (tag_lit w) = w.
Proof.
  intros w H. unfold is_tag in H. unfold tag_of_lit, tag_lit.
  apply Z.odd_spec in H. destruct H as [k ->].
  replace (2 * k + 1) with (k * 2 + 1) by lia.
  rewrite Z.div_add_l by lia. rewrite one_div_two. lia.
Qed.

(** A tagged word is POSITIVE as soon as its decoded literal is in range:
    [tag_lit] is floor division, so an odd [w <= 0] decodes to a NEGATIVE
    literal ([tag_lit (-1) = -1], [tag_lit (-3) = -2], ...).  This is why
    [binary_reason_same_level] need not carry positivity separately. *)
Lemma tag_pos_of_lit_wf : forall n w,
  is_tag w = true -> lit_wf_c n (tag_lit w) -> 0 < w.
Proof.
  intros n w Ht [Hlo _].
  rewrite <- (is_tag_odd_inv w Ht). unfold tag_of_lit. lia.
Qed.

(** The introduction form of the same bound: the only tagged reason word the
    solver ever writes is [tag_of_lit p] at a binary-propagation enqueue
    (see [propagation_binary_keep_transition]), and [p] is the watcher-list
    literal, which is well formed there. *)
Lemma tag_of_lit_reason_wf : forall n p,
  lit_wf_c n p -> 0 < tag_of_lit p /\ lit_wf_c n (tag_lit (tag_of_lit p)).
Proof.
  intros n p Hp. rewrite tag_lit_of.
  destruct Hp as [Hlo Hhi].
  split; [unfold tag_of_lit; lia | split; lia].
Qed.

(** ----- clause-level denotation ----- *)

Lemma lits_denote_cons : forall l ls,
  lits_denote (l :: ls) = lit_denote l :: lits_denote ls.
Proof. reflexivity. Qed.

Lemma lits_denote_app : forall ls ms,
  lits_denote (ls ++ ms) = lits_denote ls ++ lits_denote ms.
Proof. intros. unfold lits_denote. apply map_app. Qed.

Lemma lits_denote_length : forall ls,
  Zlength (lits_denote ls) = Zlength ls.
Proof.
  intros ls. unfold lits_denote.
  rewrite !Zlength_correct, length_map. reflexivity.
Qed.

Lemma lits_denote_in : forall l ls,
  In l ls -> In (lit_denote l) (lits_denote ls).
Proof. intros l ls H. unfold lits_denote. apply in_map. exact H. Qed.

Lemma lits_denote_in_inv : forall L ls,
  In L (lits_denote ls) -> exists l, In l ls /\ lit_denote l = L.
Proof.
  intros L ls H. unfold lits_denote in H.
  apply in_map_iff in H. destruct H as [l [Heq Hin]].
  exists l. split; assumption.
Qed.

Lemma lits_denote_wf : forall n ls,
  Forall (lit_wf_c n) ls -> Forall (literal_wf n) (lits_denote ls).
Proof.
  intros n ls H. unfold lits_denote. rewrite Forall_map.
  eapply Forall_impl; [|exact H].
  intros l Hl. apply lit_denote_wf. exact Hl.
Qed.

Lemma map_literal_var_lits_denote : forall ls,
  map literal_var (lits_denote ls) = map lit_var_c ls.
Proof.
  intros ls. unfold lits_denote. rewrite map_map.
  apply map_ext. intros l. apply lit_var_c_denote.
Qed.

Lemma lits_denote_nodup_vars : forall ls,
  NoDup (map lit_var_c ls) -> NoDup (map literal_var (lits_denote ls)).
Proof.
  intros ls H. rewrite map_literal_var_lits_denote. exact H.
Qed.

(** ----- clause status through the bridge ----- *)

Lemma lits_denote_false_iff : forall assigns ls,
  Forall (fun l => 0 <= l) ls ->
  Forall (fun l => Znth (lit_var_c l) assigns 0 = - lit_sig l) ls ->
  clause_false (assigns_pv assigns) (lits_denote ls).
Proof.
  intros assigns ls Hpos Hval.
  rewrite Forall_forall in Hpos. rewrite Forall_forall in Hval.
  unfold clause_false. intros L Hin.
  apply lits_denote_in_inv in Hin. destruct Hin as [l [Hin Heq]].
  subst L. apply lit_false_iff; auto.
Qed.

Lemma ztake_ztake : forall a b l, 0 <= a <= b -> ztake a (ztake b l) = ztake a l.
Proof.
  intros a b l H. unfold ztake. rewrite firstn_firstn. f_equal. lia.
Qed.

Lemma Forall_ztake : forall (P : Z -> Prop) k l, Forall P l -> Forall P (ztake k l).
Proof.
  intros P k l H. rewrite Forall_forall in *. intros x Hx.
  apply H. eapply In_ztake; eauto.
Qed.

Lemma Znth_zdrop : forall k l j d,
  0 <= k -> 0 <= j -> Znth j (zdrop k l) d = Znth (k + j) l d.
Proof.
  intros k l j d Hk Hj. unfold Znth, zdrop.
  rewrite nth_skipn.
  f_equal. lia.
Qed.

Lemma NoDup_snoc : forall (xs : list Z) y, NoDup xs -> ~ In y xs -> NoDup (xs ++ [y]).
Proof.
  induction xs as [|a xs IH]; intros y Hnd Hnin; simpl.
  - constructor; [intros []|constructor].
  - inversion Hnd as [|? ? Hna Hnd']; subst.
    constructor.
    + intro Hin. apply in_app_or in Hin. destruct Hin as [Hin|[Hin|[]]].
      * apply Hna; exact Hin.
      * apply Hnin. left. symmetry. exact Hin.
    + apply IH; [exact Hnd'|]. intro Hin. apply Hnin. right. exact Hin.
Qed.

Lemma In_Znth_index : forall (l : list Z) x,
  In x l -> exists j, 0 <= j < Zlength l /\ Znth j l 0 = x.
Proof.
  induction l as [|a l IH]; intros x Hin; simpl in Hin.
  - contradiction.
  - rewrite Zlength_cons. pose proof (Zlength_nonneg l).
    destruct Hin as [<-|Hin].
    + exists 0. split; [lia|apply Znth0_cons].
    + destruct (IH x Hin) as [j [Hj Hval]].
      exists (j + 1). split; [lia|].
      rewrite Znth_cons by lia. replace (j + 1 - 1) with j by lia. exact Hval.
Qed.

Lemma Zlength_map_Z : forall (f : Z -> Z) l, Zlength (map f l) = Zlength l.
Proof. intros. rewrite !Zlength_correct, length_map. reflexivity. Qed.

Lemma count_le_app : forall i l1 l2,
  count_le i (l1 ++ l2) = count_le i l1 + count_le i l2.
Proof.
  intros i l1 l2; induction l1 as [|x l1 IH]; simpl; [lia|].
  rewrite IH. lia.
Qed.

Lemma count_le_length : forall i l, count_le i l <= Zlength l.
Proof.
  intros i l; induction l as [|x l IH]; simpl; [rewrite Zlength_nil; lia|].
  rewrite Zlength_cons. destruct (x <=? i); lia.
Qed.

Lemma count_le_none : forall i l, Forall (fun x => i < x) l -> count_le i l = 0.
Proof.
  intros i l H; induction H as [|x l Hx Hl IH]; simpl; [reflexivity|].
  assert (Hb : (x <=? i) = false) by (apply Z.leb_gt; lia).
  rewrite Hb, IH. lia.
Qed.

Lemma count_le_all : forall i l, Forall (fun x => x <= i) l -> count_le i l = Zlength l.
Proof.
  intros i l H; induction H as [|x l Hx Hl IH]; simpl;
    [rewrite Zlength_nil; reflexivity|].
  assert (Hb : (x <=? i) = true) by (apply Z.leb_le; lia).
  rewrite Hb, IH, Zlength_cons. lia.
Qed.

Lemma count_le_all_inv : forall i l,
  count_le i l = Zlength l -> Forall (fun x => x <= i) l.
Proof.
  intros i l; induction l as [|x l IH]; intros Hcount; constructor.
  - simpl in Hcount. rewrite Zlength_cons in Hcount.
    destruct (x <=? i) eqn:Hx.
    + apply Z.leb_le in Hx. exact Hx.
    + pose proof (count_le_length i l). lia.
  - apply IH. simpl in Hcount. rewrite Zlength_cons in Hcount.
    destruct (x <=? i); [lia|].
    pose proof (count_le_length i l). lia.
Qed.

Lemma strict_sorted_ztake : forall k l, strict_sorted l -> strict_sorted (ztake k l).
Proof.
  intros k l; revert k; induction l as [|a l IH]; intros k Hs.
  - unfold ztake; rewrite firstn_nil; exact I.
  - unfold ztake. destruct (Z.to_nat k) as [|m] eqn:Hm; [exact I|].
    simpl. destruct Hs as [Hall Hs]. split.
    + apply (Forall_ztake _ (Z.of_nat m)) in Hall.
      unfold ztake in Hall. rewrite Nat2Z.id in Hall. exact Hall.
    + apply (IH (Z.of_nat m)) in Hs. unfold ztake in Hs.
      rewrite Nat2Z.id in Hs. exact Hs.
Qed.

Lemma strict_sorted_snoc : forall l y,
  strict_sorted l -> Forall (fun x => x < y) l -> strict_sorted (l ++ [y]).
Proof.
  induction l as [|a l IH]; intros y Hs Hall; simpl.
  - split; [constructor|exact I].
  - destruct Hs as [Hfa Hs].
    inversion Hall as [|? ? Hay Hall']; subst.
    split.
    + apply Forall_app. split; [exact Hfa|constructor; [exact Hay|constructor]].
    + apply IH; assumption.
Qed.

Lemma strict_sorted_Znth : forall l i j,
  strict_sorted l -> 0 <= i -> i < j -> j < Zlength l -> Znth i l 0 < Znth j l 0.
Proof.
  induction l as [|a l IH]; intros i j Hs Hi Hij Hj.
  - rewrite Zlength_nil in Hj; lia.
  - rewrite Zlength_cons in Hj. pose proof (Zlength_nonneg l).
    destruct Hs as [Hall Hs].
    destruct (Z.eq_dec i 0) as [->|Hi0].
    + rewrite Znth0_cons, Znth_cons by lia.
      rewrite Forall_forall in Hall. apply Hall.
      apply Znth_In. lia.
    + rewrite !Znth_cons by lia. apply IH; try lia. exact Hs.
Qed.

Lemma strict_sorted_count_prefix : forall l i k,
  strict_sorted l -> 0 <= k < count_le i l -> Znth k l 0 <= i.
Proof.
  induction l as [|a l IH]; intros i k Hs [Hk0 Hk]; simpl in Hk.
  - lia.
  - destruct Hs as [Hall Hs].
    destruct (a <=? i) eqn:Ha.
    + apply Z.leb_le in Ha.
      destruct (Z.eq_dec k 0) as [->|Hk0'].
      * rewrite Znth0_cons; exact Ha.
      * rewrite Znth_cons by lia. apply IH; [exact Hs|lia].
    + apply Z.leb_gt in Ha.
      assert (Hz : count_le i l = 0).
      { apply count_le_none. revert Hall. apply Forall_impl. intros y Hy; lia. }
      lia.
Qed.

Lemma count_le_ztake : forall l i k,
  strict_sorted l -> 0 <= k -> count_le i l <= k ->
  count_le i (ztake k l) = count_le i l.
Proof.
  induction l as [|a l IH]; intros i k Hs Hk Hcnt.
  - unfold ztake; rewrite firstn_nil; reflexivity.
  - destruct Hs as [Hall Hs]. simpl in Hcnt.
    destruct (Z.eq_dec k 0) as [->|Hk0].
    + unfold ztake; simpl.
      pose proof (count_le_nonneg i l).
      destruct (a <=? i); [lia|]. simpl. lia.
    + unfold ztake. replace (Z.to_nat k) with (S (Z.to_nat (k - 1))) by lia.
      simpl.
      assert (Hrest : count_le i (ztake (k - 1) l) = count_le i l).
      { apply IH; [exact Hs|lia|].
        destruct (a <=? i) eqn:Ha; [lia|].
        apply Z.leb_gt in Ha.
        assert (count_le i l = 0).
        { apply count_le_none. revert Hall. apply Forall_impl. intros y Hy; lia. }
        lia. }
      unfold ztake in Hrest. rewrite Hrest. reflexivity.
Qed.

Lemma find_var_pos_app : forall v l1 l2,
  find_var_pos v (l1 ++ l2) =
  match find_var_pos v l1 with
  | Some k => Some k
  | None => option_map (Nat.add (List.length l1)) (find_var_pos v l2)
  end.
Proof.
  induction l1 as [|x l1 IH]; intros l2; simpl.
  - destruct (find_var_pos v l2) as [k|]; simpl; [f_equal; lia|reflexivity].
  - destruct (lit_var_c x =? v); [reflexivity|].
    rewrite IH.
    destruct (find_var_pos v l1) as [k|]; simpl; [reflexivity|].
    destruct (find_var_pos v l2) as [k|]; simpl; [f_equal; lia|reflexivity].
Qed.

Lemma find_var_pos_in : forall v l,
  In v (map lit_var_c l) -> exists k, find_var_pos v l = Some k.
Proof.
  intros v l Hin. destruct (find_var_pos v l) as [k|] eqn:Hf; [eauto|].
  exfalso. apply (proj1 (find_var_pos_none_iff v l) Hf). exact Hin.
Qed.

Lemma find_var_pos_min : forall v l k j,
  find_var_pos v l = Some k -> (j < k)%nat -> lit_var_c (nth j l 0) <> v.
Proof.
  induction l as [|x l IH]; intros k j H Hj; simpl in *; [discriminate|].
  destruct (lit_var_c x =? v) eqn:Hx.
  - inversion H; lia.
  - destruct (find_var_pos v l) as [i|] eqn:Hf; simpl in H; [|discriminate].
    inversion H; subst k.
    destruct j as [|j]; simpl.
    + apply Z.eqb_neq in Hx. exact Hx.
    + eapply IH; [reflexivity|lia].
Qed.

Lemma find_var_pos_prefix : forall v l1 l2 k,
  find_var_pos v (l1 ++ l2) = Some k -> (k < List.length l1)%nat ->
  find_var_pos v l1 = Some k.
Proof.
  intros v l1 l2 k H Hk. rewrite find_var_pos_app in H.
  destruct (find_var_pos v l1) as [j|]; [exact H|].
  destruct (find_var_pos v l2) as [j|]; simpl in H; [|discriminate].
  inversion H; lia.
Qed.

Lemma find_var_pos_ztake_lt : forall v l k b,
  find_var_pos v l = Some k -> (k < Z.to_nat b)%nat ->
  find_var_pos v (ztake b l) = Some k.
Proof.
  intros v l k b H Hk.
  pose proof (find_var_pos_bound v l k H) as Hlen.
  rewrite <- (ztake_zdrop b l) in H.
  apply find_var_pos_prefix in H; [exact H|].
  unfold ztake. rewrite length_firstn. lia.
Qed.

Lemma find_var_pos_ztake_none : forall v l k b,
  NoDup (map lit_var_c l) -> find_var_pos v l = Some k -> (Z.to_nat b <= k)%nat ->
  find_var_pos v (ztake b l) = None.
Proof.
  intros v l k b Hnd H Hk.
  apply find_var_pos_none_iff. intro Hin.
  apply in_map_iff in Hin. destruct Hin as [x [Hx Hxin]].
  assert (Hin' : In x (ztake b l)) by exact Hxin.
  destruct (In_Znth_index _ _ Hin') as [j [Hj Hjval]].
  assert (Hjb : j < b).
  { unfold ztake in Hj. rewrite Zlength_correct, length_firstn in Hj. lia. }
  assert (Hnth : lit_var_c (nth (Z.to_nat j) l 0) = v).
  { rewrite Znth_ztake in Hjval by lia. unfold Znth in Hjval.
    rewrite Hjval. exact Hx. }
  pose proof (Zlength_nonneg (ztake b l)).
  eapply find_var_pos_min; [exact H| |exact Hnth]. lia.
Qed.

Lemma find_var_pos_ztake_inv : forall v l b k,
  find_var_pos v (ztake b l) = Some k -> exists k', find_var_pos v l = Some k'.
Proof.
  intros v l b k H.
  apply find_var_pos_in.
  assert (Hin : In v (map lit_var_c (ztake b l))).
  { destruct (find_var_pos_none_iff v (ztake b l)) as [_ Hb].
    destruct (List.in_dec Z.eq_dec v (map lit_var_c (ztake b l))) as [Hi|Hi];
      [exact Hi|]. rewrite (Hb Hi) in H; discriminate. }
  apply in_map_iff in Hin. destruct Hin as [x [<- Hx]].
  apply in_map. eapply In_ztake; eauto.
Qed.

(** The boolean a packed literal forces on its variable. *)
Definition lit_pol (l : Z) : bool := negb (Z.odd l).

Lemma lbool_val_lit_sig : forall l, lbool_val (lit_sig l) = Some (lit_pol l).
Proof. intro l. unfold lit_sig, lit_pol. destruct (Z.odd l); reflexivity. Qed.

Lemma lit_denote_satisfying : forall l,
  lit_denote l = satisfying_literal (lit_var_c l) (lit_pol l).
Proof.
  intro l. unfold lit_denote, satisfying_literal, lit_pol, lit_var_c.
  destruct (Z.odd l); reflexivity.
Qed.

Lemma lit_var_c_nonneg : forall n l, lit_wf_c n l -> 0 <= lit_var_c l.
Proof. intros n l H. apply (lit_var_c_in_range n l H). Qed.

(** *** The [assume] transient.

    [assume] does [veci_push(&s->trail_lim, s->qtail)] and only
    *then* [enqueue(s,l,NULL)].  Between the two writes the last
    [trail_lim] entry equals [Zlength (mt_trail t)], so [mtrail_wf]'s strict
    [mtw_lim_range] is momentarily false and the state at the [enqueue] call
    site has no carrier.  [mtrail_wf_pushed] is [mtrail_wf] with that single
    bound relaxed to [<=]; it is what every transition lemma below actually
    consumes, so [mtrail_wf_push] applies at the transient directly. *)
Record mtrail_wf_pushed (n : Z) (t : mtrail) : Prop := {
  mtwp_n_nonneg    : 0 <= n;
  mtwp_assigns_len : Zlength (mt_assigns t) = n;
  mtwp_levels_len  : Zlength (mt_levels t) = n;
  mtwp_cells       : Forall lbool_cell (mt_assigns t);
  mtwp_qhead_range : 0 <= mt_qhead t <= Zlength (mt_trail t);
  mtwp_trail_bound : Zlength (mt_trail t) <= n;
  mtwp_trail_lits  : Forall (lit_wf_c n) (mt_trail t);
  mtwp_trail_nodup : NoDup (map lit_var_c (mt_trail t));
  mtwp_trail_true  :
    Forall (fun l => Znth (lit_var_c l) (mt_assigns t) 0 = lit_sig l) (mt_trail t);
  mtwp_lim_sorted  : strict_sorted (mt_lim t);
  mtwp_lim_range   : Forall (fun b => 0 <= b <= Zlength (mt_trail t)) (mt_lim t);
  mtwp_levels_agree :
    forall i, 0 <= i < Zlength (mt_trail t) ->
      Znth (trail_var t i) (mt_levels t) 0 = level_of_index t i;
  mtwp_assigned_iff :
    forall v, 0 <= v < n ->
      (Znth v (mt_assigns t) 0 <> 0 <-> In v (map lit_var_c (mt_trail t)))
}.

Arguments mtwp_n_nonneg {n t} _.

Arguments mtwp_assigns_len {n t} _.

Arguments mtwp_levels_len {n t} _.

Arguments mtwp_cells {n t} _.

Arguments mtwp_qhead_range {n t} _.

Arguments mtwp_trail_bound {n t} _.

Arguments mtwp_trail_lits {n t} _.

Arguments mtwp_trail_nodup {n t} _.

Arguments mtwp_trail_true {n t} _.

Arguments mtwp_lim_sorted {n t} _.

Arguments mtwp_lim_range {n t} _.

Arguments mtwp_levels_agree {n t} _.

Arguments mtwp_assigned_iff {n t} _.

Lemma mtrail_wf_pushed_of_wf : forall n t, mtrail_wf n t -> mtrail_wf_pushed n t.
Proof.
  intros n t Hwf. constructor.
  - exact (mtw_n_nonneg Hwf).
  - exact (mtw_assigns_len Hwf).
  - exact (mtw_levels_len Hwf).
  - exact (mtw_cells Hwf).
  - exact (mtw_qhead_range Hwf).
  - exact (mtw_trail_bound Hwf).
  - exact (mtw_trail_lits Hwf).
  - exact (mtw_trail_nodup Hwf).
  - exact (mtw_trail_true Hwf).
  - exact (mtw_lim_sorted Hwf).
  - pose proof (mtw_lim_range Hwf) as HF. revert HF.
    apply Forall_impl. intros b Hb. lia.
  - exact (mtw_levels_agree Hwf).
  - exact (mtw_assigned_iff Hwf).
Qed.

(** [s->qhead++] and the [qhead = qtail] resets. *)
Definition mt_set_qhead (t : mtrail) (q : Z) : mtrail :=
  {| mt_assigns := mt_assigns t;
     mt_levels  := mt_levels t;
     mt_trail   := mt_trail t;
     mt_lim     := mt_lim t;
     mt_qhead   := q |}.

Lemma mtrail_wf_set_qhead : forall n t q,
  mtrail_wf n t ->
  0 <= q <= Zlength (mt_trail t) ->
  mtrail_wf n (mt_set_qhead t q).
Proof.
  intros n t q Hwf Hq. destruct Hwf. constructor; simpl; assumption.
Qed.

(** Consequence 1: every *unpropagated* trail index carries the current
    level -- this is the literal reading of INV-PROP-LEVEL. *)
Lemma prop_level_unpropagated_current : forall t i,
  prop_level t -> mt_qhead t <= i -> level_of_index t i = Zlength (mt_lim t).
Proof.
  intros t i Hp Hi. unfold level_of_index. apply count_le_all.
  revert Hp. apply Forall_impl. intros b Hb. lia.
Qed.

(** Consequence 2: no trail index carries a level above the current one. *)
Lemma prop_level_processed_level_le : forall t i,
  level_of_index t i <= Zlength (mt_lim t).
Proof. intros t i. apply count_le_length. Qed.

Lemma trail_lit_nonneg : forall n t i,
  mtrail_wf n t -> 0 <= i < Zlength (mt_trail t) -> 0 <= Znth i (mt_trail t) 0.
Proof.
  intros n t i Hwf Hi.
  pose proof (Forall_Znth_elim _ _ _ 0 i (mtw_trail_lits Hwf) Hi) as [H _]. lia.
Qed.

Lemma view_of_rank : forall n t r db,
  assignment_rank (view_of n t r db) = trail_pos t.
Proof. reflexivity. Qed.

Lemma trail_pos_of_index : forall t i,
  NoDup (map lit_var_c (mt_trail t)) -> 0 <= i < Zlength (mt_trail t) ->
  trail_pos t (trail_var t i) = Some (Z.to_nat i).
Proof.
  intros t i Hnd Hi.
  assert (Hin : In (trail_var t i) (map lit_var_c (mt_trail t))).
  { unfold trail_var. apply in_map. apply Znth_In. exact Hi. }
  destruct (find_var_pos_in _ _ Hin) as [k Hk].
  assert (Hkv : trail_var t (Z.of_nat k) = trail_var t i)
    by (apply trail_pos_var; exact Hk).
  pose proof (trail_pos_bound t _ _ Hk) as Hkb.
  unfold trail_pos. rewrite Hk. f_equal.
  (* NoDup on the variable list forces the two indices to agree *)
  assert (Hnodup_index : forall a b,
            0 <= a < Zlength (mt_trail t) -> 0 <= b < Zlength (mt_trail t) ->
            trail_var t a = trail_var t b -> a = b).
  { intros a b Ha Hb Heq.
    destruct (Z.eq_dec a b) as [->|Hne]; [reflexivity|exfalso].
    revert Hnd Ha Hb Heq Hne. unfold trail_var.
    generalize (mt_trail t). clear.
    intros l Hnd Ha Hb Heq Hne.
    assert (Hmap : NoDup (map lit_var_c l)) by exact Hnd.
    rewrite NoDup_nth_error in Hmap.
    specialize (Hmap (Z.to_nat a) (Z.to_nat b)).
    rewrite length_map in Hmap.
    assert (Hla : (Z.to_nat a < List.length l)%nat)
      by (rewrite Zlength_correct in Ha; lia).
    assert (Hlb : (Z.to_nat b < List.length l)%nat)
      by (rewrite Zlength_correct in Hb; lia).
    assert (Hnth : nth_error (map lit_var_c l) (Z.to_nat a) =
                   nth_error (map lit_var_c l) (Z.to_nat b)).
    { rewrite !nth_error_map.
      rewrite (nth_error_nth' l 0 Hla), (nth_error_nth' l 0 Hlb).
      simpl. unfold Znth in Heq. rewrite Heq. reflexivity. }
    specialize (Hmap Hla Hnth). lia. }
  apply Nat2Z.inj.
  rewrite Z2Nat.id by lia.
  apply Hnodup_index; [lia|lia|exact Hkv].
Qed.

(** Variable identity determines a unique concrete trail position.  Keeping
    this consequence of [mtrail_wf] explicit avoids rebuilding the
    [NoDup (map lit_var_c trail)] index argument at queue rollback sites. *)
Lemma mtrail_wf_trail_var_injective : forall n t i j,
  mtrail_wf n t ->
  0 <= i < Zlength (mt_trail t) ->
  0 <= j < Zlength (mt_trail t) ->
  trail_var t i = trail_var t j ->
  i = j.
Proof.
  intros n t i j Hwf Hi Hj Heq.
  pose proof (trail_pos_of_index t i (mtw_trail_nodup Hwf) Hi) as Hpi.
  pose proof (trail_pos_of_index t j (mtw_trail_nodup Hwf) Hj) as Hpj.
  rewrite Heq, Hpj in Hpi. inversion Hpi. lia.
Qed.

Definition mt_push_lim (t : mtrail) : mtrail :=
  {| mt_assigns := mt_assigns t;
     mt_levels  := mt_levels t;
     mt_trail   := mt_trail t;
     mt_lim     := mt_lim t ++ [Zlength (mt_trail t)];
     mt_qhead   := mt_qhead t |}.

(** [assume] = [veci_push(&trail_lim, qtail)] then [enqueue(l, NULL)]. *)
Lemma mt_decide_push_lim : forall t l, mt_decide t l = mt_enqueue (mt_push_lim t) l.
Proof. reflexivity. Qed.

Lemma Zlength_clear_vars : forall ls a, Zlength (clear_vars ls a) = Zlength a.
Proof.
  induction ls as [|x ls IH]; intros a; simpl; [reflexivity|].
  rewrite IH, Zlength_replace_Znth. reflexivity.
Qed.

Lemma Forall_replace_nth : forall (P : Z -> Prop) (a : list Z) (m : nat) (v : Z),
  Forall P a -> P v -> Forall P (replace_nth m a v).
Proof.
  induction a as [|x a IH]; intros m v Ha Hv.
  - destruct m; simpl; constructor.
  - inversion Ha as [|? ? Hx Ha']; subst.
    destruct m as [|m]; simpl; constructor; try assumption.
    apply IH; assumption.
Qed.

Lemma Forall_replace_Znth : forall (P : Z -> Prop) i v a,
  Forall P a -> P v -> Forall P (replace_Znth i v a).
Proof. intros. unfold replace_Znth. apply Forall_replace_nth; assumption. Qed.

Lemma clear_vars_cells : forall ls a,
  Forall lbool_cell a -> Forall lbool_cell (clear_vars ls a).
Proof.
  induction ls as [|x ls IH]; intros a Ha; simpl; [exact Ha|].
  apply IH. apply Forall_replace_Znth; [exact Ha|right; left; reflexivity].
Qed.

(** ----- [mtrail_wf] preservation ----- *)

Lemma mtrail_wf_push : forall n t l lim',
  mtrail_wf_pushed n t -> lit_wf_c n l ->
  Znth (lit_var_c l) (mt_assigns t) 0 = 0 ->
  strict_sorted lim' ->
  Forall (fun b => 0 <= b < Zlength (mt_trail t) + 1) lim' ->
  (forall i, 0 <= i < Zlength (mt_trail t) ->
     count_le i lim' = count_le i (mt_lim t)) ->
  count_le (Zlength (mt_trail t)) lim' = Zlength lim' ->
  mtrail_wf n (mt_push t l lim').
Proof.
  intros n t l lim' Hwf Hlwf Hz Hsorted Hrange Hcount Hcountnew.
  pose proof (lit_var_c_in_range n l Hlwf) as Hv.
  pose proof (mtwp_assigns_len Hwf) as HAlen.
  pose proof (mtwp_levels_len Hwf) as HLlen.
  pose proof (mtwp_trail_lits Hwf) as HTlits.
  pose proof (mtwp_trail_nodup Hwf) as HTnd.
  pose proof (mtwp_trail_true Hwf) as HTtrue.
  pose proof (mtwp_trail_bound Hwf) as HTb.
  pose proof (mtwp_qhead_range Hwf) as HQ.
  pose proof (Zlength_nonneg (mt_trail t)) as HT0.
  assert (Hnin : ~ In (lit_var_c l) (map lit_var_c (mt_trail t))).
  { intro Hin. destruct (mtwp_assigned_iff Hwf (lit_var_c l) Hv) as [_ Hbwd].
    apply Hbwd in Hin. contradiction. }
  assert (HlenT : Zlength (mt_trail t ++ [l]) = Zlength (mt_trail t) + 1).
  { rewrite Zlength_app, Zlength_cons, Zlength_nil. lia. }
  assert (Hmapapp : map lit_var_c (mt_trail t ++ [l])
                    = map lit_var_c (mt_trail t) ++ [lit_var_c l])
    by (rewrite map_app; reflexivity).
  assert (Hnd' : NoDup (map lit_var_c (mt_trail t ++ [l]))).
  { rewrite Hmapapp. apply NoDup_snoc; assumption. }
  assert (Hlits' : Forall (lit_wf_c n) (mt_trail t ++ [l])).
  { apply Forall_app. split; [exact HTlits|constructor; [exact Hlwf|constructor]]. }
  assert (Hnbound : Zlength (mt_trail t) + 1 <= n).
  { assert (Hall : forall x, In x (map lit_var_c (mt_trail t ++ [l])) ->
                             0 <= x < n).
    { intros x Hx. apply in_map_iff in Hx. destruct Hx as [y [<- Hy]].
      apply (lit_var_c_in_range n). rewrite Forall_forall in Hlits'. auto. }
    pose proof (NoDup_Z_bounded_length _ n (mtwp_n_nonneg Hwf) Hnd' Hall) as Hle.
    assert (Heq : Zlength (mt_trail t ++ [l])
                  = Zlength (map lit_var_c (mt_trail t ++ [l])))
      by (rewrite Zlength_map_Z; reflexivity).
    rewrite <- HlenT, Heq, Zlength_correct. exact Hle. }
  assert (HvA : 0 <= lit_var_c l < Zlength (mt_assigns t)) by (rewrite HAlen; exact Hv).
  assert (HvL : 0 <= lit_var_c l < Zlength (mt_levels t)) by (rewrite HLlen; exact Hv).
  assert (HkA : forall k, In k (mt_trail t) ->
                  0 <= lit_var_c k < Zlength (mt_assigns t)).
  { intros k Hk. rewrite HAlen. apply (lit_var_c_in_range n).
    rewrite Forall_forall in HTlits. auto. }
  assert (HkL : forall k, In k (mt_trail t) ->
                  0 <= lit_var_c k < Zlength (mt_levels t)).
  { intros k Hk. rewrite HLlen. apply (lit_var_c_in_range n).
    rewrite Forall_forall in HTlits. auto. }
  assert (Hkne : forall k, In k (mt_trail t) -> lit_var_c l <> lit_var_c k).
  { intros k Hk Heq. apply Hnin. rewrite Heq. apply in_map. exact Hk. }
  unfold mt_push.
  constructor; cbn [mt_assigns mt_levels mt_trail mt_lim mt_qhead].
  - exact (mtwp_n_nonneg Hwf).
  - rewrite Zlength_replace_Znth. exact HAlen.
  - rewrite Zlength_replace_Znth. exact HLlen.
  - apply Forall_replace_Znth; [exact (mtwp_cells Hwf)|].
    destruct (lit_sig_values l) as [H|H]; rewrite H;
      [right; right; reflexivity|left; reflexivity].
  - rewrite HlenT. lia.
  - rewrite HlenT. exact Hnbound.
  - exact Hlits'.
  - exact Hnd'.
  - apply Forall_app. split.
    + rewrite Forall_forall. intros k Hk.
      rewrite (Znth_replace_Znth_Diff 0 (mt_assigns t) (lit_var_c l) (lit_var_c k)
                 (lit_sig l) HvA (HkA k Hk) (Hkne k Hk)).
      rewrite Forall_forall in HTtrue. auto.
    + constructor; [|constructor].
      apply Znth_replace_Znth_Same. exact HvA.
  - exact Hsorted.
  - rewrite HlenT. exact Hrange.
  - intros i Hi. rewrite HlenT in Hi.
    unfold trail_var, level_of_index. cbn [mt_trail mt_lim].
    destruct (Z.eq_dec i (Zlength (mt_trail t))) as [->|Hne].
    + rewrite app_Znth2 by lia.
      replace (Zlength (mt_trail t) - Zlength (mt_trail t)) with 0 by lia.
      rewrite Znth0_cons.
      rewrite Znth_replace_Znth_Same by exact HvL.
      symmetry. exact Hcountnew.
    + rewrite app_Znth1 by lia.
      assert (Hk : In (Znth i (mt_trail t) 0) (mt_trail t))
        by (apply Znth_In; lia).
      rewrite (Znth_replace_Znth_Diff 0 (mt_levels t) (lit_var_c l)
                 (lit_var_c (Znth i (mt_trail t) 0)) (Zlength lim')
                 HvL (HkL _ Hk) (Hkne _ Hk)).
      rewrite Hcount by lia.
      assert (Hi' : 0 <= i < Zlength (mt_trail t)) by lia.
      exact (mtwp_levels_agree Hwf i Hi').
  - intros w Hw. rewrite Hmapapp.
    destruct (Z.eq_dec w (lit_var_c l)) as [->|Hne].
    + rewrite Znth_replace_Znth_Same by exact HvA.
      split.
      * intros _. apply in_or_app. right. left. reflexivity.
      * intros _. apply lit_sig_nonzero.
    + assert (HwA : 0 <= w < Zlength (mt_assigns t)) by (rewrite HAlen; exact Hw).
      rewrite (Znth_replace_Znth_Diff 0 (mt_assigns t) (lit_var_c l) w
                 (lit_sig l) HvA HwA (fun H => Hne (eq_sym H))).
      rewrite (mtwp_assigned_iff Hwf w Hw).
      split.
      * intro Hin. apply in_or_app. left. exact Hin.
      * intro Hin. apply in_app_or in Hin.
        destruct Hin as [Hin|[Hin|[]]]; [exact Hin|].
        exfalso. apply Hne. symmetry. exact Hin.
Qed.

Lemma mtrail_wf_enqueue : forall n t l,
  mtrail_wf n t -> lit_wf_c n l ->
  Znth (lit_var_c l) (mt_assigns t) 0 = 0 ->
  mtrail_wf n (mt_enqueue t l).
Proof.
  intros n t l Hwf Hlwf Hz. unfold mt_enqueue.
  apply (mtrail_wf_pushed_of_wf n t) in Hwf.
  apply mtrail_wf_push; try assumption.
  - exact (mtwp_lim_sorted Hwf).
  - revert Hwf. clear. intro Hwf.
    pose proof (mtwp_lim_range Hwf) as HF. revert HF. apply Forall_impl.
    intros b Hb. lia.
  - intros i Hi. reflexivity.
  - apply count_le_all.
    pose proof (mtwp_lim_range Hwf) as HF. revert HF. apply Forall_impl.
    intros b Hb. lia.
Qed.

(** The [assume] transient itself: after [veci_push(&s->trail_lim,s->qtail)]
    the state is [mt_push_lim t] and satisfies the relaxed shape. *)
Lemma mtrail_wf_pushed_lim : forall n t,
  mtrail_wf n t -> mtrail_wf_pushed n (mt_push_lim t).
Proof.
  intros n t Hwf.
  pose proof (mtw_lim_range Hwf) as HF.
  pose proof (Zlength_nonneg (mt_trail t)) as HT0.
  unfold mt_push_lim.
  constructor; cbn [mt_assigns mt_levels mt_trail mt_lim mt_qhead].
  - exact (mtw_n_nonneg Hwf).
  - exact (mtw_assigns_len Hwf).
  - exact (mtw_levels_len Hwf).
  - exact (mtw_cells Hwf).
  - exact (mtw_qhead_range Hwf).
  - exact (mtw_trail_bound Hwf).
  - exact (mtw_trail_lits Hwf).
  - exact (mtw_trail_nodup Hwf).
  - exact (mtw_trail_true Hwf).
  - apply strict_sorted_snoc; [exact (mtw_lim_sorted Hwf)|].
    revert HF. apply Forall_impl. intros b Hb. lia.
  - apply Forall_app. split.
    + revert HF. apply Forall_impl. intros b Hb. lia.
    + constructor; [lia|constructor].
  - intros i Hi. unfold trail_var, level_of_index. cbn [mt_trail mt_lim].
    rewrite count_le_app. simpl.
    assert (Hb : (Zlength (mt_trail t) <=? i) = false) by (apply Z.leb_gt; lia).
    rewrite Hb.
    pose proof (mtw_levels_agree Hwf i Hi) as He.
    unfold trail_var, level_of_index in He. lia.
  - exact (mtw_assigned_iff Hwf).
Qed.

(** ... and the [enqueue] that closes it restores [mtrail_wf].  This is
    [mtrail_wf_decide] refactored through the transient, so the annotation can
    stop at the intermediate program point. *)
Lemma mtrail_wf_pushed_lim_enqueue : forall n t l,
  mtrail_wf_pushed n t -> lit_wf_c n l ->
  Znth (lit_var_c l) (mt_assigns t) 0 = 0 ->
  mtrail_wf n (mt_enqueue t l).
Proof.
  intros n t l Hwf Hlwf Hz. unfold mt_enqueue.
  apply mtrail_wf_push; try assumption.
  - exact (mtwp_lim_sorted Hwf).
  - pose proof (mtwp_lim_range Hwf) as HF. revert HF. apply Forall_impl.
    intros b Hb. lia.
  - intros i Hi. reflexivity.
  - apply count_le_all.
    pose proof (mtwp_lim_range Hwf) as HF. revert HF. apply Forall_impl.
    intros b Hb. lia.
Qed.

(** The fused step really is the two-step composition. *)
Lemma mtrail_wf_decide_via_transient : forall n t l,
  mtrail_wf n t -> lit_wf_c n l ->
  Znth (lit_var_c l) (mt_assigns t) 0 = 0 ->
  mtrail_wf n (mt_enqueue (mt_push_lim t) l).
Proof.
  intros n t l Hwf Hlwf Hz.
  apply mtrail_wf_pushed_lim_enqueue; [apply mtrail_wf_pushed_lim; exact Hwf | exact Hlwf |].
  cbn [mt_assigns mt_push_lim]. exact Hz.
Qed.

Lemma mtrail_wf_decide : forall n t l,
  mtrail_wf n t -> lit_wf_c n l ->
  Znth (lit_var_c l) (mt_assigns t) 0 = 0 ->
  mtrail_wf n (mt_decide t l).
Proof.
  intros n t l Hwf Hlwf Hz. rewrite mt_decide_push_lim.
  apply mtrail_wf_decide_via_transient; assumption.
Qed.

Lemma mtrail_wf_cancel : forall n t level,
  mtrail_wf n t -> 0 <= level < Zlength (mt_lim t) ->
  mtrail_wf n (mt_cancel t level).
Proof.
  intros n t level Hwf Hlevel.
  pose proof (lim_lt_trail n t level Hwf Hlevel) as Hb.
  unfold mt_cancel.
  set (bound := Znth level (mt_lim t) 0) in *.
  pose proof (mtw_assigns_len Hwf) as HAlen.
  pose proof (mtw_trail_lits Hwf) as HTlits.
  pose proof (mtw_trail_nodup Hwf) as HTnd.
  pose proof (mtw_trail_true Hwf) as HTtrue.
  assert (HmapS : map lit_var_c (mt_trail t)
                  = map lit_var_c (ztake bound (mt_trail t))
                    ++ map lit_var_c (zdrop bound (mt_trail t)))
    by apply map_ztake_zdrop.
  assert (HndS : NoDup (map lit_var_c (ztake bound (mt_trail t))
                        ++ map lit_var_c (zdrop bound (mt_trail t))))
    by (rewrite <- HmapS; exact HTnd).
  assert (Hlen : Zlength (ztake bound (mt_trail t)) = bound)
    by (apply Zlength_ztake; lia).
  assert (Hdroprange : forall x, In x (zdrop bound (mt_trail t)) ->
                         0 <= lit_var_c x < Zlength (mt_assigns t)).
  { intros x Hx. rewrite HAlen. apply (lit_var_c_in_range n).
    rewrite Forall_forall in HTlits. apply HTlits. eapply In_zdrop; eauto. }
  assert (Hkeep : forall k, In k (ztake bound (mt_trail t)) ->
                    Znth (lit_var_c k)
                      (clear_vars (zdrop bound (mt_trail t)) (mt_assigns t)) 0
                    = Znth (lit_var_c k) (mt_assigns t) 0).
  { intros k Hk. apply clear_vars_notin.
    - rewrite HAlen. apply (lit_var_c_in_range n).
      rewrite Forall_forall in HTlits. apply HTlits. eapply In_ztake; eauto.
    - exact Hdroprange.
    - eapply NoDup_app_disjoint; [exact HndS|apply in_map; exact Hk]. }
  constructor; cbn [mt_assigns mt_levels mt_trail mt_lim mt_qhead].
  - exact (mtw_n_nonneg Hwf).
  - rewrite Zlength_clear_vars. exact HAlen.
  - exact (mtw_levels_len Hwf).
  - apply clear_vars_cells. exact (mtw_cells Hwf).
  - rewrite Hlen. lia.
  - rewrite Hlen. pose proof (mtw_trail_bound Hwf). lia.
  - apply Forall_ztake. exact HTlits.
  - eapply NoDup_app_remove_r. exact HndS.
  - rewrite Forall_forall. intros k Hk.
    rewrite (Hkeep k Hk).
    rewrite Forall_forall in HTtrue. apply HTtrue. eapply In_ztake; eauto.
  - apply strict_sorted_ztake. exact (mtw_lim_sorted Hwf).
  - rewrite Hlen, Forall_forall. intros b Hb'.
    destruct (In_Znth_index _ _ Hb') as [j [Hj Hjval]].
    assert (Hjlen : Zlength (ztake level (mt_lim t)) = level)
      by (apply Zlength_ztake; lia).
    rewrite Hjlen in Hj.
    rewrite Znth_ztake in Hjval by lia.
    assert (Hjr : 0 <= j < Zlength (mt_lim t)) by lia.
    pose proof (Forall_Znth_elim _ _ _ 0 j (mtw_lim_range Hwf) Hjr) as Hjrange.
    cbv beta in Hjrange.
    split.
    + rewrite <- Hjval. lia.
    + rewrite <- Hjval. unfold bound.
      apply strict_sorted_Znth; [exact (mtw_lim_sorted Hwf)|lia|lia|lia].
  - intros i Hi. rewrite Hlen in Hi.
    unfold trail_var, level_of_index; cbn [mt_trail mt_lim].
    rewrite Znth_ztake by lia.
    assert (Hile : count_le i (mt_lim t) <= level).
    { destruct (Z_le_gt_dec (count_le i (mt_lim t)) level) as [H|H]; [exact H|].
      exfalso.
      assert (Hp : 0 <= level < count_le i (mt_lim t)) by lia.
      pose proof (strict_sorted_count_prefix (mt_lim t) i level
                    (mtw_lim_sorted Hwf) Hp) as Hcp.
      unfold bound in Hi. lia. }
    (* Side goals in the lemma's own hypothesis order: sortedness, the
       non-negativity of the cut, and the count bound just established. *)
    rewrite count_le_ztake;
      [ | exact (mtw_lim_sorted Hwf) | lia | exact Hile ].
    assert (Hi' : 0 <= i < Zlength (mt_trail t)) by lia.
    exact (mtw_levels_agree Hwf i Hi').
  - intros w Hw.
    assert (HwA : 0 <= w < Zlength (mt_assigns t)) by (rewrite HAlen; exact Hw).
    split.
    + intro Hne.
      assert (Hnotdrop : ~ In w (map lit_var_c (zdrop bound (mt_trail t)))).
      { intro Hin. apply Hne. apply clear_vars_in; assumption. }
      rewrite clear_vars_notin in Hne by assumption.
      destruct (mtw_assigned_iff Hwf w Hw) as [Hfwd _].
      specialize (Hfwd Hne). rewrite HmapS in Hfwd.
      apply in_app_or in Hfwd. destruct Hfwd as [H|H]; [exact H|contradiction].
    + intro Hin.
      assert (Hnotdrop : ~ In w (map lit_var_c (zdrop bound (mt_trail t))))
        by (eapply NoDup_app_disjoint; [exact HndS|exact Hin]).
      rewrite clear_vars_notin by assumption.
      destruct (mtw_assigned_iff Hwf w Hw) as [_ Hbwd].
      apply Hbwd. rewrite HmapS. apply in_or_app. left. exact Hin.
Qed.

(** ----- [prop_level] (INV-PROP-LEVEL) preservation ----- *)

(** [enqueue] grows [qtail] and touches neither [qhead] nor
    [trail_lim]. *)
Lemma prop_level_enqueue : forall t l, prop_level t -> prop_level (mt_enqueue t l).
Proof. intros t l H. exact H. Qed.

(** [s->qhead++] -- and, more generally, any forward move of the
    frontier. *)
Lemma prop_level_qhead_advance : forall t q,
  prop_level t -> mt_qhead t <= q -> prop_level (mt_set_qhead t q).
Proof.
  intros t q H Hq. unfold prop_level, mt_set_qhead in *.
  cbn [mt_lim mt_qhead]. revert H. apply Forall_impl. intros b Hb. lia.
Qed.

(** Rolling the cursor onto a literal at the current level preserves the
    propagation-level boundary: its trail rank is exactly the new cursor, so
    every decision boundary is already at or below that cursor. *)
Lemma prop_level_rollback_current : forall n t reasons db p,
  mtrail_wf n t ->
  0 < mt_qhead t ->
  p = Znth (mt_qhead t - 1) (mt_trail t) 0 ->
  level_of (view_of n t reasons db) (lit_var_c p) =
    Some (Zlength (mt_lim t)) ->
  prop_level (mt_set_qhead t (mt_qhead t - 1)).
Proof.
  intros n t reasons db p Hwf Hq Hp Hlevel.
  assert (Hidx : 0 <= mt_qhead t - 1 < Zlength (mt_trail t)).
  { pose proof (mtw_qhead_range Hwf). lia. }
  pose proof
    (trail_pos_of_index t (mt_qhead t - 1) (mtw_trail_nodup Hwf) Hidx)
    as Hpos.
  assert (Hvar : trail_var t (mt_qhead t - 1) = lit_var_c p).
  { unfold trail_var. rewrite <- Hp. reflexivity. }
  rewrite Hvar in Hpos.
  unfold view_of in Hlevel. cbn [level_of] in Hlevel.
  rewrite Hpos in Hlevel. simpl in Hlevel. inversion Hlevel as [Heq].
  unfold level_of_index in Heq.
  rewrite Z2Nat.id in Heq by lia.
  unfold prop_level, mt_set_qhead. cbn [mt_lim mt_qhead].
  apply count_le_all_inv. exact Heq.
Qed.

(** [assume]'s [veci_push(&s->trail_lim,s->qtail)]: legal exactly
    because the caller has asserted [qtail == qhead]. *)
Lemma prop_level_push_lim : forall t,
  prop_level t -> mt_qhead t = Zlength (mt_trail t) ->
  prop_level (mt_push_lim t).
Proof.
  intros t H Hq. unfold prop_level, mt_push_lim in *.
  cbn [mt_lim mt_qhead]. apply Forall_app. split; [exact H|].
  constructor; [lia|constructor].
Qed.

Lemma prop_level_decide : forall t l,
  prop_level t -> mt_qhead t = Zlength (mt_trail t) ->
  prop_level (mt_decide t l).
Proof.
  intros t l H Hq. rewrite mt_decide_push_lim.
  apply prop_level_enqueue. apply prop_level_push_lim; assumption.
Qed.

(** [solver_canceluntil] sets [qhead = qtail = trail_lim[level]] and
    truncates [trail_lim] to its first [level] entries, all of which are
    strictly below that bound -- so cancel *establishes* INV-PROP-LEVEL
    outright, no hypothesis on the pre-state needed. *)
Lemma prop_level_cancel : forall n t level,
  mtrail_wf n t -> 0 <= level < Zlength (mt_lim t) ->
  prop_level (mt_cancel t level).
Proof.
  intros n t level Hwf Hlev.
  unfold prop_level, mt_cancel. cbn [mt_lim mt_qhead].
  rewrite Forall_forall. intros b Hb.
  apply In_Znth_index in Hb. destruct Hb as [k [Hk Hval]].
  assert (Hklen : Zlength (ztake level (mt_lim t)) = level)
    by (apply Zlength_ztake; lia).
  rewrite Hklen in Hk.
  rewrite Znth_ztake in Hval by lia.
  rewrite <- Hval.
  pose proof (strict_sorted_Znth (mt_lim t) k level (mtw_lim_sorted Hwf)
                (proj1 Hk) (proj2 Hk) (proj2 Hlev)). lia.
Qed.

(** ===== E. the memory-to-view bridges for enqueue / assume ===== *)

Lemma trail_pos_push_new : forall n t l lim',
  mtrail_wf n t -> lit_wf_c n l ->
  Znth (lit_var_c l) (mt_assigns t) 0 = 0 ->
  trail_pos (mt_push t l lim') (lit_var_c l) = Some (List.length (mt_trail t)).
Proof.
  intros n t l lim' Hwf Hlwf Hz.
  unfold trail_pos, mt_push; cbn [mt_trail].
  rewrite find_var_pos_app.
  assert (Hnone : find_var_pos (lit_var_c l) (mt_trail t) = None).
  { apply find_var_pos_none_iff. intro Hin.
    destruct (mtw_assigned_iff Hwf (lit_var_c l) (lit_var_c_in_range n l Hlwf))
      as [_ Hbwd].
    apply Hbwd in Hin. contradiction. }
  rewrite Hnone. simpl.
  rewrite Z.eqb_refl. simpl. f_equal. lia.
Qed.

Lemma trail_pos_push_other : forall t l lim' y,
  y <> lit_var_c l -> trail_pos (mt_push t l lim') y = trail_pos t y.
Proof.
  intros t l lim' y Hy. unfold trail_pos, mt_push; cbn [mt_trail].
  rewrite find_var_pos_app.
  destruct (find_var_pos y (mt_trail t)) as [k|]; [reflexivity|].
  simpl.
  assert (Hb : (lit_var_c l =? y) = false)
    by (apply Z.eqb_neq; intro H; apply Hy; symmetry; exact H).
  rewrite Hb. reflexivity.
Qed.

Lemma view_of_push_assignment : forall n t r db l lim',
  mtrail_wf n t -> lit_wf_c n l ->
  assignment (view_of n (mt_push t l lim') r db)
  = sat_function_update (assignment (view_of n t r db))
      (lit_var_c l) (Some (lit_pol l)).
Proof.
  intros n t r db l lim' Hwf Hlwf.
  pose proof (lit_var_c_in_range n l Hlwf) as Hv.
  pose proof (mtw_assigns_len Hwf) as HAlen.
  apply functional_extensionality. intro y.
  cbn [view_of assignment].
  destruct (Z_lt_le_dec y 0) as [Hyneg|Hy0].
  { rewrite sat_function_update_neq by lia.
    rewrite !mt_pv_neg by lia. reflexivity. }
  destruct (Z.eq_dec y (lit_var_c l)) as [->|Hne].
  - rewrite sat_function_update_eq.
    rewrite mt_pv_nonneg by lia.
    unfold mt_push; cbn [mt_assigns].
    rewrite Znth_replace_Znth_Same by (rewrite HAlen; exact Hv).
    apply lbool_val_lit_sig.
  - rewrite sat_function_update_neq by (intro H; apply Hne; symmetry; exact H).
    rewrite !mt_pv_nonneg by lia.
    unfold mt_push; cbn [mt_assigns].
    destruct (Z_lt_le_dec y (Zlength (mt_assigns t))) as [Hyl|Hyl].
    + rewrite (Znth_replace_Znth_Diff 0 (mt_assigns t) (lit_var_c l) y
                 (lit_sig l) (ltac:(rewrite HAlen; exact Hv)) (conj Hy0 Hyl)
                 (fun H => Hne (eq_sym H))).
      reflexivity.
    + assert (E1 : Znth y (replace_Znth (lit_var_c l) (lit_sig l) (mt_assigns t)) 0 = 0)
        by (apply znth_out_of_bounds; [lia|rewrite Zlength_replace_Znth; lia]).
      assert (E2 : Znth y (mt_assigns t) 0 = 0)
        by (apply znth_out_of_bounds; lia).
      rewrite E1, E2. reflexivity.
Qed.

Lemma view_of_push_level : forall n t r db l lim',
  mtrail_wf n t -> lit_wf_c n l ->
  Znth (lit_var_c l) (mt_assigns t) 0 = 0 ->
  (forall i, 0 <= i < Zlength (mt_trail t) -> count_le i lim' = count_le i (mt_lim t)) ->
  count_le (Zlength (mt_trail t)) lim' = Zlength lim' ->
  level_of (view_of n (mt_push t l lim') r db)
  = sat_function_update (level_of (view_of n t r db)) (lit_var_c l)
      (Some (Zlength lim')).
Proof.
  intros n t r db l lim' Hwf Hlwf Hz Hcount Hcountnew.
  apply functional_extensionality. intro y.
  cbn [view_of level_of].
  destruct (Z.eq_dec y (lit_var_c l)) as [->|Hne].
  - rewrite sat_function_update_eq.
    rewrite (trail_pos_push_new n t l lim' Hwf Hlwf Hz).
    cbn [option_map]. unfold level_of_index, mt_push; cbn [mt_lim].
    rewrite <- Zlength_correct, Hcountnew. reflexivity.
  - rewrite sat_function_update_neq by (intro H; apply Hne; symmetry; exact H).
    rewrite (trail_pos_push_other t l lim' y Hne).
    destruct (trail_pos t y) as [k|] eqn:Hk; [|reflexivity].
    cbn [option_map]. unfold level_of_index, mt_push; cbn [mt_lim].
    f_equal. apply Hcount.
    pose proof (trail_pos_bound t y k Hk). lia.
Qed.

Lemma view_of_push_reason : forall n t r r' db l lim' rc,
  mtrail_wf n t -> lit_wf_c n l ->
  Znth (lit_var_c l) (mt_assigns t) 0 = 0 ->
  (forall y, y <> lit_var_c l -> r' y = r y) ->
  r' (lit_var_c l) = rc ->
  reason_of (view_of n (mt_push t l lim') r' db)
  = sat_function_update (reason_of (view_of n t r db)) (lit_var_c l) rc.
Proof.
  intros n t r r' db l lim' rc Hwf Hlwf Hz Hagree Hnew.
  apply functional_extensionality. intro y.
  cbn [view_of reason_of].
  destruct (Z.eq_dec y (lit_var_c l)) as [->|Hne].
  - rewrite sat_function_update_eq.
    rewrite (trail_pos_push_new n t l lim' Hwf Hlwf Hz). exact Hnew.
  - rewrite sat_function_update_neq by (intro H; apply Hne; symmetry; exact H).
    rewrite (trail_pos_push_other t l lim' y Hne).
    destruct (trail_pos t y) as [k|]; [apply Hagree; exact Hne|reflexivity].
Qed.

Lemma count_le_enqueue_new : forall n t,
  mtrail_wf n t -> count_le (Zlength (mt_trail t)) (mt_lim t) = Zlength (mt_lim t).
Proof.
  intros n t Hwf. apply count_le_all.
  pose proof (mtw_lim_range Hwf) as HF. revert HF. apply Forall_impl.
  intros b Hb. lia.
Qed.

Lemma count_le_decide_old : forall n t i,
  mtrail_wf n t -> 0 <= i < Zlength (mt_trail t) ->
  count_le i (mt_lim t ++ [Zlength (mt_trail t)]) = count_le i (mt_lim t).
Proof.
  intros n t i Hwf Hi. rewrite count_le_app. simpl.
  assert (Hb : (Zlength (mt_trail t) <=? i) = false) by (apply Z.leb_gt; lia).
  rewrite Hb. lia.
Qed.

Lemma count_le_decide_new : forall n t,
  mtrail_wf n t ->
  count_le (Zlength (mt_trail t)) (mt_lim t ++ [Zlength (mt_trail t)])
  = Zlength (mt_lim t ++ [Zlength (mt_trail t)]).
Proof.
  intros n t Hwf. rewrite count_le_app. simpl.
  assert (Hb : (Zlength (mt_trail t) <=? Zlength (mt_trail t)) = true)
    by (apply Z.leb_le; lia).
  rewrite Hb, Zlength_app, Zlength_cons, Zlength_nil.
  rewrite (count_le_enqueue_new n t Hwf). lia.
Qed.

(** The enqueue bridge, in the relational form S3's contracts consume. *)
Lemma view_of_assign : forall n t r r' db l rc,
  mtrail_wf n t -> lit_wf_c n l ->
  Znth (lit_var_c l) (mt_assigns t) 0 = 0 ->
  (forall y, y <> lit_var_c l -> r' y = r y) ->
  r' (lit_var_c l) = rc ->
  (forall c k, rc = Some c -> In k c -> literal_wf n k) ->
  assigns_one (view_of n t r db) (view_of n (mt_enqueue t l) r' db)
              (lit_var_c l) (lit_pol l) (Zlength (mt_lim t)) rc.
Proof.
  intros n t r r' db l rc Hwf Hlwf Hz Hagree Hnew Hrcwf.
  pose proof (lit_var_c_in_range n l Hlwf) as Hv.
  assert (HA : assignment (view_of n (mt_enqueue t l) r' db)
               = sat_function_update (assignment (view_of n t r db))
                   (lit_var_c l) (Some (lit_pol l)))
    by exact (view_of_push_assignment n t r db l (mt_lim t) Hwf Hlwf).
  assert (HL : level_of (view_of n (mt_enqueue t l) r' db)
               = sat_function_update (level_of (view_of n t r db))
                   (lit_var_c l) (Some (Zlength (mt_lim t))))
    by exact (view_of_push_level n t r db l (mt_lim t) Hwf Hlwf Hz
                (fun i _ => eq_refl) (count_le_enqueue_new n t Hwf)).
  assert (HR : reason_of (view_of n (mt_enqueue t l) r' db)
               = sat_function_update (reason_of (view_of n t r db))
                   (lit_var_c l) rc)
    by exact (view_of_push_reason n t r r' db l (mt_lim t) rc Hwf Hlwf Hz
                Hagree Hnew).
  unfold assigns_one.
  split. { cbn [view_of assignment]. apply mt_pv_zero_cell; [lia|exact Hz]. }
  split. { rewrite HA. apply sat_function_update_eq. }
  split. { rewrite HL. apply sat_function_update_eq. }
  split. { rewrite HR. apply sat_function_update_eq. }
  split.
  { exists (List.length (mt_trail t)).
    split.
    { cbn [view_of assignment_rank].
      apply (trail_pos_push_new n t l (mt_lim t) Hwf Hlwf Hz). }
    intros y [cc [ly [Hreason [Hin [Hvar [Hyx Heval]]]]]].
    rewrite HR, sat_function_update_eq in Hreason.
    assert (Hlywf : literal_wf n ly) by (apply (Hrcwf cc ly Hreason Hin)).
    destruct (eval_partial_literal_assigned _ _ _ Heval) as [b Hb].
    rewrite Hvar in Hb.
    rewrite HA, sat_function_update_neq in Hb
      by (intro H; apply Hyx; symmetry; exact H).
    cbn [view_of assignment] in Hb.
    destruct (trail_pos t y) as [k|] eqn:Hk.
    - exists k. split.
      + cbn [view_of assignment_rank]. unfold mt_enqueue.
        rewrite (trail_pos_push_other t l (mt_lim t) y Hyx). exact Hk.
      + apply (find_var_pos_bound y (mt_trail t) k Hk).
    - exfalso.
      assert (Hpv : mt_pv t y = None)
        by (apply (proj2 (view_unassigned_iff n t y Hwf)); exact Hk).
      rewrite Hpv in Hb. discriminate. }
  split.
  { intros y Hyx. repeat split.
    - rewrite HA. apply sat_function_update_neq.
      intro H; apply Hyx; symmetry; exact H.
    - rewrite HL. apply sat_function_update_neq.
      intro H; apply Hyx; symmetry; exact H.
    - rewrite HR. apply sat_function_update_neq.
      intro H; apply Hyx; symmetry; exact H.
    - cbn [view_of assignment_rank]. unfold mt_enqueue.
      apply trail_pos_push_other. exact Hyx. }
  reflexivity.
Qed.

(** The [assume] bridge: same shape, one level higher, no reason. *)
Lemma view_of_decide_assign : forall n t r r' db l,
  mtrail_wf n t -> lit_wf_c n l ->
  Znth (lit_var_c l) (mt_assigns t) 0 = 0 ->
  (forall y, y <> lit_var_c l -> r' y = r y) ->
  r' (lit_var_c l) = None ->
  assigns_one (view_of n t r db) (view_of n (mt_decide t l) r' db)
              (lit_var_c l) (lit_pol l) (Zlength (mt_lim t) + 1) None.
Proof.
  intros n t r r' db l Hwf Hlwf Hz Hagree Hnew.
  pose proof (lit_var_c_in_range n l Hlwf) as Hv.
  set (lim' := mt_lim t ++ [Zlength (mt_trail t)]) in *.
  assert (Hlim' : Zlength lim' = Zlength (mt_lim t) + 1)
    by (unfold lim'; rewrite Zlength_app, Zlength_cons, Zlength_nil; lia).
  assert (HA : assignment (view_of n (mt_decide t l) r' db)
               = sat_function_update (assignment (view_of n t r db))
                   (lit_var_c l) (Some (lit_pol l)))
    by exact (view_of_push_assignment n t r db l lim' Hwf Hlwf).
  assert (HL : level_of (view_of n (mt_decide t l) r' db)
               = sat_function_update (level_of (view_of n t r db))
                   (lit_var_c l) (Some (Zlength (mt_lim t) + 1))).
  { rewrite <- Hlim'.
    exact (view_of_push_level n t r db l lim' Hwf Hlwf Hz
             (fun i Hi => count_le_decide_old n t i Hwf Hi)
             (count_le_decide_new n t Hwf)). }
  assert (HR : reason_of (view_of n (mt_decide t l) r' db)
               = sat_function_update (reason_of (view_of n t r db))
                   (lit_var_c l) None)
    by exact (view_of_push_reason n t r r' db l lim' None Hwf Hlwf Hz
                Hagree Hnew).
  unfold assigns_one.
  split. { cbn [view_of assignment]. apply mt_pv_zero_cell; [lia|exact Hz]. }
  split. { rewrite HA. apply sat_function_update_eq. }
  split. { rewrite HL. apply sat_function_update_eq. }
  split. { rewrite HR. apply sat_function_update_eq. }
  split.
  { exists (List.length (mt_trail t)).
    split.
    { cbn [view_of assignment_rank].
      apply (trail_pos_push_new n t l lim' Hwf Hlwf Hz). }
    intros y [cc [ly [Hreason [Hin [Hvar [Hyx Heval]]]]]].
    rewrite HR, sat_function_update_eq in Hreason. discriminate. }
  split.
  { intros y Hyx. repeat split.
    - rewrite HA. apply sat_function_update_neq.
      intro H; apply Hyx; symmetry; exact H.
    - rewrite HL. apply sat_function_update_neq.
      intro H; apply Hyx; symmetry; exact H.
    - rewrite HR. apply sat_function_update_neq.
      intro H; apply Hyx; symmetry; exact H.
    - cbn [view_of assignment_rank]. unfold mt_decide.
      apply trail_pos_push_other. exact Hyx. }
  reflexivity.
Qed.

Lemma mt_cancel_lim : forall t level,
  mt_lim (mt_cancel t level) = ztake level (mt_lim t).
Proof. reflexivity. Qed.

Lemma mt_cancel_qhead : forall t level,
  mt_qhead (mt_cancel t level) = Znth level (mt_lim t) 0.
Proof. reflexivity. Qed.

Lemma trail_pos_cancel : forall n t level v,
  mtrail_wf n t -> 0 <= level < Zlength (mt_lim t) ->
  trail_pos (mt_cancel t level) v
  = match trail_pos t v with
    | Some k => if Z.of_nat k <? Znth level (mt_lim t) 0 then Some k else None
    | None => None
    end.
Proof.
  intros n t level v Hwf Hlevel.
  pose proof (lim_lt_trail n t level Hwf Hlevel) as Hb.
  unfold trail_pos. rewrite mt_cancel_trail.
  destruct (find_var_pos v (mt_trail t)) as [k|] eqn:Hk.
  - destruct (Z.of_nat k <? Znth level (mt_lim t) 0) eqn:Hlt.
    + apply Z.ltb_lt in Hlt.
      apply find_var_pos_ztake_lt; [exact Hk|lia].
    + apply Z.ltb_ge in Hlt.
      apply (find_var_pos_ztake_none v (mt_trail t) k);
        [exact (mtw_trail_nodup Hwf)|exact Hk|lia].
  - destruct (find_var_pos v (ztake (Znth level (mt_lim t) 0) (mt_trail t)))
      as [j|] eqn:Hj; [|reflexivity].
    exfalso.
    destruct (find_var_pos_ztake_inv v (mt_trail t) _ _ Hj) as [k' Hk'].
    rewrite Hk' in Hk. discriminate.
Qed.

Lemma mt_pv_cancel_drop : forall n t level v,
  mtrail_wf n t -> 0 <= level < Zlength (mt_lim t) ->
  trail_pos (mt_cancel t level) v = None ->
  mt_pv (mt_cancel t level) v = None.
Proof.
  intros n t level v Hwf Hlevel H.
  apply (proj2 (view_unassigned_iff n (mt_cancel t level) v
                  (mtrail_wf_cancel n t level Hwf Hlevel))).
  exact H.
Qed.

(** [solver_canceluntil] realises S3's [restrict_above_level]: the levels at or
    below [level] survive untouched, everything above is unassigned.  Note the
    [levels] array is NOT cleaned -- the view reads levels only through
    [trail_pos], so the stale cells are invisible. *)
Lemma view_of_cancel : forall n t r db level,
  mtrail_wf n t -> 0 <= level < Zlength (mt_lim t) ->
  restrict_above_level (view_of n t r db) (view_of n (mt_cancel t level) r db) level.
Proof.
  intros n t r db level Hwf Hlevel.
  pose proof (lim_lt_trail n t level Hwf Hlevel) as Hb.
  pose proof (mtw_lim_sorted Hwf) as Hsorted.
  unfold restrict_above_level.
  split.
  { cbn [view_of current_level]. rewrite mt_cancel_lim.
    apply Zlength_ztake. lia. }
  split; [reflexivity|].
  intro x.
  pose proof (trail_pos_cancel n t level x Hwf Hlevel) as Hnewpos.
  destruct (trail_pos t x) as [k|] eqn:Hk.
  - assert (Hlo : level_of (view_of n t r db) x
                  = Some (level_of_index t (Z.of_nat k)))
      by (cbn [view_of level_of]; rewrite Hk; reflexivity).
    rewrite Hlo. cbv beta iota.
    destruct (level_of_index t (Z.of_nat k) <=? level) eqn:Hle.
    + apply Z.leb_le in Hle.
      assert (Hkb : Z.of_nat k < Znth level (mt_lim t) 0).
      { apply (strict_sorted_count_suffix (mt_lim t) (Z.of_nat k) level Hsorted);
          [exact Hle|lia]. }
      assert (Hb' : (Z.of_nat k <? Znth level (mt_lim t) 0) = true)
        by (apply Z.ltb_lt; exact Hkb).
      rewrite Hb' in Hnewpos.
      repeat split.
      * cbn [view_of assignment].
        apply (mt_pv_cancel_keep n t level x Hwf Hlevel).
        eapply find_var_pos_some_in. exact Hnewpos.
      * cbn [view_of level_of]. rewrite Hnewpos. cbn [option_map]. f_equal.
        unfold level_of_index. rewrite mt_cancel_lim.
        apply count_le_ztake; [exact Hsorted|lia|exact Hle].
      * cbn [view_of reason_of]. rewrite Hnewpos, Hk. reflexivity.
      * cbn [view_of assignment_rank]. rewrite Hnewpos, Hk. reflexivity.
    + apply Z.leb_gt in Hle.
      assert (Hkb : Znth level (mt_lim t) 0 <= Z.of_nat k).
      { destruct (Z_le_gt_dec (Znth level (mt_lim t) 0) (Z.of_nat k)) as [H|H];
          [exact H|exfalso].
        assert (Hcp : count_le (Z.of_nat k) (mt_lim t) <= level).
        { destruct (Z_le_gt_dec (count_le (Z.of_nat k) (mt_lim t)) level)
            as [H2|H2]; [exact H2|exfalso].
          assert (Hp : 0 <= level < count_le (Z.of_nat k) (mt_lim t)) by lia.
          pose proof (strict_sorted_count_prefix (mt_lim t) (Z.of_nat k) level
                        Hsorted Hp) as Hpp. lia. }
        unfold level_of_index in Hle. lia. }
      assert (Hb' : (Z.of_nat k <? Znth level (mt_lim t) 0) = false)
        by (apply Z.ltb_ge; exact Hkb).
      rewrite Hb' in Hnewpos.
      repeat split.
      * cbn [view_of assignment].
        apply (mt_pv_cancel_drop n t level x Hwf Hlevel Hnewpos).
      * cbn [view_of level_of]. rewrite Hnewpos. reflexivity.
      * cbn [view_of reason_of]. rewrite Hnewpos. reflexivity.
      * cbn [view_of assignment_rank]. exact Hnewpos.
  - assert (Hlo : level_of (view_of n t r db) x = None)
      by (cbn [view_of level_of]; rewrite Hk; reflexivity).
    rewrite Hlo. cbv beta iota.
    repeat split.
    + cbn [view_of assignment].
      apply (mt_pv_cancel_drop n t level x Hwf Hlevel Hnewpos).
    + cbn [view_of level_of]. rewrite Hnewpos. reflexivity.
    + cbn [view_of reason_of]. rewrite Hnewpos. reflexivity.
    + cbn [view_of assignment_rank]. exact Hnewpos.
Qed.

(** ===== G. TRAIL-IMPLIED ===== *)

Lemma ztake_app_le : forall d l1 l2,
  0 <= d <= Zlength l1 -> ztake d (l1 ++ l2) = ztake d l1.
Proof.
  intros d l1 l2 H. unfold ztake. rewrite firstn_app.
  rewrite Zlength_correct in H.
  replace (Z.to_nat d - List.length l1)%nat with 0%nat by lia.
  simpl. rewrite app_nil_r. reflexivity.
Qed.

Lemma ztake_all : forall d l, Zlength l <= d -> ztake d l = l.
Proof.
  intros d l H. unfold ztake. apply firstn_all2.
  rewrite Zlength_correct in H. lia.
Qed.

Definition decisions_are (t : mtrail) (A : list literal) : Prop :=
  decisions_upto t (Zlength (mt_lim t)) = A.

Lemma decisions_upto_incl : forall t d1 d2,
  0 <= d1 <= d2 -> incl (decisions_upto t d1) (decisions_upto t d2).
Proof.
  intros t d1 d2 H x Hx. unfold decisions_upto in *.
  rewrite <- (ztake_ztake d1 d2 (mt_lim t) H) in Hx.
  apply in_map_iff in Hx. destruct Hx as [b [<- Hb]].
  apply (in_map (fun b0 => lit_denote (Znth b0 (mt_trail t) 0))).
  eapply In_ztake; eauto.
Qed.

Lemma level_of_index_nonneg : forall t i, 0 <= level_of_index t i.
Proof. intros. apply count_le_nonneg. Qed.

Lemma trail_implied_upgrade : forall F t i l d,
  trail_implied F t -> 0 <= i < Zlength (mt_trail t) ->
  Znth i (mt_trail t) 0 = l ->
  level_of_index t i <= d ->
  entails_clause (cnf_with_units F (decisions_upto t d)) [lit_denote l].
Proof.
  intros F t i l d Hti Hi Hl Hd.
  eapply entails_units_mono; [apply decisions_upto_incl|apply (Hti i l Hi Hl)].
  pose proof (level_of_index_nonneg t i). lia.
Qed.

(** ----- maintenance across the three transitions ----- *)

Lemma decisions_upto_enqueue : forall n t l d,
  mtrail_wf n t -> decisions_upto (mt_enqueue t l) d = decisions_upto t d.
Proof.
  intros n t l d Hwf.
  unfold decisions_upto, mt_enqueue, mt_push; cbn [mt_trail mt_lim].
  apply map_ext_in. intros b Hb.
  assert (Hr : 0 <= b < Zlength (mt_trail t)).
  { pose proof (mtw_lim_range Hwf) as HF. rewrite Forall_forall in HF.
    apply HF. eapply In_ztake; eauto. }
  rewrite app_Znth1 by exact Hr. reflexivity.
Qed.

Lemma level_of_index_enqueue : forall t l i,
  level_of_index (mt_enqueue t l) i = level_of_index t i.
Proof. reflexivity. Qed.

Lemma trail_implied_enqueue : forall n F t l,
  mtrail_wf n t ->
  entails_clause (cnf_with_units F (decisions_upto t (Zlength (mt_lim t))))
                 [lit_denote l] ->
  trail_implied F t ->
  trail_implied F (mt_enqueue t l).
Proof.
  intros n F t l Hwf Hent Hti.
  pose proof (Zlength_nonneg (mt_trail t)) as HT0.
  intros i ll Hi Hll.
  unfold mt_enqueue, mt_push in Hi, Hll; cbn [mt_trail] in Hi, Hll.
  rewrite Zlength_app, Zlength_cons, Zlength_nil in Hi.
  rewrite (decisions_upto_enqueue n t l _ Hwf), level_of_index_enqueue.
  destruct (Z.eq_dec i (Zlength (mt_trail t))) as [->|Hne].
  - rewrite app_Znth2 in Hll by lia.
    replace (Zlength (mt_trail t) - Zlength (mt_trail t)) with 0 in Hll by lia.
    rewrite Znth0_cons in Hll. subst ll.
    unfold level_of_index. rewrite (count_le_enqueue_new n t Hwf). exact Hent.
  - rewrite app_Znth1 in Hll by lia.
    apply (Hti i ll); [lia|exact Hll].
Qed.

(** Unit propagation: the reason clause is [F]-entailed and every other literal
    of it is the negation of a literal already on the trail. *)
Lemma trail_implied_unit : forall n F t l rc,
  mtrail_wf n t -> trail_implied F t ->
  entails_clause F rc ->
  In (lit_denote l) rc ->
  (forall k, In k rc -> k <> lit_denote l ->
     exists j, 0 <= j < Zlength (mt_trail t) /\
               lit_denote (Znth j (mt_trail t) 0) = literal_neg k) ->
  trail_implied F (mt_enqueue t l).
Proof.
  intros n F t l rc Hwf Hti Hent Hin Hothers.
  apply (trail_implied_enqueue n F t l Hwf); [|exact Hti].
  eapply entails_unit_step with (c := rc).
  - apply entails_clause_units_weaken. exact Hent.
  - exact Hin.
  - intros k Hk Hne.
    destruct (Hothers k Hk Hne) as [j [Hj Hjval]].
    rewrite <- Hjval.
    eapply trail_implied_upgrade;
      [exact Hti|exact Hj|reflexivity|apply prop_level_processed_level_le].
Qed.

Lemma decisions_upto_decide_low : forall n t l d,
  mtrail_wf n t -> 0 <= d <= Zlength (mt_lim t) ->
  decisions_upto (mt_decide t l) d = decisions_upto t d.
Proof.
  intros n t l d Hwf Hd.
  unfold decisions_upto, mt_decide, mt_push; cbn [mt_trail mt_lim].
  rewrite ztake_app_le by lia.
  apply map_ext_in. intros b Hb.
  assert (Hr : 0 <= b < Zlength (mt_trail t)).
  { pose proof (mtw_lim_range Hwf) as HF. rewrite Forall_forall in HF.
    apply HF. eapply In_ztake; eauto. }
  rewrite app_Znth1 by exact Hr. reflexivity.
Qed.

Lemma decisions_upto_decide_top : forall n t l,
  mtrail_wf n t ->
  decisions_upto (mt_decide t l) (Zlength (mt_lim t) + 1)
  = decisions_upto t (Zlength (mt_lim t)) ++ [lit_denote l].
Proof.
  intros n t l Hwf.
  pose proof (Zlength_nonneg (mt_trail t)) as HT0.
  unfold decisions_upto, mt_decide, mt_push; cbn [mt_trail mt_lim].
  rewrite ztake_all by (rewrite Zlength_app, Zlength_cons, Zlength_nil; lia).
  rewrite map_app. f_equal.
  - rewrite ztake_all by lia.
    apply map_ext_in. intros b Hb.
    assert (Hr : 0 <= b < Zlength (mt_trail t)).
    { pose proof (mtw_lim_range Hwf) as HF. rewrite Forall_forall in HF. auto. }
    rewrite app_Znth1 by exact Hr. reflexivity.
  - simpl. f_equal. f_equal.
    rewrite app_Znth2 by lia.
    replace (Zlength (mt_trail t) - Zlength (mt_trail t)) with 0 by lia.
    apply Znth0_cons.
Qed.

(** A new decision extends the hypothesis set of exactly the new literal. *)
Lemma trail_implied_decision : forall n F t l,
  mtrail_wf n t -> trail_implied F t -> trail_implied F (mt_decide t l).
Proof.
  intros n F t l Hwf Hti.
  pose proof (Zlength_nonneg (mt_trail t)) as HT0.
  pose proof (Zlength_nonneg (mt_lim t)) as HL0.
  intros i ll Hi Hll.
  unfold mt_decide, mt_push in Hi, Hll; cbn [mt_trail] in Hi, Hll.
  rewrite Zlength_app, Zlength_cons, Zlength_nil in Hi.
  destruct (Z.eq_dec i (Zlength (mt_trail t))) as [->|Hne].
  - rewrite app_Znth2 in Hll by lia.
    replace (Zlength (mt_trail t) - Zlength (mt_trail t)) with 0 in Hll by lia.
    rewrite Znth0_cons in Hll. subst ll.
    assert (Hlev : level_of_index (mt_decide t l) (Zlength (mt_trail t))
                   = Zlength (mt_lim t) + 1).
    { unfold level_of_index, mt_decide, mt_push; cbn [mt_lim].
      rewrite (count_le_decide_new n t Hwf), Zlength_app, Zlength_cons,
              Zlength_nil. lia. }
    rewrite Hlev, (decisions_upto_decide_top n t l Hwf).
    apply entails_clause_units_unit.
    apply in_or_app. right. left. reflexivity.
  - rewrite app_Znth1 in Hll by lia.
    assert (Hlev : level_of_index (mt_decide t l) i = level_of_index t i).
    { unfold level_of_index, mt_decide, mt_push; cbn [mt_lim].
      apply (count_le_decide_old n t i Hwf). lia. }
    rewrite Hlev, (decisions_upto_decide_low n t l (level_of_index t i) Hwf).
    + apply (Hti i ll); [lia|exact Hll].
    + pose proof (level_of_index_nonneg t i). pose proof (prop_level_processed_level_le t i).
      lia.
Qed.

(** Truncation preserves it: the surviving literals' hypotheses only mention
    surviving decisions, precisely because they are level-indexed. *)
Lemma trail_implied_cancel : forall n F t level,
  mtrail_wf n t -> 0 <= level < Zlength (mt_lim t) ->
  trail_implied F t -> trail_implied F (mt_cancel t level).
Proof.
  intros n F t level Hwf Hlevel Hti i l Hi Hl.
  pose proof (lim_lt_trail n t level Hwf Hlevel) as Hb.
  pose proof (mtw_lim_sorted Hwf) as Hsorted.
  rewrite mt_cancel_trail in Hi, Hl.
  assert (Hlen : Zlength (ztake (Znth level (mt_lim t) 0) (mt_trail t))
                 = Znth level (mt_lim t) 0) by (apply Zlength_ztake; lia).
  rewrite Hlen in Hi.
  rewrite Znth_ztake in Hl by lia.
  assert (Hile : count_le i (mt_lim t) <= level).
  { destruct (Z_le_gt_dec (count_le i (mt_lim t)) level) as [H|H]; [exact H|].
    exfalso.
    assert (Hp : 0 <= level < count_le i (mt_lim t)) by lia.
    pose proof (strict_sorted_count_prefix (mt_lim t) i level Hsorted Hp). lia. }
  assert (Hlev : level_of_index (mt_cancel t level) i = level_of_index t i).
  { unfold level_of_index. rewrite mt_cancel_lim.
    apply count_le_ztake; [exact Hsorted|lia|exact Hile]. }
  rewrite Hlev.
  assert (Hdec : decisions_upto (mt_cancel t level) (level_of_index t i)
                 = decisions_upto t (level_of_index t i)).
  { unfold decisions_upto. rewrite mt_cancel_lim, mt_cancel_trail.
    rewrite ztake_ztake by (pose proof (level_of_index_nonneg t i);
                            unfold level_of_index in *; lia).
    apply map_ext_in. intros b Hb'.
    assert (Hdlen : Zlength (ztake (level_of_index t i) (mt_lim t))
                    = level_of_index t i).
    { apply Zlength_ztake. pose proof (level_of_index_nonneg t i).
      unfold level_of_index in *. lia. }
    destruct (In_Znth_index _ _ Hb') as [j [Hj Hjval]].
    rewrite Hdlen in Hj.
    rewrite Znth_ztake in Hjval by lia.
    assert (Hjb : b < Znth level (mt_lim t) 0).
    { rewrite <- Hjval. apply strict_sorted_Znth; [exact Hsorted|lia| |lia].
      unfold level_of_index in Hj. lia. }
    assert (Hb0 : 0 <= b).
    { pose proof (mtw_lim_range Hwf) as HF. rewrite Forall_forall in HF.
      assert (Hinb : In b (mt_lim t)) by (eapply In_ztake; eauto).
      pose proof (HF b Hinb). lia. }
    rewrite Znth_ztake by lia. reflexivity. }
  rewrite Hdec.
  apply (Hti i l); [lia|exact Hl].
Qed.

(** ===== H. the UNSAT endgame ===== *)

Lemma trail_implied_at_root : forall F t A,
  trail_implied F t -> decisions_are t A ->
  forall i, 0 <= i < Zlength (mt_trail t) ->
    entails_clause (cnf_with_units F A) [lit_denote (Znth i (mt_trail t) 0)].
Proof.
  intros F t A Hti HA i Hi. unfold decisions_are in HA. subst A.
  eapply trail_implied_upgrade;
    [exact Hti|exact Hi|reflexivity|apply prop_level_processed_level_le].
Qed.

(** At [dlevel = root_level] the decisions are
    exactly the assumptions, so a conflict clause -- entailed by [F], all of
    whose literals are false on the trail -- refutes [F /\ A]. *)
Lemma root_conflict_unsat : forall n F A t Cd,
  cnf_wf n F -> Forall (literal_wf n) A ->
  mtrail_wf n t -> trail_implied F t -> decisions_are t A ->
  entails_clause F Cd ->
  clause_false (assigns_pv (mt_assigns t)) Cd ->
  Forall (literal_wf n) Cd ->
  cnf_unsat n (cnf_with_units F A).
Proof.
  intros n F A t Cd HFwf HAwf Hwf Hti Hdec Hent Hfalse HCdwf.
  split; [apply cnf_with_units_wf; assumption|].
  intros rho Hbound Hmodels.
  destruct (proj1 (models_cnf_with_units rho F A) Hmodels) as [HmF _].
  destruct (Hent rho HmF) as [k [Hink Hktrue]].
  pose proof (Hfalse k Hink) as Hkfalse.
  rewrite Forall_forall in HCdwf.
  pose proof (HCdwf k Hink) as Hkwf.
  unfold literal_wf, var_in_range in Hkwf.
  assert (Hassigned : Znth (literal_var k) (mt_assigns t) 0 <> 0).
  { intro Hz.
    assert (Hnone : assigns_pv (mt_assigns t) (literal_var k) = None).
    { unfold assigns_pv, assigns_val. rewrite Hz.
      apply lbool_val_none. split; discriminate. }
    pose proof (eval_partial_literal_unassigned
                  (assigns_pv (mt_assigns t)) k Hnone) as Hn.
    rewrite Hn in Hkfalse. discriminate. }
  pose proof (proj1 (mtw_assigned_iff Hwf (literal_var k) Hkwf) Hassigned) as Hin.
  destruct (In_Znth_index _ _ Hin) as [j [Hj Hjval]].
  rewrite Zlength_map_Z in Hj.
  assert (Hvar : lit_var_c (Znth j (mt_trail t) 0) = literal_var k).
  { rewrite <- Hjval. symmetry.
    apply (Znth_map Z Z lit_var_c (mt_trail t) j 0 0). exact Hj. }
  pose proof (trail_implied_at_root F t A Hti Hdec j Hj) as Hentl.
  destruct (Hentl rho Hmodels) as [k' [Hink' Hk'true]].
  destruct Hink' as [Heq|[]]. subst k'.
  rewrite lit_denote_satisfying, Hvar in Hk'true.
  pose proof (eval_satisfying_literal_true_inv rho (literal_var k)
                (lit_pol (Znth j (mt_trail t) 0)) Hk'true) as Hrhov.
  assert (Hcell : assigns_pv (mt_assigns t) (literal_var k)
                  = Some (lit_pol (Znth j (mt_trail t) 0))).
  { unfold assigns_pv, assigns_val.
    assert (Hsig : Znth (literal_var k) (mt_assigns t) 0
                   = lit_sig (Znth j (mt_trail t) 0)).
    { rewrite <- Hvar.
      pose proof (mtw_trail_true Hwf) as HF. rewrite Forall_forall in HF.
      apply HF. apply Znth_In. exact Hj. }
    rewrite Hsig. apply lbool_val_lit_sig. }
  pose proof (eval_partial_literal_total_agree
                (assigns_pv (mt_assigns t)) rho k false
                (lit_pol (Znth j (mt_trail t) 0)) Hcell Hrhov Hkfalse) as Hkeval.
  rewrite Hkeval in Hktrue. discriminate.
Qed.

Lemma perm_swap_app :
  forall (X A Y : list Z), Permutation (X ++ A ++ Y) (A ++ X ++ Y).
Proof.
  intros X A Y.
  rewrite (app_assoc X A Y), (app_assoc A X Y).
  apply Permutation_app_tail. apply Permutation_app_comm.
Qed.

Lemma perm_shuffle :
  forall (X A Y B : list Z),
    Permutation ((X ++ A ++ Y) ++ B) (A ++ (X ++ B ++ Y)).
Proof.
  intros X A Y B.
  eapply Permutation_trans; [apply Permutation_app_tail, perm_swap_app|].
  rewrite <- !app_assoc.
  apply Permutation_app_head, Permutation_app_head, Permutation_app_comm.
Qed.

Lemma Zlength_two_inv :
  forall (L : list Z), Zlength L = 2 -> L = [Znth 0 L 0; Znth 1 L 0].
Proof.
  intros L HL. destruct L as [|a [|b [|c L]]].
  - rewrite Zlength_nil in HL. lia.
  - rewrite Zlength_cons, Zlength_nil in HL. lia.
  - rewrite Znth0_cons. rewrite Znth_cons by lia.
    replace (1 - 1) with 0 by lia. rewrite Znth0_cons. reflexivity.
  - rewrite !Zlength_cons in HL. pose proof (Zlength_nonneg L). lia.
Qed.

Definition db_nil : dbmap := nil.

Definition z_nil : list Z := nil.

Definition msat_false : bool := false.

Lemma db_wf_obj : forall n db p co,
  db_wf n db -> In (p, co) db -> obj_wf n co.
Proof.
  intros n db p co [_ [_ Hall]] Hin.
  rewrite Forall_forall in Hall. exact (Hall _ Hin).
Qed.

Lemma db_wf_even : forall n db p co,
  db_wf n db -> In (p, co) db -> Z.even p = true.
Proof.
  intros n db p co [_ [Hall _]] Hin.
  rewrite Forall_forall in Hall. exact (proj2 (Hall _ Hin)).
Qed.

Lemma db_wf_ptr_pos : forall n db p co,
  db_wf n db -> In (p, co) db -> 0 < p.
Proof.
  intros n db p co [_ [Hall _]] Hin.
  rewrite Forall_forall in Hall. exact (proj1 (Hall _ Hin)).
Qed.

Lemma db_wf_lookup_unique : forall n db p co co',
  db_wf n db -> In (p, co) db -> In (p, co') db -> co = co'.
Proof.
  intros n db p co co' [Hnd _] H1 H2.
  revert p co co' Hnd H1 H2.
  induction db as [|e db IH]; intros p co co' Hnd H1 H2.
  - contradiction.
  - simpl in Hnd. apply NoDup_cons_iff in Hnd. destruct Hnd as [Hni Hnd'].
    destruct H1 as [He1|H1]; destruct H2 as [He2|H2].
    + congruence.
    + exfalso. apply Hni. rewrite He1.
      change (fst (p, co)) with (fst (p, co')). apply in_map. exact H2.
    + exfalso. apply Hni. rewrite He2.
      change (fst (p, co')) with (fst (p, co)). apply in_map. exact H1.
    + exact (IH p co co' Hnd' H1 H2).
Qed.

Lemma obj_wf_watch0 : forall n co, obj_wf n co -> lit_wf_c n (co_watch0 co).
Proof.
  intros n co [Hlen [Hall _]]. unfold co_watch0.
  apply Forall_Znth_elim; [exact Hall | lia].
Qed.

Lemma obj_wf_watch1 : forall n co, obj_wf n co -> lit_wf_c n (co_watch1 co).
Proof.
  intros n co [Hlen [Hall _]]. unfold co_watch1.
  apply Forall_Znth_elim; [exact Hall | lia].
Qed.

Lemma obj_wf_watch0_in : forall n co, obj_wf n co -> In (co_watch0 co) (co_lits co).
Proof.
  intros n co [Hlen _]. unfold co_watch0. apply Znth_In. lia.
Qed.

Lemma obj_wf_watch1_in : forall n co, obj_wf n co -> In (co_watch1 co) (co_lits co).
Proof.
  intros n co [Hlen _]. unfold co_watch1. apply Znth_In. lia.
Qed.

Lemma minisat_occurrence_of_entry_wf : forall n p co,
  obj_wf n co ->
  watch_occurrence_wf n (minisat_occurrence_of_entry (p, co)).
Proof.
  intros n p co Hobj.
  pose proof Hobj as [Hlen [Hlits _]].
  split.
  - unfold denote_obj. apply lits_denote_wf. exact Hlits.
  - split; unfold denote_obj.
    + apply lits_denote_in. eapply obj_wf_watch0_in; eassumption.
    + apply lits_denote_in. eapply obj_wf_watch1_in; eassumption.
Qed.

Lemma minisat_watch_occurrences_wf : forall n db,
  db_wf n db ->
  Forall (watch_occurrence_wf n) (minisat_watch_occurrences db).
Proof.
  intros n db [_ [_ Hobjects]].
  unfold minisat_watch_occurrences.
  apply Forall_map.
  revert Hobjects. apply Forall_impl.
  intros [p co] Hobj.
  apply minisat_occurrence_of_entry_wf. exact Hobj.
Qed.

Lemma minisat_focus_words_expected : forall db p,
  minisat_focus_words (minisat_focus_contributions db p) =
  expected_watchers db p.
Proof.
  intros db p. induction db as [|e db IH]; [reflexivity|].
  change
    (minisat_focus_words
       (minisat_entry_focus_contributions p e ++
        minisat_focus_contributions db p) =
     entry_watchers e p ++ expected_watchers db p).
  rewrite <- IH.
  unfold minisat_focus_words. rewrite map_app.
  unfold minisat_entry_focus_contributions.
  rewrite map_map. simpl. rewrite map_id. reflexivity.
Qed.

Lemma minisat_focus_words_reorder : forall cs ws,
  Permutation (minisat_focus_words cs) ws ->
  exists cs',
    Permutation cs' cs /\
    minisat_focus_words cs' = ws.
Proof.
  intros cs ws Hperm.
  unfold minisat_focus_words in Hperm |- *.
  pose proof (Permutation_sym Hperm) as Hsym.
  destruct (@Permutation_map_inv minisat_focus_contribution Z snd
              ws cs Hsym) as [cs' [Hwords Hcs]].
  exists cs'. split.
  - apply Permutation_sym. exact Hcs.
  - symmetry. exact Hwords.
Qed.

Lemma minisat_focus_scan_init : forall n db wm p P,
  wmap_exact n db wm ->
  0 <= p < 2 * n ->
  minisat_focus_scan_carrier db p P [] (Znth p wm nil).
Proof.
  intros n db wm p P [_ Hexact] Hp.
  specialize (Hexact p Hp).
  rewrite <- minisat_focus_words_expected in Hexact.
  destruct (minisat_focus_words_reorder
              (minisat_focus_contributions db p)
              (Znth p wm nil) (Permutation_sym Hexact))
    as [pending [Hpending Hwords]].
  unfold minisat_focus_scan_carrier.
  exists [], pending. split.
  - simpl. exact Hpending.
  - split; [reflexivity|]. split; [exact Hwords|constructor].
Qed.

Lemma minisat_focused_occurrence_contributes : forall n db p o,
  db_wf n db ->
  lit_wf_c n p ->
  In o (minisat_watch_occurrences db) ->
  (lit_denote p = literal_neg (watch_left o) \/
   lit_denote p = literal_neg (watch_right o)) ->
  exists w, In (o, w) (minisat_focus_contributions db p).
Proof.
  intros n db p o Hdb Hp Ho Hfocus.
  unfold minisat_watch_occurrences in Ho.
  apply in_map_iff in Ho.
  destruct Ho as [[q co] [Ho Hin]]. subst o.
  assert (Hobj : obj_wf n co) by (eapply db_wf_obj; eassumption).
  assert (H0wf : lit_wf_c n (co_watch0 co))
    by (eapply obj_wf_watch0; eassumption).
  assert (H1wf : lit_wf_c n (co_watch1 co))
    by (eapply obj_wf_watch1; eassumption).
  change
    (lit_denote p = literal_neg (lit_denote (co_watch0 co)) \/
     lit_denote p = literal_neg (lit_denote (co_watch1 co)))
    in Hfocus.
  destruct Hfocus as [Hfocus | Hfocus].
  - assert (Hnegwf : lit_wf_c n (lit_neg_c (co_watch0 co)))
      by (apply lit_neg_c_wf; exact H0wf).
    assert (Hden :
      lit_denote p = lit_denote (lit_neg_c (co_watch0 co))).
    { rewrite lit_denote_neg by (destruct H0wf; lia). exact Hfocus. }
    assert (Hindex : lit_neg_c (co_watch0 co) = p).
    { pose proof (f_equal lit_encode Hden) as Hencoded.
      rewrite (lit_encode_denote n p Hp) in Hencoded.
      rewrite (lit_encode_denote
                 n (lit_neg_c (co_watch0 co)) Hnegwf) in Hencoded.
      symmetry. exact Hencoded. }
    set (w := if 3 <=? Zlength (co_lits co)
              then q else tag_of_lit (co_watch1 co)).
    assert (Hwatch : In w (entry_watchers (q, co) p)).
    { unfold entry_watchers. rewrite Hindex, Z.eqb_refl.
      apply in_or_app. left. unfold w. simpl. auto. }
    exists w. unfold minisat_focus_contributions.
    apply in_flat_map. exists (q, co). split; [exact Hin|].
    unfold minisat_entry_focus_contributions. apply in_map. exact Hwatch.
  - assert (Hnegwf : lit_wf_c n (lit_neg_c (co_watch1 co)))
      by (apply lit_neg_c_wf; exact H1wf).
    assert (Hden :
      lit_denote p = lit_denote (lit_neg_c (co_watch1 co))).
    { rewrite lit_denote_neg by (destruct H1wf; lia). exact Hfocus. }
    assert (Hindex : lit_neg_c (co_watch1 co) = p).
    { pose proof (f_equal lit_encode Hden) as Hencoded.
      rewrite (lit_encode_denote n p Hp) in Hencoded.
      rewrite (lit_encode_denote
                 n (lit_neg_c (co_watch1 co)) Hnegwf) in Hencoded.
      symmetry. exact Hencoded. }
    set (w := if 3 <=? Zlength (co_lits co)
              then q else tag_of_lit (co_watch0 co)).
    assert (Hwatch : In w (entry_watchers (q, co) p)).
    { unfold entry_watchers. apply in_or_app. right.
      rewrite Hindex, Z.eqb_refl. unfold w. simpl. auto. }
    exists w. unfold minisat_focus_contributions.
    apply in_flat_map. exists (q, co). split; [exact Hin|].
    unfold minisat_entry_focus_contributions. apply in_map. exact Hwatch.
Qed.

Lemma expected_watchers_app : forall db1 db2 l,
  expected_watchers (db1 ++ db2) l
  = expected_watchers db1 l ++ expected_watchers db2 l.
Proof. intros. unfold expected_watchers. apply flat_map_app. Qed.

Lemma expected_watchers_cons : forall e db l,
  expected_watchers (e :: db) l = entry_watchers e l ++ expected_watchers db l.
Proof. reflexivity. Qed.

(** Membership transfer: an expected contribution really sits in the list. *)
Lemma wmap_in_of_entry : forall n db wm e l w,
  wmap_exact n db wm -> In e db -> 0 <= l < 2 * n ->
  In w (entry_watchers e l) -> In w (Znth l wm nil).
Proof.
  intros n db wm e l w [_ Hp] Hin Hl Hw.
  apply (Permutation_in (l := expected_watchers db l)).
  - apply Permutation_sym. exact (Hp l Hl).
  - unfold expected_watchers. apply in_flat_map. exists e. split; assumption.
Qed.

(** The four concrete presence facts (the [vecp_remove] scans of
    [clause_remove] need exactly these). *)

Lemma wmap_present_real0 : forall n db wm p co,
  db_wf n db -> wmap_exact n db wm -> In (p, co) db ->
  3 <= Zlength (co_lits co) ->
  In p (Znth (lit_neg_c (co_watch0 co)) wm nil).
Proof.
  intros n db wm p co Hdb Hex Hin Hbig.
  assert (Hobj : obj_wf n co) by (eapply db_wf_obj; eassumption).
  assert (Hwf : lit_wf_c n (lit_neg_c (co_watch0 co)))
    by (apply lit_neg_c_wf; eapply obj_wf_watch0; eassumption).
  eapply wmap_in_of_entry; [exact Hex | exact Hin | exact Hwf |].
  simpl. rewrite Z.eqb_refl.
  assert (H3 : (3 <=? Zlength (co_lits co)) = true) by (apply Z.leb_le; lia).
  rewrite H3. simpl. left. reflexivity.
Qed.

Lemma wmap_present_real1 : forall n db wm p co,
  db_wf n db -> wmap_exact n db wm -> In (p, co) db ->
  3 <= Zlength (co_lits co) ->
  In p (Znth (lit_neg_c (co_watch1 co)) wm nil).
Proof.
  intros n db wm p co Hdb Hex Hin Hbig.
  assert (Hobj : obj_wf n co) by (eapply db_wf_obj; eassumption).
  assert (Hwf : lit_wf_c n (lit_neg_c (co_watch1 co)))
    by (apply lit_neg_c_wf; eapply obj_wf_watch1; eassumption).
  eapply wmap_in_of_entry; [exact Hex | exact Hin | exact Hwf |].
  simpl. rewrite Z.eqb_refl.
  assert (H3 : (3 <=? Zlength (co_lits co)) = true) by (apply Z.leb_le; lia).
  rewrite H3.
  destruct (lit_neg_c (co_watch0 co) =? lit_neg_c (co_watch1 co));
    simpl; [right | ]; left; reflexivity.
Qed.

Lemma wmap_present_bin0 : forall n db wm p co,
  db_wf n db -> wmap_exact n db wm -> In (p, co) db ->
  Zlength (co_lits co) = 2 ->
  In (tag_of_lit (co_watch1 co)) (Znth (lit_neg_c (co_watch0 co)) wm nil).
Proof.
  intros n db wm p co Hdb Hex Hin H2.
  assert (Hobj : obj_wf n co) by (eapply db_wf_obj; eassumption).
  assert (Hwf : lit_wf_c n (lit_neg_c (co_watch0 co)))
    by (apply lit_neg_c_wf; eapply obj_wf_watch0; eassumption).
  eapply wmap_in_of_entry; [exact Hex | exact Hin | exact Hwf |].
  simpl. rewrite Z.eqb_refl.
  assert (H3 : (3 <=? Zlength (co_lits co)) = false) by (apply Z.leb_gt; lia).
  rewrite H3. simpl. left. reflexivity.
Qed.

Lemma wmap_present_bin1 : forall n db wm p co,
  db_wf n db -> wmap_exact n db wm -> In (p, co) db ->
  Zlength (co_lits co) = 2 ->
  In (tag_of_lit (co_watch0 co)) (Znth (lit_neg_c (co_watch1 co)) wm nil).
Proof.
  intros n db wm p co Hdb Hex Hin H2.
  assert (Hobj : obj_wf n co) by (eapply db_wf_obj; eassumption).
  assert (Hwf : lit_wf_c n (lit_neg_c (co_watch1 co)))
    by (apply lit_neg_c_wf; eapply obj_wf_watch1; eassumption).
  eapply wmap_in_of_entry; [exact Hex | exact Hin | exact Hwf |].
  simpl. rewrite Z.eqb_refl.
  assert (H3 : (3 <=? Zlength (co_lits co)) = false) by (apply Z.leb_gt; lia).
  rewrite H3.
  destruct (lit_neg_c (co_watch0 co) =? lit_neg_c (co_watch1 co));
    simpl; [right | ]; left; reflexivity.
Qed.

(** *** The two converse (witness) lemmas. *)

Lemma wmap_tag_witness : forall n db wm l w,
  db_wf n db -> wmap_exact n db wm -> 0 <= l < 2 * n ->
  In w (Znth l wm nil) -> is_tag w = true ->
  exists p co, In (p, co) db /\ Zlength (co_lits co) = 2 /\
               Permutation (co_lits co) [lit_neg_c l; tag_lit w].
Proof.
  intros n db wm l w Hdb [_ Hp] Hl Hin Htag.
  assert (Hexp : In w (expected_watchers db l))
    by (apply (Permutation_in (l := Znth l wm nil)); [exact (Hp l Hl) | exact Hin]).
  unfold expected_watchers in Hexp. apply in_flat_map in Hexp.
  destruct Hexp as [[q co] [Hq Hw]].
  assert (Hobj : obj_wf n co) by (eapply db_wf_obj; eassumption).
  assert (Hqe : Z.even q = true) by (eapply db_wf_even; eassumption).
  assert (Hqt : is_tag q = false) by (apply even_not_tag; exact Hqe).
  assert (H0wf : lit_wf_c n (co_watch0 co)) by (eapply obj_wf_watch0; eassumption).
  assert (H1wf : lit_wf_c n (co_watch1 co)) by (eapply obj_wf_watch1; eassumption).
  exists q, co.
  simpl in Hw. apply in_app_or in Hw.
  destruct (3 <=? Zlength (co_lits co)) eqn:Hbig.
  { exfalso.
    destruct Hw as [Hw|Hw];
      destruct (lit_neg_c (co_watch0 co) =? l);
      destruct (lit_neg_c (co_watch1 co) =? l);
      simpl in Hw; try contradiction;
      destruct Hw as [Hw|Hw]; try contradiction; subst; congruence. }
  assert (Hlen2 : Zlength (co_lits co) = 2).
  { apply Z.leb_gt in Hbig. destruct Hobj as [Hge _]. lia. }
  assert (Hshape : co_lits co = [co_watch0 co; co_watch1 co]).
  { unfold co_watch0, co_watch1. apply Zlength_two_inv. exact Hlen2. }
  destruct Hw as [Hw|Hw].
  - destruct (lit_neg_c (co_watch0 co) =? l) eqn:E0; simpl in Hw; [|contradiction].
    destruct Hw as [Hw|Hw]; [|contradiction].
    apply Z.eqb_eq in E0. subst l w.
    rewrite lit_neg_c_involutive.
    rewrite tag_lit_of.
    split; [exact Hq | split; [exact Hlen2 |]].
    rewrite Hshape. apply Permutation_refl.
  - destruct (lit_neg_c (co_watch1 co) =? l) eqn:E1; simpl in Hw; [|contradiction].
    destruct Hw as [Hw|Hw]; [|contradiction].
    apply Z.eqb_eq in E1. subst l w.
    rewrite lit_neg_c_involutive.
    rewrite tag_lit_of.
    split; [exact Hq | split; [exact Hlen2 |]].
    rewrite Hshape. apply perm_swap.
Qed.

Lemma wmap_real_witness : forall n db wm l w,
  db_wf n db -> wmap_exact n db wm -> 0 <= l < 2 * n ->
  In w (Znth l wm nil) -> is_tag w = false ->
  exists co, In (w, co) db /\ 3 <= Zlength (co_lits co) /\
             (lit_neg_c (co_watch0 co) = l \/ lit_neg_c (co_watch1 co) = l).
Proof.
  intros n db wm l w Hdb [_ Hp] Hl Hin Hreal.
  assert (Hexp : In w (expected_watchers db l))
    by (apply (Permutation_in (l := Znth l wm nil)); [exact (Hp l Hl) | exact Hin]).
  unfold expected_watchers in Hexp. apply in_flat_map in Hexp.
  destruct Hexp as [[q co] [Hq Hw]].
  simpl in Hw. apply in_app_or in Hw.
  destruct (3 <=? Zlength (co_lits co)) eqn:Hbig.
  - apply Z.leb_le in Hbig.
    destruct Hw as [Hw|Hw].
    + destruct (lit_neg_c (co_watch0 co) =? l) eqn:E0; simpl in Hw; [|contradiction].
      destruct Hw as [Hw|Hw]; [|contradiction]. subst q.
      apply Z.eqb_eq in E0.
      exists co. split; [exact Hq | split; [exact Hbig | left; exact E0]].
    + destruct (lit_neg_c (co_watch1 co) =? l) eqn:E1; simpl in Hw; [|contradiction].
      destruct Hw as [Hw|Hw]; [|contradiction]. subst q.
      apply Z.eqb_eq in E1.
      exists co. split; [exact Hq | split; [exact Hbig | right; exact E1]].
  - exfalso.
    destruct Hw as [Hw|Hw];
      [ destruct (lit_neg_c (co_watch0 co) =? l); simpl in Hw; [|contradiction]
      | destruct (lit_neg_c (co_watch1 co) =? l); simpl in Hw; [|contradiction] ];
      destruct Hw as [Hw|Hw]; try contradiction; subst w;
      rewrite is_tag_of in Hreal; discriminate.
Qed.

(** *** INV-W1 maintenance: insertion, in-place move, removal. *)


(** The propagate replacement step (upstream [solver.c]'s new-watch move
    inside [solver_propagate]: its [vecp_push]/[goto next] step)
    and the [lits[1] <-> lits[k]] mutation, stated as a difference: [wm'] is
    [wm] with the old entry's contributions removed and the new entry's
    added.  This also covers the [lits[0] <-> lits[1]] normalization that
    upstream writes as [lits[0] = lits[1]; lits[1] = false_lit;] (the
    contribution multiset is unchanged). *)
Lemma wmap_move : forall n db1 e e' db2 wm wm',
  wmap_exact n (db1 ++ e :: db2) wm ->
  Zlength wm' = 2 * n ->
  (forall l, 0 <= l < 2 * n ->
     Permutation (Znth l wm' nil ++ entry_watchers e l)
                 (Znth l wm nil ++ entry_watchers e' l)) ->
  wmap_exact n (db1 ++ e' :: db2) wm'.
Proof.
  intros n db1 e e' db2 wm wm' [_ Hp] Hlen Hdiff.
  split; [exact Hlen|]. intros l Hl.
  rewrite expected_watchers_app, expected_watchers_cons.
  specialize (Hp l Hl). specialize (Hdiff l Hl).
  rewrite expected_watchers_app, expected_watchers_cons in Hp.
  apply (Permutation_app_inv_l (entry_watchers e l)).
  eapply Permutation_trans; [apply Permutation_app_comm|].
  eapply Permutation_trans; [exact Hdiff|].
  eapply Permutation_trans;
    [apply Permutation_app_tail; exact Hp|].
  apply perm_shuffle.
Qed.

Lemma wmap_remove_clause : forall n db1 e db2 wm wm',
  wmap_exact n (db1 ++ e :: db2) wm ->
  Zlength wm' = 2 * n ->
  (forall l, 0 <= l < 2 * n ->
     Permutation (Znth l wm nil) (entry_watchers e l ++ Znth l wm' nil)) ->
  wmap_exact n (db1 ++ db2) wm'.
Proof.
  intros n db1 e db2 wm wm' [_ Hp] Hlen Hdiff.
  split; [exact Hlen|]. intros l Hl.
  specialize (Hp l Hl). specialize (Hdiff l Hl).
  rewrite expected_watchers_app, expected_watchers_cons in Hp.
  rewrite expected_watchers_app.
  apply (Permutation_app_inv_l (entry_watchers e l)).
  eapply Permutation_trans;
    [apply Permutation_sym; exact Hdiff|].
  eapply Permutation_trans; [exact Hp|].
  apply perm_swap_app.
Qed.

Lemma lit_sig_neg : forall l, lit_sig (lit_neg_c l) = - lit_sig l.
Proof.
  intros l. unfold lit_sig. rewrite lit_neg_c_odd_parity.
  destruct (Z.odd l); simpl; lia.
Qed.

Lemma lit_true_false_contra : forall assigns l,
  lit_true assigns l -> lit_false assigns l -> False.
Proof.
  intros assigns l Ht Hf. unfold lit_true, lit_false in *.
  destruct (lit_sig_values l) as [H|H]; rewrite H in *; lia.
Qed.

Lemma lit_true_assigned : forall assigns l,
  lit_true assigns l -> Znth (lit_var_c l) assigns 0 <> 0.
Proof.
  intros assigns l Ht. unfold lit_true in Ht.
  destruct (lit_sig_values l) as [H|H]; rewrite H in Ht; lia.
Qed.

Lemma lit_false_neg_true : forall assigns l,
  lit_false assigns l -> lit_true assigns (lit_neg_c l).
Proof.
  intros assigns l Hf. unfold lit_true, lit_false in *.
  rewrite lit_var_c_neg, lit_sig_neg. exact Hf.
Qed.

Definition assigns_total (n : Z) (assigns : list Z) : Prop :=
  forall v, 0 <= v < n -> Znth v assigns 0 = 1 \/ Znth v assigns 0 = -1.

Lemma lit_true_or_false : forall n assigns l,
  assigns_total n assigns -> lit_wf_c n l ->
  lit_true assigns l \/ lit_false assigns l.
Proof.
  intros n assigns l Htot Hwf.
  destruct (Htot (lit_var_c l) (lit_var_c_in_range n l Hwf)) as [H|H];
    unfold lit_true, lit_false; rewrite H; unfold lit_sig;
    destruct (Z.odd l); lia.
Qed.

(** The total valuation read off a fully-assigned [assigns] array. *)
Definition rho_of_assigns (assigns : list Z) : valuation :=
  fun x => Znth x assigns 0 =? 1.

Lemma eval_true_of_lit_true : forall assigns l,
  lit_true assigns l -> eval_literal (rho_of_assigns assigns) (lit_denote l) = true.
Proof.
  intros assigns l Ht. unfold lit_true, lit_sig, lit_var_c in Ht.
  unfold lit_denote, eval_literal, rho_of_assigns.
  destruct (Z.odd l); rewrite Ht; reflexivity.
Qed.

(** The literal currently being propagated cannot have the same variable as
    a fresh enqueue target.  This is the direct producer for the different-
    variable field of a newly installed tagged reason. *)
Lemma processed_fresh_target_different : forall assigns trail qhead p q,
  processed assigns trail qhead p ->
  Znth (lit_var_c q) assigns 0 = 0 ->
  lit_var_c q <> lit_var_c p.
Proof.
  intros assigns trail qhead p q [Hp _] Hfresh Heq.
  apply lit_true_assigned in Hp. apply Hp.
  rewrite <- Heq. exact Hfresh.
Qed.

Lemma minisat_processed_denote : forall n assigns trail qhead packed,
  lit_wf_c n packed ->
  (minisat_processed n assigns trail qhead (lit_denote packed) <->
   processed assigns trail qhead packed).
Proof.
  intros n assigns trail qhead packed Hpacked. split.
  - intros [packed' [Hpacked' [Hden Hprocessed]]].
    pose proof (lit_encode_denote n packed Hpacked) as Hencode.
    pose proof (lit_encode_denote n packed' Hpacked') as Hencode'.
    rewrite Hden, Hencode in Hencode'. subst packed'. exact Hprocessed.
  - intros Hprocessed. exists packed. split; [exact Hpacked|].
    split; [reflexivity|exact Hprocessed].
Qed.

(** Once the pending physical suffix is empty, exact contribution coverage
    turns the scanned-token facts into the focused premise required by the
    shared frontier-closing theorem. *)
Lemma minisat_watch_frontier_close_scan :
  forall n db assigns trail qhead p kept,
    db_wf n db ->
    lit_wf_c n p ->
    minisat_watch_frontier_except
      n db assigns trail qhead (lit_denote p) ->
    minisat_focus_scan_carrier
      db p (minisat_processed n assigns trail qhead) kept [] ->
    minisat_watch_frontier n db assigns trail qhead.
Proof.
  intros n db assigns trail qhead p kept Hdb Hp Hexcept Hscan.
  unfold minisat_focus_scan_carrier in Hscan.
  destruct Hscan as
    [scanned [pending [Hperm [Hkept [Hrest Hsafe]]]]].
  assert (Hpending : pending = []).
  { destruct pending as [|c pending]; [reflexivity|].
    unfold minisat_focus_words in Hrest. simpl in Hrest. discriminate. }
  subst pending. rewrite app_nil_r in Hperm.
  unfold minisat_watch_frontier.
  unfold minisat_watch_frontier_except in Hexcept.
  eapply watch_frontier_close; [exact Hexcept|].
  intros o Ho Hfocused.
  destruct (minisat_focused_occurrence_contributes
              n db p o Hdb Hp Ho Hfocused) as [w Hw].
  assert (Hscanned : In (o, w) scanned).
  { eapply Permutation_in.
    - apply Permutation_sym. exact Hperm.
    - exact Hw. }
  rewrite Forall_forall in Hsafe.
  pose proof (Hsafe (o, w) Hscanned) as Htoken.
  unfold minisat_occurrence_safe in Htoken. simpl in Htoken. exact Htoken.
Qed.

(** Capacity rollback removes only the dequeue performed by the current outer
    propagation iteration.  Earlier processed positions remain processed;
    trail-variable uniqueness shows that the current cursor literal was not
    already present in that earlier prefix. *)
Lemma minisat_watch_frontier_rollback_current :
  forall n db t q p,
    mtrail_wf n t ->
    0 <= q < Zlength (mt_trail t) ->
    p = Znth q (mt_trail t) 0 ->
    minisat_watch_frontier_except
      n db (mt_assigns t) (mt_trail t) (q + 1) (lit_denote p) ->
    minisat_watch_frontier
      n db (mt_assigns t) (mt_trail t) q.
Proof.
  intros n db t q p Hwf Hq Hp Hexcept.
  unfold minisat_watch_frontier, minisat_watch_frontier_except in *.
  eapply watch_frontier_rollback with
    (Pnew := minisat_processed
      n (mt_assigns t) (mt_trail t) (q + 1))
    (focus := lit_denote p).
  - exact Hexcept.
  - intros l [packed [Hpacked [Hden [Htrue [i [Hi Htrail]]]]]].
    exists packed. split; [exact Hpacked|].
    split; [exact Hden|]. split; [exact Htrue|].
    exists i. split; [lia|exact Htrail].
  - intros [packed [Hpacked [Hden [_ [i [Hi Htrail]]]]]].
    assert (Hp_wf : lit_wf_c n p).
    { rewrite Hp. eapply Forall_Znth_elim.
      - exact (mtw_trail_lits Hwf).
      - exact Hq. }
    assert (Hpacked_eq : packed = p).
    { pose proof (f_equal lit_encode Hden) as Hencoded.
      rewrite (lit_encode_denote n packed Hpacked) in Hencoded.
      rewrite (lit_encode_denote n p Hp_wf) in Hencoded.
      exact Hencoded. }
    assert (Htrail_p : Znth i (mt_trail t) 0 = p).
    { rewrite Htrail. exact Hpacked_eq. }
    assert (Hi_full : 0 <= i < Zlength (mt_trail t)) by lia.
    pose proof (trail_pos_of_index t i (mtw_trail_nodup Hwf) Hi_full)
      as Hpos_i.
    pose proof (trail_pos_of_index t q (mtw_trail_nodup Hwf) Hq)
      as Hpos_q.
    assert (Hvar_i : trail_var t i = lit_var_c p).
    { unfold trail_var. rewrite Htrail_p. reflexivity. }
    assert (Hvar_q : trail_var t q = lit_var_c p).
    { unfold trail_var. rewrite <- Hp. reflexivity. }
    rewrite Hvar_i in Hpos_i. rewrite Hvar_q in Hpos_q.
    rewrite Hpos_i in Hpos_q. injection Hpos_q as Heq.
    apply (f_equal Z.of_nat) in Heq.
    rewrite !Z2Nat.id in Heq by lia. lia.
Qed.

(** A genuine backjump is not the one-cell qhead rollback above: it truncates
    the trail and clears every assignment above [level].  A focus known to be
    at the old current level is therefore absent after any strict backjump.
    Every literal processed by the cancelled state lies in the retained trail
    prefix, so it was already processed before cancellation.  These are
    exactly the two premises needed to close a focused watcher frontier. *)
Lemma minisat_watch_frontier_cancel_current_level :
  forall n db t reasons clauses level focus,
    mtrail_wf n t ->
    prop_level t ->
    lit_wf_c n focus ->
    0 <= level < Zlength (mt_lim t) ->
    level_of (view_of n t reasons clauses) (lit_var_c focus) =
      Some (Zlength (mt_lim t)) ->
    minisat_watch_frontier_except
      n db (mt_assigns t) (mt_trail t) (mt_qhead t) (lit_denote focus) ->
    minisat_watch_frontier
      n db (mt_assigns (mt_cancel t level))
      (mt_trail (mt_cancel t level)) (mt_qhead (mt_cancel t level)).
Proof.
  intros n db t reasons clauses level focus
    Hwf Hprop _ Hlevel Hfocus Hfrontier.
  assert (Hbound : Znth level (mt_lim t) 0 <= mt_qhead t).
  { eapply Forall_Znth_elim; [exact Hprop|exact Hlevel]. }
  pose proof (lim_lt_trail n t level Hwf Hlevel) as Hbound_range.
  assert (Htake_len :
    Zlength (ztake (Znth level (mt_lim t) 0) (mt_trail t)) =
      Znth level (mt_lim t) 0).
  { apply Zlength_ztake. lia. }
  unfold minisat_watch_frontier, minisat_watch_frontier_except in *.
  eapply watch_frontier_rollback with
      (Pnew := minisat_processed
        n (mt_assigns t) (mt_trail t) (mt_qhead t))
      (focus := lit_denote focus).
  - exact Hfrontier.
  - intros l [packed [Hpacked [Hden [Htrue [i [Hi Htrail]]]]]].
    exists packed. split; [exact Hpacked|]. split; [exact Hden|].
    split.
    + unfold lit_true in Htrue |- *.
      rewrite mt_cancel_assigns in Htrue.
      rewrite <- Htrue. symmetry. apply clear_vars_notin.
      * rewrite (mtw_assigns_len Hwf). apply lit_var_c_in_range. exact Hpacked.
      * intros x Hx. rewrite (mtw_assigns_len Hwf).
        apply lit_var_c_in_range.
        pose proof (mtw_trail_lits Hwf) as Htrail_lits.
        rewrite Forall_forall in Htrail_lits.
        apply Htrail_lits. eapply In_zdrop; eauto.
      * eapply NoDup_app_disjoint.
        -- rewrite <- map_ztake_zdrop. exact (mtw_trail_nodup Hwf).
        -- rewrite mt_cancel_qhead in Hi. rewrite mt_cancel_trail in Htrail.
           apply in_map. rewrite <- Htrail. apply Znth_In.
           rewrite Htake_len. exact Hi.
    + exists i. rewrite mt_cancel_qhead in Hi.
      rewrite mt_cancel_trail in Htrail.
      split; [lia|]. rewrite Znth_ztake in Htrail by lia. exact Htrail.
  - intros [packed [Hpacked [Hden [_ [i [Hi Htrail]]]]]].
    assert (Hvar : lit_var_c packed = lit_var_c focus).
    { rewrite <- (lit_var_c_denote packed), <- (lit_var_c_denote focus).
      rewrite Hden. reflexivity. }
    pose proof (view_of_cancel n t reasons clauses level Hwf Hlevel)
      as Hcancel.
    destruct Hcancel as [_ [_ Hcancel]].
    specialize (Hcancel (lit_var_c focus)). rewrite Hfocus in Hcancel.
    assert (Habove : (Zlength (mt_lim t) <=? level) = false)
      by (apply Z.leb_gt; lia).
    rewrite Habove in Hcancel.
    destruct Hcancel as [_ [_ [_ Hrank]]].
    cbn [view_of assignment_rank] in Hrank.
    assert (Hin : In (lit_var_c focus)
      (map lit_var_c (mt_trail (mt_cancel t level)))).
    { rewrite <- Hvar. apply in_map. rewrite <- Htrail. apply Znth_In.
      pose proof (mtw_qhead_range
        (mtrail_wf_cancel n t level Hwf Hlevel)). lia. }
    destruct (find_var_pos_in _ _ Hin) as [k Hk].
    unfold trail_pos in Hrank. rewrite Hk in Hrank. discriminate.
Qed.

Lemma minisat_watch_frontier_before_first_dequeue :
  forall db assigns trail qhead,
    qhead <= 0 -> forall n, minisat_watch_frontier n db assigns trail qhead.
Proof.
  intros db assigns trail qhead Hq n.
  unfold minisat_watch_frontier, watch_frontier.
  rewrite Forall_forall. intros o Ho [Hleft _].
  unfold minisat_processed in Hleft.
  destruct Hleft as [packed [_ [_ [_ [i [Hi _]]]]]]. lia.
Qed.

(** *** FIXPOINT.

    Every literal that is true is on the trail; if the queue is drained
    ([qhead = |trail|]) every true literal is therefore processed. *)
Definition trail_covers (n : Z) (assigns trail : list Z) : Prop :=
  forall l, lit_wf_c n l -> lit_true assigns l ->
    exists i, 0 <= i < Zlength trail /\ Znth i trail 0 = l.

Lemma minisat_processed_false_complete :
  forall n assigns trail qhead,
    assigns_total n assigns ->
    qhead = Zlength trail ->
    trail_covers n assigns trail ->
    processed_false_complete n (rho_of_assigns assigns)
      (minisat_processed n assigns trail qhead).
Proof.
  intros n assigns trail qhead Htotal Hqhead Hcovers l Hwf Hfalse.
  set (packed := lit_encode l).
  assert (Hpacked_wf : lit_wf_c n packed).
  { unfold packed. apply lit_encode_wf. exact Hwf. }
  destruct (lit_true_or_false n assigns packed Htotal Hpacked_wf)
    as [Htrue|Hpacked_false].
  - pose proof (eval_true_of_lit_true assigns packed Htrue) as Heval.
    unfold packed in Heval.
    rewrite (lit_denote_encode n l Hwf) in Heval.
    congruence.
  - assert (Hneg_true : lit_true assigns (lit_neg_c packed)).
    { apply lit_false_neg_true. exact Hpacked_false. }
    assert (Hneg_wf : lit_wf_c n (lit_neg_c packed)).
    { apply lit_neg_c_wf. exact Hpacked_wf. }
    destruct (Hcovers _ Hneg_wf Hneg_true) as [i [Hi Htrail]].
    exists (lit_neg_c packed). split; [exact Hneg_wf|]. split.
    + rewrite lit_denote_neg.
      * unfold packed. rewrite (lit_denote_encode n l Hwf). reflexivity.
      * destruct Hpacked_wf. lia.
    + split; [exact Hneg_true|].
      exists i. split; [rewrite Hqhead; exact Hi|exact Htrail].
Qed.

Lemma minisat_watch_fixpoint_sat : forall n db assigns trail qhead,
  db_wf n db ->
  minisat_watch_frontier n db assigns trail qhead ->
  qhead = Zlength trail ->
  trail_covers n assigns trail ->
  assigns_total n assigns ->
  forall p co, In (p, co) db ->
    clause_satisfied (rho_of_assigns assigns) (denote_obj co).
Proof.
  intros n db assigns trail qhead Hdb Hfrontier Hqhead Hcovers Htotal.
  pose proof (minisat_watch_occurrences_wf n db Hdb) as Hwf.
  pose proof
    (minisat_processed_false_complete
      n assigns trail qhead Htotal Hqhead Hcovers) as Hcomplete.
  pose proof
    (watch_frontier_total_satisfies
      Z n (minisat_watch_occurrences db) (rho_of_assigns assigns)
      (minisat_processed n assigns trail qhead) Hwf Hfrontier Hcomplete)
    as Hsatisfied.
  rewrite Forall_forall in Hsatisfied.
  intros p co Hin.
  specialize (Hsatisfied (minisat_occurrence_of_entry (p, co))).
  apply Hsatisfied.
  unfold minisat_watch_occurrences. apply in_map. exact Hin.
Qed.

(** Keep step: the entry is copied to [*j] (each of upstream's
    [*j++ = *i] write-back steps). *)
Lemma wlist_scan_keep : forall ws0 kept moved w rest,
  wlist_scan_inv ws0 kept moved (w :: rest) ->
  wlist_scan_inv ws0 (kept ++ [w]) moved rest.
Proof.
  intros ws0 kept moved w rest H. unfold wlist_scan_inv in *.
  eapply Permutation_trans; [| exact H].
  rewrite <- app_assoc. simpl.
  apply Permutation_app_head.
  apply Permutation_middle.
Qed.

(** Move step: the entry is dropped from this list and pushed onto
    [wlists[~lits[1]_new]] (upstream's
    [vecp_push(solver_read_wlist(s, lit_neg(lits[1])), *i); goto next;]
    pair); it is not copied to [*j]. *)
Lemma wlist_scan_move : forall ws0 kept moved w rest,
  wlist_scan_inv ws0 kept moved (w :: rest) ->
  wlist_scan_inv ws0 kept (moved ++ [w]) rest.
Proof.
  intros ws0 kept moved w rest H. unfold wlist_scan_inv in *.
  rewrite <- app_assoc. simpl. exact H.
Qed.

(** Conflict copy-back (upstream's two [while (i < end) *j++ = *i++;]
    loops, one after each failing [enqueue]): the whole remaining
    suffix is retained verbatim. *)
Lemma wlist_scan_abort : forall ws0 kept moved rest,
  wlist_scan_inv ws0 kept moved rest ->
  wlist_scan_inv ws0 (kept ++ rest) moved nil.
Proof.
  intros ws0 kept moved rest H. unfold wlist_scan_inv in *.
  eapply Permutation_trans; [| exact H].
  rewrite app_nil_r, <- app_assoc.
  apply Permutation_app_head. apply Permutation_app_comm.
Qed.

(** The frontier is occurrence-indexed rather than membership-only.  A scan
    moves exactly one focused occurrence at a time; cancellation rolls back
    only work in the current outer propagation iteration. *)

(* ================= SECTION msat_s6_learn ================= *)

(** * S6 -- resolution carrier for [solver_analyze] + conflict-clause
    minimization soundness ([solver_lit_removable]).

    New material.  The
    analyze loop is modelled over the S3 [cdcl_view]: the implicit
    resolvent is [learnt ++ map (fun x => literal_neg (view_lit a x)) S],
    where [S] holds the tagged current-level variables not yet resolved
    (the C counter satisfies [cnt = Zlength S]) and [learnt] collects the
    strictly-lower-level literals.  [analyze_init] /
    [analyze_resolve_step] / [analyze_exit] are the loop lemmas;
    [minimization_sound] is the redundant-literal removal soundness
    theorem (strong induction on [assignment_rank] through the reason
    graph); [dfs_witness_extend] supports the [solver_lit_removable]
    DFS contract. *)

(** ----- generic list helpers ----- *)

Definition zmem (x : Z) (l : list Z) : bool := existsb (Z.eqb x) l.

Lemma zmem_true_iff : forall x l, zmem x l = true <-> In x l.
Proof.
  intros x l. unfold zmem. rewrite existsb_exists. split.
  - intros [y [Hy He]]. apply Z.eqb_eq in He. subst y. exact Hy.
  - intro Hin. exists x. split; [exact Hin | apply Z.eqb_refl].
Qed.

Lemma zmem_false_iff : forall x l, zmem x l = false <-> ~ In x l.
Proof.
  intros x l. split.
  - intros Hf Hin. apply zmem_true_iff in Hin. congruence.
  - intro Hn. destruct (zmem x l) eqn:E; [|reflexivity].
    exfalso. apply Hn. apply zmem_true_iff. exact E.
Qed.

Definition zremove (x : Z) (l : list Z) : list Z :=
  filter (fun y => negb (Z.eqb y x)) l.

Lemma In_zremove_iff : forall x y l,
  In y (zremove x l) <-> In y l /\ y <> x.
Proof.
  intros x y l. unfold zremove. rewrite filter_In. split.
  - intros [H1 H2]. split; [exact H1|].
    apply negb_true_iff in H2. apply Z.eqb_neq in H2. exact H2.
  - intros [H1 H2]. split; [exact H1|].
    apply negb_true_iff. apply Z.eqb_neq. exact H2.
Qed.

Lemma NoDup_app_intro : forall (A : Type) (l1 l2 : list A),
  NoDup l1 -> NoDup l2 -> (forall x, In x l1 -> ~ In x l2) ->
  NoDup (l1 ++ l2).
Proof.
  intros A l1 l2 H1 H2 Hdis.
  induction l1 as [|a l1 IH]; [exact H2|].
  cbn [app]. inversion H1 as [|? ? Hna H1']; subst.
  constructor.
  - intro Hin. apply in_app_or in Hin. destruct Hin as [Hin|Hin].
    + exact (Hna Hin).
    + exact (Hdis a (or_introl eq_refl) Hin).
  - apply IH; [exact H1'|].
    intros x Hx. apply Hdis. right. exact Hx.
Qed.

Lemma In_map_filter :
  forall (A B : Type) (f : A -> B) (g : A -> bool) (l : list A) (y : B),
  In y (map f (filter g l)) -> In y (map f l).
Proof.
  intros A B f g l y Hin.
  rewrite in_map_iff in Hin. destruct Hin as [x [Hf Hx]].
  apply filter_In in Hx. destruct Hx as [Hx _].
  rewrite in_map_iff. exists x. split; assumption.
Qed.

Lemma NoDup_map_filter :
  forall (A B : Type) (f : A -> B) (g : A -> bool) (l : list A),
  NoDup (map f l) -> NoDup (map f (filter g l)).
Proof.
  intros A B f g l Hnd.
  induction l as [|a l IH]; [constructor|].
  cbn [map filter] in *.
  inversion Hnd as [|? ? Hna Hnd']; subst.
  destruct (g a).
  - cbn [map]. constructor.
    + intro Hin. apply In_map_filter in Hin. exact (Hna Hin).
    + apply IH. exact Hnd'.
  - apply IH. exact Hnd'.
Qed.

(** ----- literal-shape helpers ----- *)

Lemma satisfying_literal_var : forall x b,
  literal_var (satisfying_literal x b) = x.
Proof. intros x [|]; reflexivity. Qed.

(** ----- the trail literal of an assigned variable, on the view ----- *)

Definition view_lit (a : cdcl_view) (x : Z) : literal :=
  match assignment a x with
  | Some b => satisfying_literal x b
  | None => Pos x
  end.

Lemma view_lit_assigned : forall a x b,
  assignment a x = Some b -> view_lit a x = satisfying_literal x b.
Proof. intros a x b H. unfold view_lit. rewrite H. reflexivity. Qed.

Lemma view_lit_var : forall a x, literal_var (view_lit a x) = x.
Proof.
  intros a x. unfold view_lit.
  destruct (assignment a x) as [[|]|]; reflexivity.
Qed.

Lemma neg_view_lit_false : forall a x b,
  assignment a x = Some b ->
  eval_partial_literal (assignment a) (literal_neg (view_lit a x))
  = Some false.
Proof.
  intros a x b H.
  rewrite (view_lit_assigned a x b H), literal_neg_satisfying.
  apply eval_falsified_literal_false. exact H.
Qed.

(** ----- decision-level classifiers (booleans, so the ghost sets are
    computed by [filter] exactly as the C loop walks the clause) ----- *)

Definition at_current_level_b (a : cdcl_view) (l : literal) : bool :=
  match level_of a (literal_var l) with
  | Some d => Z.eqb d (current_level a)
  | None => false
  end.

Definition below_current_b (a : cdcl_view) (l : literal) : bool :=
  match level_of a (literal_var l) with
  | Some d => andb (Z.ltb 0 d) (Z.ltb d (current_level a))
  | None => false
  end.

Lemma at_current_level_b_true_iff : forall a l,
  at_current_level_b a l = true <->
  level_of a (literal_var l) = Some (current_level a).
Proof.
  intros a l. unfold at_current_level_b.
  destruct (level_of a (literal_var l)) as [d|] eqn:E.
  - split; intro H.
    + apply Z.eqb_eq in H. subst d. reflexivity.
    + injection H as ->. apply Z.eqb_refl.
  - split; intro H; discriminate.
Qed.

Lemma below_current_b_true_iff : forall a l,
  below_current_b a l = true <->
  (exists d, level_of a (literal_var l) = Some d /\
             0 < d < current_level a).
Proof.
  intros a l. unfold below_current_b.
  destruct (level_of a (literal_var l)) as [d|] eqn:E.
  - split.
    + intro H. apply andb_prop in H. destruct H as [H1 H2].
      apply Z.ltb_lt in H1. apply Z.ltb_lt in H2.
      exists d. split; [reflexivity|lia].
    + intros [d0 [Hd0 Hb]]. injection Hd0 as ->.
      apply andb_true_intro. split; apply Z.ltb_lt; lia.
  - split; [discriminate|].
    intros [d0 [Hd0 _]]. discriminate.
Qed.

(** ----- the analyze-loop carrier ----- *)

(** Rank (= trail position) comparison on the view. *)
Definition rank_lt (a : cdcl_view) (y z : Z) : Prop :=
  exists ry rz,
    assignment_rank a y = Some ry /\
    assignment_rank a z = Some rz /\ (ry < rz)%nat.

(** The ghost image of the C [tags] array (never cleared inside the
    analyze loop): pending current-level variables
    [S], already-resolved current-level variables [R], and the variables
    of the collected lower-level literals. *)
Definition analyze_tags (S R : list Z) (learnt : clause) : list Z :=
  S ++ R ++ map literal_var learnt.

(** [S] = tagged current-level variables not yet resolved, [R] = the
    already-resolved current-level variables (they stay
    tagged in the C, so the ghost must model them to match the [tags]
    test, and they sit strictly above every pending [S] member in trail
    order -- resolution proceeds in reverse trail order), [learnt] = the
    collected strictly-lower-level literals; the implicit resolvent is
    [learnt] plus the negated trail literals of [S].  Level-0 literals
    have been dropped (they are permanently implied).  The invariant also
    carries assignedness of [S] and falseness of [learnt] -- both are loop
    invariants of the C code and both are needed by [analyze_exit].
    The C counter
    satisfies [cnt = Zlength S]; the entailment conjunct and the exit
    lemma mention only [S]/[learnt]. *)
Definition analyze_inv
    (F : cnf) (a : cdcl_view) (S R : list Z) (learnt : clause) : Prop :=
  entails_clause F
    (learnt ++ map (fun x => literal_neg (view_lit a x)) S) /\
  NoDup (analyze_tags S R learnt) /\
  Forall (fun x => level_of a x = Some (current_level a)) S /\
  Forall (fun x => exists b, assignment a x = Some b) S /\
  Forall (fun x => level_of a x = Some (current_level a)) R /\
  Forall (fun r => forall s, In s S -> rank_lt a s r) R /\
  Forall (fun l => exists d, level_of a (literal_var l) = Some d /\
                             0 < d < current_level a) learnt /\
  clause_false (assignment a) learnt.

(** Variables at the current level and literals strictly below it never
    share a variable. *)
Lemma level_disjoint_S_learnt :
  forall (a : cdcl_view) (S : list Z) (learnt : clause),
  Forall (fun x => level_of a x = Some (current_level a)) S ->
  Forall (fun l => exists d, level_of a (literal_var l) = Some d /\
                             0 < d < current_level a) learnt ->
  forall x, In x S -> ~ In x (map literal_var learnt).
Proof.
  intros a S learnt HS HL x HxS HxL.
  rewrite Forall_forall in HS, HL.
  rewrite in_map_iff in HxL. destruct HxL as [l [Hvl Hin]].
  destruct (HL l Hin) as [d [Hld Hd]].
  specialize (HS x HxS). rewrite <- Hvl in HS. rewrite HS in Hld.
  injection Hld as Heq. lia.
Qed.

(** ----- initialization from the conflict clause ----- *)

Definition analyze_start_S (a : cdcl_view) (C : clause) : list Z :=
  map literal_var (filter (at_current_level_b a) C).

Definition analyze_start_learnt (a : cdcl_view) (C : clause) : clause :=
  filter (below_current_b a) C.

Lemma analyze_init : forall (F : cnf) (a : cdcl_view) (C : clause),
  grounded_at a ->
  closed_levels a ->
  (forall x b, assignment a x = Some b -> level_of a x = Some 0 ->
     entails_clause F [satisfying_literal x b]) ->
  entails_clause F C ->
  clause_false (assignment a) C ->
  NoDup (map literal_var C) ->
  analyze_inv F a (analyze_start_S a C) [] (analyze_start_learnt a C).
Proof.
  intros F a C Hg Hcl Hpre HentC Hfalse Hnd.
  destruct Hcl as [_ [Hbound _]].
  (* every conflict literal is the falsified literal of an assigned,
     levelled variable within the level bounds *)
  assert (Hlit : forall l, In l C ->
    exists b d, assignment a (literal_var l) = Some b /\
                l = falsified_literal (literal_var l) b /\
                level_of a (literal_var l) = Some d /\
                0 <= d <= current_level a).
  { intros l Hin.
    destruct (eval_partial_false_shape _ _ (Hfalse l Hin))
      as [b [Hass Hshape]].
    destruct (Hg (literal_var l) b Hass) as [d [rx [Hlev _]]].
    exists b, d. repeat split; try assumption.
    - exact (proj1 (Hbound _ _ _ Hass Hlev)).
    - exact (proj2 (Hbound _ _ _ Hass Hlev)). }
  assert (E1 : entails_clause F
    (analyze_start_learnt a C
       ++ map (fun x => literal_neg (view_lit a x)) (analyze_start_S a C))).
  { intros rho Hmod.
    destruct (HentC rho Hmod) as [l [Hin Ht]].
    destruct (Hlit l Hin) as [b [d [Hass [Hshape [Hlev Hbd]]]]].
    destruct (Z.eq_dec d 0) as [-> | Hd0].
    - exfalso.
      destruct (Hpre _ _ Hass Hlev rho Hmod) as [k [Hk Hkt]].
      destruct Hk as [Heq|[]]. subst k.
      rewrite Hshape, <- literal_neg_satisfying, eval_literal_neg, Hkt
        in Ht.
      discriminate.
    - destruct (Z.eq_dec d (current_level a)) as [Heq | Hne].
      + subst d.
        assert (Hb : at_current_level_b a l = true)
          by (apply (proj2 (at_current_level_b_true_iff a l)); exact Hlev).
        assert (HinS : In (literal_var l) (analyze_start_S a C)).
        { unfold analyze_start_S. apply in_map.
          apply filter_In. split; assumption. }
        assert (Hkl : literal_neg (view_lit a (literal_var l)) = l).
        { rewrite (view_lit_assigned a (literal_var l) b Hass),
            literal_neg_satisfying. symmetry. exact Hshape. }
        exists l. split; [|exact Ht].
        apply in_or_app. right. rewrite <- Hkl.
        apply (in_map (fun x => literal_neg (view_lit a x))). exact HinS.
      + assert (Hb : below_current_b a l = true).
        { apply (proj2 (below_current_b_true_iff a l)).
          exists d. split; [exact Hlev|lia]. }
        exists l. split; [|exact Ht].
        apply in_or_app. left. unfold analyze_start_learnt.
        apply filter_In. split; assumption. }
  assert (E2 : NoDup (analyze_start_S a C))
    by (apply NoDup_map_filter; exact Hnd).
  assert (E3 : Forall (fun x => level_of a x = Some (current_level a))
                 (analyze_start_S a C)).
  { rewrite Forall_forall. intros x Hx.
    unfold analyze_start_S in Hx. rewrite in_map_iff in Hx.
    destruct Hx as [l [Hvl Hlf]]. apply filter_In in Hlf.
    destruct Hlf as [_ Hb].
    apply at_current_level_b_true_iff in Hb. rewrite <- Hvl. exact Hb. }
  assert (E4 : Forall (fun x => exists b, assignment a x = Some b)
                 (analyze_start_S a C)).
  { rewrite Forall_forall. intros x Hx.
    unfold analyze_start_S in Hx. rewrite in_map_iff in Hx.
    destruct Hx as [l [Hvl Hlf]]. apply filter_In in Hlf.
    destruct Hlf as [Hin _].
    destruct (Hlit l Hin) as [b [d [Hass _]]].
    exists b. rewrite <- Hvl. exact Hass. }
  assert (E5 : Forall (fun l => exists d,
                 level_of a (literal_var l) = Some d /\
                 0 < d < current_level a) (analyze_start_learnt a C)).
  { rewrite Forall_forall. intros l Hl.
    unfold analyze_start_learnt in Hl. apply filter_In in Hl.
    destruct Hl as [_ Hb].
    apply below_current_b_true_iff in Hb. exact Hb. }
  assert (E6 : clause_false (assignment a) (analyze_start_learnt a C)).
  { intros l Hl. unfold analyze_start_learnt in Hl.
    apply filter_In in Hl. destruct Hl as [Hin _].
    exact (Hfalse l Hin). }
  assert (E7 : NoDup (map literal_var (analyze_start_learnt a C)))
    by (apply NoDup_map_filter; exact Hnd).
  assert (Etags : NoDup (analyze_tags (analyze_start_S a C) []
                           (analyze_start_learnt a C))).
  { unfold analyze_tags. cbn [app]. apply NoDup_app_intro.
    - exact E2.
    - exact E7.
    - exact (level_disjoint_S_learnt a _ _ E3 E5). }
  exact (conj E1 (conj Etags (conj E3 (conj E4 (conj (Forall_nil _)
          (conj (Forall_nil _) (conj E5 E6))))))).
Qed.

(** ----- the resolution step ----- *)

(** New current-level variables contributed by the reason clause [c] of
    the resolved variable [x]; variables already tagged (members of
    [analyze_tags S R learnt] -- [x] itself is among them, being in [S])
    are skipped, exactly as [solver_analyze]'s [tags] test skips
    them; the test consults the WHOLE tag set, including the
    already-resolved variables [R]. *)
Definition resolve_new_S
    (a : cdcl_view) (c : clause) (tags : list Z) : list Z :=
  filter (fun y => negb (zmem y tags))
         (map literal_var (filter (at_current_level_b a) c)).

Definition resolve_S
    (a : cdcl_view) (x : Z) (c : clause) (S R : list Z)
    (learnt : clause) : list Z :=
  zremove x S ++ resolve_new_S a c (analyze_tags S R learnt).

(** New strictly-lower-level literals contributed by [c]; literals whose
    variable is already tagged are skipped (for a [learnt] variable its
    unique false literal is already there; [S]/[R] variables sit at the
    current level, so those parts of the test never fire on a lower-level
    literal -- but the ghost test is the C test, verbatim). *)
Definition resolve_new_lits
    (a : cdcl_view) (c : clause) (tags : list Z) : clause :=
  filter (fun l =>
            andb (below_current_b a l)
                 (negb (zmem (literal_var l) tags)))
         c.

Definition resolve_learnt
    (a : cdcl_view) (c : clause) (S R : list Z) (learnt : clause)
    : clause :=
  learnt ++ resolve_new_lits a c (analyze_tags S R learnt).

(** The step hypothesis [Hscan] is the trail-scan fact: the C resolves
    the trail-latest tagged variable first, so
    when [x] is picked every other pending variable sits strictly below
    it in trail order.  It is what makes the ghost [tags] test and the C
    test agree: a side literal of [x]'s reason has rank strictly BELOW
    [x] ([reason_valid]), while every member of [R] has rank strictly
    ABOVE some [S] member -- in particular above [x] -- so the reason
    clause can never mention an [R] variable. *)
(* The entailment component of [analyze_resolve_step]'s conclusion.  Resolving the
   conflict clause against [x]'s reason keeps the model-refuting clause: every
   witness literal is either inherited, re-enters the pending set, or is
   recorded in the learnt clause below the current level. *)
Lemma analyze_resolve_entails :
  forall (F : cnf) (a : cdcl_view) (S R : list Z) (learnt : clause)
    (x : Z) (c : clause) (b : bool),
  entails_clause F (learnt ++ map (fun y => literal_neg (view_lit a y)) S) ->
  (forall x' b', assignment a x' = Some b' -> level_of a x' = Some 0 ->
     entails_clause F [satisfying_literal x' b']) ->
  assignment a x = Some b ->
  entails_clause F c ->
  clause_var_injective c ->
  In (satisfying_literal x b) c ->
  (forall m, In m c -> literal_var m <> x ->
    exists b'' dy, assignment a (literal_var m) = Some b'' /\
      m = falsified_literal (literal_var m) b'' /\
      level_of a (literal_var m) = Some dy /\
      0 <= dy <= current_level a) ->
  (forall z, In z (analyze_tags S R learnt) <->
    In z S \/ In z R \/ In z (map literal_var learnt)) ->
  (forall m, In m c -> literal_var m <> x -> ~ In (literal_var m) R) ->
  (forall z, level_of a z = Some (current_level a) ->
    ~ In z (map literal_var learnt)) ->
  (forall (P : list Z) z dy,
    Forall (fun y => level_of a y = Some (current_level a)) P ->
    level_of a z = Some dy -> dy < current_level a -> ~ In z P) ->
  Forall (fun y => level_of a y = Some (current_level a)) S ->
  Forall (fun y => level_of a y = Some (current_level a)) R ->
  clause_false (assignment a) learnt ->
  entails_clause F
    (resolve_learnt a c S R learnt
       ++ map (fun y => literal_neg (view_lit a y))
              (resolve_S a x c S R learnt)).
Proof.
  intros F a S R learnt x c b Hent Hpre Hass Hentc Hinj Hsat Hcfacts
    Htags_iff HnotR HcurnotL Hlevel_notin HlevS HlevR HfalseL.
  intros rho Hmod.
    destruct (Hent rho Hmod) as [k [Hk Hkt]].
    apply in_app_or in Hk. destruct Hk as [HkL | HkS].
    - exists k. split; [|exact Hkt].
      apply in_or_app. left. unfold resolve_learnt.
      apply in_or_app. left. exact HkL.
    - rewrite in_map_iff in HkS. destruct HkS as [y [Hky HyS]].
      destruct (Z.eq_dec y x) as [-> | Hyx].
      + (* the pivot: resolve against the reason clause *)
        subst k.
        rewrite eval_literal_neg in Hkt. apply negb_true_iff in Hkt.
        rewrite (view_lit_assigned a x b Hass) in Hkt.
        destruct (Hentc rho Hmod) as [m [Hm Hmt]].
        destruct (Z.eq_dec (literal_var m) x) as [Hmx | Hmx].
        * (* the reason clause is satisfied at its pivot literal:
             contradiction with the resolvent's negated pivot *)
          exfalso.
          assert (Hme : m = satisfying_literal x b)
            by (exact (clause_var_injective_var_lit c x b m Hinj Hsat
                         Hm Hmx)).
          subst m. rewrite Hmt in Hkt. discriminate.
        * destruct (Hcfacts m Hm Hmx)
            as (b'' & dy & Hassy & Hshape & Hlevy & Hdy).
          destruct (Z.eq_dec dy 0) as [-> | Hdy0].
          -- (* level-0 side literal: permanently implied, dropped *)
             exfalso.
             destruct (Hpre _ _ Hassy Hlevy rho Hmod) as [k' [Hk' Hk't]].
             destruct Hk' as [Heq|[]]. subst k'.
             rewrite Hshape, <- literal_neg_satisfying,
               eval_literal_neg, Hk't in Hmt.
             discriminate.
          -- assert (Hmk : literal_neg (view_lit a (literal_var m)) = m).
             { rewrite (view_lit_assigned a (literal_var m) b'' Hassy),
                 literal_neg_satisfying. symmetry. exact Hshape. }
             destruct (Z.eq_dec dy (current_level a)) as [Heqc | Hnec].
             ++ (* current level: lands in the new S (or is pending) *)
                subst dy.
                destruct (zmem (literal_var m)
                            (analyze_tags S R learnt)) eqn:Hz.
                ** apply zmem_true_iff in Hz. apply Htags_iff in Hz.
                   destruct Hz as [HzS | [HzR | HzL]].
                   --- (* still pending: survives [zremove] *)
                       exists m. split; [|exact Hmt].
                       apply in_or_app. right. rewrite <- Hmk.
                       apply (in_map
                                (fun y0 => literal_neg (view_lit a y0))).
                       unfold resolve_S. apply in_or_app. left.
                       apply In_zremove_iff. split; assumption.
                   --- (* already resolved: impossible by trail order *)
                       exfalso. exact (HnotR m Hm Hmx HzR).
                   --- (* current-level learnt variable: impossible *)
                       exfalso. exact (HcurnotL _ Hlevy HzL).
                ** exists m. split; [|exact Hmt].
                   apply in_or_app. right. rewrite <- Hmk.
                   apply (in_map (fun y0 => literal_neg (view_lit a y0))).
                   unfold resolve_S. apply in_or_app. right.
                   unfold resolve_new_S. apply filter_In. split.
                   --- apply in_map. apply filter_In.
                       split; [exact Hm|].
                       apply (proj2 (at_current_level_b_true_iff a m)).
                       exact Hlevy.
                   --- rewrite Hz. reflexivity.
             ++ (* strictly below: lands in the new learnt *)
                assert (Hdyc : dy < current_level a) by lia.
                destruct (zmem (literal_var m)
                            (analyze_tags S R learnt)) eqn:Hz.
                ** apply zmem_true_iff in Hz. apply Htags_iff in Hz.
                   destruct Hz as [HzS | [HzR | HzL]].
                   --- exfalso.
                       exact (Hlevel_notin S _ _ HlevS Hlevy Hdyc HzS).
                   --- exfalso.
                       exact (Hlevel_notin R _ _ HlevR Hlevy Hdyc HzR).
                   --- (* variable already in learnt: the literal is *)
                       rewrite in_map_iff in HzL.
                       destruct HzL as [k' [Hvk' Hk'in]].
                       pose proof (HfalseL k' Hk'in) as Hk'f.
                       destruct (eval_partial_false_shape _ _ Hk'f)
                         as [b3 [Hass3 Hshape3]].
                       rewrite Hvk' in Hass3, Hshape3.
                       assert (Hb3 : b3 = b'') by congruence.
                       subst b3.
                       assert (Hkm : k' = m) by congruence.
                       rewrite Hkm in Hk'in.
                       exists m. split; [|exact Hmt].
                       apply in_or_app. left. unfold resolve_learnt.
                       apply in_or_app. left. exact Hk'in.
                ** exists m. split; [|exact Hmt].
                   apply in_or_app. left. unfold resolve_learnt.
                   apply in_or_app. right. unfold resolve_new_lits.
                   apply filter_In. split; [exact Hm|].
                   apply andb_true_intro. split.
                   --- apply (proj2 (below_current_b_true_iff a m)).
                       exists dy. split; [exact Hlevy|lia].
                   --- rewrite Hz. reflexivity.
      + (* a surviving member of S *)
        exists k. split; [|exact Hkt].
        apply in_or_app. right. rewrite <- Hky.
        apply (in_map (fun y0 => literal_neg (view_lit a y0))).
        unfold resolve_S. apply in_or_app. left.
        apply In_zremove_iff. split; assumption.
Qed.

(* The tag-disjointness component of [analyze_resolve_step]'s conclusion.  The four
   contributions -- the surviving pending set, the fresh current-level
   variables, the old learnt variables and the fresh lower-level ones -- are
   pairwise disjoint, by the freshness test and the level split. *)
Lemma analyze_resolve_tags_nodup :
  forall (a : cdcl_view) (S R : list Z) (learnt : clause)
    (x : Z) (c : clause),
  In x S ->
  NoDup S ->
  NoDup R ->
  NoDup (map literal_var learnt) ->
  NoDup (resolve_new_S a c (analyze_tags S R learnt)) ->
  NoDup (map literal_var (resolve_new_lits a c (analyze_tags S R learnt))) ->
  (forall z, In z S -> ~ In z (R ++ map literal_var learnt)) ->
  (forall z, In z R -> ~ In z (map literal_var learnt)) ->
  (forall z, zmem z (analyze_tags S R learnt) = false ->
    ~ In z S /\ ~ In z R /\ ~ In z (map literal_var learnt)) ->
  (forall y, In y (resolve_new_S a c (analyze_tags S R learnt)) ->
    exists m, In m c /\ literal_var m = y /\
      level_of a y = Some (current_level a) /\
      zmem y (analyze_tags S R learnt) = false) ->
  (forall z, In z (map literal_var
            (resolve_new_lits a c (analyze_tags S R learnt))) ->
    (exists dy, level_of a z = Some dy /\ 0 < dy < current_level a) /\
    zmem z (analyze_tags S R learnt) = false) ->
  NoDup (analyze_tags (resolve_S a x c S R learnt) (x :: R)
           (resolve_learnt a c S R learnt)).
Proof.
  intros a S R learnt x c HinS HndS HndR HndL HndnewSv HndnewL
    HdisS HdisRL Hfresh_notin HnewS_char HnewLvar_char.
  unfold analyze_tags at 1. unfold resolve_S, resolve_learnt.
    rewrite map_app.
    apply NoDup_app_intro.
    - (* zremove x S ++ fresh current-level variables *)
      apply NoDup_app_intro.
      + unfold zremove. apply NoDup_filter. exact HndS.
      + exact HndnewSv.
      + intros z Hz1 Hz2.
        apply In_zremove_iff in Hz1. destruct Hz1 as [Hz1 _].
        destruct (HnewS_char z Hz2) as [m [_ [_ [_ Hzf]]]].
        destruct (Hfresh_notin z Hzf) as (HnS & _ & _).
        exact (HnS Hz1).
    - (* (x :: R) ++ (old learnt vars ++ fresh learnt vars) *)
      apply NoDup_app_intro.
      + constructor.
        * intro HxR.
          exact (HdisS x HinS (in_or_app _ _ _ (or_introl HxR))).
        * exact HndR.
      + apply NoDup_app_intro.
        * exact HndL.
        * exact HndnewL.
        * intros z Hz1 Hz2.
          destruct (HnewLvar_char z Hz2) as (_ & Hzf).
          destruct (Hfresh_notin z Hzf) as (_ & _ & HnL).
          exact (HnL Hz1).
      + intros z Hz1 Hz2.
        apply in_app_or in Hz2.
        destruct Hz1 as [<- | Hz1].
        * destruct Hz2 as [Hz2 | Hz2].
          -- exact (HdisS x HinS (in_or_app _ _ _ (or_intror Hz2))).
          -- destruct (HnewLvar_char x Hz2) as (_ & Hzf).
             destruct (Hfresh_notin x Hzf) as (HnS & _ & _).
             exact (HnS HinS).
        * destruct Hz2 as [Hz2 | Hz2].
          -- exact (HdisRL z Hz1 Hz2).
          -- destruct (HnewLvar_char z Hz2) as (_ & Hzf).
             destruct (Hfresh_notin z Hzf) as (_ & HnR & _).
             exact (HnR Hz1).
    - (* the two big blocks are disjoint *)
      intros z Hz1 Hz2.
      apply in_app_or in Hz1.
      assert (Hz2' : z = x \/ In z R \/ In z (map literal_var learnt) \/
        In z (map literal_var
                (resolve_new_lits a c (analyze_tags S R learnt)))).
      { apply in_app_or in Hz2. destruct Hz2 as [Hz2|Hz2].
        - destruct Hz2 as [->|Hz2];
            [left; reflexivity|right; left; exact Hz2].
        - apply in_app_or in Hz2.
          destruct Hz2 as [Hz2|Hz2];
            [right; right; left; exact Hz2|
             right; right; right; exact Hz2]. }
      destruct Hz1 as [Hz1 | Hz1].
      + (* z survives in S *)
        apply In_zremove_iff in Hz1. destruct Hz1 as [HzS Hzx].
        destruct Hz2' as [-> | [HzR | [HzL | HzNew]]].
        * exact (Hzx eq_refl).
        * exact (HdisS z HzS (in_or_app _ _ _ (or_introl HzR))).
        * exact (HdisS z HzS (in_or_app _ _ _ (or_intror HzL))).
        * destruct (HnewLvar_char z HzNew) as (_ & Hzf).
          destruct (Hfresh_notin z Hzf) as (HnS & _ & _).
          exact (HnS HzS).
      + (* z is a fresh current-level variable *)
        destruct (HnewS_char z Hz1) as [m [Hmc [Hvm [Hlevz Hzf]]]].
        destruct (Hfresh_notin z Hzf) as (HnS & HnR & HnL).
        destruct Hz2' as [-> | [HzR | [HzL | HzNew]]].
        * exact (HnS HinS).
        * exact (HnR HzR).
        * exact (HnL HzL).
        * (* both fresh: the level split separates them *)
          destruct (HnewLvar_char z HzNew) as ([dy [Hzdy Hdy']] & _).
          assert (dy = current_level a) by congruence. lia.
Qed.

Lemma analyze_resolve_step :
  forall (F : cnf) (a : cdcl_view) (S R : list Z) (learnt : clause)
         (x : Z) (c : clause),
  closed_levels a ->
  (forall x' b, assignment a x' = Some b -> level_of a x' = Some 0 ->
     entails_clause F [satisfying_literal x' b]) ->
  analyze_inv F a S R learnt ->
  In x S ->
  reason_of a x = Some c ->
  reason_valid a x c ->
  entails_clause F c ->
  NoDup (map literal_var c) ->
  (forall s, In s S -> s <> x -> rank_lt a s x) ->
  analyze_inv F a (resolve_S a x c S R learnt) (x :: R)
              (resolve_learnt a c S R learnt).
Proof.
  intros F a S R learnt x c Hcl Hpre Hinv HinS Hreason Hrv Hentc Hndc
    Hscan.
  destruct Hcl as [_ [Hbound _]].
  destruct Hinv as (Hent & Hnd & HlevS & HassS & HlevR & HrankR & HlevL
                    & HfalseL).
  unfold analyze_tags in Hnd.
  assert (HndS : NoDup S)
    by (eapply NoDup_app_remove_r; exact Hnd).
  assert (HndRV : NoDup (R ++ map literal_var learnt))
    by (eapply NoDup_app_remove_l; exact Hnd).
  assert (HndR : NoDup R)
    by (eapply NoDup_app_remove_r; exact HndRV).
  assert (HndL : NoDup (map literal_var learnt))
    by (eapply NoDup_app_remove_l; exact HndRV).
  assert (HdisS : forall z, In z S ->
    ~ In z (R ++ map literal_var learnt))
    by (intros z Hz; eapply NoDup_app_disjoint; [exact Hnd|exact Hz]).
  assert (HdisRL : forall z, In z R -> ~ In z (map literal_var learnt))
    by (intros z Hz; eapply NoDup_app_disjoint; [exact HndRV|exact Hz]).
  assert (Htags_iff : forall z,
    In z (analyze_tags S R learnt) <->
    In z S \/ In z R \/ In z (map literal_var learnt)).
  { intros z. unfold analyze_tags. rewrite ! in_app_iff. tauto. }
  assert (Hfresh_notin : forall z,
    zmem z (analyze_tags S R learnt) = false ->
    ~ In z S /\ ~ In z R /\ ~ In z (map literal_var learnt)).
  { intros z Hz. apply zmem_false_iff in Hz.
    split; [|split]; intro Hc0; apply Hz; apply Htags_iff; tauto. }
  destruct Hrv as [b [d [rx [Hass [Hlev [Hrank [Hsat Hothers]]]]]]].
  assert (Hinj : clause_var_injective c)
    by (apply NoDup_map_var_injective; exact Hndc).
  assert (Hlevx : level_of a x = Some (current_level a))
    by (rewrite Forall_forall in HlevS; exact (HlevS x HinS)).
  (* an unresolved side variable of the reason clause is never an
     already-resolved variable (trail-order argument, see the header) *)
  assert (HnotR : forall m, In m c -> literal_var m <> x ->
    ~ In (literal_var m) R).
  { intros m Hm Hmx HinR.
    destruct (Hothers m Hm Hmx)
      as [_ [dy [ry [_ [Hranky [_ Hry]]]]]].
    rewrite Forall_forall in HrankR.
    destruct (HrankR _ HinR x HinS) as [r1 [r2 [Hr1 [Hr2 Hlt]]]].
    assert (Hr1x : r1 = rx) by congruence.
    assert (Hr2y : r2 = ry) by congruence.
    subst r1 r2. lia. }
  (* a current-level variable is never a learnt-clause variable *)
  assert (HcurnotL : forall z,
    level_of a z = Some (current_level a) ->
    ~ In z (map literal_var learnt)).
  { intros z Hz HinL.
    rewrite in_map_iff in HinL. destruct HinL as [l' [Hvl' Hl'in]].
    rewrite Forall_forall in HlevL.
    destruct (HlevL l' Hl'in) as [d0 [Hld0 Hd0]].
    rewrite Hvl' in Hld0.
    assert (d0 = current_level a) by congruence. lia. }
  (* a below-current variable is never in a current-level-only list *)
  assert (Hlevel_notin : forall (P : list Z) z dy,
    Forall (fun y => level_of a y = Some (current_level a)) P ->
    level_of a z = Some dy -> dy < current_level a -> ~ In z P).
  { intros P z dy HP Hz Hdy HinP.
    rewrite Forall_forall in HP.
    pose proof (HP z HinP) as Hz'.
    assert (dy = current_level a) by congruence. lia. }
  (* the non-pivot literals of the reason clause *)
  assert (Hcfacts : forall m, In m c -> literal_var m <> x ->
    exists b'' dy, assignment a (literal_var m) = Some b'' /\
      m = falsified_literal (literal_var m) b'' /\
      level_of a (literal_var m) = Some dy /\
      0 <= dy <= current_level a).
  { intros m Hm Hmx.
    destruct (Hothers m Hm Hmx)
      as [Hmfalse [dy [ry [Hlevy [Hranky [Hdyd Hry]]]]]].
    destruct (eval_partial_false_shape _ _ Hmfalse)
      as [b'' [Hassy Hshape]].
    exists b'', dy. repeat split; try assumption.
    - exact (proj1 (Hbound _ _ _ Hassy Hlevy)).
    - exact (proj2 (Hbound _ _ _ Hassy Hlevy)). }
  (* characterization of the newly tagged current-level variables *)
  assert (HnewS_char : forall y,
    In y (resolve_new_S a c (analyze_tags S R learnt)) ->
    exists m, In m c /\ literal_var m = y /\
      level_of a y = Some (current_level a) /\
      zmem y (analyze_tags S R learnt) = false).
  { intros y Hy. unfold resolve_new_S in Hy.
    apply filter_In in Hy. destruct Hy as [Hy Hz].
    apply negb_true_iff in Hz.
    rewrite in_map_iff in Hy. destruct Hy as [m [Hvm Hmf]].
    apply filter_In in Hmf. destruct Hmf as [Hmc Hb].
    apply at_current_level_b_true_iff in Hb. rewrite Hvm in Hb.
    exists m. repeat split; assumption. }
  assert (HnewS_side : forall y,
    In y (resolve_new_S a c (analyze_tags S R learnt)) ->
    exists m, In m c /\ literal_var m = y /\ literal_var m <> x).
  { intros y Hy.
    destruct (HnewS_char y Hy) as [m [Hmc [Hvm [_ Hzf]]]].
    destruct (Hfresh_notin y Hzf) as (HnS & _ & _).
    exists m. split; [exact Hmc|]. split; [exact Hvm|].
    intro Hmx. apply HnS. rewrite <- Hvm, Hmx. exact HinS. }
  (* characterization of the newly collected lower-level literals *)
  assert (HnewL_char : forall l,
    In l (resolve_new_lits a c (analyze_tags S R learnt)) ->
    In l c /\ (exists dy, level_of a (literal_var l) = Some dy /\
                          0 < dy < current_level a) /\
    zmem (literal_var l) (analyze_tags S R learnt) = false).
  { intros l Hl. unfold resolve_new_lits in Hl.
    apply filter_In in Hl. destruct Hl as [Hlc Hb].
    apply andb_prop in Hb. destruct Hb as [Hb1 Hb2].
    apply negb_true_iff in Hb2.
    apply below_current_b_true_iff in Hb1.
    split; [ | split ]; assumption. }
  assert (HnewLvar_char : forall z,
    In z (map literal_var
            (resolve_new_lits a c (analyze_tags S R learnt))) ->
    (exists dy, level_of a z = Some dy /\ 0 < dy < current_level a) /\
    zmem z (analyze_tags S R learnt) = false).
  { intros z Hz. rewrite in_map_iff in Hz.
    destruct Hz as [l [Hvl Hl]]. subst z.
    destruct (HnewL_char l Hl) as (_ & Hlev' & Hzm).
    split; assumption. }
  (* (1) the entailment *)
  assert (E1 : entails_clause F
    (resolve_learnt a c S R learnt
       ++ map (fun y => literal_neg (view_lit a y))
              (resolve_S a x c S R learnt)))
    by (eapply analyze_resolve_entails; eassumption).
  (* pieces for (2): NoDup of the two fresh contributions *)
  assert (HndnewSv : NoDup (resolve_new_S a c (analyze_tags S R learnt)))
    by (unfold resolve_new_S; apply NoDup_filter;
        apply NoDup_map_filter; exact Hndc).
  assert (HndnewL : NoDup
      (map literal_var (resolve_new_lits a c (analyze_tags S R learnt))))
    by (unfold resolve_new_lits; apply NoDup_map_filter; exact Hndc).
  (* (2) NoDup of the whole new tag set *)
  assert (E2 : NoDup (analyze_tags (resolve_S a x c S R learnt) (x :: R)
                        (resolve_learnt a c S R learnt)))
    by (apply analyze_resolve_tags_nodup; assumption).
  (* (3) all of the new S is at the current level *)
  assert (E3 : Forall (fun y => level_of a y = Some (current_level a))
                 (resolve_S a x c S R learnt)).
  { rewrite Forall_forall. intros z Hz. unfold resolve_S in Hz.
    apply in_app_or in Hz. destruct Hz as [Hz|Hz].
    - apply In_zremove_iff in Hz. destruct Hz as [Hz _].
      rewrite Forall_forall in HlevS. exact (HlevS z Hz).
    - destruct (HnewS_char z Hz) as [m [_ [_ [Hlev' _]]]]. exact Hlev'. }
  (* (4) all of the new S is assigned *)
  assert (E4 : Forall (fun y => exists b0, assignment a y = Some b0)
                 (resolve_S a x c S R learnt)).
  { rewrite Forall_forall. intros z Hz. unfold resolve_S in Hz.
    apply in_app_or in Hz. destruct Hz as [Hz|Hz].
    - apply In_zremove_iff in Hz. destruct Hz as [Hz _].
      rewrite Forall_forall in HassS. exact (HassS z Hz).
    - destruct (HnewS_side z Hz) as [m [Hmc [Hvm Hmx]]].
      destruct (Hcfacts m Hmc Hmx) as (b'' & dy & Hassy & _).
      exists b''. rewrite <- Hvm. exact Hassy. }
  (* (5) the resolved set stays at the current level *)
  assert (E5 : Forall (fun y => level_of a y = Some (current_level a))
                 (x :: R))
    by (constructor; [exact Hlevx | exact HlevR]).
  (* (6) the resolved set sits strictly above the pending set in trail
     order *)
  assert (E6 : Forall (fun r => forall s,
                 In s (resolve_S a x c S R learnt) -> rank_lt a s r)
                 (x :: R)).
  { constructor.
    - (* the fresh member [x] *)
      intros s Hs. unfold resolve_S in Hs.
      apply in_app_or in Hs. destruct Hs as [Hs|Hs].
      + apply In_zremove_iff in Hs. destruct Hs as [HsS Hsx].
        exact (Hscan s HsS Hsx).
      + destruct (HnewS_side s Hs) as [m [Hmc [Hvm Hmx]]].
        destruct (Hothers m Hmc Hmx)
          as [_ [dy [ry [_ [Hranky [_ Hry]]]]]].
        unfold rank_lt. rewrite <- Hvm.
        exists ry, rx.
        split; [exact Hranky | split; [exact Hrank | exact Hry]].
    - (* the old members of R, by transitivity through [x] *)
      rewrite Forall_forall. intros r HrR s Hs.
      rewrite Forall_forall in HrankR.
      unfold resolve_S in Hs. apply in_app_or in Hs.
      destruct Hs as [Hs|Hs].
      + apply In_zremove_iff in Hs. destruct Hs as [HsS _].
        exact (HrankR r HrR s HsS).
      + destruct (HnewS_side s Hs) as [m [Hmc [Hvm Hmx]]].
        destruct (Hothers m Hmc Hmx)
          as [_ [dy [ry [_ [Hranky [_ Hry]]]]]].
        destruct (HrankR r HrR x HinS) as [r1 [r2 [Hr1 [Hr2 Hlt]]]].
        assert (Hr1x : r1 = rx) by congruence. subst r1.
        unfold rank_lt. rewrite <- Hvm.
        exists ry, r2.
        split; [exact Hranky | split; [exact Hr2 | lia]]. }
  (* (7) all of the new learnt is strictly below the current level *)
  assert (E7 : Forall (fun l => exists d0,
                 level_of a (literal_var l) = Some d0 /\
                 0 < d0 < current_level a)
                 (resolve_learnt a c S R learnt)).
  { rewrite Forall_forall. intros l Hl. unfold resolve_learnt in Hl.
    apply in_app_or in Hl. destruct Hl as [Hl|Hl].
    - rewrite Forall_forall in HlevL. exact (HlevL l Hl).
    - destruct (HnewL_char l Hl) as (_ & Hlev' & _). exact Hlev'. }
  (* (8) all of the new learnt is false *)
  assert (E8 : clause_false (assignment a)
                 (resolve_learnt a c S R learnt)).
  { intros l Hl. unfold resolve_learnt in Hl.
    apply in_app_or in Hl. destruct Hl as [Hl|Hl].
    - exact (HfalseL l Hl).
    - destruct (HnewL_char l Hl) as (Hlc & [d0 [Hld0 Hd0]] & _).
      assert (Hlx : literal_var l <> x).
      { intro Hc0. rewrite Hc0 in Hld0.
        rewrite Hlevx in Hld0. injection Hld0 as Heq0. lia. }
      destruct (Hothers l Hlc Hlx) as [Hlf _]. exact Hlf. }
  exact (conj E1 (conj E2 (conj E3 (conj E4 (conj E5 (conj E6 (conj E7
          E8))))))).
Qed.

(** ----- the exit certificate ----- *)

(** When the pending set has shrunk to the single first-UIP variable,
    the resolvent is the learned clause and it satisfies the S3 exit
    certificate: sound, variable-distinct (the invariant's
    tag-set [NoDup] hands it over), all-false, head at the current level,
    tail strictly below.  The resolved set [R] merely passes through. *)
Lemma analyze_exit : forall (F : cnf) (a : cdcl_view) (uip : Z)
                            (R : list Z) (learnt : clause),
  analyze_inv F a [uip] R learnt ->
  uip_exit_cert F a (literal_neg (view_lit a uip) :: learnt).
Proof.
  intros F a uip R learnt Hinv.
  destruct Hinv as (Hent & Hnd & HlevS & HassS & _ & _ & HlevL &
                    HfalseL).
  assert (Hlevu : level_of a uip = Some (current_level a))
    by (exact (Forall_inv HlevS)).
  destruct (Forall_inv HassS) as [b Hassu].
  unfold analyze_tags in Hnd. cbn [app] in Hnd.
  split; [|split].
  - split.
    + (* entailment, via the permutation learnt ++ [k] ~ k :: learnt *)
      apply entails_clause_perm
        with (c := learnt ++ [literal_neg (view_lit a uip)]).
      * apply Permutation_sym. apply Permutation_cons_append.
      * cbn [map] in Hent. exact Hent.
    + (* every literal of the learned clause is false *)
      intros l Hl. destruct Hl as [Heq | Hl].
      * subst l. exact (neg_view_lit_false a uip b Hassu).
      * exact (HfalseL l Hl).
  - (* variable-distinctness of the learned clause *)
    cbn [map]. rewrite literal_var_neg, view_lit_var.
    inversion Hnd as [|? ? Hnotin Hnd']; subst.
    constructor.
    + intro Hc0. apply Hnotin. apply in_or_app. right. exact Hc0.
    + eapply NoDup_app_remove_l. exact Hnd'.
  - exists (literal_neg (view_lit a uip)), learnt.
    split; [reflexivity|]. split.
    + rewrite literal_var_neg, view_lit_var. exact Hlevu.
    + eapply Forall_impl; [|exact HlevL].
      intros k [dk [Hldk Hdk]]. exists dk. split; [exact Hldk|lia].
Qed.

(** ----- variable-distinctness suppliers for reason clauses ----- *)

(** Real (database) reason: [db_wf]/[obj_wf] already carry packed
    variable-distinctness; transport it through [denote_obj]
    ([analyze_resolve_step] and [minimization_sound]
    demand [NoDup (map literal_var c)] of the reason clause, and for a
    DB-resident reason this is where it comes from). *)
Lemma obj_wf_nodup_vars : forall (n : Z) (co : clause_obj),
  obj_wf n co -> NoDup (map literal_var (denote_obj co)).
Proof.
  intros n co Hwf. destruct Hwf as (_ & _ & Hnd).
  unfold denote_obj. apply lits_denote_nodup_vars. exact Hnd.
Qed.

(** Tagged (binary) reason [q; ~p]: variable-distinctness reduces to the
    packed variable disequality, which the use site supplies from the
    same-level/different-variable facts of the propagation. *)
Lemma tagged_reason_nodup_vars : forall q p : Z,
  lit_var_c q <> lit_var_c p ->
  NoDup (map literal_var [lit_denote q; literal_neg (lit_denote p)]).
Proof.
  intros q p Hne. cbn [map].
  rewrite literal_var_neg, ! lit_var_c_denote.
  constructor.
  - intros [He|[]]. apply Hne. symmetry. exact He.
  - constructor; [intros []|constructor].
Qed.

(** ----- conflict-clause minimization ----- *)

(** [T] is a valid redundancy witness set with respect to the seen set
    [S0] (analyze's tagged variables): every member has a reason clause
    all of whose side literals are level-0, seen, or again in [T]. *)
Definition removable_witness
    (a : cdcl_view) (S0 T : list Z) : Prop :=
  forall x, In x T -> exists c, reason_of a x = Some c /\
    (forall l, In l c -> literal_var l <> x ->
       level_of a (literal_var l) = Some 0 \/
       In (literal_var l) S0 \/ In (literal_var l) T).

(** Every variable contributed by a successful removability DFS is assigned
    strictly below the current decision level, with a concrete trail rank.
    Keeping the level and rank together is what lets a later minimization step
    shrink the DFS base from the whole tag set to its still-live learnt suffix. *)
Definition assigned_below_current (a : cdcl_view) (x : Z) : Prop :=
  exists d r,
    level_of a x = Some d /\
    assignment_rank a x = Some r /\
    d < current_level a.

(** The well-founded core: under any model of [F] that falsifies every
    kept literal, the trail literal of every level-0 / seen-but-kept /
    witnessed variable is true.  Strong induction on [assignment_rank];
    the rank strictly decreases through [reason_valid]'s side literals
    (TAG-IMPLIED). *)
Lemma removable_trail_lit_true :
  forall (F : cnf) (a : cdcl_view) (S0 T : list Z) (kept : clause),
  grounded_at a ->
  (forall x b, assignment a x = Some b -> level_of a x = Some 0 ->
     entails_clause F [satisfying_literal x b]) ->
  (forall x b, In x S0 -> ~ In x T -> assignment a x = Some b ->
     entails_clause (cnf_with_units F (map literal_neg kept))
       [satisfying_literal x b]) ->
  removable_witness a S0 T ->
  (forall x c, In x T -> reason_of a x = Some c ->
     entails_clause F c) ->
  (forall x c, In x T -> reason_of a x = Some c ->
     NoDup (map literal_var c)) ->
  forall (r : nat) (x : Z) (b : bool) (rho : valuation),
    (level_of a x = Some 0 \/ (In x S0 /\ ~ In x T) \/ In x T) ->
    assignment a x = Some b ->
    assignment_rank a x = Some r ->
    models rho F ->
    (forall k, In k kept -> eval_literal rho k = false) ->
    eval_literal rho (satisfying_literal x b) = true.
Proof.
  intros F a S0 T kept Hg Hpre HS0 Hw HTe HTi r.
  induction r using lt_wf_ind.
  rename H into IH.
  intros x b rho Hscope Hass Hrank Hmod Hkf.
  destruct Hscope as [Hlev0 | [[HinS0 HnotT] | HinT]].
  - (* level 0: directly F-entailed *)
    destruct (Hpre x b Hass Hlev0 rho Hmod) as [k [Hk Hkt]].
    destruct Hk as [Heq|[]]. subst k. exact Hkt.
  - (* seen and kept: entailed by F plus the negated kept literals *)
    assert (Hmu : models rho (cnf_with_units F (map literal_neg kept))).
    { apply models_clause_units_intro; [exact Hmod|].
      rewrite Forall_forall. intros k' Hk'.
      rewrite in_map_iff in Hk'. destruct Hk' as [k0 [Hk0eq Hk0]].
      subst k'. rewrite eval_literal_neg. rewrite (Hkf k0 Hk0).
      reflexivity. }
    destruct (HS0 x b HinS0 HnotT Hass rho Hmu) as [k [Hk Hkt]].
    destruct Hk as [Heq|[]]. subst k. exact Hkt.
  - (* witnessed: recurse through the reason clause *)
    destruct (Hw x HinT) as [c [Hreason Hants]].
    destruct (Hg x b Hass) as [d [rx [Hlev [Hrank' Horigin]]]].
    (* The NULL arm cannot occur here because [Hreason] supplies a reason. *)
    destruct Horigin as [Hnone | [c' [Hreason' Hrv]]].
    + rewrite Hnone in Hreason. discriminate.
    + assert (Hcc : c' = c) by congruence. subst c'.
      destruct Hrv
        as [b' [d' [rx' [Hass' [Hlev' [Hrank'' [Hsat Hothers]]]]]]].
      assert (Hbb : b' = b) by congruence. subst b'.
      assert (Hrr : rx' = r) by congruence. subst rx'.
      destruct (HTe x c HinT Hreason rho Hmod) as [m [Hm Hmt]].
      destruct (Z.eq_dec (literal_var m) x) as [Hmx|Hmx].
      * (* the model satisfies the reason at the propagated literal *)
        assert (Hinj : clause_var_injective c)
          by (apply NoDup_map_var_injective;
              exact (HTi x c HinT Hreason)).
        assert (Hme : m = satisfying_literal x b)
          by (exact (clause_var_injective_var_lit c x b m Hinj Hsat
                       Hm Hmx)).
        subst m. exact Hmt.
      * (* a side literal: its variable has strictly smaller rank *)
        destruct (Hothers m Hm Hmx)
          as [Hmfalse [dy [ry [Hlevy [Hranky [Hdyd Hry]]]]]].
        destruct (eval_partial_false_shape _ _ Hmfalse)
          as [b'' [Hassy Hshape]].
        assert (Hscope' : level_of a (literal_var m) = Some 0 \/
                (In (literal_var m) S0 /\ ~ In (literal_var m) T) \/
                In (literal_var m) T).
        { destruct (Hants m Hm Hmx) as [Hh|[Hh|Hh]].
          - left; exact Hh.
          - destruct (List.in_dec Z.eq_dec (literal_var m) T)
              as [Hyt|Hyt].
            + right; right; exact Hyt.
            + right; left; split; assumption.
          - right; right; exact Hh. }
        pose proof (IH ry Hry (literal_var m) b'' rho Hscope' Hassy
                      Hranky Hmod Hkf) as Hsy.
        exfalso.
        rewrite Hshape, <- literal_neg_satisfying, eval_literal_neg,
          Hsy in Hmt.
        discriminate.
Qed.

(** Removing the [T]-witnessed literals from an entailed, all-false
    learned clause preserves [F]-entailment, which justifies the C
    compaction in [solver_analyze].  Hypotheses: the level-0 prefix is
    [F]-entailed; every seen-and-kept variable's trail
    literal is entailed by [F] plus the negations of the kept literals
    (TAG-IMPLIED, established by the analyze derivation); [T] is a valid
    witness set whose reasons are entailed and variable-distinct.

    USAGE (the non-obvious instantiation): instantiate
    [S0 := map literal_var kept], NOT the whole
    C [tags] set -- with the full tag set the TAG-IMPLIED hypothesis is
    circular.  Two-stage discharge: (i) for [x] a variable of [kept] the
    TAG-IMPLIED hypothesis is trivial ([satisfying_literal x b] is the
    negation of a kept literal, so it is one of the added units);
    (ii) [removable_witness a (map literal_var kept) T] follows from the
    DFS witness because every [T]-variable sits strictly below the
    current level, so a tagged antecedent can only be a learnt-clause
    variable -- kept (hence in [S0]) or removed (hence in [T]) -- and
    never a resolved current-level variable.  The C's per-literal
    rollback in [solver_lit_removable] restores [tags] to [top] on
    a failed call and contributes nothing to [T]; only successful calls
    grow [T]. *)
Lemma minimization_sound :
  forall (F : cnf) (a : cdcl_view) (S0 T : list Z)
         (learnt kept removed : clause),
  grounded_at a ->
  (forall x b, assignment a x = Some b -> level_of a x = Some 0 ->
     entails_clause F [satisfying_literal x b]) ->
  (forall x b, In x S0 -> ~ In x T -> assignment a x = Some b ->
     entails_clause (cnf_with_units F (map literal_neg kept))
       [satisfying_literal x b]) ->
  removable_witness a S0 T ->
  (forall x c, In x T -> reason_of a x = Some c ->
     entails_clause F c) ->
  (forall x c, In x T -> reason_of a x = Some c ->
     NoDup (map literal_var c)) ->
  Permutation learnt (kept ++ removed) ->
  Forall (fun l => In (literal_var l) T) removed ->
  clause_false (assignment a) learnt ->
  entails_clause F learnt ->
  entails_clause F kept.
Proof.
  intros F a S0 T learnt kept removed
    Hg Hpre HS0 Hw HTe HTi Hperm Hrem Hfalse Hent rho Hmod.
  destruct (existsb (fun k => eval_literal rho k) kept) eqn:Hex.
  - (* some kept literal is already true *)
    apply existsb_exists in Hex. destruct Hex as [k [Hk Hkt]].
    exists k. split; assumption.
  - (* all kept literals false: the witnessed removed literals cannot
       carry the entailment either -- contradiction *)
    assert (Hkf : forall k, In k kept -> eval_literal rho k = false).
    { intros k Hk. destruct (eval_literal rho k) eqn:E; [|reflexivity].
      exfalso.
      assert (Hex' : existsb (fun k0 => eval_literal rho k0) kept
                     = true).
      { apply existsb_exists. exists k. split; assumption. }
      congruence. }
    destruct (Hent rho Hmod) as [l [Hl Hlt]].
    pose proof (Permutation_in _ Hperm Hl) as Hl'.
    apply in_app_or in Hl'. destruct Hl' as [Hlk | Hlr].
    + exists l. split; assumption.
    + exfalso.
      rewrite Forall_forall in Hrem.
      pose proof (Hrem l Hlr) as HxT.
      pose proof (Hfalse l Hl) as Hlf.
      destruct (eval_partial_false_shape _ _ Hlf) as [b [Hass Hshape]].
      destruct (Hg _ _ Hass) as [d [rx [Hlev [Hrank _]]]].
      pose proof (removable_trail_lit_true F a S0 T kept Hg Hpre HS0
                    Hw HTe HTi rx (literal_var l) b rho
                    (or_intror (or_intror HxT)) Hass Hrank Hmod Hkf)
        as Hst.
      rewrite Hshape, <- literal_neg_satisfying, eval_literal_neg,
        Hst in Hlt.
      discriminate.
Qed.

(** ----- the lit_removable DFS invariant ----- *)

(** Mid-run shape of [solver_lit_removable]'s iterative DFS: [dn] holds
    the expanded variables, [stk] the pending ones; every expanded
    variable's reason has all its side variables level-0, seen, expanded,
    or still pending. *)
Definition dfs_witness
    (a : cdcl_view) (S0 dn stk : list Z) : Prop :=
  forall x, In x dn -> exists c, reason_of a x = Some c /\
    (forall l, In l c -> literal_var l <> x ->
       level_of a (literal_var l) = Some 0 \/
       In (literal_var l) S0 \/
       In (literal_var l) dn \/ In (literal_var l) stk).

(** Expanding the top pending variable preserves the invariant: its
    antecedents must all be level-0 / seen / already-expanded / on the
    (possibly grown) new stack. *)
Lemma dfs_witness_extend :
  forall (a : cdcl_view) (S0 dn stk stk' : list Z) (v : Z) (c : clause),
  dfs_witness a S0 dn (v :: stk) ->
  reason_of a v = Some c ->
  (forall l, In l c -> literal_var l <> v ->
     level_of a (literal_var l) = Some 0 \/
     In (literal_var l) S0 \/
     In (literal_var l) (v :: dn) \/ In (literal_var l) stk') ->
  incl stk stk' ->
  dfs_witness a S0 (v :: dn) stk'.
Proof.
  intros a S0 dn stk stk' v c Hdfs Hr Hc Hincl x Hx.
  destruct Hx as [<- | Hx].
  - exists c. split; [exact Hr|]. exact Hc.
  - destruct (Hdfs x Hx) as [c' [Hr' Hc']].
    exists c'. split; [exact Hr'|].
    intros l Hl Hvl.
    destruct (Hc' l Hl Hvl) as [H|[H|[H|H]]].
    + left; exact H.
    + right; left; exact H.
    + right; right; left; right; exact H.
    + destruct H as [Heq | H].
      * right; right; left; left; exact Heq.
      * right; right; right; apply Hincl; exact H.
Qed.

(** An exhausted DFS yields a valid redundancy witness set. *)
Lemma dfs_witness_complete :
  forall (a : cdcl_view) (S0 dn : list Z),
  dfs_witness a S0 dn [] -> removable_witness a S0 dn.
Proof.
  intros a S0 dn H x Hx.
  destruct (H x Hx) as [c [Hr Hc]].
  exists c. split; [exact Hr|].
  intros l Hl Hvl.
  destruct (Hc l Hl Hvl) as [Hh|[Hh|[Hh|Hh]]].
  - left; exact Hh.
  - right; left; exact Hh.
  - right; right; exact Hh.
  - destruct Hh.
Qed.

(* ================= SECTION msat_s7_heur ================= *)

(** * S7 -- variable order heap and the random seed.

    Two independent pure layers.

    (1) The order heap.  MiniSat keeps a binary max-heap [s->order] of
    variables keyed by the (double) activity, plus an inverse index
    [s->orderpos] with [-1] meaning "not in the heap".  The heap ORDER is
    deliberately NOT modelled: the key comparisons are IEEE doubles and
    carry no logical content, and nothing in the correctness argument
    depends on which variable is popped.  What the correctness argument
    does need is (a) the heap/orderpos bijection ([heap_wf]) so that the
    sift/pop/insert code is memory-safe and orderpos stays a real inverse,
    and (b) the ORD-INV coverage property ([heap_covers]): a
    variable missing from the heap is assigned AND already propagated.
    ORD-INV is what makes [order_select] returning [var_Undef] mean "the
    assignment is total", which is the SAT endgame's first step.

    (2) The random seed.  [drand]/[irand] run the multiplicative
    recurrence [seed := seed * 1389796 mod 2147483647] in a double.  Here
    we prove the integer shadow: the recurrence never reaches 0 (which
    would freeze the generator) and the [irand] scaling stays in range.
    The floating-point binding is deferred by design. *)

(** ----- small generic helpers ----- *)

Lemma Z_In_dec : forall (x : Z) (l : list Z), {In x l} + {~ In x l}.
Proof.
  intros x l. induction l as [|a l IH].
  - right. intros [].
  - destruct (Z.eq_dec a x) as [->|Hne].
    + left. left. reflexivity.
    + destruct IH as [Hin|Hout].
      * left. right. exact Hin.
      * right. intros [He|He]; [apply Hne; exact He | apply Hout; exact He].
Qed.

Lemma In_Znth_ex : forall (A : Type) (l : list A) (d : A) x,
  In x l -> exists i, 0 <= i < Zlength l /\ Znth i l d = x.
Proof.
  intros A l d x. induction l as [|a l IH]; intros Hin.
  - destruct Hin.
  - pose proof (Zlength_nonneg l).
    destruct Hin as [->|Hin].
    + exists 0. rewrite Zlength_cons. split; [lia|].
      rewrite Znth0_cons. reflexivity.
    + destruct (IH Hin) as [i [Hi Hval]].
      exists (i + 1). rewrite Zlength_cons. split; [lia|].
      rewrite Znth_cons by lia.
      replace (i + 1 - 1) with i by lia. exact Hval.
Qed.

(** At a propagation fixpoint every assigned variable, including one still
    present in the decision heap, already occurs below [qhead].  This is the
    extra carrier needed when [order_select] discards assigned heap roots. *)
Definition assigned_below_qhead
    (n : Z) (assigns trail : list Z) (qhead : Z) : Prop :=
  forall v, 0 <= v < n -> Znth v assigns 0 <> 0 ->
    exists i, 0 <= i < qhead /\ lit_var_c (Znth i trail 0) = v.

Lemma mtrail_wf_assigned_below_qhead : forall n t qhead,
  mtrail_wf n t ->
  qhead = Zlength (mt_trail t) ->
  assigned_below_qhead n (mt_assigns t) (mt_trail t) qhead.
Proof.
  intros n t qhead Hwf Hq v Hv Hassigned.
  pose proof
    (proj1 (mtw_assigned_iff Hwf v Hv) Hassigned) as Hin.
  apply in_map_iff in Hin. destruct Hin as [l [Hvar Hin]].
  destruct (In_Znth_ex Z (mt_trail t) 0 l Hin) as [i [Hi Hlit]].
  exists i. split; [rewrite Hq; exact Hi|].
  rewrite Hlit. exact Hvar.
Qed.

(** ----- [heap_wf] toolbox ----- *)

Lemma heap_wf_orderpos_length : forall n h,
  heap_wf n h -> Zlength (mh_orderpos h) = n.
Proof. intros n h H. apply H. Qed.

Lemma heap_wf_nodup : forall n h, heap_wf n h -> NoDup (mh_heap h).
Proof. intros n h H. apply H. Qed.

Lemma heap_wf_range : forall n h,
  heap_wf n h -> Forall (fun v => 0 <= v < n) (mh_heap h).
Proof. intros n h H. apply H. Qed.

Lemma heap_wf_inverse : forall n h i,
  heap_wf n h -> 0 <= i < Zlength (mh_heap h) ->
  Znth (Znth i (mh_heap h) (-1)) (mh_orderpos h) (-1) = i.
Proof. intros n h i H. apply H. Qed.

Lemma heap_wf_lookup : forall n h v,
  heap_wf n h -> 0 <= v < n ->
  Znth v (mh_orderpos h) (-1) <> -1 ->
  0 <= Znth v (mh_orderpos h) (-1) < Zlength (mh_heap h) /\
  Znth (Znth v (mh_orderpos h) (-1)) (mh_heap h) (-1) = v.
Proof.
  intros n h v Hwf Hv Hne.
  destruct Hwf as (_ & _ & _ & Hop & _).
  destruct (Hop v Hv) as [Hm1|Hgood]; [contradiction|exact Hgood].
Qed.

(** membership in the heap array is exactly "orderpos is not [-1]" *)
Lemma heap_wf_in_iff : forall n h v,
  heap_wf n h -> 0 <= v < n ->
  (In v (mh_heap h) <-> Znth v (mh_orderpos h) (-1) <> -1).
Proof.
  intros n h v Hwf Hv. split.
  - intros Hin.
    destruct (In_Znth_ex Z (mh_heap h) (-1) v Hin) as [i [Hi Hval]].
    pose proof (heap_wf_inverse n h i Hwf Hi) as Hinv.
    rewrite Hval in Hinv. rewrite Hinv. lia.
  - intros Hne.
    destruct (heap_wf_lookup n h v Hwf Hv Hne) as [Hr Heq].
    rewrite <- Heq. apply Znth_In. exact Hr.
Qed.

(** If a well-formed heap only gains members, a variable missing from the
    larger heap was already missing from the smaller one. *)
Lemma heap_wf_incl_missing_mono : forall n h h' v,
  heap_wf n h -> heap_wf n h' -> incl (mh_heap h) (mh_heap h') ->
  0 <= v < n -> Znth v (mh_orderpos h') (-1) = -1 ->
  Znth v (mh_orderpos h) (-1) = -1.
Proof.
  intros n h h' v Hwf Hwf' Hincl Hv Hmissing.
  destruct (Z.eq_dec (Znth v (mh_orderpos h) (-1)) (-1)) as [H|H];
    [exact H|].
  exfalso.
  apply (heap_wf_in_iff n h v Hwf Hv) in H.
  apply Hincl in H.
  apply (heap_wf_in_iff n h' v Hwf' Hv) in H.
  contradiction.
Qed.

(** A well-formed heap that omits one in-range variable has strictly fewer
    than [n] entries.  This is the bounded-growth fact used when reinserting
    an unassigned variable into a potentially full vector. *)
Lemma heap_wf_missing_length : forall n h v,
  0 <= n ->
  heap_wf n h ->
  0 <= v < n ->
  Znth v (mh_orderpos h) (-1) = -1 ->
  Zlength (mh_heap h) < n.
Proof.
  intros n h v Hn Hwf Hv Hmissing.
  assert (Hnotin : ~ In v (mh_heap h)).
  { intro Hin.
    apply (heap_wf_in_iff n h v Hwf Hv) in Hin.
    contradiction. }
  assert (Hnodup : NoDup (v :: mh_heap h)).
  { constructor; [exact Hnotin|apply (heap_wf_nodup n h Hwf)]. }
  assert (Hbounded : forall x, In x (v :: mh_heap h) -> 0 <= x < n).
  { intros x [->|Hin]; [exact Hv|].
    pose proof (heap_wf_range n h Hwf) as Hrange.
    rewrite Forall_forall in Hrange.
    exact (Hrange x Hin). }
  pose proof (NoDup_Z_bounded_length (v :: mh_heap h) n Hn Hnodup Hbounded)
    as Hlen.
  rewrite <- Zlength_correct in Hlen.
  rewrite Zlength_cons in Hlen. lia.
Qed.

Lemma heap_wf_not_in : forall n h v,
  heap_wf n h -> 0 <= v < n ->
  ~ In v (mh_heap h) -> Znth v (mh_orderpos h) (-1) = -1.
Proof.
  intros n h v Hwf Hv Hout.
  destruct (Z.eq_dec (Znth v (mh_orderpos h) (-1)) (-1)) as [E|E];
    [exact E|].
  exfalso. apply Hout. apply (heap_wf_in_iff n h v Hwf Hv). exact E.
Qed.

(** reconstruction principle: all the preservation lemmas go through it *)
Lemma heap_wf_intro : forall n h,
  Zlength (mh_orderpos h) = n ->
  NoDup (mh_heap h) ->
  Forall (fun v => 0 <= v < n) (mh_heap h) ->
  (forall v, 0 <= v < n -> ~ In v (mh_heap h) ->
     Znth v (mh_orderpos h) (-1) = -1) ->
  (forall i, 0 <= i < Zlength (mh_heap h) ->
     Znth (Znth i (mh_heap h) (-1)) (mh_orderpos h) (-1) = i) ->
  heap_wf n h.
Proof.
  intros n h H1 H2 H3 H4 H5.
  unfold heap_wf. split; [exact H1|]. split; [exact H2|].
  split; [exact H3|]. split; [|exact H5].
  intros v Hv.
  destruct (Z_In_dec v (mh_heap h)) as [Hin|Hout].
  - right.
    destruct (In_Znth_ex Z (mh_heap h) (-1) v Hin) as [i [Hi Hval]].
    pose proof (H5 i Hi) as Hinv. rewrite Hval in Hinv.
    rewrite Hinv. split; [exact Hi|exact Hval].
  - left. apply H4; assumption.
Qed.

(** ----- the ORD-INV consequence: empty heap ==> total assignment ----- *)

Lemma heap_covers_total : forall n h assigns trail qhead,
  heap_wf n h ->
  mh_heap h = [] ->
  heap_covers n h assigns trail qhead ->
  forall v, 0 <= v < n -> Znth v assigns 0 <> 0.
Proof.
  intros n h assigns trail qhead Hwf Hempty Hcov v Hv.
  assert (Hm1 : Znth v (mh_orderpos h) (-1) = -1).
  { apply (heap_wf_not_in n h v Hwf Hv). rewrite Hempty. intros []. }
  destruct (Hcov v Hv Hm1) as [Ha _]. exact Ha.
Qed.


(** ----- [heap_wf] preservation ----- *)

(** sift up / sift down: the heap array is permuted, orderpos is rebuilt as
    its inverse.  Nothing about the ORDER is asserted -- the comparisons are
    IEEE doubles.  Both [order_update] and the sift-down inside
    [order_select] instantiate this. *)

(** Pop: one variable leaves the heap and its orderpos cell is
    set to [-1]; the remaining entries are permuted and reindexed. *)
Lemma heap_wf_pop : forall n h h' v,
  heap_wf n h ->
  0 <= v < n ->
  Permutation (mh_heap h) (v :: mh_heap h') ->
  Zlength (mh_orderpos h') = n ->
  Znth v (mh_orderpos h') (-1) = -1 ->
  (forall u, 0 <= u < n -> u <> v -> ~ In u (mh_heap h') ->
     Znth u (mh_orderpos h') (-1) = -1) ->
  (forall i, 0 <= i < Zlength (mh_heap h') ->
     Znth (Znth i (mh_heap h') (-1)) (mh_orderpos h') (-1) = i) ->
  heap_wf n h'.
Proof.
  intros n h h' v Hwf Hv Hperm Hlen Hpv Hout Hinv.
  assert (Hnd : NoDup (v :: mh_heap h')).
  { apply (Permutation_NoDup Hperm). apply (heap_wf_nodup n h Hwf). }
  apply heap_wf_intro; try assumption.
  - inversion Hnd; assumption.
  - pose proof (heap_wf_range n h Hwf) as Hr.
    rewrite Forall_forall in Hr |- *.
    intros x Hx. apply Hr.
    apply (Permutation_in _ (Permutation_sym Hperm)). right. exact Hx.
  - intros u Hu Hnotin.
    destruct (Z.eq_dec u v) as [->|Hne]; [exact Hpv|].
    apply Hout; assumption.
Qed.

(** Insertion in [order_unassigned]: push at the end of the heap
    array and record the position in orderpos. *)
Lemma heap_wf_insert : forall n h v,
  heap_wf n h ->
  0 <= v < n ->
  Znth v (mh_orderpos h) (-1) = -1 ->
  heap_wf n {| mh_heap := mh_heap h ++ [v];
               mh_orderpos :=
                 replace_Znth v (Zlength (mh_heap h)) (mh_orderpos h) |}.
Proof.
  intros n h v Hwf Hv Hm1.
  pose proof (heap_wf_orderpos_length n h Hwf) as Hlen.
  pose proof (heap_wf_range n h Hwf) as Hrange.
  pose proof (Zlength_nonneg (mh_heap h)) as Hhn.
  assert (Hvop : 0 <= v < Zlength (mh_orderpos h)) by lia.
  assert (Hnotin : ~ In v (mh_heap h)).
  { intros Hin.
    apply (heap_wf_in_iff n h v Hwf Hv) in Hin. contradiction. }
  apply heap_wf_intro; simpl.
  - rewrite Zlength_replace_Znth. exact Hlen.
  - assert (HA : Add v (mh_heap h) (mh_heap h ++ [v])).
    { pose proof (Add_app v (mh_heap h) (@nil Z)) as HAdd.
      rewrite app_nil_r in HAdd. exact HAdd. }
    apply (NoDup_Add HA). split.
    + apply (heap_wf_nodup n h Hwf).
    + exact Hnotin.
  - apply Forall_app. split; [exact Hrange|].
    constructor; [exact Hv|constructor].
  - intros u Hu Hnu.
    assert (Hne : u <> v).
    { intros ->. apply Hnu. apply in_or_app. right. left. reflexivity. }
    assert (Hnh : ~ In u (mh_heap h)).
    { intros Hin. apply Hnu. apply in_or_app. left. exact Hin. }
    rewrite (Znth_replace_Znth_Diff (-1) (mh_orderpos h) v u); try lia.
    apply (heap_wf_not_in n h u Hwf Hu Hnh).
  - intros i Hi.
    rewrite Zlength_app in Hi. rewrite Zlength_cons, Zlength_nil in Hi.
    destruct (Z.eq_dec i (Zlength (mh_heap h))) as [->|Hne].
    + rewrite app_Znth2 by lia.
      replace (Zlength (mh_heap h) - Zlength (mh_heap h)) with 0 by lia.
      rewrite Znth0_cons.
      rewrite Znth_replace_Znth_Same by lia. reflexivity.
    + assert (Hi' : 0 <= i < Zlength (mh_heap h)) by lia.
      rewrite app_Znth1 by lia.
      set (u := Znth i (mh_heap h) (-1)).
      assert (Hin : In u (mh_heap h)) by (apply Znth_In; exact Hi').
      assert (Hune : u <> v) by (intros ->; contradiction).
      assert (Hur : 0 <= u < n).
      { rewrite Forall_forall in Hrange. apply Hrange. exact Hin. }
      rewrite (Znth_replace_Znth_Diff (-1) (mh_orderpos h) v u); try lia.
      apply (heap_wf_inverse n h i Hwf Hi').
Qed.

(** ----- [heap_covers] preservation ----- *)

(** any change that only ADDS variables to the heap preserves coverage
    (insertion, and the sift steps, which move entries but keep the set). *)
Lemma heap_covers_weaken_heap : forall n h h' assigns trail qhead,
  heap_covers n h assigns trail qhead ->
  (forall v, 0 <= v < n -> Znth v (mh_orderpos h') (-1) = -1 ->
     Znth v (mh_orderpos h) (-1) = -1) ->
  heap_covers n h' assigns trail qhead.
Proof.
  intros n h h' assigns trail qhead Hcov Hmono v Hv Hm1.
  apply Hcov; [exact Hv|]. apply Hmono; assumption.
Qed.

Lemma heap_covers_qhead_mono : forall n h assigns trail qhead qhead',
  heap_covers n h assigns trail qhead ->
  qhead <= qhead' ->
  heap_covers n h assigns trail qhead'.
Proof.
  intros n h assigns trail qhead qhead' Hcov Hle v Hv Hm1.
  destruct (Hcov v Hv Hm1) as [Ha [i [Hi Hval]]].
  split; [exact Ha|]. exists i. split; [lia|exact Hval].
Qed.

(** [enqueue] + [propagate]'s [qhead++]: the trail only grows at the end,
    [assigns] cells only go from unassigned to assigned. *)
Lemma heap_covers_enqueue : forall n h assigns assigns' trail trail' qhead qhead',
  heap_covers n h assigns trail qhead ->
  qhead <= qhead' ->
  (forall v, 0 <= v < n -> Znth v assigns 0 <> 0 -> Znth v assigns' 0 <> 0) ->
  (forall i, 0 <= i < qhead -> Znth i trail' 0 = Znth i trail 0) ->
  heap_covers n h assigns' trail' qhead'.
Proof.
  intros n h assigns assigns' trail trail' qhead qhead'
         Hcov Hq Hassign Htrail v Hv Hm1.
  destruct (Hcov v Hv Hm1) as [Ha [i [Hi Hval]]].
  split; [apply Hassign; assumption|].
  exists i. split; [lia|]. rewrite Htrail by lia. exact Hval.
Qed.

(** Pure carriers for the in-place heap loops.  The saved value [x] lives in
    a C local while one concrete array position is a logical hole.  Removing
    that one cell and adding [x] back preserves the original multiset even
    though the cell currently at the hole can be a duplicate. *)
Definition list_without_Znth (i : Z) (l : list Z) : list Z :=
  sublist 0 i l ++ sublist (i + 1) (Zlength l) l.

Definition order_heap_wf (n : Z) (heap orderpos : list Z) : Prop :=
  heap_wf n {| mh_heap := heap; mh_orderpos := orderpos |}.

(** The [NoDup] and [Forall]-range conjuncts on [origin] are what make the
    loop-exit write ([heap[hole] := x; orderpos[x] := hole]) re-establish
    [order_heap_wf]; see [order_heap_one_hole_close].  Both are carried on
    [origin] rather than on [heap] because [origin] is the ghost anchor:
    [Permutation] transports them to [x :: list_without_Znth hole heap], and
    the cell sitting at [hole] is junk that neither must constrain.

    Without [NoDup origin] the lifted [x] may duplicate a live entry --
    [order_heap_one_hole 4 [3;3] 3 0 [0;3] [-1;-1;-1;1]] holds but closes to
    the heap [[3;3]], refuting [NoDup].  Without [Forall (0 <= _ < n) origin]
    a NEGATIVE cell survives the forward inverse below, because [Znth] at a
    negative index returns the HEAD of the list, not the default: with
    [heap = [7;-3]] and [orderpos = [1;-1]] one has
    [Znth (Znth 1 heap (-1)) orderpos (-1) = Znth (-3) orderpos (-1) = 1].
    Both countermodels are checked in [order_heap_one_hole_cm1_*] /
    [order_heap_one_hole_cm2_*] below.

    Note that [Znth x orderpos (-1)] is deliberately NOT constrained: at the
    [order_select] sift entry it is the STALE pre-truncation index, one past
    the end of the truncated heap, so any
    [heap_wf]-shaped constraint on it would be unsatisfiable there.  The code
    overwrites it at loop exit, which is exactly what [_close] models. *)
Definition order_heap_one_hole
    (n : Z) (origin : list Z) (x hole : Z)
    (heap orderpos : list Z) : Prop :=
  Zlength orderpos = n /\
  Zlength heap = Zlength origin /\
  0 <= hole < Zlength heap /\
  0 <= x < n /\
  NoDup origin /\
  Forall (fun v => 0 <= v < n) origin /\
  Permutation origin (x :: list_without_Znth hole heap) /\
  (forall i, 0 <= i < Zlength heap -> i <> hole ->
     Znth (Znth i heap (-1)) orderpos (-1) = i) /\
  (forall v, 0 <= v < n -> ~ In v origin ->
     Znth v orderpos (-1) = -1).

Definition order_update_pre
    (n v : Z) (heap orderpos : list Z) : Prop :=
  order_heap_wf n heap orderpos /\
  0 <= v < n /\ Znth v orderpos (-1) <> -1.

Definition order_update_loop_inv
    (n v : Z) (origin : list Z) (x i : Z)
    (heap orderpos : list Z) : Prop :=
  0 <= v < n /\ In v origin /\
  order_heap_one_hole n origin x i heap orderpos.

Definition order_update_post
    (n v : Z) (before_heap before_pos after_heap after_pos : list Z) : Prop :=
  order_update_pre n v before_heap before_pos /\
  order_heap_wf n after_heap after_pos /\
  Permutation before_heap after_heap /\
  (forall u, 0 <= u < n ->
     (Znth u before_pos (-1) = -1 <-> Znth u after_pos (-1) = -1)).

Definition order_unassigned_pre
    (n v cap : Z) (heap orderpos : list Z) : Prop :=
  order_heap_wf n heap orderpos /\
  0 <= v < n /\
  0 < cap <= INT_MAX /\ Zlength heap <= cap /\ 2 * n <= INT_MAX.

Definition order_unassigned_post
    (n v before_cap : Z) (before_heap before_pos : list Z)
    (after_cap : Z) (after_heap after_pos : list Z) : Prop :=
  order_heap_wf n after_heap after_pos /\
  before_cap <= after_cap <= INT_MAX /\ Zlength after_heap <= after_cap /\
  ((Znth v before_pos (-1) = -1 /\
    Permutation after_heap (before_heap ++ [v])) \/
   (Znth v before_pos (-1) <> -1 /\
    after_heap = before_heap /\ after_pos = before_pos /\
    after_cap = before_cap)).

Definition order_select_pre
    (n : Z) (heap orderpos assigns trail : list Z) (qhead : Z) : Prop :=
  2 * n <= INT_MAX /\
  order_heap_wf n heap orderpos /\
  heap_covers n {| mh_heap := heap; mh_orderpos := orderpos |}
    assigns trail qhead /\
  assigned_below_qhead n assigns trail qhead /\
  Zlength assigns = n /\
  Forall (fun x => x = -1 \/ x = 0 \/ x = 1) assigns.

Definition order_select_loop_inv
    (n : Z) (origin heap orderpos assigns trail : list Z) (qhead : Z) : Prop :=
  order_select_pre n heap orderpos assigns trail qhead /\
  incl heap origin.

Definition order_select_sift_inv
    (n popped x hole : Z)
    (origin before heap orderpos assigns trail : list Z) (qhead : Z) : Prop :=
  2 * n <= INT_MAX /\
  0 <= popped < n /\
  incl before origin /\
  Zlength assigns = n /\
  Forall (fun a => a = -1 \/ a = 0 \/ a = 1) assigns /\
  assigned_below_qhead n assigns trail qhead /\
  heap_covers_except n {| mh_heap := heap; mh_orderpos := orderpos |}
    assigns trail qhead popped /\
  order_heap_one_hole n (list_without_Znth 0 before)
    x hole heap orderpos.

Definition order_select_post
    (n ret : Z) (before_heap after_heap after_pos assigns trail : list Z)
    (qhead : Z) : Prop :=
  order_heap_wf n after_heap after_pos /\
  incl after_heap before_heap /\
  ((ret = -1 /\ after_heap = [] /\
    forall v, 0 <= v < n -> Znth v assigns 0 <> 0) \/
   (0 <= ret < n /\ Znth ret assigns 0 = 0 /\
    heap_covers_except n
      {| mh_heap := after_heap; mh_orderpos := after_pos |}
      assigns trail qhead ret)).

Lemma Zlength_list_without_Znth : forall i l,
  0 <= i < Zlength l ->
  Zlength (list_without_Znth i l) = Zlength l - 1.
Proof.
  intros i l Hi. unfold list_without_Znth.
  rewrite Zlength_app.
  rewrite (Zlength_sublist 0 i l) by lia.
  rewrite (Zlength_sublist (i + 1) (Zlength l) l) by lia.
  lia.
Qed.

(** removing one cell and putting its value back in front is a permutation *)
Lemma list_without_Znth_perm : forall (d : Z) i l,
  0 <= i < Zlength l ->
  Permutation l (Znth i l d :: list_without_Znth i l).
Proof.
  intros d i l Hi. unfold list_without_Znth.
  pose proof (list_Znth_split d l i Hi) as E.
  remember (Znth i l d) as a eqn:Ha.
  remember (sublist 0 i l) as A eqn:HA.
  remember (sublist (i + 1) (Zlength l) l) as B eqn:HB.
  rewrite E. apply Permutation_sym. apply Permutation_middle.
Qed.

Lemma replace_Znth_split : forall (d v : Z) i l,
  0 <= i < Zlength l ->
  replace_Znth i v l = sublist 0 i l ++ v :: sublist (i + 1) (Zlength l) l.
Proof.
  intros d v i l Hi.
  pose proof (list_Znth_split d l i Hi) as E.
  assert (HA : Zlength (sublist 0 i l) = i)
    by (apply Zlength_sublist0; lia).
  rewrite E at 1.
  rewrite replace_Znth_app_r by lia.
  rewrite replace_Znth_nothing by lia.
  rewrite HA. replace (i - i) with 0 by lia.
  reflexivity.
Qed.

(** overwriting one cell = deleting it and prepending the new value *)
Lemma list_without_Znth_replace_perm : forall (d v : Z) i l,
  0 <= i < Zlength l ->
  Permutation (replace_Znth i v l) (v :: list_without_Znth i l).
Proof.
  intros d v i l Hi.
  rewrite (replace_Znth_split d v i l Hi).
  unfold list_without_Znth.
  apply Permutation_sym. apply Permutation_middle.
Qed.

Lemma In_list_without_Znth : forall (d : Z) i j l,
  0 <= i < Zlength l -> 0 <= j < Zlength l -> i <> j ->
  In (Znth i l d) (list_without_Znth j l).
Proof.
  intros d i j l Hi Hj Hne. unfold list_without_Znth.
  apply in_or_app.
  destruct (Z.lt_ge_cases i j) as [Hlt|Hge].
  - left. rewrite <- (Znth_sublist0 d i j l) by lia.
    apply Znth_In. rewrite Zlength_sublist0 by lia. lia.
  - right.
    assert (E : Znth i l d
                = Znth (i - (j + 1)) (sublist (j + 1) (Zlength l) l) d).
    { rewrite (Znth_sublist d (j + 1) (i - (j + 1)) (Zlength l) l) by lia.
      f_equal. lia. }
    rewrite E. apply Znth_In. rewrite Zlength_sublist by lia. lia.
Qed.

Lemma In_replace_Znth_same : forall (x i : Z) (l : list Z),
  0 <= i < Zlength l -> In x (replace_Znth i x l).
Proof.
  intros x i l Hi.
  pose proof (Znth_In Z (replace_Znth i x l) (-1) i) as HI.
  rewrite (Znth_replace_Znth_Same (-1) l i x) in HI by lia.
  apply HI. rewrite Zlength_replace_Znth. lia.
Qed.

(** ----- [order_heap_one_hole] toolbox ----- *)

(** every cell other than the hole still belongs to the ghost anchor ... *)
Lemma order_heap_one_hole_cell_in : forall n origin x hole heap orderpos i,
  order_heap_one_hole n origin x hole heap orderpos ->
  0 <= i < Zlength heap -> i <> hole ->
  In (Znth i heap (-1)) origin.
Proof.
  intros n origin x hole heap orderpos i
         (Hoplen & Hlen & Hhole & Hx & Hnd & Hrng & Hperm & Hinv & Hout) Hi Hne.
  apply (Permutation_in _ (Permutation_sym Hperm)).
  right. apply In_list_without_Znth; [lia|lia|lia].
Qed.

(** ... hence is a genuine variable index *)
Lemma order_heap_one_hole_cell_range : forall n origin x hole heap orderpos i,
  order_heap_one_hole n origin x hole heap orderpos ->
  0 <= i < Zlength heap -> i <> hole ->
  0 <= Znth i heap (-1) < n.
Proof.
  intros n origin x hole heap orderpos i H Hi Hne.
  pose proof (order_heap_one_hole_cell_in n origin x hole heap orderpos i H Hi
                Hne) as Hin.
  destruct H as (Hoplen & Hlen & Hhole & Hx & Hnd & Hrng & Hperm & Hinv & Hout).
  rewrite Forall_forall in Hrng. exact (Hrng _ Hin).
Qed.

Lemma order_heap_one_hole_perm : forall n origin x hole heap orderpos,
  order_heap_one_hole n origin x hole heap orderpos ->
  Permutation origin (replace_Znth hole x heap).
Proof.
  intros n origin x hole heap orderpos
         (Hoplen & Hlen & Hhole & Hx & Hnd & Hrng & Hperm & Hinv & Hout).
  apply (Permutation_trans Hperm). apply Permutation_sym.
  apply (list_without_Znth_replace_perm (-1)). lia.
Qed.

(** CONCLUSION.  The loop exit [heap[hole] := x; orderpos[x] := hole]
    re-establishes [order_heap_wf].  This is the whole point of the
    [NoDup] / range conjuncts: without [NoDup origin] the fifth [heap_wf]
    clause fails at every [i <> hole] whose cell equals [x], and without the
    range conjunct the third one fails on a negative cell. *)
Lemma order_heap_one_hole_close : forall n origin x hole heap orderpos,
  order_heap_one_hole n origin x hole heap orderpos ->
  order_heap_wf n (replace_Znth hole x heap) (replace_Znth x hole orderpos).
Proof.
  intros n origin x hole heap orderpos H.
  pose proof H as Hfull.
  destruct H as (Hoplen & Hlen & Hhole & Hx & Hnd & Hrng & Hperm & Hinv & Hout).
  assert (Hph : Permutation (replace_Znth hole x heap)
                            (x :: list_without_Znth hole heap))
    by (apply (list_without_Znth_replace_perm (-1)); lia).
  assert (Hpo : Permutation origin (replace_Znth hole x heap))
    by (apply (Permutation_trans Hperm (Permutation_sym Hph))).
  assert (Hnd2 : NoDup (x :: list_without_Znth hole heap))
    by (apply (Permutation_NoDup Hperm); exact Hnd).
  assert (HxNI : ~ In x (list_without_Znth hole heap))
    by (inversion Hnd2; assumption).
  unfold order_heap_wf. apply heap_wf_intro; cbn [mh_heap mh_orderpos].
  - rewrite Zlength_replace_Znth. exact Hoplen.
  - apply (Permutation_NoDup Hpo). exact Hnd.
  - rewrite Forall_forall. intros u Hu.
    apply (Permutation_in _ (Permutation_sym Hpo)) in Hu.
    rewrite Forall_forall in Hrng. exact (Hrng u Hu).
  - intros v Hv Hnotin.
    assert (Hvx : v <> x).
    { intros Hev. apply Hnotin. rewrite Hev.
      apply In_replace_Znth_same. lia. }
    rewrite (Znth_replace_Znth_Diff (-1) orderpos x v hole) by lia.
    apply Hout; [lia|]. intros Hin. apply Hnotin.
    apply (Permutation_in _ Hpo). exact Hin.
  - intros i Hi. rewrite Zlength_replace_Znth in Hi.
    destruct (Z.eq_dec i hole) as [->|Hne].
    + rewrite (Znth_replace_Znth_Same (-1) heap hole x) by lia.
      rewrite (Znth_replace_Znth_Same (-1) orderpos x hole) by lia.
      reflexivity.
    + rewrite (Znth_replace_Znth_Diff (-1) heap hole i x) by lia.
      assert (Hne2 : Znth i heap (-1) <> x).
      { intros E. apply HxNI. rewrite <- E.
        apply In_list_without_Znth; lia. }
      assert (Hr : 0 <= Znth i heap (-1) < n)
        by (apply (order_heap_one_hole_cell_range n origin x hole heap orderpos
                     i Hfull); [lia|lia]).
      rewrite (Znth_replace_Znth_Diff (-1) orderpos x (Znth i heap (-1)) hole)
        by lia.
      apply Hinv; [lia|lia].
Qed.

(** the membership half of [order_update_post] / [order_select_post]:
    after the closing write, "absent from orderpos" is exactly "absent from
    the ghost anchor" *)
Lemma order_heap_one_hole_close_missing :
  forall n origin x hole heap orderpos u,
  order_heap_one_hole n origin x hole heap orderpos ->
  0 <= u < n ->
  (Znth u (replace_Znth x hole orderpos) (-1) = -1 <-> ~ In u origin).
Proof.
  intros n origin x hole heap orderpos u H Hu.
  pose proof (order_heap_one_hole_close n origin x hole heap orderpos H) as Hwf.
  pose proof (order_heap_one_hole_perm n origin x hole heap orderpos H) as Hpo.
  unfold order_heap_wf in Hwf.
  pose proof (heap_wf_in_iff n
    {| mh_heap := replace_Znth hole x heap;
       mh_orderpos := replace_Znth x hole orderpos |} u Hwf Hu) as Hiff.
  cbn [mh_heap mh_orderpos] in Hiff.
  split.
  - intros Hm1 Hin. apply (Permutation_in _ Hpo) in Hin.
    apply Hiff in Hin. contradiction.
  - intros Hnin.
    destruct (Z.eq_dec (Znth u (replace_Znth x hole orderpos) (-1)) (-1))
      as [E|E]; [exact E|].
    exfalso. apply Hnin. apply (Permutation_in _ (Permutation_sym Hpo)).
    apply Hiff. exact E.
Qed.

(** PRESERVATION.  One sift step: the hole moves to [child] and that child's
    value is shifted up into the old hole. *)
Lemma order_heap_one_hole_step :
  forall n origin x hole child heap orderpos,
  order_heap_one_hole n origin x hole heap orderpos ->
  0 <= child < Zlength heap -> child <> hole ->
  order_heap_one_hole n origin x child
    (replace_Znth hole (Znth child heap (-1)) heap)
    (replace_Znth (Znth child heap (-1)) hole orderpos).
Proof.
  intros n origin x hole child heap orderpos H Hchild Hne.
  pose proof H as Hfull.
  destruct H as (Hoplen & Hlen & Hhole & Hx & Hnd & Hrng & Hperm & Hinv & Hout).
  assert (Hw : 0 <= Znth child heap (-1) < n)
    by (apply (order_heap_one_hole_cell_range n origin x hole heap orderpos
                 child Hfull); [lia|lia]).
  assert (Hcw : Znth child (replace_Znth hole (Znth child heap (-1)) heap) (-1)
                = Znth child heap (-1))
    by (apply (Znth_replace_Znth_Diff (-1) heap hole child); lia).
  assert (Hlh : Zlength (replace_Znth hole (Znth child heap (-1)) heap)
                = Zlength heap) by apply Zlength_replace_Znth.
  assert (Hp1 : Permutation (replace_Znth hole (Znth child heap (-1)) heap)
                  (Znth child heap (-1) :: list_without_Znth hole heap))
    by (apply (list_without_Znth_replace_perm (-1)); lia).
  assert (Hp2 : Permutation (replace_Znth hole (Znth child heap (-1)) heap)
                  (Znth child heap (-1)
                   :: list_without_Znth child
                        (replace_Znth hole (Znth child heap (-1)) heap))).
  { rewrite <- Hcw at 2.
    apply (list_without_Znth_perm (-1)). lia. }
  assert (Hp3 : Permutation (list_without_Znth hole heap)
                  (list_without_Znth child
                     (replace_Znth hole (Znth child heap (-1)) heap))).
  { apply (Permutation_cons_inv (a := Znth child heap (-1))).
    apply (Permutation_trans (Permutation_sym Hp1) Hp2). }
  unfold order_heap_one_hole.
  split; [rewrite Zlength_replace_Znth; exact Hoplen|].
  split; [rewrite Zlength_replace_Znth; exact Hlen|].
  split; [rewrite Hlh; lia|].
  split; [lia|].
  split; [exact Hnd|].
  split; [exact Hrng|].
  split; [apply (Permutation_trans Hperm); apply perm_skip; exact Hp3|].
  split.
  - intros i Hi Hic. rewrite Hlh in Hi.
    destruct (Z.eq_dec i hole) as [->|Hih].
    + rewrite (Znth_replace_Znth_Same (-1) heap hole (Znth child heap (-1)))
        by lia.
      apply (Znth_replace_Znth_Same (-1) orderpos (Znth child heap (-1)) hole).
      lia.
    + rewrite (Znth_replace_Znth_Diff (-1) heap hole i (Znth child heap (-1)))
        by lia.
      assert (Hu : 0 <= Znth i heap (-1) < n)
        by (apply (order_heap_one_hole_cell_range n origin x hole heap orderpos
                     i Hfull); [lia|lia]).
      assert (Hune : Znth i heap (-1) <> Znth child heap (-1)).
      { intros E. pose proof (Hinv i ltac:(lia) Hih) as E1.
        pose proof (Hinv child ltac:(lia) Hne) as E2.
        rewrite E in E1. lia. }
      rewrite (Znth_replace_Znth_Diff (-1) orderpos (Znth child heap (-1))
                 (Znth i heap (-1)) hole) by lia.
      apply Hinv; [lia|lia].
  - intros v Hv Hvout.
    assert (Hvw : v <> Znth child heap (-1)).
    { intros E. apply Hvout. rewrite E.
      apply (order_heap_one_hole_cell_in n origin x hole heap orderpos child
               Hfull); [lia|lia]. }
    rewrite (Znth_replace_Znth_Diff (-1) orderpos (Znth child heap (-1)) v hole)
      by lia.
    apply Hout; [lia|exact Hvout].
Qed.

(** ESTABLISHMENT 1 -- [order_update]: [i := orderpos[v]; x := heap[i]]
    turns the incoming [order_heap_wf] into the loop invariant (and, as a
    by-product, [x] is [v] itself). *)
Lemma order_update_loop_inv_init : forall n v i x heap orderpos,
  order_update_pre n v heap orderpos ->
  i = Znth v orderpos (-1) ->
  x = Znth i heap (-1) ->
  0 <= i < Zlength heap /\ x = v /\
  order_update_loop_inv n v heap x i heap orderpos.
Proof.
  intros n v i x heap orderpos (Hwf & Hv & Hne) Hi Hx.
  unfold order_heap_wf in Hwf.
  pose proof (heap_wf_lookup n _ v Hwf Hv) as Hlk.
  cbn [mh_heap mh_orderpos] in Hlk.
  destruct (Hlk Hne) as [Hirange Hival].
  rewrite <- Hi in Hirange, Hival.
  pose proof (heap_wf_orderpos_length n _ Hwf) as Hoplen.
  pose proof (heap_wf_nodup n _ Hwf) as Hnd.
  pose proof (heap_wf_range n _ Hwf) as Hrng.
  pose proof (fun j => heap_wf_inverse n
                 {| mh_heap := heap; mh_orderpos := orderpos |} j Hwf) as Hinv.
  cbn [mh_heap mh_orderpos] in Hoplen, Hnd, Hrng, Hinv.
  assert (Hxv : x = v) by (rewrite Hx; exact Hival).
  assert (Hin : In v heap) by (rewrite <- Hival; apply Znth_In; lia).
  split; [lia|]. split; [exact Hxv|].
  unfold order_update_loop_inv, order_heap_one_hole.
  split; [lia|]. split; [exact Hin|].
  split; [exact Hoplen|].
  split; [reflexivity|].
  split; [lia|].
  split; [lia|].
  split; [exact Hnd|].
  split; [exact Hrng|].
  split; [rewrite Hx; apply (list_without_Znth_perm (-1)); lia|].
  split.
  - intros j Hj _. apply Hinv. lia.
  - intros u Hu Hout.
    apply (heap_wf_not_in n {| mh_heap := heap; mh_orderpos := orderpos |} u
             Hwf Hu Hout).
Qed.

(** ESTABLISHMENT 2 -- [order_select]: after [veci_resize(order, size)] and
    [orderpos[next] := -1], the truncated array with the saved last element
    [x] and a hole at index 0 is a one-hole heap over the ghost anchor
    [list_without_Znth 0 before]. *)
Lemma order_heap_one_hole_init_select :
  forall n size before orderpos next x,
  order_heap_wf n before orderpos ->
  Zlength before = size + 1 ->
  0 < size ->
  next = Znth 0 before (-1) ->
  x = Znth size before (-1) ->
  order_heap_one_hole n (list_without_Znth 0 before) x 0
    (sublist 0 size before)
    (replace_Znth next (-1) orderpos).
Proof.
  intros n size before orderpos next x Hwf Hlen0 Hsz Hnext Hx.
  unfold order_heap_wf in Hwf.
  pose proof (heap_wf_orderpos_length n _ Hwf) as Hoplen.
  pose proof (heap_wf_nodup n _ Hwf) as Hnd.
  pose proof (heap_wf_range n _ Hwf) as Hrng.
  pose proof (fun j => heap_wf_inverse n
                 {| mh_heap := before; mh_orderpos := orderpos |} j Hwf) as Hinv.
  cbn [mh_heap mh_orderpos] in Hoplen, Hnd, Hrng, Hinv.
  rewrite Forall_forall in Hrng.
  assert (Hhl : Zlength (sublist 0 size before) = size)
    by (apply Zlength_sublist0; lia).
  assert (Hnr : 0 <= next < n)
    by (rewrite Hnext; apply Hrng; apply Znth_In; lia).
  assert (Hxr : 0 <= x < n)
    by (rewrite Hx; apply Hrng; apply Znth_In; lia).
  assert (Hn0 : Znth 0 (sublist 0 size before) (-1) = next)
    by (rewrite Hnext; apply Znth_sublist0; lia).
  assert (Hpb : Permutation before (next :: list_without_Znth 0 before)).
  { rewrite Hnext. apply (list_without_Znth_perm (-1)). lia. }
  assert (Hph : Permutation (sublist 0 size before)
                  (next :: list_without_Znth 0 (sublist 0 size before))).
  { rewrite <- Hn0. apply (list_without_Znth_perm (-1)). lia. }
  assert (Hsplit : before = sublist 0 size before ++ [x]).
  { pose proof (list_Znth_split (-1) before size ltac:(lia)) as Hs.
    rewrite Hlen0 in Hs.
    rewrite (Zsublist_nil before (size + 1) (size + 1) ltac:(lia)) in Hs.
    rewrite <- Hx in Hs. exact Hs. }
  assert (Hbx : Permutation before (x :: sublist 0 size before)).
  { rewrite Hsplit at 1. apply Permutation_sym. apply Permutation_cons_append. }
  assert (Hndb : NoDup (next :: list_without_Znth 0 before))
    by (apply (Permutation_NoDup Hpb); exact Hnd).
  unfold order_heap_one_hole.
  split; [rewrite Zlength_replace_Znth; exact Hoplen|].
  split; [rewrite Hhl, Zlength_list_without_Znth by lia; lia|].
  split; [lia|].
  split; [lia|].
  split; [inversion Hndb; assumption|].
  split.
  { rewrite Forall_forall. intros u Hu. apply Hrng.
    apply (Permutation_in _ (Permutation_sym Hpb)). right. exact Hu. }
  split.
  { apply (Permutation_cons_inv (a := next)).
    apply (Permutation_trans (Permutation_sym Hpb)).
    apply (Permutation_trans Hbx).
    apply (Permutation_trans (perm_skip x Hph)).
    apply perm_swap. }
  split.
  - intros i Hi Hi0. rewrite Hhl in Hi.
    rewrite (Znth_sublist0 (-1) i size before) by lia.
    assert (Hur : 0 <= Znth i before (-1) < n)
      by (apply Hrng; apply Znth_In; lia).
    assert (Hune : Znth i before (-1) <> next).
    { intros E. pose proof (Hinv i ltac:(lia)) as E1.
      pose proof (Hinv 0 ltac:(lia)) as E2. rewrite <- Hnext in E2.
      rewrite E in E1. lia. }
    rewrite (Znth_replace_Znth_Diff (-1) orderpos next (Znth i before (-1)) (-1))
      by lia.
    apply Hinv. lia.
  - intros v Hv Hvout.
    destruct (Z.eq_dec v next) as [->|Hvn].
    + apply (Znth_replace_Znth_Same (-1) orderpos next (-1)). lia.
    + rewrite (Znth_replace_Znth_Diff (-1) orderpos next v (-1)) by lia.
      apply (heap_wf_not_in n {| mh_heap := before; mh_orderpos := orderpos |}
               v Hwf Hv).
      cbn [mh_heap]. intros Hin.
      destruct (Permutation_in _ Hpb Hin) as [He|He];
        [apply Hvn; symmetry; exact He|apply Hvout; exact He].
Qed.




(** plain coverage trivially covers-except any variable *)
Lemma heap_covers_except_weaken : forall n h assigns trail qhead v0,
  heap_covers n h assigns trail qhead ->
  heap_covers_except n h assigns trail qhead v0.
Proof.
  intros n h assigns trail qhead v0 Hcov v Hv _ Hm1.
  exact (Hcov v Hv Hm1).
Qed.

(** [order_select]'s pop of [v0]: the only variable newly missing from
    the heap is [v0] itself (the sift-down moves entries but keeps the
    set). *)
Lemma heap_covers_except_intro : forall n h h' assigns trail qhead v0,
  heap_covers n h assigns trail qhead ->
  (forall u, 0 <= u < n -> Znth u (mh_orderpos h') (-1) = -1 ->
     u = v0 \/ Znth u (mh_orderpos h) (-1) = -1) ->
  heap_covers_except n h' assigns trail qhead v0.
Proof.
  intros n h h' assigns trail qhead v0 Hcov Hmono v Hv Hne Hm1.
  destruct (Hmono v Hv Hm1) as [->|Hold].
  - exact (False_ind _ (Hne eq_refl)).
  - exact (Hcov v Hv Hold).
Qed.

(** [assume]/[enqueue] of [v0] itself (trail grows at the end, [v0]'s
    cell flips to assigned, [qhead] does not move past anything): the
    transient survives -- [v0] needs no coverage, every other variable's
    witness is untouched. *)
Lemma heap_covers_except_assume :
  forall n h assigns assigns' trail trail' qhead qhead' v0,
  heap_covers_except n h assigns trail qhead v0 ->
  qhead <= qhead' ->
  (forall v, 0 <= v < n -> Znth v assigns 0 <> 0 ->
     Znth v assigns' 0 <> 0) ->
  (forall i, 0 <= i < qhead -> Znth i trail' 0 = Znth i trail 0) ->
  heap_covers_except n h assigns' trail' qhead' v0.
Proof.
  intros n h assigns assigns' trail trail' qhead qhead' v0
         Hcov Hq Hassign Htrail v Hv Hne Hm1.
  destruct (Hcov v Hv Hne Hm1) as [Ha [i [Hi Hval]]].
  split; [apply Hassign; assumption|].
  exists i. split; [lia|]. rewrite Htrail by lia. exact Hval.
Qed.

(** propagate's first dequeue: once [v0] is assigned and its trail index
    is below the (advanced) [qhead], full coverage is restored. *)
Lemma heap_covers_except_qhead :
  forall n h assigns trail qhead qhead' v0,
  heap_covers_except n h assigns trail qhead v0 ->
  qhead <= qhead' ->
  Znth v0 assigns 0 <> 0 ->
  (exists i, 0 <= i < qhead' /\ lit_var_c (Znth i trail 0) = v0) ->
  heap_covers n h assigns trail qhead'.
Proof.
  intros n h assigns trail qhead qhead' v0 Hcov Hq Ha0 Hi0 v Hv Hm1.
  destruct (Z.eq_dec v v0) as [->|Hne].
  - split; assumption.
  - destruct (Hcov v Hv Hne Hm1) as [Ha [i [Hi Hval]]].
    split; [exact Ha|]. exists i. split; [lia|exact Hval].
Qed.

(** The [order_unassigned] loop of [solver_canceluntil] runs
    downwards over [[bound, qhead)]; this is its invariant. *)
Definition cancel_reinserted (h : mheap) (trail : list Z) (lo hi : Z) : Prop :=
  forall i, lo <= i < hi ->
    Znth (lit_var_c (Znth i trail 0)) (mh_orderpos h) (-1) <> -1.

Lemma cancel_reinserted_init : forall h trail hi,
  cancel_reinserted h trail hi hi.
Proof. intros h trail hi i Hi. lia. Qed.


(** Heap coverage survives [solver_canceluntil] even though the
    reinsertion loop is asymmetric: variables in [[qhead, qtail)] are
    unassigned WITHOUT being reinserted, but the new [qhead] is [bound], so
    they are no longer required to be covered.  Trail variable-distinctness
    is what rules out a variable being both below [bound] and cancelled. *)
Lemma heap_covers_cancel : forall n h h' assigns assigns' trail bound qhead qtail,
  heap_covers n h assigns trail qhead ->
  0 <= bound <= qhead ->
  qhead <= qtail ->
  (forall i j, 0 <= i < qtail -> 0 <= j < qtail ->
     lit_var_c (Znth i trail 0) = lit_var_c (Znth j trail 0) -> i = j) ->
  (forall v, 0 <= v < n -> Znth v assigns' 0 = 0 -> Znth v assigns 0 <> 0 ->
     exists i, bound <= i < qtail /\ lit_var_c (Znth i trail 0) = v) ->
  cancel_reinserted h' trail bound qhead ->
  (forall v, 0 <= v < n -> Znth v (mh_orderpos h') (-1) = -1 ->
     Znth v (mh_orderpos h) (-1) = -1) ->
  heap_covers n h' assigns' trail bound.
Proof.
  intros n h h' assigns assigns' trail bound qhead qtail
         Hcov Hb Hq Hdist Hcancel Hre Hmono v Hv Hm1.
  destruct (Hcov v Hv (Hmono v Hv Hm1)) as [Ha [i [Hi Hval]]].
  assert (Hlow : i < bound).
  { destruct (Z_lt_le_dec i bound) as [Hlt|Hge]; [exact Hlt|].
    exfalso. apply (Hre i); [lia|]. rewrite Hval. exact Hm1. }
  assert (Ha' : Znth v assigns' 0 <> 0).
  { intros Hz.
    destruct (Hcancel v Hv Hz Ha) as [j [Hj Hjval]].
    assert (i = j).
    { apply Hdist; [lia|lia|]. rewrite Hval, Hjval. reflexivity. }
    lia. }
  split; [exact Ha'|]. exists i. split; [lia|exact Hval].
Qed.

Definition seed_next (s : Z) : Z := (s * 1389796) mod 2147483647.

Lemma seed_next_range : forall s, 0 <= seed_next s < 2147483647.
Proof.
  intros s. unfold seed_next. apply Z.mod_pos_bound. lia.
Qed.

(** the generator never reaches the absorbing state 0.  No primality
    certificate is needed: [gcd 2147483647 1389796 = 1] plus Gauss's lemma
    forces [2147483647 | s], impossible for [s] in range. *)
Lemma seed_next_nonzero : forall s, seed_ok s -> seed_next s <> 0.
Proof.
  intros s [H1 H2] Hz. unfold seed_next in Hz.
  apply Z.mod_divide in Hz; [|lia].
  assert (Hd : (2147483647 | 1389796 * s)).
  { rewrite Z.mul_comm. exact Hz. }
  pose proof (Z.gauss _ _ _ Hd ltac:(vm_compute; reflexivity)) as Hds.
  assert (Hle : 2147483647 <= s) by (apply Z.divide_pos_le; [lia|exact Hds]).
  lia.
Qed.




Lemma activity_state_undef : forall c learnt,
  activity_state c learnt |-- clause_act_addr c # Float |->_.
Proof.
  intros c learnt. unfold activity_state. destruct learnt.
  - Intros a. apply store_float_undef_store_float.
  - msat_entailer_with lia.
Qed.

(** ** Clause-pointer parity.

    Every clause predicate carries
    [0 < c /\ c mod 2 = 0].  Its supplier is the frozen allocator contract
    (the clause allocator in minisat_qcp_compat.h: [Ensure __return != 0 &&
    __return % 2 == 0 && MiniSatClause::undef(__return, size)]), and its two
    consumers are
    [clause_new]'s [assert(((unsigned int)c & 1) == 0)]
    and S5's [db_wf], whose [Z.even (fst e) = true] conjunct has no other
    supplier.  The spelling is the C one ([c % 2 == 0]); the two
    bridging lemmas convert to [Z.even] / [is_tag]. *)

Lemma clause_ptr_even : forall c, c mod 2 = 0 -> Z.even c = true.
Proof.
  intros c H. apply Z.even_spec. exists (c / 2).
  pose proof (Z.div_mod c 2 ltac:(lia)) as Hd. lia.
Qed.

Lemma clause_ptr_mod2 : forall c, Z.even c = true -> c mod 2 = 0.
Proof.
  intros c H. apply Z.even_spec in H. destruct H as [m ->].
  rewrite Z.mul_comm. apply Z_mod_mult.
Qed.



(** [CORE] *)
Lemma MiniSatClause_rep_owned : forall c learnt lits,
  MiniSatClause.rep c learnt lits |-- MiniSatClause.owned c (Zlength lits).
Proof.
  intros. unfold MiniSatClause.rep, MiniSatClause.owned.
  apply coq_prop_andp_left. intros Hpure.
  sep_apply store_int_undef_store_int.
  sep_apply activity_state_undef.
  sep_apply (IntArray.seg_to_undef_seg (clause_lits_addr c) 0 (Zlength lits) lits).
  msat_entailer_with lia.
Qed.



(** The header word round-trips through MiniSat's two accessors. *)
Lemma Zdiv2_pack : forall q r, 0 <= r < 2 -> (2 * q + r) / 2 = q.
Proof.
  intros q r Hr. replace (2 * q + r) with (q * 2 + r) by lia.
  rewrite Z.div_add_l by lia. rewrite Z.div_small by lia. lia.
Qed.

Lemma Zmod2_pack : forall q r, 0 <= r < 2 -> (2 * q + r) mod 2 = r.
Proof.
  intros q r Hr. replace (2 * q + r) with (r + q * 2) by lia.
  rewrite Z.mod_add by lia. rewrite Z.mod_small by lia. reflexivity.
Qed.

Lemma Zland_mod2 : forall x, Z.land x 1 = x mod 2.
Proof.
  intros x. replace 1 with (Z.ones 1) by reflexivity.
  rewrite Z.land_ones by lia. reflexivity.
Qed.

Lemma clause_hdr_word_div2 : forall learnt size,
  0 <= size -> clause_hdr_word learnt size / 2 = size.
Proof.
  intros learnt size _. unfold clause_hdr_word.
  destruct learnt; apply Zdiv2_pack; lia.
Qed.

Lemma clause_hdr_word_nonneg : forall learnt size,
  0 <= size -> 0 <= clause_hdr_word learnt size.
Proof. intros. unfold clause_hdr_word. destruct learnt; lia. Qed.

(** QCP names the ownership of an uninitialized local struct by its C tag.
    For [veci_t] this is exactly the three field cells consumed by [veci_new]. *)
Definition UndefStructPredveci_t (v : Z) : Assertion :=
  veci_size_addr v # Int |->_ **
  veci_cap_addr  v # Int |->_ **
  veci_ptr_addr  v # Ptr |->_.


(** [vecp_remove] removes the first matching watch word.  Watch lists are
    positional and may contain duplicates, so this is deliberately not a
    set-level removal.  The scan invariant makes the next read safe by
    retaining membership in the unread suffix; the shift invariant records
    the temporary duplicate at the moving hole. *)
Definition vecp_remove_found (e : Z) (l : list Z) (found : Z) : Prop :=
  0 <= found < Zlength l /\
  Znth found l 0 = e /\
  Forall (fun x => x <> e) (sublist 0 found l).

Definition vecp_remove_result (l : list Z) (found : Z) : list Z :=
  sublist 0 found l ++ sublist (found + 1) (Zlength l) l.

Definition vecp_remove_member (e : Z) (l : list Z) : Prop := In e l.

Definition vecp_remove_scan_inv (e : Z) (l : list Z) (j : Z) : Prop :=
  0 <= j < Zlength l /\
  In e (sublist j (Zlength l) l) /\
  Forall (fun x => x <> e) (sublist 0 j l).

Definition vecp_remove_shift_inv
    (e : Z) (l : list Z) (found j : Z) (current : list Z) : Prop :=
  vecp_remove_found e l found /\
  found <= j < Zlength l /\
  current =
    sublist 0 found l ++
    sublist (found + 1) (j + 1) l ++
    sublist j (Zlength l) l.

(** The signed [lbool] value which makes a packed literal true. *)
Definition packed_lit_satisfying_value (l : Z) : Z :=
  1 - 2 * lit_sign_c l.

Definition clause_simplify_scan_inv
    (n : Z) (lits assigns : list Z) (i : Z) : Prop :=
  0 <= i <= Zlength lits /\
  Zlength assigns = n /\
  Forall (lit_wf_c n) lits /\
  Forall lbool_cell assigns /\
  (forall j, 0 <= j < i ->
     Znth (lit_var_c (Znth j lits 0)) assigns 0 <>
       packed_lit_satisfying_value (Znth j lits 0)).

Definition clause_simplify_result
    (lits assigns : list Z) (ret : Z) : Prop :=
  (ret = 1 /\ exists i, 0 <= i < Zlength lits /\
     Znth (lit_var_c (Znth i lits 0)) assigns 0 =
       packed_lit_satisfying_value (Znth i lits 0)) \/
  (ret = -1 /\ forall i, 0 <= i < Zlength lits ->
     Znth (lit_var_c (Znth i lits 0)) assigns 0 <>
       packed_lit_satisfying_value (Znth i lits 0)).

Definition wmap_remove_first
    (wm : wmap) (index word found : Z) : wmap :=
  replace_Znth index
    (vecp_remove_result (Znth index wm []) found) wm.

Definition clause_remove_ready
    (n c : Z) (lits : list Z) (wm : wmap) (caps stats : list Z) : Prop :=
  2 <= Zlength lits /\ Forall (lit_wf_c n) lits /\
  lit_var_c (Znth 0 lits 0) <> lit_var_c (Znth 1 lits 0) /\
  Zlength wm = 2 * n /\ Zlength caps = 2 * n /\
  Zlength stats = 11 /\
  In (clause_watch_word c lits (Znth 1 lits 0))
     (Znth (lit_neg_c (Znth 0 lits 0)) wm []) /\
  In (clause_watch_word c lits (Znth 0 lits 0))
     (Znth (lit_neg_c (Znth 1 lits 0)) wm []).

Definition clause_remove_result
    (c : Z) (lits : list Z) (wm wm' : wmap) : Prop :=
  exists found0 found1 wm0,
    vecp_remove_found
      (clause_watch_word c lits (Znth 1 lits 0))
      (Znth (lit_neg_c (Znth 0 lits 0)) wm []) found0 /\
    wm0 = wmap_remove_first wm (lit_neg_c (Znth 0 lits 0))
            (clause_watch_word c lits (Znth 1 lits 0)) found0 /\
    vecp_remove_found
      (clause_watch_word c lits (Znth 0 lits 0))
      (Znth (lit_neg_c (Znth 1 lits 0)) wm0 []) found1 /\
    wm' = wmap_remove_first wm0 (lit_neg_c (Znth 1 lits 0))
            (clause_watch_word c lits (Znth 0 lits 0)) found1.

Definition clause_unlocked_words (c : Z) (reasons : list Z) : Prop :=
  Forall (fun r => r <> c) reasons.

(** The separation the gap needed: a pointer resident in [prob ++ learnt]
    whose object is tagged learnt is resident in [learnt]. *)


Lemma prob_db_app : forall d1 d2,
  prob_db d1 -> prob_db d2 -> prob_db (d1 ++ d2).
Proof. intros d1 d2 H1 H2. apply Forall_app. split; assumption. Qed.

(** Sorting is a heuristic-only permutation.  No ordering theorem is exposed:
    MiniSat's comparator deliberately returns [1], not [0], on aliases. *)
Definition learnt_sort_domain (db : dbmap) (words : list Z) : Prop :=
  learnt_db db /\ Permutation words (map fst db).

(** Recursive sorting works on proper subarrays, so its domain records only
    that every segment pointer belongs to the one immutable learnt database.
    Exact whole-database provenance remains confined to [sort]. *)
Definition learnt_sort_segment_domain (db : dbmap) (words : list Z) : Prop :=
  Forall (fun p => In p (db_words db)) words.

Definition learnt_sort_context
    (db : dbmap) (activities : list fp32) : Prop :=
  NoDup (db_words db) /\
  Zlength activities = Zlength db /\
  Forall msat_fp32_nonnegative activities.

Definition selectionsort_outer_inv
    (db : dbmap) (activities : list fp32)
    (origin current : list Z) (size i : Z) : Prop :=
  learnt_sort_context db activities /\
  learnt_sort_segment_domain db origin /\
  Permutation origin current /\
  Zlength current = size /\ 0 <= i <= Z.max 0 (size - 1).

Definition selectionsort_inner_inv
    (db : dbmap) (activities : list fp32) (origin current : list Z)
    (size i j best : Z) : Prop :=
  learnt_sort_context db activities /\
  learnt_sort_segment_domain db origin /\
  Permutation origin current /\
  Zlength current = size /\
  0 <= i < size /\ i <= best < j /\ i + 1 <= j <= size.

Definition sortrnd_partition_inv
    (db : dbmap) (activities : list fp32) (origin current : list Z)
    (size pivot i j : Z) : Prop :=
  learnt_sort_segment_domain db origin /\
  learnt_sort_context db activities /\
  In pivot (db_words db) /\
  Permutation origin current /\
  Zlength current = size /\
  -1 <= i < j /\ 0 < j <= size /\
  exists L R,
    i < L < size /\ L <= j /\ 0 <= R < j /\
    learnt_cmp_stop db activities (Znth L current 0) pivot /\
    learnt_cmp_stop db activities pivot (Znth R current 0).

Definition sortrnd_left_scan_inv
    (db : dbmap) (activities : list fp32) (origin current : list Z)
    (size pivot i j : Z) : Prop :=
  sortrnd_partition_inv db activities origin current size pivot i j.

Definition sortrnd_right_scan_inv
    (db : dbmap) (activities : list fp32) (origin current : list Z)
    (size pivot i j : Z) : Prop :=
  learnt_sort_segment_domain db origin /\
  learnt_sort_context db activities /\
  In pivot (db_words db) /\
  Permutation origin current /\
  Zlength current = size /\
  0 <= i < size /\ 0 < j <= size /\
  learnt_cmp_stop db activities (Znth i current 0) pivot /\
  exists R, 0 <= R < j /\
    learnt_cmp_stop db activities pivot (Znth R current 0).

Definition sortrnd_split
    (db : dbmap) (origin current left right : list Z)
    (size cut : Z) : Prop :=
  Permutation origin current /\ Zlength current = size /\
  0 <= cut <= size /\ current = left ++ right /\
  Zlength left = cut /\ Zlength right = size - cut /\
  learnt_sort_segment_domain db left /\
  learnt_sort_segment_domain db right.

(** A database clause can be opened without conflating it with the separate
    two-cell binary scratch object.  The remainder remembers which of the
    problem/learnt lists contained the object and owns every other object;
    [clause_db_pair_focus] adds the selected object itself. *)
Definition clause_db_pair_contents
    (prob learnt : dbmap) (p : Z) (lits : list Z) : Prop :=
  exists co : clause_obj,
    In (p, co) (prob ++ learnt) /\ co_lits co = lits.

Definition clause_db_pair_focus
    (prob learnt : dbmap) (p : Z) (lits : list Z) : Assertion :=
  EX is_learnt : bool,
    MiniSatClause.rep p is_learnt lits **
    clause_db_pair_remainder prob learnt p is_learnt lits.

(** Alias-aware two-object focus for the comparator.  The distinct arm owns
    each selected object once and partitions the remaining database by their
    actual order; the alias arm exposes only one object. *)


Lemma clause_db_rep_nil : clause_db_rep nil = emp.
Proof. reflexivity. Qed.

Lemma clause_db_rep_cons : forall e rest,
  clause_db_rep (e :: rest)
  = MiniSatClause.rep (fst e) (co_learnt (snd e)) (co_lits (snd e)) **
    clause_db_rep rest.
Proof. reflexivity. Qed.

Lemma clause_db_rep_app_elim : forall db1 db2,
  clause_db_rep (db1 ++ db2) |-- clause_db_rep db1 ** clause_db_rep db2.
Proof.
  induction db1 as [| e db1 IH]; intros db2; simpl.
  - entailer_with lia.
  - sep_apply IH. msat_entailer_with lia.
Qed.

(* Database concatenation has a shared spatial equivalence for reconstruction proofs. *)
Lemma clause_db_rep_app_equiv : forall db1 db2,
  clause_db_rep (db1 ++ db2) --||-- clause_db_rep db1 ** clause_db_rep db2.
Proof. intros. split; [apply clause_db_rep_app_elim|apply clause_db_rep_app_intro]. Qed.

(** Owning the database supplies the pointer half of [db_wf]
    ([0 < p] and [Z.even p]) for every entry, so [db_wf]'s evenness conjunct
    -- which nothing else supplies -- is readable off the
    spatial bundle. [CORE] *)
Lemma clause_db_rep_ptrs : forall entries,
  clause_db_rep entries
  |-- “ Forall (fun e => 0 < fst e /\ Z.even (fst e) = true) entries ” &&
      clause_db_rep entries.
Proof.
  induction entries as [| e entries IH].
  - rewrite clause_db_rep_nil.
    entailer_with lia.
  - rewrite clause_db_rep_cons at 1.
    sep_apply IH.
    rewrite clause_db_rep_cons.
    unfold MiniSatClause.rep at 1.
    entailer_with lia.
    + unfold MiniSatClause.rep. entailer_with lia.
    + constructor; [| exact H].
      split; [tauto | apply clause_ptr_even; tauto].
Qed.

(** A newly allocated clause cannot alias an already owned clause object:
    both would own the same initialized-or-undefined header cell. *)
Lemma MiniSatClause_undef_rep_distinct : forall c size p learnt lits,
  MiniSatClause.undef c size ** MiniSatClause.rep p learnt lits
  |-- “ c <> p ” &&
      (MiniSatClause.undef c size ** MiniSatClause.rep p learnt lits).
Proof.
  intros c size p learnt lits.
  unfold MiniSatClause.undef at 1.
  coq_prop_lift.
  apply coq_prop_andp_left. intros Hc.
  unfold MiniSatClause.rep at 1.
  coq_prop_lift.
  apply coq_prop_andp_left. intros Hp.
  destruct (Z.eq_dec c p) as [Heq | Hneq].
  - subst p.
    sep_apply (store_int_undef_store_int
      (clause_hdr_addr c) (clause_hdr_word learnt (Zlength lits))).
    sep_apply (dup_undef_store_int (clause_hdr_addr c)).
    entailer_with lia.
  - unfold MiniSatClause.undef, MiniSatClause.rep.
    msat_entailer_with lia.
Qed.

(** Iterating the same separation argument extracts non-membership from the
    complete old database without trusting the allocator with ghost state. *)
Lemma MiniSatClause_undef_db_distinct : forall c size db,
  MiniSatClause.undef c size ** clause_db_rep db
  |-- “ ~ In c (map fst db) ” &&
      (MiniSatClause.undef c size ** clause_db_rep db).
Proof.
  intros c size db. induction db as [| [p co] db IH].
  - rewrite clause_db_rep_nil at 1. entailer_with int_auto.
  - rewrite clause_db_rep_cons at 1.
    sep_apply (MiniSatClause_undef_rep_distinct
      c size p (co_learnt co) (co_lits co)).
    coq_prop_lift.
    apply coq_prop_andp_left. intros Hcp.
    sep_apply IH.
    coq_prop_lift.
    apply coq_prop_andp_left. intros Htail.
    assert (Hnotin : ~ In c (map fst ((p, co) :: db))).
    { simpl. intros [Hpc | Hin].
      - apply Hcp. symmetry. exact Hpc.
      - apply Htail. exact Hin. }
    rewrite clause_db_rep_cons.
    msat_entailer_with int_auto.
Qed.

(** Every database object can be handed to [minisat_clause_free]. *)
Fixpoint clause_db_owned (entries : dbmap) : Assertion :=
  match entries with
  | nil => emp
  | e :: rest =>
      MiniSatClause.owned (fst e) (Zlength (co_lits (snd e))) **
      clause_db_owned rest
  end.


Definition stats_set_decisions        (v : Z) (l : list Z) : list Z := replace_Znth 1 v l.

Definition stats_set_propagations     (v : Z) (l : list Z) : list Z := replace_Znth 2 v l.

Definition stats_set_inspects         (v : Z) (l : list Z) : list Z := replace_Znth 3 v l.

Definition stats_set_conflicts        (v : Z) (l : list Z) : list Z := replace_Znth 4 v l.

Definition stats_set_clauses          (v : Z) (l : list Z) : list Z := replace_Znth 5 v l.

Definition stats_set_clauses_literals (v : Z) (l : list Z) : list Z := replace_Znth 6 v l.

Definition stats_set_learnts          (v : Z) (l : list Z) : list Z := replace_Znth 7 v l.

Definition stats_set_learnts_literals (v : Z) (l : list Z) : list Z := replace_Znth 8 v l.

(* Runtime configuration updates share all solver storage and logical state. *)
Definition msolver_runtime_update (M : msolver)
    (model : list Z)
    (var_inc : fp64)
    (var_decay : fp64)
    (cla_inc : fp32)
    (cla_decay : fp32)
    (progress : fp64)
    (stats : list Z) : msolver := {|
  ms_size := ms_size M;
  ms_cap := ms_cap M;
  ms_qtail := ms_qtail M;
  ms_capacity_pending_qhead := ms_capacity_pending_qhead M;
  ms_capacity_root_propagation_pending := ms_capacity_root_propagation_pending M;
  ms_core := ms_core M;
  ms_root_level := ms_root_level M;
  ms_reason_words := ms_reason_words M;
  ms_reason_of := ms_reason_of M;
  ms_prob := ms_prob M;
  ms_learnt := ms_learnt M;
  ms_prob_cap := ms_prob_cap M;
  ms_learnt_cap := ms_learnt_cap M;
  ms_binary := ms_binary M;
  ms_binary_lits := ms_binary_lits M;
  ms_wm := ms_wm M;
  ms_wcaps := ms_wcaps M;
  ms_activity := ms_activity M;
  ms_orderpos := ms_orderpos M;
  ms_order := ms_order M;
  ms_order_cap := ms_order_cap M;
  ms_lim_cap := ms_lim_cap M;
  ms_model := model;
  ms_model_cap := ms_model_cap M;
  ms_tags := ms_tags M;
  ms_tagged := ms_tagged M;
  ms_tagged_cap := ms_tagged_cap M;
  ms_stack := ms_stack M;
  ms_stack_cap := ms_stack_cap M;
  ms_var_inc := var_inc;
  ms_var_decay := var_decay;
  ms_cla_inc := cla_inc;
  ms_cla_decay := cla_decay;
  ms_random_seed := ms_random_seed M;
  ms_progress := progress;
  ms_simpdb_assigns := ms_simpdb_assigns M;
  ms_simpdb_props := ms_simpdb_props M;
  ms_verbosity := ms_verbosity M;
  ms_stats := stats
|}.

Definition msolver_resume (M : msolver) : msolver :=
  msolver_propagation_update M (ms_cap M) (ms_qtail M) (0) (mt_set_qhead (ms_core M) (ms_capacity_pending_qhead
    M)) (ms_reason_words M) (ms_reason_of M) (ms_prob M) (ms_learnt M) (ms_binary_lits M) (ms_wm M) (ms_wcaps M)
    (ms_simpdb_props M) (ms_stats M).

(** The exact ghost record exposed by a propagation capacity abort after the
    failing outer iteration has been copied back and its queue cursor rolled
    back.  The caller supplies the normalized database maps, compacted watcher
    table, current simpdb counter, and incremented propagation counter; every
    other logical component is definitionally preserved. *)
Definition msolver_propagation_abort
    (M : msolver) (prob learnt : dbmap) (wm : wmap) (wcaps : list Z)
    (simpdb_props propagation_count : Z) : msolver :=
  msolver_propagation_update M (ms_cap M) (ms_qtail M) (ms_capacity_root_propagation_pending M) (mt_set_qhead
    (ms_core M) (mt_qhead (ms_core M) - 1)) (ms_reason_words M) (ms_reason_of M) (prob) (learnt) (ms_binary_lits
    M) (wm) (wcaps) (simpdb_props) (stats_set_propagations propagation_count (ms_stats M)).

(** The mutable ghost projection while [solver_propagate] is scanning one
    watcher vector.  The source vector is spatially open during the scan, so
    callers supply the evolving trail/reason, database, watcher-map and
    bookkeeping components; every field outside propagation's footprint is
    definitionally inherited from the state at the outer-iteration entry. *)
Definition msolver_propagation_scan
    (M : msolver) (core : mtrail) (qtail : Z)
    (reason_words : list Z) (reason_of : Z -> option clause)
    (prob learnt : dbmap) (wm : wmap) (wcaps : list Z)
    (simpdb_props propagation_count : Z) : msolver :=
  msolver_propagation_update M (ms_cap M) (qtail) (ms_capacity_root_propagation_pending M) (core) (reason_words)
    (reason_of) (prob) (learnt) (ms_binary_lits M) (wm) (wcaps) (simpdb_props) (stats_set_propagations
    propagation_count (ms_stats M)).

Definition msolver_propagation_scan_begin
    (M : msolver) (simpdb_props propagation_count : Z) : msolver :=
  msolver_propagation_scan M
    (mt_set_qhead (ms_core M) (mt_qhead (ms_core M) + 1))
    (ms_qtail M) (ms_reason_words M) (ms_reason_of M)
    (ms_prob M) (ms_learnt M) (ms_wm M) (ms_wcaps M)
    simpdb_props propagation_count.

(** Exact successful [enqueue] projection.  The already-true arm is the
    identity; only an unassigned variable extends the trail and reason map. *)
Definition msolver_propagation_enqueue_success
    (M : msolver) (l reason_word : Z) (reason_clause : clause) : msolver :=
  let v := lit_var_c l in
  if Znth v (mt_assigns (ms_core M)) 0 =? 0 then
    msolver_propagation_overlay M
      (mt_enqueue (ms_core M) l) (ms_qtail M + 1)
      (replace_Znth v reason_word (ms_reason_words M))
      (sat_function_update (ms_reason_of M) v (Some reason_clause))
      (ms_prob M) (ms_learnt M) (ms_binary_lits M)
      (ms_wm M) (ms_wcaps M) (ms_stats M)
  else M.

(** Exact bookkeeping projection after [act_clause_bump] and the two
    unsigned learned-clause counters.  Every semantic field, including the
    saved model and its capacity, is inherited from [M]. *)
Definition msolver_with_cla_inc_stats
    (M : msolver) (cla_inc : fp32) (stats : list Z) : msolver := {|
  ms_size := ms_size M; ms_cap := ms_cap M; ms_qtail := ms_qtail M;
  ms_capacity_pending_qhead := ms_capacity_pending_qhead M;
  ms_capacity_root_propagation_pending :=
    ms_capacity_root_propagation_pending M;
  ms_core := ms_core M; ms_root_level := ms_root_level M;
  ms_reason_words := ms_reason_words M; ms_reason_of := ms_reason_of M;
  ms_prob := ms_prob M; ms_learnt := ms_learnt M;
  ms_prob_cap := ms_prob_cap M; ms_learnt_cap := ms_learnt_cap M;
  ms_binary := ms_binary M; ms_binary_lits := ms_binary_lits M;
  ms_wm := ms_wm M; ms_wcaps := ms_wcaps M;
  ms_activity := ms_activity M; ms_orderpos := ms_orderpos M;
  ms_order := ms_order M; ms_order_cap := ms_order_cap M;
  ms_lim_cap := ms_lim_cap M; ms_model := ms_model M;
  ms_model_cap := ms_model_cap M; ms_tags := ms_tags M;
  ms_tagged := ms_tagged M; ms_tagged_cap := ms_tagged_cap M;
  ms_stack := ms_stack M; ms_stack_cap := ms_stack_cap M;
  ms_var_inc := ms_var_inc M; ms_var_decay := ms_var_decay M;
  ms_cla_inc := cla_inc; ms_cla_decay := ms_cla_decay M;
  ms_random_seed := ms_random_seed M; ms_progress := ms_progress M;
  ms_simpdb_assigns := ms_simpdb_assigns M;
  ms_simpdb_props := ms_simpdb_props M;
  ms_verbosity := ms_verbosity M; ms_stats := stats
|}.

(** Replace only the saved-model vector and its capacity.  Model copying
    keeps one semantic base state fixed while the physical vector grows, then
    uses this projection exactly once when the completed vector is refolded. *)
Definition msolver_with_model
    (M : msolver) (model : list Z) (model_cap : Z) : msolver := {|
  ms_size := ms_size M; ms_cap := ms_cap M; ms_qtail := ms_qtail M;
  ms_capacity_pending_qhead := ms_capacity_pending_qhead M;
  ms_capacity_root_propagation_pending :=
    ms_capacity_root_propagation_pending M;
  ms_core := ms_core M; ms_root_level := ms_root_level M;
  ms_reason_words := ms_reason_words M; ms_reason_of := ms_reason_of M;
  ms_prob := ms_prob M; ms_learnt := ms_learnt M;
  ms_prob_cap := ms_prob_cap M; ms_learnt_cap := ms_learnt_cap M;
  ms_binary := ms_binary M; ms_binary_lits := ms_binary_lits M;
  ms_wm := ms_wm M; ms_wcaps := ms_wcaps M;
  ms_activity := ms_activity M; ms_orderpos := ms_orderpos M;
  ms_order := ms_order M; ms_order_cap := ms_order_cap M;
  ms_lim_cap := ms_lim_cap M; ms_model := model;
  ms_model_cap := model_cap; ms_tags := ms_tags M;
  ms_tagged := ms_tagged M; ms_tagged_cap := ms_tagged_cap M;
  ms_stack := ms_stack M; ms_stack_cap := ms_stack_cap M;
  ms_var_inc := ms_var_inc M; ms_var_decay := ms_var_decay M;
  ms_cla_inc := ms_cla_inc M; ms_cla_decay := ms_cla_decay M;
  ms_random_seed := ms_random_seed M; ms_progress := ms_progress M;
  ms_simpdb_assigns := ms_simpdb_assigns M;
  ms_simpdb_props := ms_simpdb_props M;
  ms_verbosity := ms_verbosity M; ms_stats := ms_stats M
|}.

(** Exact transient after the search decision counter and [order_select].
    Only heap metadata, random seed, and fact-free statistics may differ. *)
Definition msolver_search_select
    (M : msolver) (orderpos order : list Z)
    (seed : fp64) (stats : list Z) : msolver := {|
  ms_size := ms_size M; ms_cap := ms_cap M; ms_qtail := ms_qtail M;
  ms_capacity_pending_qhead := ms_capacity_pending_qhead M;
  ms_capacity_root_propagation_pending :=
    ms_capacity_root_propagation_pending M;
  ms_core := ms_core M; ms_root_level := ms_root_level M;
  ms_reason_words := ms_reason_words M; ms_reason_of := ms_reason_of M;
  ms_prob := ms_prob M; ms_learnt := ms_learnt M;
  ms_prob_cap := ms_prob_cap M; ms_learnt_cap := ms_learnt_cap M;
  ms_binary := ms_binary M; ms_binary_lits := ms_binary_lits M;
  ms_wm := ms_wm M; ms_wcaps := ms_wcaps M;
  ms_activity := ms_activity M; ms_orderpos := orderpos;
  ms_order := order; ms_order_cap := ms_order_cap M;
  ms_lim_cap := ms_lim_cap M; ms_model := ms_model M;
  ms_model_cap := ms_model_cap M; ms_tags := ms_tags M;
  ms_tagged := ms_tagged M; ms_tagged_cap := ms_tagged_cap M;
  ms_stack := ms_stack M; ms_stack_cap := ms_stack_cap M;
  ms_var_inc := ms_var_inc M; ms_var_decay := ms_var_decay M;
  ms_cla_inc := ms_cla_inc M; ms_cla_decay := ms_cla_decay M;
  ms_random_seed := seed; ms_progress := ms_progress M;
  ms_simpdb_assigns := ms_simpdb_assigns M;
  ms_simpdb_props := ms_simpdb_props M;
  ms_verbosity := ms_verbosity M; ms_stats := stats
|}.

Definition msolver_reorder_learnts (M : msolver) (learnt : dbmap) : msolver :=
  msolver_propagation_overlay M
    (ms_core M) (ms_qtail M) (ms_reason_words M) (ms_reason_of M)
    (ms_prob M) learnt (ms_binary_lits M)
    (ms_wm M) (ms_wcaps M) (ms_stats M).

Definition msolver_set_root (M : msolver) (root : Z) : msolver :=
  msolver_core_heap_update M (ms_core M) (ms_qtail M)
    (ms_reason_words M) (ms_reason_of M)
    (ms_orderpos M) (ms_order M) (ms_order_cap M) root.

Definition msolver_heap_project
    (M : msolver) (orderpos order : list Z) (order_cap : Z) : msolver :=
  msolver_core_heap_update M (ms_core M) (ms_qtail M)
    (ms_reason_words M) (ms_reason_of M) orderpos order order_cap
    (ms_root_level M).

(* Analysis updates preserve the database and trail while replacing scratch and heap components. *)
Definition msolver_analysis_update (M : msolver)
    (activity : list fp64)
    (orderpos : list Z)
    (order : list Z)
    (tags : list Z)
    (tagged : list Z)
    (tagged_cap : Z)
    (stack : list Z)
    (stack_cap : Z)
    (var_inc : fp64) : msolver := {|
  ms_size := ms_size M;
  ms_cap := ms_cap M;
  ms_qtail := ms_qtail M;
  ms_capacity_pending_qhead := ms_capacity_pending_qhead M;
  ms_capacity_root_propagation_pending := ms_capacity_root_propagation_pending M;
  ms_core := ms_core M;
  ms_root_level := ms_root_level M;
  ms_reason_words := ms_reason_words M;
  ms_reason_of := ms_reason_of M;
  ms_prob := ms_prob M;
  ms_learnt := ms_learnt M;
  ms_prob_cap := ms_prob_cap M;
  ms_learnt_cap := ms_learnt_cap M;
  ms_binary := ms_binary M;
  ms_binary_lits := ms_binary_lits M;
  ms_wm := ms_wm M;
  ms_wcaps := ms_wcaps M;
  ms_activity := activity;
  ms_orderpos := orderpos;
  ms_order := order;
  ms_order_cap := ms_order_cap M;
  ms_lim_cap := ms_lim_cap M;
  ms_model := ms_model M;
  ms_model_cap := ms_model_cap M;
  ms_tags := tags;
  ms_tagged := tagged;
  ms_tagged_cap := tagged_cap;
  ms_stack := stack;
  ms_stack_cap := stack_cap;
  ms_var_inc := var_inc;
  ms_var_decay := ms_var_decay M;
  ms_cla_inc := ms_cla_inc M;
  ms_cla_decay := ms_cla_decay M;
  ms_random_seed := ms_random_seed M;
  ms_progress := ms_progress M;
  ms_simpdb_assigns := ms_simpdb_assigns M;
  ms_simpdb_props := ms_simpdb_props M;
  ms_verbosity := ms_verbosity M;
  ms_stats := ms_stats M
|}.

Definition msolver_scratch_update
    (M : msolver) (tags tagged : list Z) (tagged_cap : Z)
    (stack : list Z) (stack_cap : Z) : msolver :=
  msolver_analysis_update M (ms_activity M) (ms_orderpos M) (ms_order M) (tags) (tagged) (tagged_cap) (stack)
    (stack_cap) (ms_var_inc M).

(** The ghost state reached by one tagging step of [solver_analyze]: the
    variable's tag cell is written, the variable is pushed onto [tagged]
    (possibly growing its capacity), and [act_var_bump] updates the activity
    vector, percolates the order heap (mutating [orderpos] and [order]) and
    may rescale [var_inc].  Every other field is inherited definitionally, so
    the CDCL view, the clause database, the assignment core and the analysis
    frame are all *convertible* across the step.

    [ms_order_cap] is deliberately not an argument: [act_var_bump] only
    percolates an element already present in the heap, so it cannot grow it. *)
Definition analyze_tag_step_msolver
    (M : msolver) (tags tagged : list Z) (tagged_cap : Z)
    (activity : list fp64) (orderpos order : list Z)
    (var_inc : fp64) : msolver :=
  msolver_analysis_update M (activity) (orderpos) (order) (tags) (tagged) (tagged_cap) (ms_stack M)
    (ms_stack_cap M) (var_inc).

(** Projection reduction.  [msolver] is a plain record, so each of these
    holds by conversion; they exist so a script can [rewrite] instead of
    [cbn]-ing a 39-field literal into view during entailment automation. *)
Lemma analyze_tag_step_msolver_proj :
  forall M tags tagged tagged_cap activity orderpos order var_inc,
    let M' := analyze_tag_step_msolver M tags tagged tagged_cap
                activity orderpos order var_inc in
    ms_tags M' = tags /\ ms_tagged M' = tagged /\
    ms_tagged_cap M' = tagged_cap /\ ms_activity M' = activity /\
    ms_orderpos M' = orderpos /\ ms_order M' = order /\
    ms_var_inc M' = var_inc /\
    ms_size M' = ms_size M /\ ms_cap M' = ms_cap M /\
    ms_qtail M' = ms_qtail M /\ ms_core M' = ms_core M /\
    ms_reason_words M' = ms_reason_words M /\
    ms_reason_of M' = ms_reason_of M /\
    ms_order_cap M' = ms_order_cap M /\
    ms_stack M' = ms_stack M /\ ms_stack_cap M' = ms_stack_cap M /\
    ms_stats M' = ms_stats M /\ ms_cla_inc M' = ms_cla_inc M /\
    ms_lim_cap M' = ms_lim_cap M.
Proof. intros. repeat split; reflexivity. Qed.

(** The identity law: retagging with the fields already in place is a no-op.
    This is what collapses a constructed [Mtag] back to [Mcur] on the
    fall-through arms of the analysis loop. *)
Lemma analyze_tag_step_msolver_id : forall M : msolver,
  analyze_tag_step_msolver M (ms_tags M) (ms_tagged M) (ms_tagged_cap M)
    (ms_activity M) (ms_orderpos M) (ms_order M) (ms_var_inc M) = M.
Proof. intros M. destruct M. reflexivity. Qed.

(** Exact record published after a capacity abort has been cancelled to
    level zero.  The public object exposes a drained queue, remembers the
    old propagation cursor, clears the analysis scratch vectors, and uses
    [pending_flag] to distinguish an ordinary idle root from a suspended
    retry.  All database, capacity, heap, seed, and statistic fields are
    inherited definitionally from the cancelled state. *)
Definition msolver_publish_capacity
    (M : msolver) (pending_flag : Z) : msolver := {|
  ms_size           := ms_size M;
  ms_cap            := ms_cap M;
  ms_qtail          := ms_qtail M;
  ms_capacity_pending_qhead := mt_qhead (ms_core M);
  ms_capacity_root_propagation_pending := pending_flag;
  ms_core           := mt_set_qhead (ms_core M) (ms_qtail M);
  ms_root_level     := 0;
  ms_reason_words   := ms_reason_words M;
  ms_reason_of      := ms_reason_of M;
  ms_prob           := ms_prob M;
  ms_learnt         := ms_learnt M;
  ms_prob_cap       := ms_prob_cap M;
  ms_learnt_cap     := ms_learnt_cap M;
  ms_binary         := ms_binary M;
  ms_binary_lits    := ms_binary_lits M;
  ms_wm             := ms_wm M;
  ms_wcaps          := ms_wcaps M;
  ms_activity       := ms_activity M;
  ms_orderpos       := ms_orderpos M;
  ms_order          := ms_order M;
  ms_order_cap      := ms_order_cap M;
  ms_lim_cap        := ms_lim_cap M;
  ms_model          := ms_model M;
  ms_model_cap      := ms_model_cap M;
  ms_tags           := ms_tags M;
  ms_tagged         := [];
  ms_tagged_cap     := ms_tagged_cap M;
  ms_stack          := [];
  ms_stack_cap      := ms_stack_cap M;
  ms_var_inc        := ms_var_inc M;
  ms_var_decay      := ms_var_decay M;
  ms_cla_inc        := ms_cla_inc M;
  ms_cla_decay      := ms_cla_decay M;
  ms_random_seed    := ms_random_seed M;
  ms_progress       := ms_progress M;
  ms_simpdb_assigns := ms_simpdb_assigns M;
  ms_simpdb_props   := ms_simpdb_props M;
  ms_verbosity      := ms_verbosity M;
  ms_stats          := ms_stats M
|}.

Definition msolver_simpdb_update
    (M : msolver) (simpdb_assigns simpdb_props : Z) : msolver := {|
  ms_size := ms_size M; ms_cap := ms_cap M; ms_qtail := ms_qtail M;
  ms_capacity_pending_qhead := ms_capacity_pending_qhead M;
  ms_capacity_root_propagation_pending :=
    ms_capacity_root_propagation_pending M;
  ms_core := ms_core M; ms_root_level := ms_root_level M;
  ms_reason_words := ms_reason_words M; ms_reason_of := ms_reason_of M;
  ms_prob := ms_prob M; ms_learnt := ms_learnt M;
  ms_prob_cap := ms_prob_cap M; ms_learnt_cap := ms_learnt_cap M;
  ms_binary := ms_binary M; ms_binary_lits := ms_binary_lits M;
  ms_wm := ms_wm M; ms_wcaps := ms_wcaps M;
  ms_activity := ms_activity M; ms_orderpos := ms_orderpos M;
  ms_order := ms_order M; ms_order_cap := ms_order_cap M;
  ms_lim_cap := ms_lim_cap M; ms_model := ms_model M;
  ms_model_cap := ms_model_cap M; ms_tags := ms_tags M;
  ms_tagged := ms_tagged M; ms_tagged_cap := ms_tagged_cap M;
  ms_stack := ms_stack M; ms_stack_cap := ms_stack_cap M;
  ms_var_inc := ms_var_inc M; ms_var_decay := ms_var_decay M;
  ms_cla_inc := ms_cla_inc M; ms_cla_decay := ms_cla_decay M;
  ms_random_seed := ms_random_seed M; ms_progress := ms_progress M;
  ms_simpdb_assigns := simpdb_assigns;
  ms_simpdb_props := simpdb_props;
  ms_verbosity := ms_verbosity M; ms_stats := ms_stats M
|}.

Fixpoint clear_indices (xs tags : list Z) : list Z :=
  match xs with
  | [] => tags
  | x :: rest => clear_indices rest (replace_Znth x 0 tags)
  end.

Definition analysis_tags_exact
    (n : Z) (tags tagged : list Z) : Prop :=
  Zlength tags = n /\ NoDup tagged /\
  Forall (fun v => 0 <= v < n) tagged /\
  Forall (fun z => z = 0 \/ z = 1) tags /\
  (forall v, 0 <= v < n ->
     (Znth v tags 0 = 1 <-> In v tagged)).

(** Parent-owned freed-hole state for learned-database compaction.  The live
    database is exactly the already-kept prefix plus the unvisited suffix of
    the still-full vector.  Cells in [[j,i)) may contain stale freed pointers
    but are never dereferenced again and are discarded by the final resize. *)
Definition db_compaction_inv
    (M : msolver) (words : list Z) (i j : Z) : Prop :=
  0 <= j /\ j <= i /\ i <= Zlength words /\
  map fst (ms_learnt M) =
    sublist 0 j words ++ sublist i (Zlength words) words.

Definition db_compaction_step (M : msolver) (c : Z) (M' : msolver) : Prop :=
  (M' = M \/
   exists wm stats,
     M' = msolver_remove_clause M true c wm stats) /\
  ms_model M' = ms_model M /\
  ms_cla_decay M' = ms_cla_decay M.

(** Downward clearing progress for the first cancellation loop. *)
Definition cancel_clear_loop_inv
    (M : msolver) (level c : Z) (assigns reasons : list Z) : Prop :=
  let trail := mt_trail (ms_core M) in
  let qtail := ms_qtail M in
  let bound := Znth level (mt_lim (ms_core M)) 0 in
  0 <= level < Zlength (mt_lim (ms_core M)) /\
  bound - 1 <= c < qtail /\
  assigns = clear_vars (sublist (c + 1) qtail trail)
                        (mt_assigns (ms_core M)) /\
  reasons = clear_vars (sublist (c + 1) qtail trail)
                        (ms_reason_words M).

(** Progress of the second loop: the cleared arrays are already final and
    [[c+1,qhead)) has been restored to the heap. *)
Definition cancel_reinsert_loop_inv
    (M : msolver) (level c order_cap : Z)
    (assigns reasons order orderpos : list Z)
    : Prop :=
  let trail := mt_trail (ms_core M) in
  let qhead := mt_qhead (ms_core M) in
  let bound := Znth level (mt_lim (ms_core M)) 0 in
  assigns = clear_vars (zdrop bound trail) (mt_assigns (ms_core M)) /\
  reasons = clear_vars (zdrop bound trail) (ms_reason_words M) /\
  0 <= level < Zlength (mt_lim (ms_core M)) /\
  bound - 1 <= c < qhead /\
  ms_order_cap M <= order_cap <= INT_MAX /\ 0 < order_cap /\
  Zlength order <= order_cap /\
  heap_wf (ms_size M) (heap_of_lists order orderpos) /\
  incl (ms_order M) order /\
  cancel_reinserted (heap_of_lists order orderpos)
                      trail (c + 1) qhead.

Definition capacity_reinsert_loop_inv
    (M : msolver) (level c order_cap : Z) (order orderpos : list Z) : Prop :=
  let trail := mt_trail (ms_core M) in
  let qhead := mt_qhead (ms_core M) in
  let qtail := ms_qtail M in
  level = 0 /\ qhead - 1 <= c < qtail /\
  ms_order_cap M <= order_cap <= INT_MAX /\ 0 < order_cap /\
  Zlength order <= order_cap /\
  heap_wf (ms_size M) (heap_of_lists order orderpos) /\
  incl (ms_order M) order /\
  cancel_reinserted (heap_of_lists order orderpos)
                      trail (c + 1) qtail.

Definition cancel_bound_ready (M : msolver) (level : Z) : Prop :=
  Zlength (mt_lim (ms_core M)) <= level \/
  Znth level (mt_lim (ms_core M)) 0 <= mt_qhead (ms_core M).

Definition msolver_propagation_binary_conflict
    (M : msolver) (implied propagator : Z) : msolver :=
  msolver_propagation_overlay M
    (ms_core M) (ms_qtail M) (ms_reason_words M) (ms_reason_of M)
    (ms_prob M) (ms_learnt M) [implied; lit_neg_c propagator]
    (ms_wm M) (ms_wcaps M) (ms_stats M).

(** The common scan exit changes only the accumulated inspect statistic. *)
Definition msolver_propagation_scan_finish
    (M : msolver) (inspect_delta : Z) : msolver :=
  msolver_propagation_overlay M
    (ms_core M) (ms_qtail M) (ms_reason_words M) (ms_reason_of M)
    (ms_prob M) (ms_learnt M) (ms_binary_lits M)
    (ms_wm M) (ms_wcaps M)
    (stats_set_inspects (MiniSatTarget.lo64
                    (stats_inspects (ms_stats M) + inspect_delta)) (ms_stats M)).

Lemma msolver_propagation_scan_begin_qhead :
  forall M simpdb_props propagation_count,
    mt_qhead (ms_core
      (msolver_propagation_scan_begin M simpdb_props propagation_count)) =
    mt_qhead (ms_core M) + 1.
Proof. reflexivity. Qed.

(** Of the seven fields a tagging step mutates, only [ms_orderpos],
    [ms_activity] and [ms_tags] occur in [solver_shape]; [ms_tagged],
    [ms_tagged_cap], [ms_order] and [ms_var_inc] do not appear at all.  The
    shape obligation at the tagged state is therefore exactly three length
    side conditions. *)
Lemma solver_shape_analyze_tag_step :
  forall M tags tagged tagged_cap activity orderpos order var_inc,
    solver_shape M ->
    Zlength tags = ms_size M ->
    Zlength activity = ms_size M ->
    Zlength orderpos = ms_size M ->
    solver_shape (analyze_tag_step_msolver M tags tagged tagged_cap
                    activity orderpos order var_inc).
Proof.
  intros M tags tagged tagged_cap activity orderpos order var_inc
         Hshape Htags Hact Hopos.
  unfold solver_shape, analyze_tag_step_msolver, msolver_analysis_update in *. cbn in *. tauto.
Qed.

(** The clause-count cell, named for use before the public solver layout
    is complete. Other vector fields and its storage remain caller frames. *)
Definition solver_clause_count_cell (s n : Z) : Assertion :=
  vecp_size_addr &( s # "solver_t" ->ₛ "clauses") # Int |-> n.

(** The nine pointer fields. *)
Definition solver_ptrs_rep
    (s wl act asg opos rsn lvl trl bin tgs : Z) : Assertion :=
  &( s # "solver_t" ->ₛ "wlists")   # Ptr |-> wl **
  &( s # "solver_t" ->ₛ "activity") # Ptr |-> act **
  &( s # "solver_t" ->ₛ "assigns")  # Ptr |-> asg **
  &( s # "solver_t" ->ₛ "orderpos") # Ptr |-> opos **
  &( s # "solver_t" ->ₛ "reasons")  # Ptr |-> rsn **
  &( s # "solver_t" ->ₛ "levels")   # Ptr |-> lvl **
  &( s # "solver_t" ->ₛ "trail")    # Ptr |-> trl **
  &( s # "solver_t" ->ₛ "binary")   # Ptr |-> bin **
  &( s # "solver_t" ->ₛ "tags")     # Ptr |-> tgs.

(** *** The bundle. *)
Definition solver_rep (s : Z) (M : msolver) : Assertion :=
  “ solver_shape M ” &&
  (EX lvl : Z,
     solver_nonlevel_rep s M ** solver_levels_slice_at s M lvl).

(* Keep the outer watcher-table address public; inner vector allocations
   remain existential inside the existing representation. *)
Definition solver_rep_wl (s : Z) (M : msolver) (wl : Z) : Assertion :=
  EX lvl : Z, solver_rep_levels_wl_at s M wl lvl.

(** Components used by loops that must expose one array and, for model
    copying, the mutable model vector.  These are exact complements of the
    exposed cells; they do not weaken [solver_shape] or duplicate a solver
    representation. *)
(* ==== Clause-count lemmas for the solver_nclauses contract ==== *)

(** [solver_nclauses] returns the value of the size cell of the
    `clauses` vector, and [solver_nclauses_spec] says only that.  This lemma
    names what that cell holds for a solver that represents [M]: the number of
    clauses RESIDENT in the problem database, [Zlength (db_words (ms_prob M))]
    (equivalently [Zlength (ms_prob M)]).  It is deliberately not [Zlength F]:
    the stored database is only model-equivalent to the clause set the client
    inserted -- solver_addclause may drop root-false literals, skip tautologies
    and record a simplified clause -- so the count is an implementation
    observation, not a property of [F]. *)
Lemma solver_clause_count_cell_problem_clauses__api_reentry : forall s M,
  vecp_rep &( s # "solver_t" ->ₛ "clauses")
           (db_words (ms_prob M)) (ms_prob_cap M) |--
  solver_clause_count_cell s (Zlength (db_words (ms_prob M))) **
  (EX p : Z,
     vecp_cap_addr &( s # "solver_t" ->ₛ "clauses") # Int |-> ms_prob_cap M **
     vecp_ptr_addr &( s # "solver_t" ->ₛ "clauses") # Ptr |-> p **
     PtrArray.seg p 0 (Zlength (db_words (ms_prob M))) (db_words (ms_prob M)) **
     PtrArray.undef_seg p (Zlength (db_words (ms_prob M))) (ms_prob_cap M)).
Proof.
  intros s M. unfold vecp_rep, vecp_rep_at, solver_clause_count_cell.
  Intros p. Exists p. msat_entailer_with ltac:(tauto).
Qed.

Lemma solver_problem_clause_count_length__api_reentry : forall M,
  Zlength (db_words (ms_prob M)) = Zlength (ms_prob M).
Proof.
  intros M. unfold db_words. rewrite !Zlength_correct, length_map. reflexivity.
Qed.

Definition solver_scalars_without_size_rep
    (s : Z) (M : msolver) : Assertion :=
  clause_new_scalars_frame s M.

Definition solver_vecs_without_model_rep
    (s : Z) (M : msolver) : Assertion :=
  vecp_rep &( s # "solver_t" ->ₛ "clauses")
           (map fst (ms_prob M)) (ms_prob_cap M) **
  vecp_rep &( s # "solver_t" ->ₛ "learnts")
           (map fst (ms_learnt M)) (ms_learnt_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "tagged")
           (ms_tagged M) (ms_tagged_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "stack")
           (ms_stack M) (ms_stack_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "order")
           (ms_order M) (ms_order_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "trail_lim")
           (mt_lim (ms_core M)) (ms_lim_cap M).

Definition solver_vecs_without_clauses_rep
    (s : Z) (M : msolver) : Assertion :=
  vecp_rep &( s # "solver_t" ->ₛ "learnts")
           (map fst (ms_learnt M)) (ms_learnt_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "tagged")
           (ms_tagged M) (ms_tagged_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "stack")
           (ms_stack M) (ms_stack_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "order")
           (ms_order M) (ms_order_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "trail_lim")
           (mt_lim (ms_core M)) (ms_lim_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "model")
           (ms_model M) (ms_model_cap M).

(** Exact full-solver remainder after removing only the assignment pointer
    and its live/undefined slices.  Supplying smaller scalar/vector bundles
    specializes the same footprint for model copying without a second large
    representation. *)
(* The shared cells retain the same association under either watch-address binder policy. *)
Definition solver_without_assigns_cells_at
    (s : Z) (M : msolver) (wl act opos rsn trl tgs lvl : Z) : Assertion :=
      (&( s # "solver_t" ->ₛ "wlists") # Ptr |-> wl **
       &( s # "solver_t" ->ₛ "activity") # Ptr |-> act **
       &( s # "solver_t" ->ₛ "orderpos") # Ptr |-> opos **
       &( s # "solver_t" ->ₛ "reasons") # Ptr |-> rsn **
       &( s # "solver_t" ->ₛ "trail") # Ptr |-> trl **
       &( s # "solver_t" ->ₛ "binary") # Ptr |-> ms_binary M **
       &( s # "solver_t" ->ₛ "tags") # Ptr |-> tgs) **
      (DoubleArray.seg act 0 (ms_size M) (ms_activity M) **
       DoubleArray.undef_seg act (ms_size M) (ms_cap M) **
       IntArray.seg opos 0 (ms_size M) (ms_orderpos M) **
       IntArray.undef_seg opos (ms_size M) (ms_cap M) **
       PtrArray.seg rsn 0 (ms_size M) (ms_reason_words M) **
       PtrArray.undef_seg rsn (ms_size M) (ms_cap M) **
       CharArray.seg tgs 0 (ms_size M) (ms_tags M) **
       CharArray.undef_seg tgs (ms_size M) (ms_cap M)) **
      solver_trail_array_rep M trl **
      wlists_rep wl (ms_size M) (ms_wm M) (ms_wcaps M) **
      clause_db_rep (ms_prob M) ** clause_db_rep (ms_learnt M) **
      MiniSatClause.rep (ms_binary M) false (ms_binary_lits M) **
      stats_rep &( s # "solver_t" ->ₛ "stats") (ms_stats M) **
      solver_levels_slice_at s M lvl.

Definition solver_without_assigns_frame_at
    (s : Z) (M : msolver) (lvl : Z)
    (scalars vectors : Assertion) : Assertion :=
  “ solver_shape M ” &&
  (scalars ** solver_fp_rep s M ** vectors **
   (EX wl act opos rsn trl tgs : Z,
    solver_without_assigns_cells_at s M wl act opos rsn trl tgs lvl)).


Definition solver_without_assigns_frame_wl_at
    (s : Z) (M : msolver) (wl lvl : Z)
    (scalars vectors : Assertion) : Assertion :=
  “ solver_shape M ” &&
  (scalars ** solver_fp_rep s M ** vectors **
   (EX act opos rsn trl tgs : Z,
    solver_without_assigns_cells_at s M wl act opos rsn trl tgs lvl)).


Definition solver_assigns_focus_frame_at
    (s : Z) (M : msolver) (lvl : Z) : Assertion :=
  solver_without_assigns_frame_at
    s M lvl (solver_scalars_rep s M) (solver_vecs_rep s M).

(** Entry focus used only by [solver_solve]'s initializers: the original
    clause vector is exposed for [solver_nclauses], while the assignment
    pointer stays readable for the immediately following cached local. *)


(** Opaque complement used while [solver_solve] keeps the original-clause
    vector and assignment array concrete for its two native initializers. *)
Definition solver_solve_entry_rest_at
    (s : Z) (M : msolver) (lvl : Z) (wl : Z) : Assertion :=
  solver_without_assigns_frame_wl_at
    s M wl lvl (solver_scalars_rep s M)
    (solver_vecs_without_clauses_rep s M).

Definition solver_model_copy_frame_at
    (s : Z) (M : msolver) (lvl : Z) (wl : Z) : Assertion :=
  solver_without_assigns_frame_wl_at
    s M wl lvl (solver_scalars_without_size_rep s M)
    (solver_vecs_without_model_rep s M).

Definition solver_scalars_without_root_rep
    (s : Z) (M : msolver) : Assertion :=
  &( s # "solver_t" ->ₛ "size") # Int |-> ms_size M **
  &( s # "solver_t" ->ₛ "cap") # Int |-> ms_cap M **
  &( s # "solver_t" ->ₛ "qhead") # Int |-> mt_qhead (ms_core M) **
  &( s # "solver_t" ->ₛ "qtail") # Int |-> ms_qtail M **
  &( s # "solver_t" ->ₛ "capacity_pending_qhead")
    # Int |-> ms_capacity_pending_qhead M **
  &( s # "solver_t" ->ₛ "capacity_root_propagation_pending")
    # Int |-> ms_capacity_root_propagation_pending M **
  &( s # "solver_t" ->ₛ "simpdb_assigns")
    # Int |-> ms_simpdb_assigns M **
  &( s # "solver_t" ->ₛ "simpdb_props") # Int |-> ms_simpdb_props M **
  &( s # "solver_t" ->ₛ "verbosity") # Int |-> ms_verbosity M.

Definition solver_vecs_without_lim_rep
    (s : Z) (M : msolver) : Assertion :=
  vecp_rep &( s # "solver_t" ->ₛ "clauses")
           (map fst (ms_prob M)) (ms_prob_cap M) **
  vecp_rep &( s # "solver_t" ->ₛ "learnts")
           (map fst (ms_learnt M)) (ms_learnt_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "tagged")
           (ms_tagged M) (ms_tagged_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "stack")
           (ms_stack M) (ms_stack_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "order")
           (ms_order M) (ms_order_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "model")
           (ms_model M) (ms_model_cap M).

Definition solver_simplify_lim_frame_at
    (s : Z) (M : msolver) (asg lvl : Z) (wl : Z) : Assertion :=
  solver_without_assigns_frame_wl_at
    s M wl lvl (solver_scalars_rep s M)
    (solver_vecs_without_lim_rep s M) **
  &( s # "solver_t" ->ₛ "assigns") # Ptr |-> asg **
  CharArray.seg asg 0 (ms_size M) (mt_assigns (ms_core M)) **
  CharArray.undef_seg asg (ms_size M) (ms_cap M).

Definition solver_simplify_control_scalars_frame
    (s : Z) (M : msolver) : Assertion :=
  &( s # "solver_t" ->ₛ "size") # Int |-> ms_size M **
  &( s # "solver_t" ->ₛ "cap") # Int |-> ms_cap M **
  &( s # "solver_t" ->ₛ "qtail") # Int |-> ms_qtail M **
  &( s # "solver_t" ->ₛ "capacity_pending_qhead")
    # Int |-> ms_capacity_pending_qhead M **
  &( s # "solver_t" ->ₛ "capacity_root_propagation_pending")
    # Int |-> ms_capacity_root_propagation_pending M **
  &( s # "solver_t" ->ₛ "root_level") # Int |-> ms_root_level M **
  &( s # "solver_t" ->ₛ "verbosity") # Int |-> ms_verbosity M.

(** Exact complement of the three simplify guard cells and the cached
    reasons pointer.  The reasons array remains owned by this frame. *)
Definition solver_simplify_control_frame_at
    (s : Z) (M : msolver) (asg lvl rsn : Z) (wl : Z) : Assertion :=
  “ solver_shape M ” &&
  (solver_simplify_control_scalars_frame s M **
   solver_fp_rep s M ** solver_vecs_rep s M **
   (EX act opos trl tgs : Z,
      (&( s # "solver_t" ->ₛ "wlists") # Ptr |-> wl **
       &( s # "solver_t" ->ₛ "activity") # Ptr |-> act **
       &( s # "solver_t" ->ₛ "assigns") # Ptr |-> asg **
       &( s # "solver_t" ->ₛ "orderpos") # Ptr |-> opos **
       &( s # "solver_t" ->ₛ "levels") # Ptr |-> lvl **
       &( s # "solver_t" ->ₛ "trail") # Ptr |-> trl **
       &( s # "solver_t" ->ₛ "binary") # Ptr |-> ms_binary M **
       &( s # "solver_t" ->ₛ "tags") # Ptr |-> tgs) **
      solver_var_arrays_rep M act asg opos rsn lvl tgs **
      solver_trail_array_rep M trl **
      wlists_rep wl (ms_size M) (ms_wm M) (ms_wcaps M) **
      clause_db_rep (ms_prob M) ** clause_db_rep (ms_learnt M) **
      MiniSatClause.rep (ms_binary M) false (ms_binary_lits M) **
      stats_rep &( s # "solver_t" ->ₛ "stats") (ms_stats M))).

(** Exact remainder while installing the completed assumption prefix as the
    search root.  [root_level] and [trail_lim] stay visible for the single C
    assignment and its [solver_dlevel] read. *)
Definition solver_root_install_frame_at
    (s : Z) (M : msolver) (asg lvl : Z) (wl : Z) : Assertion :=
  solver_without_assigns_frame_wl_at
    s M wl lvl (solver_scalars_without_root_rep s M)
    (solver_vecs_without_lim_rep s M) **
  &( s # "solver_t" ->ₛ "assigns") # Ptr |-> asg **
  CharArray.seg asg 0 (ms_size M) (mt_assigns (ms_core M)) **
  CharArray.undef_seg asg (ms_size M) (ms_cap M).

(** Exact complement of the four scalar cells and decision-level vector
    touched while resuming a suspended level-zero propagation. *)
Definition solver_resume_scalars_frame
    (s : Z) (M : msolver) : Assertion :=
  &( s # "solver_t" ->ₛ "size") # Int |-> ms_size M **
  &( s # "solver_t" ->ₛ "cap") # Int |-> ms_cap M **
  &( s # "solver_t" ->ₛ "root_level") # Int |-> ms_root_level M **
  &( s # "solver_t" ->ₛ "simpdb_assigns")
    # Int |-> ms_simpdb_assigns M **
  &( s # "solver_t" ->ₛ "simpdb_props") # Int |-> ms_simpdb_props M **
  &( s # "solver_t" ->ₛ "verbosity") # Int |-> ms_verbosity M.

Definition solver_resume_frame_at
    (s : Z) (M : msolver) (asg lvl : Z) (wl : Z) : Assertion :=
  solver_without_assigns_frame_wl_at
    s M wl lvl (solver_resume_scalars_frame s M)
    (solver_vecs_without_lim_rep s M) **
  &( s # "solver_t" ->ₛ "assigns") # Ptr |-> asg **
  CharArray.seg asg 0 (ms_size M) (mt_assigns (ms_core M)) **
  CharArray.undef_seg asg (ms_size M) (ms_cap M).

(** Search repeatedly exposes a few embedded scalar/vector/statistic cells
    while keeping the pointer-indexed solver payload and cached level address
    fixed.  Parameterizing only those four embedded bundles avoids repeating
    the full payload at every branch. *)
(** Pointer-indexed arrays and clauses kept stable while search updates its
    embedded scalar, vector and statistics bundles. *)
Definition solver_payload_cells (s : Z) (M : msolver) (wl : Z) : Assertion :=
  (EX act asg opos rsn trl tgs : Z,
      (&( s # "solver_t" ->ₛ "wlists") # Ptr |-> wl **
       &( s # "solver_t" ->ₛ "activity") # Ptr |-> act **
       &( s # "solver_t" ->ₛ "assigns") # Ptr |-> asg **
       &( s # "solver_t" ->ₛ "orderpos") # Ptr |-> opos **
       &( s # "solver_t" ->ₛ "reasons") # Ptr |-> rsn **
       &( s # "solver_t" ->ₛ "trail") # Ptr |-> trl **
       &( s # "solver_t" ->ₛ "binary") # Ptr |-> ms_binary M **
       &( s # "solver_t" ->ₛ "tags") # Ptr |-> tgs) **
      (DoubleArray.seg act 0 (ms_size M) (ms_activity M) **
       DoubleArray.undef_seg act (ms_size M) (ms_cap M) **
       CharArray.seg asg 0 (ms_size M) (mt_assigns (ms_core M)) **
       CharArray.undef_seg asg (ms_size M) (ms_cap M) **
       IntArray.seg opos 0 (ms_size M) (ms_orderpos M) **
       IntArray.undef_seg opos (ms_size M) (ms_cap M) **
       PtrArray.seg rsn 0 (ms_size M) (ms_reason_words M) **
       PtrArray.undef_seg rsn (ms_size M) (ms_cap M) **
       CharArray.seg tgs 0 (ms_size M) (ms_tags M) **
       CharArray.undef_seg tgs (ms_size M) (ms_cap M)) **
      solver_trail_array_rep M trl **
      wlists_rep wl (ms_size M) (ms_wm M) (ms_wcaps M) **
      clause_db_rep (ms_prob M) ** clause_db_rep (ms_learnt M) **
      MiniSatClause.rep (ms_binary M) false (ms_binary_lits M)).

Definition solver_search_payload
    (s : Z) (M : msolver)
    (wl : Z) (scalars fps vectors statistics : Assertion) : Assertion :=
  “ solver_shape M ” &&
  (scalars ** fps ** vectors ** statistics **
   solver_payload_cells s M wl).

Definition solver_search_bundle_at
    (s : Z) (M : msolver) (lvl wl : Z)
    (scalars fps vectors statistics : Assertion) : Assertion :=
  solver_search_payload s M wl scalars fps vectors statistics **
  solver_levels_slice_at s M lvl.

Definition solver_fp_without_decays_rep (s : Z) (M : msolver) : Assertion :=
  &( s # "solver_t" ->ₛ "var_inc") # Double |-> ms_var_inc M **
  &( s # "solver_t" ->ₛ "cla_inc") # Float |-> ms_cla_inc M **
  &( s # "solver_t" ->ₛ "random_seed") # Double |-> ms_random_seed M **
  &( s # "solver_t" ->ₛ "progress_estimate") # Double |-> ms_progress M.

