Lemma veci_rep_bounds_keep__lit_removable :
  forall v l cap,
    veci_rep v l cap |--
      “ 0 <= Zlength l <= cap /\ 0 < cap <= INT_MAX ” &&
      veci_rep v l cap.
Proof.
  intros v l cap.
  unfold veci_rep at 1. Intros p.
  unfold veci_rep_at at 1. Intros_p Hbounds.
  unfold veci_rep. Exists p.
