Lemma assumption_prefix_snoc__solve : forall raw k,
  0 <= k < Zlength raw ->
  assumption_prefix raw (k + 1) =
  assumption_prefix raw k ++ (lit_denote (Znth k raw 0) :: nil).
Proof.
  intros raw k Hk. unfold assumption_prefix.
  rewrite (sublist_split 0 (k + 1) k raw) by lia.
  rewrite (sublist_single 0 k raw) by lia.
  rewrite lits_denote_app. reflexivity.
Qed.

Lemma assumption_fresh_transition_intro__solve :
  forall n F A_arr raw k M lim_cap,
  msolver_inv_assuming_strong n F A_arr (assumption_prefix raw k) M ->
  assumption_fresh_ready n raw k M ->
  msolver_seed_shadow M ->
  ms_capacity_root_propagation_pending M = 0 ->
  A_arr = assumption_prefix raw (Zlength raw) ->
  Forall (lit_wf_c n) raw ->
  0 <= k -> k < Zlength raw ->
  ms_lim_cap M <= lim_cap <= INT_MAX ->
  assumption_fresh_transition n F A_arr raw k lim_cap M
    (msolver_assume M (Znth k raw 0) lim_cap).
Proof.
  intros n F A_arr raw k M lim_cap Hstrong Hready Hseed Hpending
    Harr Hrawwf Hk0 Hklt Hcap.
  pose proof (msas_weak Hstrong) as Hweak.
  pose proof (msas_prop_level Hstrong) as Hprop.
  pose proof (msas_watch_frontier Hstrong) as Hwatch.
  pose proof (msas_heap_covers Hstrong) as Hheap.
  pose proof (msas_reasonless_current Hstrong) as Hreasonless.
  pose proof (msa_shape Hweak) as Hshape.
  pose proof (msa_trail_wf Hweak) as Htrailwf.
  pose proof (msa_size Hweak) as Hsize.
  unfold assumption_fresh_ready in Hready.
  destruct Hready as [Hsize' [Hdrain [Hfresh [Hlevelroom Henq]]]].
  unfold enqueue_input in Henq.
  destruct Henq as [Hlit [Htwice [Haslen [Hlvlen [Hrslen
    [Htrlen [Hqrange [Hroom Hcells]]]]]]]].
  set (l := Znth k raw 0).
  assert (Hfreshl : Znth (lit_var_c l) (mt_assigns (ms_core M)) 0 = 0)
    by exact Hfresh.
  assert (Hroomcap : ms_qtail M < ms_cap M).
  { specialize (Hroom Hfreshl). unfold solver_shape in Hshape. lia. }
  assert (Htrailnew : mtrail_wf n (ms_core (msolver_assume M l lim_cap))).
  { unfold msolver_assume. cbn [ms_core].
    apply mtrail_wf_decide; assumption. }
  assert (Hassign := msolver_assume_assigns_one__search n M l lim_cap
    Htrailwf Hlit Hfreshl).
  assert (Hsizenew : n = ms_size (msolver_assume M l lim_cap)) by exact Hsize.
  assert (Hprefix : assumption_prefix raw (k + 1) =
      assumption_prefix raw k ++ (lit_denote l :: nil)).
  { unfold l. apply assumption_prefix_snoc__solve. lia. }
  assert (Hweaknew : msolver_inv_assuming n F A_arr
      (assumption_prefix raw (k + 1)) (msolver_assume M l lim_cap)).
  { refine {| msa_size := Hsizenew; msa_n_range := msa_n_range Hweak;
      msa_shape := solver_shape_assume__search M l lim_cap Hshape Hroomcap Hpending Hcap;
      msa_F_wf := msa_F_wf Hweak; msa_A_wf := msa_A_wf Hweak;
      msa_trail_wf := Htrailnew;
      msa_level_bound := _;
      msa_decisions := _; msa_proc_incl := _; msa_proc_sat := _;
      msa_stable := _; msa_reasons_ent := _; msa_reasons_inj := _;
      msa_trail_impl := _; msa_db_wf := msa_db_wf Hweak;
      msa_db_matches := msa_db_matches Hweak;
      msa_db_implied := msa_db_implied Hweak;
      msa_db_complete := db_complete_assume_assuming__solve
        n F A_arr (assumption_prefix raw k) M l lim_cap Hweak Hlit Hfreshl;
      msa_learnt_db := msa_learnt_db Hweak; msa_prob_db := msa_prob_db Hweak;
      msa_binary_out := msa_binary_out Hweak;
      msa_reasons_mem := reasons_match_assume_assuming__solve
        n F A_arr (assumption_prefix raw k) M l lim_cap Hweak Hlit;
      msa_reason_head := reason_head_ok_assume_assuming__solve
        n F A_arr (assumption_prefix raw k) M l lim_cap Hweak Hlit;
      msa_reason_bin := binary_reason_same_level_assume_assuming__solve
        n F A_arr (assumption_prefix raw k) M l lim_cap Hweak Hlit Hfreshl;
      msa_wmap_exact := msa_wmap_exact Hweak; msa_tags_clear := msa_tags_clear Hweak;
      msa_heap_wf := msa_heap_wf Hweak;
      msa_cla_inc_nonnegative := msa_cla_inc_nonnegative Hweak;
      msa_seed := msa_seed Hweak |}.
    - unfold msolver_assume, mt_decide, mt_push. cbn [ms_core mt_lim].
      rewrite Zlength_app, Zlength_cons, Zlength_nil. lia.
    - destruct (msa_decisions Hweak) as [A_inst [Hdec Hincl]].
      exists (A_inst ++ (lit_denote l :: nil)). split.
      + unfold msolver_assume. cbn [ms_core].
        replace (Zlength (mt_lim (mt_decide (ms_core M) l))) with
          (Zlength (mt_lim (ms_core M)) + 1) by
          (unfold mt_decide, mt_push; cbn [mt_lim];
           rewrite Zlength_app, Zlength_cons, Zlength_nil; lia).
        rewrite (decisions_upto_decide_top n (ms_core M) l Htrailwf).
        rewrite Hdec. reflexivity.
      + rewrite Hprefix. intros a Ha.
        rewrite in_app_iff in Ha |- *. destruct Ha as [Ha|Ha];
          [left; apply Hincl; exact Ha|right; exact Ha].
    - rewrite Hprefix. intros a Ha.
      rewrite in_app_iff in Ha. destruct Ha as [Ha|Ha].
      + apply (msa_proc_incl Hweak) in Ha. exact Ha.
      + simpl in Ha. destruct Ha as [<-|[]].
        rewrite Harr. unfold assumption_prefix, lits_denote.
        apply in_map.
        replace (sublist 0 (Zlength raw) raw) with raw by
          (symmetry; apply sublist_self; reflexivity).
        apply Znth_In. lia.
    - rewrite Hprefix. apply Forall_app. split.
      + pose proof (msa_proc_sat Hweak) as Hold. revert Hold.
        apply Forall_impl. intros a Ha.
        unfold msolver_assume. cbn [ms_core].
        destruct (assump_true_at_root_decide__search n
          (ms_core M) l (Zlength (mt_lim (ms_core M))) a
          Htrailwf Hlit Hfreshl Ha) as [Htrue Hlevel].
        split; [exact Htrue|].
        eapply Z.le_trans; [exact Hlevel|].
        unfold mt_decide, mt_push. cbn [mt_lim].
        rewrite Zlength_app, Zlength_cons, Zlength_nil. lia.
      + constructor; [|constructor].
        destruct Hassign as
          [Hxnone [Hxassign [Hxlevel [Hxreason [[rx [Hxrank Hdeps]] [Hother Hdb]]]]]].
        unfold assump_true_at_root. split.
        * rewrite lit_denote_satisfying. apply eval_satisfying_literal_true.
          change (assignment (msolver_view n (msolver_assume M l lim_cap))
            (lit_var_c l) = Some (lit_pol l)). exact Hxassign.
        * rewrite lit_var_c_denote.
          unfold msolver_assume, mt_decide, mt_push.
          cbn [ms_core mt_levels mt_lim].
          rewrite Znth_replace_Znth_Same.
          2: { apply lit_var_c_in_range in Hlit.
               rewrite (mtw_levels_len Htrailwf). exact Hlit. }
          reflexivity.
    - eapply stable_view_decision_assign__search;
        [exact (msa_stable Hweak)|exact Hassign|].
      unfold msolver_view, msolver_assume, view_of, mt_decide, mt_push.
      cbn [current_level ms_core mt_lim].
      rewrite Zlength_app, Zlength_cons, Zlength_nil. reflexivity.
    - eapply reasons_entailed_decision_assign__search;
        eauto using msa_reasons_ent.
    - eapply reasons_var_injective_decision_assign__search;
        eauto using msa_reasons_inj.
    - unfold msolver_assume. cbn [ms_core].
      eapply trail_implied_decision; eauto using msa_trail_impl.
  }
  assert (Hqhead : mt_qhead (ms_core M) = Zlength (mt_trail (ms_core M)))
    by lia.
  destruct (msolver_assume_prop_watch__search n M l lim_cap
    Htrailwf Hlit Hfreshl Hqhead Hprop Hwatch) as [Hpropnew Hwatchnew].
  assert (Hreasonnew : current_reasonless_earliest n
      (msolver_assume M l lim_cap)).
  { eapply current_reasonless_earliest_assume__solve;
      [exact Hweak|exact Hreasonless|exact Hlit|exact Hfreshl]. }
  assert (Hheapnew : heap_covers n (msolver_heap (msolver_assume M l lim_cap))
      (mt_assigns (ms_core (msolver_assume M l lim_cap)))
      (mt_trail (ms_core (msolver_assume M l lim_cap)))
      (mt_qhead (ms_core (msolver_assume M l lim_cap)))).
  { unfold msolver_assume, mt_decide, mt_push.
    cbn [msolver_heap ms_core mt_assigns mt_trail mt_qhead].
    eapply heap_covers_enqueue; [exact Hheap|lia| |].
    - intros v Hv Hvassigned.
      destruct (Z.eq_dec v (lit_var_c l)) as [->|Hvne].
      + rewrite Znth_replace_Znth_Same;
          [apply lit_sig_nonzero|].
        apply lit_var_c_in_range in Hlit. rewrite (mtw_assigns_len Htrailwf). lia.
      + rewrite Znth_replace_Znth_Diff;
          [exact Hvassigned| | |congruence].
        * apply lit_var_c_in_range in Hlit. rewrite (mtw_assigns_len Htrailwf).
          exact Hlit.
        * rewrite (mtw_assigns_len Htrailwf). exact Hv.
    - intros i Hi. rewrite app_Znth1; reflexivity || lia.
  }
  unfold assumption_fresh_transition. fold l.
  split; [reflexivity|]. split; [exact Hcap|]. split.
  - split; [change (ms_capacity_root_propagation_pending M = 0); exact Hpending|].
    refine {| msap_weak := Hweaknew; msap_prop_level := Hpropnew;
      msap_watch_frontier := Hwatchnew; msap_heap_ready := or_introl Hheapnew;
      msap_reasonless_current := Hreasonnew |}.
  - change (msolver_seed_shadow M). exact Hseed.
Qed.

Lemma assume_post_refold_assigns_levels__solve :
  forall wl s asg lvl l n cap qtail assigns levels reasons trail lim lim_cap M,
  n = ms_size M -> cap = ms_cap M -> qtail = ms_qtail M ->
  assigns = mt_assigns (ms_core M) -> levels = mt_levels (ms_core M) ->
  reasons = ms_reason_words M -> trail = mt_trail (ms_core M) ->
  lim = mt_lim (ms_core M) -> lim_cap = ms_lim_cap M ->
  solver_shape M -> ms_qtail M < ms_cap M ->
  ms_capacity_root_propagation_pending M = 0 ->
  mt_qhead (ms_core M) = ms_qtail M ->
  Znth (lit_var_c l) assigns 0 = 0 ->
  assume_post_at s asg lvl l n cap qtail assigns levels reasons trail lim lim_cap **
  solver_assume_frame_wl s M wl
  |-- EX lim_cap' : Z,
      “ ms_lim_cap M <= lim_cap' <= INT_MAX ” &&
      solver_rep_assigns_levels_at s (msolver_assume M l lim_cap') asg lvl wl.
Proof.
  intros wl s asg lvl l n cap qtail assigns levels reasons trail lim lim_cap M
    Hn Hcap Hq Hassigns Hlevels Hreasons Htrail Hlim Hlimcap
    Hshape Hroom Hpending Hdrain Hfresh.
  subst n. subst cap. subst qtail. subst assigns. subst levels.
  subst reasons. subst trail. subst lim. subst lim_cap.
  assert (Htrailq : Zlength (mt_trail (ms_core M)) = ms_qtail M).
  { unfold solver_shape in Hshape. tauto. }
  unfold assume_post_at. Intros lim_cap'. Exists lim_cap'. entailer_with lia.
  assert (Hshapenew : solver_shape (msolver_assume M l lim_cap')).
  { eapply solver_shape_assume__search; eauto. }
  unfold enqueue_post_at. Intros qtail' assigns' levels' reasons' trail'.
  unfold enqueue_state_at. Intros rsn trl.
  unfold enqueue_transition in *.
  match goal with
  | Ht : _ \/ (_ \/ _) |- _ =>
      destruct Ht as [Hsame | [Hconflict | Hnew]]
  end.
  - destruct Hsame as [Hsame _]. rewrite Hfresh in Hsame.
    pose proof (lit_sig_nonzero l). lia.
  - destruct Hconflict as [Hne _]. contradiction.
  - destruct Hnew as
      [Hz [_ [Hassigns' [Hlevels' [Hreasons' [Htrail' Hqtail']]]]]].
    subst assigns'. subst levels'. subst reasons'. subst trail'. subst qtail'.
    unfold solver_assume_frame_wl, solver_enqueue_frame_with_scalars_wl, solver_enqueue_cells_at.
    Intros act opos tgs.
    unfold solver_rep_assigns_levels_at, solver_rep_at.
    Exists act opos rsn trl tgs.
    unfold solver_nonlevel_rep_at, solver_nonlevel_rep_nostats_at, solver_assume_scalars_frame,
      solver_enqueue_vecs_frame, msolver_assume.
    unfold solver_fp_rep, solver_scalars_rep, solver_vecs_rep,
      solver_var_arrays_rep, solver_trail_array_rep,
      solver_levels_slice_at.
    try rewrite Hdrain.
    try rewrite Htrailq.
    (* The record-literal reduction must run AFTER the rep unfolds -- they are
       what creates the `ms_X {| ...39 fields... |}` projection redexes -- and
       its delta list must name those projections.  Run before them, every RHS
       atom carries an unreduced 39-field literal into the entailer's
       unification, which is far more expensive. *)
    cbn [mt_decide mt_push ms_size ms_cap ms_qtail ms_capacity_pending_qhead
      ms_capacity_root_propagation_pending ms_core ms_root_level
      ms_reason_words ms_reason_of ms_prob ms_learnt ms_prob_cap
      ms_learnt_cap ms_binary ms_binary_lits ms_wm ms_wcaps ms_activity
      ms_orderpos ms_order ms_order_cap ms_lim_cap ms_model ms_model_cap
      ms_tags ms_tagged ms_tagged_cap ms_stack ms_stack_cap ms_var_inc
      ms_var_decay ms_cla_inc ms_cla_decay ms_random_seed ms_progress
      ms_simpdb_assigns ms_simpdb_props ms_verbosity ms_stats].
    entailer_with lia.
    (* Same tail as [assume_post_refold__search], and rewritten the
       same way: no [all:] selectors, no [try] guards, and none of the three
       guarded closers ([exact Hshapenew], two [Zlength ...; lia] chains); the
       proof reaches [Qed] without them. *)
    cbn.
    entailer_with lia.
    rewrite Hdrain.
    rewrite Htrailq.
    (* Same sizeof/ptr_size_Z re-normalisation note as in [assume_post_refold__search] above. *)
    unfold DoubleArray.seg, IntArray.seg, CharArray.seg, PtrArray.seg,
      StoreDoubleAsElement.storeA, store_double, bits_of_double_value.
    cbn.
    msat_entailer_with lia.
Qed.

(** ===== group: solver_solve ===== *)
Lemma assumption_root_install_intro__solve :
  forall n F A_arr M,
  msolver_inv_assuming_strong n F A_arr A_arr M ->
  mt_qhead (ms_core M) = ms_qtail M ->
  ms_capacity_root_propagation_pending M = 0 ->
  msolver_seed_shadow M ->
  assumption_root_install n F A_arr M
    (msolver_set_root M (Zlength (mt_lim (ms_core M))))
    (decisions_upto (ms_core M) (Zlength (mt_lim (ms_core M)))).
Proof.
  intros n F A_arr M Hstrong Hdrain Hpending Hseed.
  pose proof (msas_weak Hstrong) as Hweak.
  set (L := Zlength (mt_lim (ms_core M))).
  set (Mroot := msolver_set_root M L).
  set (A_inst := decisions_upto (ms_core M) L).
  assert (Hroot_shape : solver_shape Mroot).
  { pose proof (msa_shape Hweak) as Hshape.
    unfold solver_shape in Hshape |- *.
    unfold Mroot, msolver_set_root, msolver_core_heap_update.
    cbn in *.
    pose proof (Zlength_nonneg (mt_lim (ms_core M))).
    tauto. }
  assert (Hroot_weak : msolver_inv_weak n F A_arr A_inst Mroot).
  { constructor; cbn [Mroot msolver_set_root msolver_core_heap_update].
    - exact (msa_size Hweak).
    - exact (msa_n_range Hweak).
    - exact Hroot_shape.
    - exact (msa_F_wf Hweak).
    - exact (msa_A_wf Hweak).
    - exact (msa_trail_wf Hweak).
    - exact (msa_level_bound Hweak).
    - unfold Mroot, L, msolver_set_root, msolver_core_heap_update. cbn.
      pose proof (Zlength_nonneg (mt_lim (ms_core M))). lia.
    - unfold Mroot, A_inst, msolver_set_root, msolver_core_heap_update. cbn.
      reflexivity.
    - destruct (msa_decisions Hweak) as [A0 [Hdec Hincl]].
      unfold Mroot, A_inst, L, msolver_set_root, msolver_core_heap_update. cbn.
      rewrite Hdec. exact Hincl.
    - unfold Mroot, L, msolver_set_root, msolver_core_heap_update. cbn.
      exact (msa_proc_sat Hweak).
    - exact (msa_stable Hweak).
    - exact (msa_reasons_ent Hweak).
    - exact (msa_reasons_inj Hweak).
    - exact (msa_trail_impl Hweak).
    - exact (msa_db_wf Hweak).
    - exact (msa_db_matches Hweak).
    - exact (msa_db_implied Hweak).
    - exact (msa_db_complete Hweak).
    - exact (msa_learnt_db Hweak).
    - exact (msa_prob_db Hweak).
    - exact (msa_binary_out Hweak).
    - exact (msa_reasons_mem Hweak).
    - exact (msa_reason_head Hweak).
    - exact (msa_reason_bin Hweak).
    - exact (msa_wmap_exact Hweak).
    - exact (msa_tags_clear Hweak).
    - exact (msa_heap_wf Hweak).
    - exact (msa_cla_inc_nonnegative Hweak).
    - exact (msa_seed Hweak). }
  assert (Hroot_inv : msolver_inv n F A_arr A_inst Mroot).
  { constructor; cbn [Mroot msolver_set_root msolver_core_heap_update].
    - exact Hroot_weak.
    - exact (msas_prop_level Hstrong).
    - exact (msas_watch_frontier Hstrong).
    - exact (msas_heap_covers Hstrong).
    - unfold current_reasonless_earliest.
      intros d Hd. exfalso.
      unfold Mroot, L, msolver_set_root, msolver_core_heap_update in Hd.
      cbn in Hd. lia. }
  unfold assumption_root_install.
  repeat apply conj.
  - unfold A_inst, L. reflexivity.
  - unfold Mroot, L. reflexivity.
  - exact Hroot_inv.
  - unfold solver_at_root, Mroot, L, msolver_set_root,
      msolver_core_heap_update. cbn. reflexivity.
  - unfold Mroot, msolver_set_root, msolver_core_heap_update. cbn.
    exact Hdrain.
  - unfold Mroot, msolver_set_root, msolver_core_heap_update. cbn.
    exact Hpending.
  - unfold Mroot, msolver_set_root, msolver_core_heap_update. cbn.
    exact Hseed.
Qed.

(** ===== group: solver_solve ===== *)
Lemma sort_Znth_in__solve : forall db origin current k,
  learnt_sort_segment_domain db origin ->
  Permutation origin current ->
  0 <= k < Zlength current ->
  In (Znth k current 0) (db_words db).
Proof.
  intros db origin current k Hdomain Hperm Hk.
  unfold learnt_sort_segment_domain in Hdomain.
  rewrite Forall_forall in Hdomain.
  apply Hdomain.
  eapply Permutation_in.
  - apply Permutation_sym. exact Hperm.
  - apply Znth_In. exact Hk.
Qed.

Lemma sort_Znth_in_sep__solve : forall db origin current k P,
  learnt_sort_segment_domain db origin ->
  Permutation origin current ->
  0 <= k < Zlength current ->
  P |-- “ In (Znth k current 0) (db_words db) ”.
Proof.
  intros db origin current k P Hdomain Hperm Hk.
  pose proof (sort_Znth_in__solve
    db origin current k Hdomain Hperm Hk).
  msat_entailer_with lia.
Qed.

Lemma replace_znth_swap_form__solve :
  forall (l1 l2 l3 : list Z) (xi xj : Z),
  replace_Znth (Zlength l1 + 1 + Zlength l2) xi
    (replace_Znth (Zlength l1) xj (l1 ++ xi :: l2 ++ xj :: l3)) =
  l1 ++ xj :: l2 ++ xi :: l3.
Proof.
  intros.
  pose proof (Zlength_nonneg l2) as Hlen2.
  set (n1 := Zlength l1).
  set (n2 := Zlength l1 + 1 + Zlength l2).
  rewrite replace_Znth_app_r with (l1 := l1)
    (l2 := (xi :: l2 ++ xj :: l3)) by (subst n1; lia).
  rewrite (replace_Znth_nothing (A := Z) n1 l1 xj) by (subst n1; lia).
  replace (n1 - Zlength l1) with 0 by (subst n1; lia).
  assert (H0 : replace_Znth 0 xj (xi :: l2 ++ xj :: l3) =
               xj :: l2 ++ xj :: l3) by reflexivity.
  rewrite H0.
  rewrite replace_Znth_app_r with (l1 := l1)
    (l2 := (xj :: l2 ++ xj :: l3)) by (subst n2; lia).
  rewrite (replace_Znth_nothing (A := Z)
    (n1 + 1 + Zlength l2) l1 xi) by (subst n1; lia).
  replace (n1 + 1 + Zlength l2 - Zlength l1)
    with (1 + Zlength l2) by (subst n1; lia).
  rewrite replace_Znth_cons by lia.
  replace (1 + Zlength l2 - 1) with (Zlength l2) by lia.
  rewrite replace_Znth_app_r with (l1 := l2) (l2 := (xj :: l3)) by lia.
  rewrite (replace_Znth_nothing (A := Z) (Zlength l2) l2 xi) by lia.
  replace (Zlength l2 - Zlength l2) with 0 by lia.
  assert (H1 : replace_Znth 0 xi (xj :: l3) = xi :: l3) by reflexivity.
  rewrite H1. reflexivity.
Qed.

Lemma permutation_swap_znth_lt__solve : forall
    (l : list Z) i j d,
  0 <= i /\ i < j /\ j < Zlength l ->
  Permutation l
    (replace_Znth j (Znth i l d) (replace_Znth i (Znth j l d) l)).
Proof.
  intros l i j d (Hi & Hij & Hj).
  remember (Znth i l d) as xi0.
  remember (Znth j l d) as xj0.
  set (ni := Z.to_nat i).
  set (nj := Z.to_nat (j - i - 1)).
  set (l1 := firstn ni l).
  set (lr := skipn (S ni) l).
  set (l2 := firstn nj lr).
  set (l3 := skipn (S nj) lr).
  assert (Hsplit_i : l = l1 ++ xi0 :: lr).
  { subst l1 lr ni.
    rewrite (list_split_nth _ (Z.to_nat i) l d) at 1.
    2:{ rewrite Zlength_correct in Hj. lia. }
    rewrite Heqxi0. reflexivity. }
  assert (Hj_lr : (nj < List.length lr)%nat).
  { subst nj lr ni. rewrite length_skipn.
    rewrite Zlength_correct in Hj. lia. }
  assert (Hsplit_j : lr = l2 ++ xj0 :: l3).
  { subst l2 l3.
    rewrite (list_split_nth _ nj lr d) at 1 by exact Hj_lr.
    replace xj0 with (nth nj lr d).
    2:{ subst nj lr ni. rewrite Heqxj0. unfold Znth. rewrite nth_skipn.
        assert (Hnat :
          (Z.to_nat (j - i - 1) + S (Z.to_nat i))%nat = Z.to_nat j).
        { apply Nat2Z.inj. rewrite Nat2Z.inj_add, Nat2Z.inj_succ.
          rewrite !Z2Nat.id by lia. lia. }
        rewrite Nat.add_comm, Hnat. reflexivity. }
    reflexivity. }
  assert (Hl : l = l1 ++ xi0 :: l2 ++ xj0 :: l3).
  { rewrite Hsplit_j in Hsplit_i. exact Hsplit_i. }
  replace l with (l1 ++ xi0 :: l2 ++ xj0 :: l3)
    by (symmetry; exact Hl).
  replace i with (Zlength l1).
  2:{ subst l1 ni. rewrite Zlength_correct, length_firstn.
      rewrite Zlength_correct in Hj. rewrite Nat.min_l by lia. lia. }
  replace j with (Zlength l1 + 1 + Zlength l2).
  2:{ subst l1 l2 lr ni nj. rewrite !Zlength_correct.
      rewrite !length_firstn, length_skipn.
      rewrite Zlength_correct in Hj. lia. }
  rewrite replace_znth_swap_form__solve.
  eapply Permutation_trans.
  2:{ reflexivity. }
  apply Permutation_app_head.
  eapply Permutation_trans.
  - apply Permutation_middle.
  - eapply Permutation_trans.
    + apply Permutation_app_head. apply perm_swap.
    + apply Permutation_sym. apply Permutation_middle.
Qed.

Lemma selectionsort_swap_perm__solve : forall
    (l : list Z) i j,
  0 <= i < Zlength l ->
  i <= j < Zlength l ->
  Permutation l
    (replace_Znth j (Znth i l 0) (replace_Znth i (Znth j l 0) l)).
Proof.
  intros l i j Hi Hj.
  destruct (Z.eq_dec i j) as [-> | Hne].
  - rewrite replace_Znth_Znth by lia.
    rewrite replace_Znth_Znth by lia.
    apply Permutation_refl.
  - apply permutation_swap_znth_lt__solve. lia.
Qed.

Lemma learnt_sort_key_in__solve : forall
    db activities p co a,
  learnt_sort_key db activities p co a ->
  In p (db_words db).
Proof.
  induction db as [|[q cq] db IH]; intros activities p co a Hkey;
    destruct activities as [|aq activities]; simpl in *; try contradiction.
  destruct Hkey as [[-> [_ _]] | Hkey].
  - left. reflexivity.
  - right. eapply IH; eauto.
Qed.

Lemma learnt_sort_key_unique__solve : forall
    db activities p co1 co2 a1 a2,
  NoDup (db_words db) ->
  learnt_sort_key db activities p co1 a1 ->
  learnt_sort_key db activities p co2 a2 ->
  co1 = co2 /\ a1 = a2.
Proof.
  induction db as [|[q cq] db IH];
    intros activities p co1 co2 a1 a2 Hnodup Hkey1 Hkey2;
    destruct activities as [|aq activities]; simpl in *; try contradiction.
  inversion Hnodup as [|? ? Hnotin Hnodup']; subst.
  destruct Hkey1 as [[Hp1 [Hco1 Ha1]] | Hkey1];
    destruct Hkey2 as [[Hp2 [Hco2 Ha2]] | Hkey2].
  - subst. split; reflexivity.
  - subst. exfalso. apply Hnotin.
    eapply learnt_sort_key_in__solve; eauto.
  - subst. exfalso. apply Hnotin.
    eapply learnt_sort_key_in__solve; eauto.
  - eapply IH; eauto.
Qed.

Lemma learnt_sort_key_nonnegative__solve : forall
    db activities p co a,
  Forall msat_fp32_nonnegative activities ->
  learnt_sort_key db activities p co a ->
  msat_fp32_nonnegative a.
Proof.
  induction db as [|[q cq] db IH]; intros activities p co a Hnonneg Hkey;
    destruct activities as [|aq activities]; simpl in *; try contradiction.
  inversion Hnonneg as [|? ? Ha Hnonneg']; subst.
  destruct Hkey as [[_ [_ ->]] | Hkey].
  - exact Ha.
  - eapply IH; eauto.
Qed.

Lemma learnt_cmp_stop_refl__solve : forall
    db activities x,
  learnt_sort_context db activities ->
  learnt_cmp_stop db activities x x.
Proof.
  intros db activities x Hcontext Hlt.
  unfold learnt_cmp_lt in Hlt.
  destruct Hlt as
    (cox & coy & ax & ay & Hkeyx & Hkeyy & Hlong & Hlast).
  unfold learnt_sort_context in Hcontext.
  destruct Hcontext as (Hnodup & _ & Hnonneg).
  pose proof (learnt_sort_key_unique__solve
    db activities x cox coy ax ay Hnodup Hkeyx Hkeyy) as [Hco Ha].
  subst coy ay.
  destruct Hlast as [Hbinary | Hflt].
  - lia.
  - pose proof (learnt_sort_key_nonnegative__solve
      db activities x cox ax Hnonneg Hkeyx) as Hax.
    pose proof (MSatFloatFacts.fp32_nonnegative_eq_refl ax Hax) as Heq.
    unfold fp32_eq, fp32_lt in *. congruence.
Qed.

Lemma sortrnd_initial_partition__solve : forall
    db activities origin k,
  learnt_sort_context db activities ->
  learnt_sort_segment_domain db origin ->
  0 <= k < Zlength origin ->
  sortrnd_partition_inv db activities origin origin (Zlength origin)
    (Znth k origin 0) (-1) (Zlength origin).
Proof.
  intros db activities origin k Hcontext Hdomain Hk.
  pose proof (sort_Znth_in__solve
    db origin origin k Hdomain (Permutation_refl origin) Hk) as Hin.
  pose proof (learnt_cmp_stop_refl__solve
    db activities (Znth k origin 0) Hcontext) as Hstop.
  unfold sortrnd_partition_inv.
  split; [exact Hdomain|].
  split; [exact Hcontext|].
  split; [exact Hin|].
  split; [apply Permutation_refl|].
  split; [reflexivity|].
  split; [lia|].
  split; [lia|].
  exists k, k. repeat split; try assumption; lia.
Qed.

(** ===== group: sortrnd ===== *)
Lemma learnt_sort_segment_domain_perm__sortrnd : forall db l1 l2,
  Permutation l1 l2 ->
  learnt_sort_segment_domain db l1 -> learnt_sort_segment_domain db l2.
Proof.
  intros db l1 l2 Hperm Hdom.
  unfold learnt_sort_segment_domain in *.
  rewrite Forall_forall in *.
  intros x Hx.
  apply Hdom.
  eapply Permutation_in; [apply Permutation_sym; exact Hperm | exact Hx].
Qed.

Lemma learnt_sort_segment_domain_Znth__sortrnd : forall db l i,
  learnt_sort_segment_domain db l -> 0 <= i < Zlength l ->
  In (Znth i l 0) (db_words db).
Proof.
  intros db l i Hdom Hi.
  apply (Forall_Znth_elim _ _ _ 0 i Hdom Hi).
Qed.

Lemma learnt_cmp_result_neg_not_stop__sortrnd : forall db acts x y r,
  learnt_cmp_result db acts x y r -> r < 0 ->
  ~ learnt_cmp_stop db acts x y.
Proof.
  intros db acts x y r Hcmp Hr Hstop.
  destruct Hcmp as [[Heq Hlt] | [Heq Hstop']].
  - apply Hstop. exact Hlt.
  - lia.
Qed.

Lemma learnt_cmp_result_nonneg_stop__sortrnd : forall db acts x y r,
  learnt_cmp_result db acts x y r -> r >= 0 ->
  learnt_cmp_stop db acts x y.
Proof.
  intros db acts x y r Hcmp Hr.
  destruct Hcmp as [[Heq Hlt] | [Heq Hstop]].
  - lia.
  - exact Hstop.
Qed.

Lemma perm_move_in__sortrnd : forall (A : Type) (d a : A)
    (l : list A) (k : nat),
  (k < List.length l)%nat ->
  Permutation (a :: l) (nth k l d :: replace_nth k l a).
Proof.
  intros A d a l.
  induction l as [|b l' IH]; intros k Hk; simpl in Hk.
  - exfalso. inversion Hk.
  - destruct k as [|k']; simpl.
    + apply perm_swap.
    + eapply Permutation_trans; [apply perm_swap |].
      eapply Permutation_trans.
      * apply perm_skip. apply (IH k'). lia.
      * apply perm_swap.
Qed.

Lemma perm_swap_nth__sortrnd : forall (A : Type) (d : A)
    (l : list A) (i j : nat),
  (i < List.length l)%nat -> (j < List.length l)%nat ->
  Permutation l
    (replace_nth j (replace_nth i l (nth j l d)) (nth i l d)).
Proof.
  intros A d l.
  induction l as [|a l' IH]; intros i j Hi Hj; simpl in Hi, Hj.
  - exfalso. inversion Hi.
  - destruct i as [|i']; destruct j as [|j']; simpl.
    + apply Permutation_refl.
    + apply perm_move_in__sortrnd. lia.
    + apply perm_move_in__sortrnd. lia.
    + apply perm_skip. apply IH; lia.
Qed.

Lemma perm_swap_Znth__sortrnd : forall (l : list Z) (i j : Z),
  0 <= i < Zlength l -> 0 <= j < Zlength l ->
  Permutation l
    (replace_Znth j (Znth i l 0)
       (replace_Znth i (Znth j l 0) l)).
Proof.
  intros l i j Hi Hj.
  rewrite Zlength_correct in Hi, Hj.
  unfold replace_Znth, Znth.
  apply (perm_swap_nth__sortrnd Z 0 l
           (Z.to_nat i) (Z.to_nat j)); lia.
Qed.

Lemma sortrnd_left_scan_step__sortrnd :
  forall db acts origin cur size pivot i j r,
  sortrnd_partition_inv db acts origin cur size pivot (i - 1) j ->
  learnt_cmp_result db acts (Znth i cur 0) pivot r ->
  r < 0 ->
  Zlength cur = size -> 0 <= i -> i < size -> 0 < j -> j <= size ->
  i + 1 < Zlength cur /\
  sortrnd_partition_inv db acts origin cur (Zlength cur) pivot i j.
Proof.
  intros db acts origin cur size pivot i j r Hinv Hcmp Hr Hlen
         Hi0 Hilt Hj0 Hjle.
  unfold sortrnd_partition_inv in Hinv.
  destruct Hinv as
    [Hdom [Hctx [Hpiv [Hperm [Hcl [Hij [Hjr [L [R Hex]]]]]]]]].
  destruct Hex as
    [[HLlo HLhi] [HLj [[HRlo HRhi] [HstopL HstopR]]]].
  assert (HLne : L <> i).
  { intro Heq. subst L.
    exact (learnt_cmp_result_neg_not_stop__sortrnd
             _ _ _ _ _ Hcmp Hr HstopL). }
  split; [lia |].
  unfold sortrnd_partition_inv.
  split; [exact Hdom |].
  split; [exact Hctx |].
  split; [exact Hpiv |].
  split; [exact Hperm |].
  split; [reflexivity |].
  split; [lia |].
  split; [lia |].
  exists L, R.
  split; [lia |].
  split; [lia |].
  split; [lia |].
  split; assumption.
Qed.

Lemma sortrnd_left_scan_entry__sortrnd :
  forall db acts origin cur size pivot i j,
  sortrnd_partition_inv db acts origin cur size pivot i j ->
  Zlength cur = size ->
  i + 1 < Zlength cur /\
  sortrnd_partition_inv db acts origin cur (Zlength cur) pivot i j.
Proof.
  intros db acts origin cur size pivot i j Hinv Hlen.
  pose proof Hinv as Hinv'.
  unfold sortrnd_partition_inv in Hinv.
  destruct Hinv as
    [Hdom [Hctx [Hpiv [Hperm [Hcl [Hij [Hjr [L [R Hex]]]]]]]]].
  destruct Hex as
    [[HLlo HLhi] [HLj [[HRlo HRhi] [HstopL HstopR]]]].
  split; [lia |].
  rewrite Hlen. exact Hinv'.
Qed.

Lemma sortrnd_right_scan_step__sortrnd :
  forall db acts origin cur size pivot i j r,
  sortrnd_right_scan_inv db acts origin cur size pivot i (j + 1) ->
  learnt_cmp_result db acts pivot (Znth j cur 0) r ->
  r < 0 ->
  Zlength cur = size -> 0 <= j -> j < size ->
  0 <= j - 1 /\
  sortrnd_right_scan_inv db acts origin cur (Zlength cur) pivot i j.
Proof.
  intros db acts origin cur size pivot i j r Hinv Hcmp Hr Hlen
         Hj0 Hjlt.
  unfold sortrnd_right_scan_inv in Hinv.
  destruct Hinv as
    [Hdom [Hctx [Hpiv [Hperm [Hcl [Hi [Hj [HstopI
      [R [HR HstopR]]]]]]]]]].
  assert (HRne : R <> j).
  { intro Heq. subst R.
    exact (learnt_cmp_result_neg_not_stop__sortrnd
             _ _ _ _ _ Hcmp Hr HstopR). }
  split; [lia |].
  unfold sortrnd_right_scan_inv.
  split; [exact Hdom |].
  split; [exact Hctx |].
  split; [exact Hpiv |].
  split; [exact Hperm |].
  split; [reflexivity |].
  split; [lia |].
  split; [lia |].
  split; [exact HstopI |].
  exists R. split; [lia | exact HstopR].
Qed.

Lemma sortrnd_right_scan_entry__sortrnd :
  forall db acts origin cur size pivot i j r,
  sortrnd_partition_inv db acts origin cur size pivot (i - 1) j ->
  learnt_cmp_result db acts (Znth i cur 0) pivot r ->
  r >= 0 ->
  Zlength cur = size -> 0 <= i -> i < size -> 0 < j -> j <= size ->
  sortrnd_right_scan_inv db acts origin cur (Zlength cur) pivot i j.
Proof.
  intros db acts origin cur size pivot i j r Hinv Hcmp Hr Hlen
         Hi0 Hilt Hj0 Hjle.
  unfold sortrnd_partition_inv in Hinv.
  destruct Hinv as
    [Hdom [Hctx [Hpiv [Hperm [Hcl [Hij [Hjr [L [R Hex]]]]]]]]].
  destruct Hex as
    [[HLlo HLhi] [HLj [[HRlo HRhi] [HstopL HstopR]]]].
  unfold sortrnd_right_scan_inv.
  split; [exact Hdom |].
  split; [exact Hctx |].
  split; [exact Hpiv |].
  split; [exact Hperm |].
  split; [reflexivity |].
  split; [lia |].
  split; [lia |].
  split.
  - exact (learnt_cmp_result_nonneg_stop__sortrnd
             _ _ _ _ _ Hcmp Hr).
  - exists R. split; [lia | exact HstopR].
Qed.

Lemma sortrnd_swap_preserves_partition_inv__sortrnd :
  forall db acts origin cur size pivot i j r,
  sortrnd_right_scan_inv db acts origin cur size pivot i (j + 1) ->
  learnt_cmp_result db acts pivot (Znth j cur 0) r ->
  r >= 0 -> i < j ->
  Zlength cur = size -> 0 <= i -> i < size -> 0 <= j -> j < size ->
  sortrnd_partition_inv db acts origin
    (replace_Znth j (Znth i cur 0)
       (replace_Znth i (Znth j cur 0) cur))
    size pivot i j.
Proof.
  intros db acts origin cur size pivot i j r Hinv Hcmp Hr Hij Hlen
         Hi0 Hilt Hj0 Hjlt.
  unfold sortrnd_right_scan_inv in Hinv.
  destruct Hinv as
    [Hdom [Hctx [Hpiv [Hperm [Hcl [Hi [Hj [HstopI
      [R [HR HstopR]]]]]]]]]].
  set (cur' := replace_Znth j (Znth i cur 0)
                 (replace_Znth i (Znth j cur 0) cur)).
  assert (Hlen' : Zlength cur' = Zlength cur).
  { unfold cur'. rewrite Zlength_replace_Znth, Zlength_replace_Znth.
    reflexivity. }
  assert (Hatj : Znth j cur' 0 = Znth i cur 0).
  { unfold cur'. apply Znth_replace_Znth_Same.
    rewrite Zlength_replace_Znth. lia. }
  assert (Hati : Znth i cur' 0 = Znth j cur 0).
  { unfold cur'.
    rewrite Znth_replace_Znth_Diff
      by (rewrite ?Zlength_replace_Znth; lia).
    apply Znth_replace_Znth_Same. lia. }
  unfold sortrnd_partition_inv.
  split; [exact Hdom |].
  split; [exact Hctx |].
  split; [exact Hpiv |].
  split.
  { eapply Permutation_trans; [exact Hperm |].
    unfold cur'. apply perm_swap_Znth__sortrnd; lia. }
  split; [lia |].
  split; [lia |].
  split; [lia |].
  exists j, i.
  split; [lia |].
  split; [lia |].
  split; [lia |].
  split.
  - rewrite Hatj. exact HstopI.
  - rewrite Hati.
    exact (learnt_cmp_result_nonneg_stop__sortrnd
             _ _ _ _ _ Hcmp Hr).
Qed.

(** ===== group: sortrnd ===== *)
Lemma clause_db_rep_learnt_to_sort__sortrnd : forall db,
  learnt_db db ->
  clause_db_rep db |--
    EX activities : list fp32,
      “ Zlength activities = Zlength db /\
        Forall msat_fp32_nonnegative activities ” &&
      learnt_sort_rep db activities.
Proof.
  intros db. induction db as [|[p co] db IH]; intros Hlearnt.
  - cbn [clause_db_rep]. Exists (@nil fp32).
    cbn [learnt_sort_rep]. entailer_with lia.
  - inversion Hlearnt as [|e rest Htag Htail]; subst.
    cbn in Htag.
    cbn [clause_db_rep].
    unfold MiniSatClause.rep.
    cbn [fst snd].
    rewrite Htag.
    unfold activity_state.
    Intros a.
    sep_apply (IH Htail).
    Intros activities.
    Exists (a :: activities).
    cbn [learnt_sort_rep]. rewrite Htag.
    entailer_with lia.
    rewrite !Zlength_cons. lia.
    constructor; [exact H0 | exact (proj2 H1)].
Qed.

Lemma learnt_sort_rep_to_clause_db__sortrnd : forall db activities,
  learnt_sort_rep db activities |-- clause_db_rep db.
Proof.
  intros db. induction db as [|[p co] db IH]; intros activities.
  - destruct activities; cbn [learnt_sort_rep clause_db_rep]; entailer_with lia.
  - destruct activities as [|a activities].
    + cbn [learnt_sort_rep]. entailer_with lia.
    + cbn [learnt_sort_rep]. Intros_p Hhead.
      destruct Hhead as [Htag [Hp [Hmod Hnonneg]]].
      sep_apply (IH activities).
      cbn [clause_db_rep fst snd].
      unfold MiniSatClause.rep.
      rewrite Htag.
      unfold activity_state.
      Exists a.
      entailer_with lia.
      apply Zlength_nonneg.
Qed.

(** Shared core: a clause whose head watcher is false owns no live reason.
    The weak and the assuming bundle supply exactly the same six facts, so the
    argument is stated once over those facts. *)
Lemma no_live_reason_owner_head_false_core : forall n M p co,
  db_wf n (msolver_db M) ->
  mtrail_wf n (ms_core M) ->
  stable_view (msolver_view n M) ->
  reasons_match n (ms_core M) (msolver_db M) (ms_reason_words M)
    (ms_reason_of M) ->
  reason_head_ok M ->
  n = ms_size M ->
  In (p, co) (msolver_db M) ->
  lit_false (mt_assigns (ms_core M)) (co_watch0 co) ->
  forall v, 0 <= v < n -> Znth v (ms_reason_words M) 0 <> p.
Proof.
  intros n M p co Hdbwf Htrailwf Hstable Hreasons Hheadok Hsize
    Hin Hheadfalse v Hv Heq.
  pose proof (db_wf_obj n (msolver_db M) p co Hdbwf Hin) as Hobj.
  pose proof (db_wf_ptr_pos n (msolver_db M) p co Hdbwf Hin) as Hptrpos.
  pose proof (db_wf_even n (msolver_db M) p co Hdbwf Hin) as Hptreven.
  assert (Htag : is_tag p = false).
  { apply even_not_tag. exact Hptreven. }
  specialize (Hreasons v Hv).
  unfold reason_word_ok in Hreasons. rewrite Heq in Hreasons.
  assert (Hz : (p =? 0)%Z = false).
  { apply Z.eqb_neq. lia. }
  rewrite Hz, Htag in Hreasons.
  destruct Hreasons as [Hvassigned [co' [Hlookup Hr]]].
  assert (Hco : co' = co).
  { unfold db_lookup in Hlookup.
    eapply db_wf_lookup_unique; [exact Hdbwf|exact Hlookup|exact Hin]. }
  subst co'.
  assert (Hheadvar : lit_var_c (co_watch0 co) = v).
  { apply (Hheadok v co).
    - rewrite <- Hsize. exact Hv.
    - rewrite Heq. exact Htag.
    - rewrite Heq. lia.
    - rewrite Heq. exact Hin. }
  assert (Hpv : exists b, mt_pv (ms_core M) v = Some b).
  { pose proof (Forall_Znth_elim Z lbool_cell
      (mt_assigns (ms_core M)) 0 v (mtw_cells Htrailwf)
      ltac:(rewrite (mtw_assigns_len Htrailwf); exact Hv)) as Hcell.
    unfold lbool_cell in Hcell.
    destruct Hcell as [Hcell | [Hcell | Hcell]].
    - exists false. rewrite mt_pv_nonneg by lia. rewrite Hcell. reflexivity.
    - contradiction.
    - exists true. rewrite mt_pv_nonneg by lia. rewrite Hcell. reflexivity. }
  destruct Hpv as [b Hpv].
  assert (Htp : exists k, trail_pos (ms_core M) v = Some k).
  { destruct (trail_pos (ms_core M) v) as [k|] eqn:Htp.
    - exists k. reflexivity.
    - exfalso. apply trail_pos_none_iff in Htp. apply Htp.
      apply (proj1 (mtw_assigned_iff Htrailwf v Hv)). exact Hvassigned. }
  destruct Htp as [k Htp].
  unfold stable_view in Hstable. destruct Hstable as [Hground _].
  specialize (Hground v b Hpv).
  destruct Hground as [d [rx [_ [_ [Hnone | [C [HC Hvalid]]]]]]].
  - unfold msolver_view, view_of in Hnone; cbn in Hnone.
    rewrite Htp, Hr in Hnone. discriminate.
  - unfold msolver_view, view_of in HC; cbn in HC.
    rewrite Htp, Hr in HC. inversion HC; subst C.
    destruct Hvalid as [b' [d' [rx'
      [Hpv' [_ [_ [Hsat _]]]]]]].
    change (mt_pv (ms_core M) v = Some b') in Hpv'.
    rewrite Hpv in Hpv'. inversion Hpv'; subst b'.
    assert (Hwatchin :
        In (lit_denote (co_watch0 co)) (denote_obj co)).
    { unfold denote_obj. apply lits_denote_in.
      apply obj_wf_watch0_in with (n := n). exact Hobj. }
    assert (Hlit_eq :
        satisfying_literal v b = lit_denote (co_watch0 co)).
    { apply (NoDup_map_var_injective (denote_obj co)).
      - apply obj_wf_nodup_vars with (n := n). exact Hobj.
      - exact Hsat.
      - exact Hwatchin.
      - rewrite satisfying_literal_var, lit_var_c_denote, Hheadvar.
        reflexivity. }
    pose proof (eval_satisfying_literal_true
      (mt_pv (ms_core M)) v b Hpv) as Htrue.
    rewrite Hlit_eq in Htrue.
    assert (Hheadnonneg : 0 <= co_watch0 co).
    { pose proof (obj_wf_watch0 n co Hobj). destruct H. lia. }
    pose proof (proj1 (lit_false_iff
      (mt_assigns (ms_core M)) (co_watch0 co) Hheadnonneg)
      Hheadfalse) as Hfalse.
    unfold eval_partial_literal in Htrue, Hfalse.
    rewrite lit_var_c_denote in Htrue, Hfalse.
    rewrite mt_pv_nonneg in Htrue by
      (apply lit_var_c_nonneg with (n := n);
       apply obj_wf_watch0; exact Hobj).
    unfold assigns_pv, assigns_val in Hfalse.
    congruence.
Qed.

(** No live variable can name a clause whose head literal is false, from
    either propagation view. *)
Lemma ctx_no_live_reason_owner_head_false__propagate_dbu :
  forall n F A_arr K M p co,
    msolver_inv_ctx n F A_arr K M ->
    In (p, co) (msolver_db M) ->
    lit_false (mt_assigns (ms_core M)) (co_watch0 co) ->
    forall v, 0 <= v < n -> Znth v (ms_reason_words M) 0 <> p.
Proof.
  intros n F A_arr K M p co Hweak Hin Hheadfalse.
  destruct K as [A_inst|A_proc]; cbn in Hweak; destruct Hweak;
    apply (no_live_reason_owner_head_false_core n M p co); assumption.
Qed.

(** A pairwise literal update that no live reason owns rebuilds the
    stable-point bundle of EITHER propagation view: one statement over the
    context sum, discharged twice by the shared script above -- the [revert]s
    put each arm's goal back into the telescope the [Tactic Notation]'s own
    [intros] expects. *)
Lemma ctx_db_pair_lits_no_owner__propagate_dbu :
  forall n F A_arr K M p old_lits new_lits prob' learnt',
    msolver_inv_ctx n F A_arr K M ->
    db_pair_lits_update (ms_prob M) (ms_learnt M)
      p old_lits new_lits prob' learnt' ->
    Permutation new_lits old_lits ->
    (forall l,
      Permutation (expected_watchers (msolver_db M) l)
        (expected_watchers (prob' ++ learnt') l)) ->
    (forall v, 0 <= v < n -> Znth v (ms_reason_words M) 0 <> p) ->
    msolver_inv_ctx n F A_arr K
      (msolver_propagation_db_wmap_update
        M prob' learnt' (ms_wm M) (ms_wcaps M)).
Proof.
  intros n F A_arr K; destruct K as [A_x|A_x]; cbn [msolver_inv_ctx];
    revert n F A_arr A_x.
  - msat_inv_db_pair_lits_no_owner msw_db_wf msw_db_matches msw_db_implied
      msw_db_complete msw_prob_db msw_learnt_db msw_binary_out msw_reasons_mem
      msw_reason_head msw_size msw_wmap_exact.
  - msat_inv_db_pair_lits_no_owner msa_db_wf msa_db_matches msa_db_implied
      msa_db_complete msa_prob_db msa_learnt_db msa_binary_out msa_reasons_mem
      msa_reason_head msa_size msa_wmap_exact.
Qed.

Lemma minisat_focus_real_word_owner__propagate_dbu :
  forall n db p o w,
    db_wf n db ->
    In (o, w) (minisat_focus_contributions db p) ->
    is_tag w = false ->
    exists co, In (w, co) db /\
      o = minisat_occurrence_of_entry (w, co).
Proof.
  intros n db p o w Hdb Hin Hreal.
  unfold minisat_focus_contributions in Hin.
  apply in_flat_map in Hin as [[q co] [Hentry Hin]].
  unfold minisat_entry_focus_contributions in Hin.
  apply in_map_iff in Hin as [w0 [Hpair Hinw]].
  inversion Hpair; subst o w.
  assert (Hqe : Z.even q = true).
  { eapply db_wf_even; eassumption. }
  unfold entry_watchers in Hinw; cbn in Hinw.
  apply in_app_or in Hinw.
  destruct (3 <=? Zlength (co_lits co)) eqn:Hbig.
  - destruct Hinw as [Hinw | Hinw].
    + destruct (lit_neg_c (co_watch0 co) =? p);
        cbn in Hinw; try contradiction.
      destruct Hinw as [Heq | []]. subst w0.
      exists co. split; [exact Hentry|reflexivity].
    + destruct (lit_neg_c (co_watch1 co) =? p);
        cbn in Hinw; try contradiction.
      destruct Hinw as [Heq | []]. subst w0.
      exists co. split; [exact Hentry|reflexivity].
  - exfalso. destruct Hinw as [Hinw | Hinw].
    + destruct (lit_neg_c (co_watch0 co) =? p);
        cbn in Hinw; try contradiction.
      destruct Hinw as [Heq | []]. subst w0.
      rewrite is_tag_of in Hreal. discriminate.
    + destruct (lit_neg_c (co_watch1 co) =? p);
        cbn in Hinw; try contradiction.
      destruct Hinw as [Heq | []]. subst w0.
      rewrite is_tag_of in Hreal. discriminate.
Qed.

Lemma minisat_focus_contributions_app__propagate_dbu :
  forall db1 db2 p,
    minisat_focus_contributions (db1 ++ db2) p =
      minisat_focus_contributions db1 p ++
      minisat_focus_contributions db2 p.
Proof.
  intros. unfold minisat_focus_contributions. apply flat_map_app.
Qed.

Lemma minisat_focus_contributions_cons__propagate_dbu :
  forall e db p,
    minisat_focus_contributions (e :: db) p =
      minisat_entry_focus_contributions p e ++
      minisat_focus_contributions db p.
Proof. reflexivity. Qed.

Lemma db_pair_lits_update_focus_single__propagate_dbu :
  forall prob learnt current old_lits new_lits prob' learnt' p oold onew,
    db_pair_lits_update prob learnt current old_lits new_lits prob' learnt' ->
    (forall co,
      co_lits co = old_lits ->
      minisat_entry_focus_contributions p (current, co) = [(oold, current)]) ->
    (forall co,
      co_lits co = old_lits ->
      minisat_entry_focus_contributions p
        (current, clause_obj_with_lits co new_lits) = [(onew, current)]) ->
    exists pre post,
      minisat_focus_contributions (prob ++ learnt) p =
        pre ++ (oold, current) :: post /\
      minisat_focus_contributions (prob' ++ learnt') p =
        pre ++ (onew, current) :: post.
Proof.
  intros prob learnt current old_lits new_lits prob' learnt' p oold onew
    Hupdate Hold Hnew.
  destruct Hupdate as
    [[co [pre [post [Hprob [Hlits [Hprob' Hlearnt']]]]]]
    |[co [pre [post [Hlearnt [Hlits [Hprob' Hlearnt']]]]]]].
  - subst prob prob' learnt'.
    exists (minisat_focus_contributions pre p),
      (minisat_focus_contributions post p ++
       minisat_focus_contributions learnt p).
    rewrite !minisat_focus_contributions_app__propagate_dbu.
    rewrite !minisat_focus_contributions_cons__propagate_dbu.
    rewrite (Hold co Hlits), (Hnew co Hlits). cbn.
    split.
    + rewrite <- app_assoc. reflexivity.
    + rewrite <- app_assoc. reflexivity.
  - subst learnt prob' learnt'.
    exists (minisat_focus_contributions prob p ++
      minisat_focus_contributions pre p),
      (minisat_focus_contributions post p).
    rewrite !minisat_focus_contributions_app__propagate_dbu.
    rewrite !minisat_focus_contributions_cons__propagate_dbu.
    rewrite (Hold co Hlits), (Hnew co Hlits). cbn.
    split; rewrite <- app_assoc; reflexivity.
Qed.

Lemma focus_scan_carrier_db_pair_token_replace__propagate_dbu :
  forall n olddb newdb p P kept rest current co onew pre post,
    db_wf n olddb ->
    In (current, co) olddb ->
    is_tag current = false ->
    minisat_focus_contributions olddb p =
      pre ++ (minisat_occurrence_of_entry (current, co), current) :: post ->
    minisat_focus_contributions newdb p =
      pre ++ (onew, current) :: post ->
    minisat_occurrence_safe P onew ->
    minisat_focus_scan_carrier olddb p P kept (current :: rest) ->
    minisat_focus_scan_carrier newdb p P (kept ++ (current :: nil)) rest.
Proof.
  intros n olddb newdb p P kept rest current co onew pre post
    Hdb Hselected Hreal Hold Hnew Hnewsafe Hscan.
  unfold minisat_focus_scan_carrier in Hscan |- *.
  destruct Hscan as [scanned [pending [Hcover [Hkept [Hrest Hsafe]]]]].
  destruct pending as [|[o w] pending]; cbn in Hrest; [discriminate|].
  inversion Hrest; subst w.
  assert (Hinold : In (o, current) (minisat_focus_contributions olddb p)).
  { eapply Permutation_in; [exact Hcover|].
    apply in_or_app. right. simpl. auto. }
  destruct (minisat_focus_real_word_owner__propagate_dbu
    n olddb p o current Hdb Hinold Hreal) as [co' [Hco' Ho]].
  assert (Hco : co' = co).
  { eapply db_wf_lookup_unique; [exact Hdb|exact Hco'|exact Hselected]. }
  subst co'. subst o.
  assert (Hbase : Permutation (scanned ++ pending) (pre ++ post)).
  { apply (Permutation_cons_inv
      (a := (minisat_occurrence_of_entry (current, co), current))).
    eapply Permutation_trans.
    - apply Permutation_middle.
    - eapply Permutation_trans; [exact Hcover|].
      rewrite Hold. apply Permutation_sym. apply Permutation_middle. }
  exists (scanned ++ ((onew, current) :: nil)), pending.
  split.
  - rewrite Hnew. rewrite <- app_assoc. cbn.
    eapply Permutation_trans.
    + apply Permutation_sym. apply Permutation_middle.
    + eapply Permutation_trans.
      * apply perm_skip. exact Hbase.
      * apply Permutation_middle.
  - split.
    + unfold minisat_focus_words in Hkept |- *.
      rewrite map_app. cbn.
      exact (f_equal (fun xs : list Z => xs ++ (current :: nil)) Hkept).
    + split; [reflexivity|].
      apply Forall_app. split; [exact Hsafe|].
      constructor; [exact Hnewsafe|constructor].
Qed.

(* ===== wit_54 capacity-abort helper set: the decomposition of the
   capacity-abort obligation into its independent pieces ===== *)
Lemma solver_propagation_nonwatch_rest_abort_fold__propagate_dbu :
  forall (s : Z) (M : msolver) (prob learnt : dbmap)
    (wm : wmap) (wcaps : list Z) (simp prop asg rsn lvl trl : Z),
    map fst prob = map fst (ms_prob M) ->
    map fst learnt = map fst (ms_learnt M) ->
    Zlength (ms_stats M) = 11 ->
    (&(s # "solver_t" ->ₛ "qhead") # Int
       |-> (mt_qhead (ms_core M) - 1) **
     &(s # "solver_t" ->ₛ "levels") # Ptr |-> lvl **
     &(s # "solver_t" ->ₛ "trail") # Ptr |-> trl **
     &(s # "solver_t" ->ₛ "reasons") # Ptr |-> rsn **
     solver_propagation_scan_arrays_noqh_at
       s M asg rsn lvl trl simp prop)
    |-- solver_propagation_nonwatch_rest_at s
      (msolver_propagation_abort M prob learnt wm wcaps simp prop)
      asg lvl.
Proof.
  intros s M prob learnt wm wcaps simp prop asg rsn lvl trl
    Hprobkeys Hlearntkeys Hstatslen.
  set (Mafter :=
    msolver_propagation_abort M prob learnt wm wcaps simp prop).
  assert (Hframe :
    solver_propagate_frame s Mafter = solver_propagate_frame s M).
  {
    unfold Mafter, solver_propagate_frame,
      solver_fp_rep, stats_propagate_frame,
      msolver_propagation_abort, msolver_propagation_update.
    cbn [fst ms_size ms_cap ms_capacity_pending_qhead
      ms_capacity_root_propagation_pending ms_root_level ms_prob ms_learnt
      ms_prob_cap ms_learnt_cap ms_activity ms_orderpos ms_order ms_order_cap
      ms_model ms_model_cap ms_tags ms_tagged ms_tagged_cap ms_stack
      ms_stack_cap ms_var_inc ms_var_decay ms_cla_inc ms_cla_decay
      ms_random_seed ms_progress ms_simpdb_assigns ms_verbosity ms_stats].
    rewrite Hprobkeys, Hlearntkeys.
    unfold stats_set_propagations, stats_starts, stats_decisions, stats_propagations,
    stats_inspects, stats_conflicts, stats_clauses, stats_clauses_literals,
    stats_learnts, stats_learnts_literals, stats_max_literals, stats_tot_literals.
    rewrite Zlength_replace_Znth, Hstatslen.
    rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 0 prop) by lia.
    rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 1 prop) by lia.
    rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 4 prop) by lia.
    rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 5 prop) by lia.
    rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 6 prop) by lia.
    rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 7 prop) by lia.
    rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 8 prop) by lia.
    rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 9 prop) by lia.
    rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 10 prop) by lia.
    reflexivity.
  }
  assert (Hbinary : solver_binary_rep Mafter = solver_binary_rep M).
  {
    unfold Mafter, solver_binary_rep, msolver_propagation_abort, msolver_propagation_update.
    cbn [ms_binary ms_binary_lits].
    reflexivity.
  }
  assert (Hstatscarrier :
    (&( s # "solver_t" ->ₛ "stats" .ₛ "propagations")
       # UInt64 |-> stats_propagations (ms_stats Mafter) **
     &( s # "solver_t" ->ₛ "stats" .ₛ "inspects")
       # UInt64 |-> stats_inspects (ms_stats Mafter)) =
    stats_propagate_scan &( s # "solver_t" ->ₛ "stats")
      prop (stats_inspects (ms_stats M))).
  {
    unfold Mafter, stats_propagate_scan, msolver_propagation_abort, msolver_propagation_update.
    cbn [ms_stats].
    unfold stats_propagations, stats_inspects, stats_set_propagations.
    rewrite (Znth_replace_Znth_Same 0 (ms_stats M) 2 prop) by lia.
    rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 3 prop) by lia.
    csimpl; reflexivity.
  }
  unfold solver_propagation_nonwatch_rest_at.
  Exists rsn trl.
  unfold solver_propagation_scan_arrays_noqh_at,
    solver_propagation_scan_core_at.
  rewrite Hframe, Hbinary.
  rewrite <- Hstatscarrier.
  unfold Mafter, msolver_propagation_abort, msolver_propagation_update.
  cbn [ms_size ms_cap ms_qtail ms_capacity_pending_qhead
    ms_capacity_root_propagation_pending ms_core ms_root_level
    ms_reason_words ms_prob ms_learnt ms_prob_cap ms_learnt_cap
    ms_binary ms_binary_lits ms_lim_cap ms_simpdb_props ms_stats
    mt_set_qhead mt_qhead mt_trail mt_assigns mt_levels mt_lim].
  unfold stats_propagations, stats_inspects, stats_set_propagations.
  rewrite (Znth_replace_Znth_Same 0 (ms_stats M) 2 prop) by lia.
  rewrite (Znth_replace_Znth_Diff 0 (ms_stats M) 2 3 prop) by lia.
  cancel (solver_propagate_frame s M).
  cancel (solver_binary_rep M).
  cancel
    (&( s # "solver_t" ->ₛ "stats" .ₛ "propagations")
       # UInt64 |-> prop).
  cancel
    (&( s # "solver_t" ->ₛ "stats" .ₛ "inspects")
       # UInt64 |-> stats_inspects (ms_stats M)).
  cancel (veci_rep &( s # "solver_t" ->ₛ "trail_lim")
    (mt_lim (ms_core M)) (ms_lim_cap M)).
  cancel (CharArray.seg asg 0 (ms_size M) (mt_assigns (ms_core M))).
  cancel (CharArray.undef_seg asg (ms_size M) (ms_cap M)).
  cancel (PtrArray.seg rsn 0 (ms_size M) (ms_reason_words M)).
  cancel (PtrArray.undef_seg rsn (ms_size M) (ms_cap M)).
  cancel (IntArray.seg lvl 0 (ms_size M) (mt_levels (ms_core M))).
  cancel (IntArray.undef_seg lvl (ms_size M) (ms_cap M)).
  cancel (IntArray.seg trl 0 (ms_qtail M) (mt_trail (ms_core M))).
  cancel (IntArray.undef_seg trl (ms_qtail M) (ms_cap M)).
  cancel
    (&( s # "solver_t" ->ₛ "qhead") # Int
       |-> (mt_qhead (ms_core M) - 1)).
  cancel (&( s # "solver_t" ->ₛ "qtail") # Int |-> ms_qtail M).
  cancel (&( s # "solver_t" ->ₛ "simpdb_props") # Int |-> simp).
  cancel (&( s # "solver_t" ->ₛ "assigns") # Ptr |-> asg).
  cancel (&( s # "solver_t" ->ₛ "levels") # Ptr |-> lvl).
  cancel (&( s # "solver_t" ->ₛ "reasons") # Ptr |-> rsn).
  cancel
    (&( s # "solver_t" ->ₛ "trail") # Ptr |-> trl).
  cancel
    (&( s # "solver_t" ->ₛ "binary") # Ptr |-> ms_binary M).
Qed.

Lemma propagation_normalized_clause_db_rebuild__propagate_dbu :
  forall (n : Z) (prob learnt : dbmap)
    (scan_current clause_lits stop k offset : Z)
    (false_lit p candidate sig watch0 : Z) (clause_contents : list Z),
    db_wf n (prob ++ learnt) ->
    propagation_scan_candidate_layout scan_current clause_lits stop k offset
      false_lit p candidate sig clause_contents ->
    (clause_db_pair_frame
       prob learnt scan_current clause_contents **
     (clause_lits + 0 * sizeof(INT)) # Int |-> watch0 **
     (clause_lits + 1 * sizeof(INT)) # Int |-> false_lit **
     k # Int |-> candidate **
     IntArray.missing_i clause_lits offset 2 (Zlength clause_contents)
       (sublist 2 (Zlength clause_contents) clause_contents))
    |-- EX prob_after learnt_after : dbmap,
      “ db_pair_lits_update prob learnt scan_current clause_contents
          (propagation_normalized_clause watch0 false_lit clause_contents)
          prob_after learnt_after ” &&
      (clause_db_rep prob_after ** clause_db_rep learnt_after).
Proof.
  intros n prob learnt scan_current clause_lits stop k offset false_lit p
    candidate sig watch0 clause_contents Hdbwf Hlayout.
  unfold propagation_scan_candidate_layout in Hlayout.
  destruct Hlayout as
    [Hlits [Hlen [Hfalse [Hstop [Hk [Hoffset [Hcandidate Hsig]]]]]]].
  unfold clause_lits_pointer in Hlits.
  subst clause_lits.
  subst k.
  assert (Hnewlen :
    Zlength (propagation_normalized_clause
      watch0 false_lit clause_contents) = Zlength clause_contents).
  {
    apply propagation_normalized_clause_length.
    lia.
  }
  unfold clause_db_pair_frame.
  Intros is_learnt.
  sep_apply_l_atomic
    (IntArray.missing_i_merge_to_seg (clause_lits_addr scan_current)
      2 offset (Zlength clause_contents) candidate
      (sublist 2 (Zlength clause_contents) clause_contents)).
  - dump_pre_spatial. lia.
  - rewrite Hcandidate, replace_Znth_Znth.
    sep_apply_l_atomic
      (IntArray.seg_single (clause_lits_addr scan_current) 0 watch0).
    sep_apply_l_atomic
      (IntArray.seg_single (clause_lits_addr scan_current) 1 false_lit).
    sepcon_lift
      (IntArray.seg (clause_lits_addr scan_current) 0 (0 + 1)
        (watch0 :: nil)).
    replace (0 + 1) with 1 by lia.
    replace (1 + 1) with 2 by lia.
    sep_apply_l_atomic
      (IntArray.seg_merge_to_seg (clause_lits_addr scan_current)
        0 1 2 (watch0 :: nil) (false_lit :: nil)).
    + dump_pre_spatial. lia.
    + cbn [app].
      sep_apply_l_atomic
        (IntArray.seg_merge_to_seg (clause_lits_addr scan_current)
          0 2 (Zlength clause_contents) (watch0 :: false_lit :: nil)
          (sublist 2 (Zlength clause_contents) clause_contents)).
      * dump_pre_spatial. lia.
      * cbn [app].
        fold (propagation_normalized_clause
          watch0 false_lit clause_contents).
        unfold clause_db_pair_remainder.
        Split.
        -- Intros co pre post. coq_prop_lift.
           destruct H as [Hprob [Hco_lits Hco_learnt]].
           assert (Hin : In (scan_current, co) (prob ++ learnt)).
           { rewrite Hprob, !in_app_iff. cbn. tauto. }
           assert (Hpos : 0 < scan_current).
           { eapply db_wf_ptr_pos; [exact Hdbwf | exact Hin]. }
           assert (Hmod : scan_current mod 2 = 0).
           { apply clause_ptr_mod2.
             eapply db_wf_even; [exact Hdbwf | exact Hin]. }
           set (new_lits := propagation_normalized_clause
             watch0 false_lit clause_contents).
           set (co_new := clause_obj_with_lits co new_lits).
           set (prob_after := pre ++ (scan_current, co_new) :: post).
           Exists prob_after learnt.
           split_pure_spatial.
           ++ unfold prob_after.
              rewrite clause_db_rep_app_equiv, clause_db_rep_cons.
              unfold MiniSatClause.rep, co_new, clause_obj_with_lits,
                new_lits.
              cbn [fst snd co_lits co_learnt].
              rewrite Hco_learnt, Hnewlen.
              entailer_with lia.
           ++ apply derivable1s_coq_prop_r.
              left. exists co, pre, post.
              split; [exact Hprob|].
              split; [exact Hco_lits|].
              split; reflexivity.
        -- Intros co pre post. coq_prop_lift.
           destruct H as [Hlearnt [Hco_lits Hco_learnt]].
           assert (Hin : In (scan_current, co) (prob ++ learnt)).
           { rewrite Hlearnt, !in_app_iff. cbn. tauto. }
           assert (Hpos : 0 < scan_current).
           { eapply db_wf_ptr_pos; [exact Hdbwf | exact Hin]. }
           assert (Hmod : scan_current mod 2 = 0).
           { apply clause_ptr_mod2.
             eapply db_wf_even; [exact Hdbwf | exact Hin]. }
           set (new_lits := propagation_normalized_clause
             watch0 false_lit clause_contents).
           set (co_new := clause_obj_with_lits co new_lits).
           set (learnt_after := pre ++ (scan_current, co_new) :: post).
           Exists prob learnt_after.
           split_pure_spatial.
           ++ unfold learnt_after.
              rewrite clause_db_rep_app_equiv, clause_db_rep_cons.
              unfold MiniSatClause.rep, co_new, clause_obj_with_lits,
                new_lits.
              cbn [fst snd co_lits co_learnt].
              rewrite Hco_learnt, Hnewlen.
              entailer_with lia.
           ++ apply derivable1s_coq_prop_r.
              right. exists co, pre, post.
              split; [exact Hlearnt|].
              split; [exact Hco_lits|].
              split; reflexivity.
Qed.

Lemma solver_propagation_capacity_rest_fold__propagate_dbu :
  forall (s : Z) (M : msolver) (wl hole target : Z)
    (pre post : list (list Z)) (capspre capspost : list Z)
    (asg lvl : Z),
    (solver_propagation_nonwatch_rest_at s M asg lvl **
     solver_wlists_handle s wl **
     wlists_split_except_two
       wl hole target pre post capspre capspost **
     clause_db_rep (ms_prob M) **
     clause_db_rep (ms_learnt M))
    |-- solver_propagation_capacity_rest_at
      s M wl hole target pre post capspre capspost asg lvl.
Proof.
  intros s M wl hole target pre post capspre capspost asg lvl.
  unfold solver_propagation_nonwatch_rest_at.
  Intros rsn trl.
  unfold solver_propagation_capacity_rest_at.
  unfold solver_propagate_frame.
  Intros act opos tgs.
  Exists act opos rsn trl tgs.
  cancel (solver_fp_rep s M).
  unfold solver_scalars_rep, solver_vecs_rep,
    solver_ptrs_rep, solver_var_arrays_rep, solver_trail_array_rep,
    solver_binary_rep, stats_rep, stats_propagate_frame,
    solver_wlists_handle.
  split_pure_spatial.
  - Intros. msat_cancel_sound. entailer_with lia.
    assert (Hstatscarrier :
      (&( s # "solver_t" ->ₛ "stats" .ₛ "propagations")
         # UInt64 |-> stats_propagations (ms_stats M) **
       &( s # "solver_t" ->ₛ "stats" .ₛ "inspects")
         # UInt64 |-> stats_inspects (ms_stats M)) =
      stats_propagate_scan &( s # "solver_t" ->ₛ "stats")
        (stats_propagations (ms_stats M)) (stats_inspects (ms_stats M))).
    {
      unfold stats_propagate_scan.
      csimpl; reflexivity.
    }
    rewrite Hstatscarrier.
    fold (stats_propagate_scan &( s # "solver_t" ->ₛ "stats")
      (stats_propagations (ms_stats M)) (stats_inspects (ms_stats M))).
    cancel (stats_propagate_scan &( s # "solver_t" ->ₛ "stats")
      (stats_propagations (ms_stats M)) (stats_inspects (ms_stats M))).
  - entailer_with lia.
Qed.

Lemma focus_scan_current_real_watch_pair__propagate_dbu :
  forall (n : Z) (db : dbmap) (p current : Z) (co : clause_obj)
    (P : literal -> Prop) (kept rest : list Z),
    db_wf n db ->
    In (current, co) db ->
    is_tag current = false ->
    3 <= Zlength (co_lits co) ->
    minisat_focus_scan_carrier db p P kept (current :: rest) ->
    real_watch_pair p (co_lits co).
Proof.
  intros n db p current co P kept rest Hdb Hselected Hreal Hlen Hscan.
  pose proof (db_wf_obj n db current co Hdb Hselected) as Hobj.
  pose proof (obj_wf_watch0 n co Hobj) as Hwatch0wf.
  pose proof (obj_wf_watch1 n co Hobj) as Hwatch1wf.
  unfold minisat_focus_scan_carrier in Hscan.
  destruct Hscan as
    [scanned [pending [Hcover [Hkept [Hwords Hsafe]]]]].
  destruct pending as [|[o w] pending]; cbn in Hwords; [discriminate|].
  inversion Hwords; subst w.
  assert (Hin : In (o, current) (minisat_focus_contributions db p)).
  {
    eapply Permutation_in; [exact Hcover|].
    apply in_or_app. right. cbn. auto.
  }
  unfold minisat_focus_contributions in Hin.
  apply in_flat_map in Hin.
  destruct Hin as [[q co'] [Hentry Hinwatch]].
  unfold minisat_entry_focus_contributions in Hinwatch.
  apply in_map_iff in Hinwatch.
  destruct Hinwatch as [word [Hpair Hinwatch]].
  inversion Hpair; subst word o.
  unfold entry_watchers in Hinwatch; cbn in Hinwatch.
  apply in_app_or in Hinwatch.
  destruct Hinwatch as [Hinwatch | Hinwatch].
  - destruct (lit_neg_c (co_watch0 co') =? p)%Z eqn:Hwatch;
      cbn in Hinwatch; [|contradiction].
    destruct (3 <=? Zlength (co_lits co'))%Z eqn:Hlarge;
      cbn in Hinwatch.
    + destruct Hinwatch as [Hq | []]. subst q.
      assert (Hco : co' = co).
      { eapply db_wf_lookup_unique;
          [exact Hdb | exact Hentry | exact Hselected]. }
      subst co'.
      apply Z.eqb_eq in Hwatch.
      unfold real_watch_pair, co_watch0.
      left. rewrite <- Hwatch.
      rewrite lit_neg_c_involutive.
      reflexivity.
    + destruct Hinwatch as [Htag | []]. subst current.
      rewrite is_tag_of in Hreal. discriminate.
  - destruct (lit_neg_c (co_watch1 co') =? p)%Z eqn:Hwatch;
      cbn in Hinwatch; [|contradiction].
    destruct (3 <=? Zlength (co_lits co'))%Z eqn:Hlarge;
      cbn in Hinwatch.
    + destruct Hinwatch as [Hq | []]. subst q.
      assert (Hco : co' = co).
      { eapply db_wf_lookup_unique;
          [exact Hdb | exact Hentry | exact Hselected]. }
      subst co'.
      apply Z.eqb_eq in Hwatch.
      unfold real_watch_pair, co_watch1.
      right. rewrite <- Hwatch.
      rewrite lit_neg_c_involutive.
      reflexivity.
    + destruct Hinwatch as [Htag | []]. subst current.
      rewrite is_tag_of in Hreal. discriminate.
Qed.

Lemma solver_propagation_weak_rewatch__propagate_dbu :
  forall (n : Z) (F : cnf) (A_arr : list literal)
    (K : solver_propagation_context) (M : msolver)
    (prob learnt : dbmap) (wm : wmap) (wcaps : list Z),
    solver_propagation_weak n F A_arr K
      (msolver_propagation_db_wmap_update
        M prob learnt (ms_wm M) (ms_wcaps M)) ->
    Zlength wm = Zlength (ms_wm M) ->
    Zlength wcaps = Zlength (ms_wcaps M) ->
    wmap_exact n (prob ++ learnt) wm ->
    solver_propagation_weak n F A_arr K
      (msolver_propagation_db_wmap_update M prob learnt wm wcaps).
Proof.
  intros n F A_arr K M prob learnt wm wcaps
    Hweak Hwm_len Hwcaps_len Hwm_exact.
  unfold solver_propagation_weak in Hweak |- *.
  destruct Hweak as [Hroot Hctx].
  split.
  - change (ms_capacity_root_propagation_pending M = 0).
    exact Hroot.
  - assert (Hshape : solver_shape
      (msolver_propagation_db_wmap_update M prob learnt wm wcaps)).
    {
      pose proof (msolver_inv_ctx_shape n F A_arr K _ Hctx) as Hshape0.
      unfold solver_shape in Hshape0 |- *.
      unfold msolver_propagation_db_wmap_update,
        msolver_propagation_overlay, msolver_propagation_update in Hshape0 |- *.
      cbn in Hshape0 |- *.
      rewrite Hwm_len, Hwcaps_len.
      exact Hshape0.
    }
    destruct K as [A_inst | A_proc]; cbn in Hctx |- *;
      unfold msolver_propagation_db_wmap_update,
        msolver_propagation_overlay, msolver_propagation_update in Hctx |- *;
      cbn in Hctx |- *; destruct Hctx; constructor; assumption.
Qed.

Lemma solver_shape_propagation_abort__propagate_dbu :
  forall (M : msolver) (prob learnt : dbmap) (wm : wmap)
    (wcaps : list Z) (simp prop : Z),
    solver_shape M ->
    ms_capacity_root_propagation_pending M = 0 ->
    Zlength wm = Zlength (ms_wm M) ->
    Zlength wcaps = Zlength (ms_wcaps M) ->
    0 < mt_qhead (ms_core M) ->
    solver_shape
      (msolver_propagation_abort M prob learnt wm wcaps simp prop).
Proof.
  intros M prob learnt wm wcaps simp prop
    Hshape Hroot Hwm_len Hwcaps_len Hqpos.
  unfold solver_shape, msolver_propagation_abort, msolver_propagation_update in Hshape |- *.
  simpl in Hshape |- *. unfold stats_set_propagations.
  rewrite Hwm_len, Hwcaps_len, Zlength_replace_Znth.
  destruct Hshape as
    [Hsize [Hcap [Htwosize [Hassigns [Hlevels [Hreasons
    [Horderpos [Hactivity [Htags [Htrail [Hqhead [Hpending
    [Hrootflag [Hrootgate [Hqtail [Hwm [Hwcaps [Hbinarylen
    [Hstatslen [Hrootlevel [Hbinary Hbinaryeven]]]]]]]]]]]]]]]]]]]]].
  (* Twenty-nine conjuncts, each either a field of [solver_shape M] carried
     over unchanged or an arithmetic consequence of one (the three that mention
     the decremented [mt_qhead]): [assumption] takes the former, [lia] the rest. *)
  repeat split; try assumption; lia.
Qed.

Lemma solver_propagation_weak_abort__propagate_dbu :
  forall (n : Z) (F : cnf) (A_arr : list literal)
    (K : solver_propagation_context) (M : msolver)
    (prob learnt : dbmap) (wm : wmap) (wcaps : list Z)
    (simp prop : Z),
    solver_propagation_weak n F A_arr K
      (msolver_propagation_db_wmap_update M prob learnt wm wcaps) ->
    mtrail_wf n (ms_core
      (msolver_propagation_abort M prob learnt wm wcaps simp prop)) ->
    solver_shape
      (msolver_propagation_abort M prob learnt wm wcaps simp prop) ->
    solver_propagation_weak n F A_arr K
      (msolver_propagation_abort M prob learnt wm wcaps simp prop).
Proof.
  intros n F A_arr K M prob learnt wm wcaps simp prop
    Hweak Htrail Hshape.
  unfold solver_propagation_weak in Hweak |- *.
  destruct Hweak as [Hroot Hctx].
  split.
  - change (ms_capacity_root_propagation_pending M = 0).
    exact Hroot.
  - destruct K as [A_inst | A_proc]; cbn in Hctx |- *.
    + unfold msolver_propagation_db_wmap_update,
        msolver_propagation_overlay, msolver_propagation_update in Hctx.
      unfold msolver_propagation_abort, msolver_propagation_update.
      cbn [mt_set_qhead] in Hctx |- *.
      destruct Hctx. constructor; assumption.
    + unfold msolver_propagation_db_wmap_update,
        msolver_propagation_overlay, msolver_propagation_update in Hctx.
      unfold msolver_propagation_abort, msolver_propagation_update.
      cbn [mt_set_qhead] in Hctx |- *.
      destruct Hctx. constructor; assumption.
Qed.

(* Writing a bounded block preserves the preceding cells and leaves exactly
   the unwritten suffix length. The physical copy loop and binary-conflict
   packaging use the same prefix guarantee. *)
Lemma binary_watch_write_prefix__propagate_dbu :
  forall (xs mem prefix : list Z) (write_at : Z),
    0 <= write_at ->
    write_at + Zlength xs <= Zlength mem ->
    Zlength prefix = write_at ->
    sublist 0 write_at mem = prefix ->
    exists tail,
      binary_watch_write write_at xs mem = prefix ++ xs ++ tail /\
      Zlength tail = Zlength mem - write_at - Zlength xs.
Proof.
  intros xs. induction xs as [|a xs IH];
    intros mem prefix write_at Hwrite0 Hbound Hplen Hprefix.
  - simpl. rewrite Zlength_nil in Hbound.
    exists (sublist write_at (Zlength mem) mem). simpl.
    split.
    + rewrite <- Hprefix.
      rewrite <- (sublist_split 0 (Zlength mem) write_at mem) by lia.
      rewrite sublist_self by reflexivity. reflexivity.
    + rewrite Zlength_nil. rewrite Zlength_sublist by lia. lia.
  - rewrite Zlength_cons in Hbound.
    pose proof (Zlength_nonneg xs).
    assert (Hindex : 0 <= write_at < Zlength mem) by lia.
    simpl.
    destruct (IH (replace_Znth write_at a mem)
      (prefix ++ (a :: nil)%list) (write_at + 1))
      as [tail [Htail Htail_len]].
    + lia.
    + rewrite Zlength_replace_Znth. lia.
    + rewrite Zlength_app, Zlength_cons, Zlength_nil, Hplen. lia.
    + rewrite (replace_Znth_split 0 a write_at mem Hindex).
      rewrite Hprefix.
      replace (prefix ++ a ::
        sublist (write_at + 1) (Zlength mem) mem)
        with ((prefix ++ (a :: nil)%list) ++
          sublist (write_at + 1) (Zlength mem) mem)
        by (rewrite <- app_assoc; reflexivity).
      replace (write_at + 1) with
        (Zlength (prefix ++ (a :: nil)%list)) by
        (rewrite Zlength_app, Zlength_cons, Zlength_nil, Hplen; lia).
      apply sublist_app_exact1.
    + exists tail. split.
      * rewrite Htail. rewrite <- !app_assoc. reflexivity.
      * rewrite Zlength_replace_Znth in Htail_len.
        rewrite Zlength_cons. lia.
Qed.

Lemma propagation_copy_completion__propagate_dbu :
  forall (source kept moved rest garbage words raw_prefix : list Z)
    (current : Z) (suffix memory : list Z)
    (ii jj src dst endvar begin i j : Z),
    propagation_watch_scan_physical
      source kept moved rest garbage words ii jj ->
    binary_watch_copy_progress
      words raw_prefix current suffix ii jj src dst memory ->
    endvar = begin + Zlength source * sizeof(PTR) ->
    i >= endvar ->
    i = begin + src * sizeof(PTR) ->
    j = begin + dst * sizeof(PTR) ->
    src <= Zlength source ->
    exists copied,
      rest = current :: copied /\
      (j - begin) ÷ sizeof(PTR) = dst /\
      sublist 0 dst memory = kept ++ rest.
Proof.
  intros source kept moved rest garbage words raw_prefix current suffix
    memory ii jj src dst endvar begin i j Hphysical Hcopyprogress
    Hend Hige Hi Hj Hsrcbound.
  unfold propagation_watch_scan_physical in Hphysical.
  destruct Hphysical as
    [Hscanphysical [Hmemory [Hjj [Hii Hwatchlen]]]].
  unfold binary_watch_copy_progress in Hcopyprogress.
  destruct Hcopyprogress as
    [copied [copy_rest [Hwords [Hrawlen [Hdstle [Hsuffix
    [Hsrc [Hdst [Hcopy Hcopylen]]]]]]]]].
  (* `ptr_size_Z` and `addr_max_unsigned` reach goals through the Arch functor
     parameter, so `sizeof_ptr` yields the Arch alias rather than the literal 4,
     and `fold_arch` folds `Arch32.ptr_size_Z` back to the rules-exported
     `ptr_size_Z`, so
     the byte-offset hypotheses stay ARCH-GENERIC - no pointer width is assumed here.
     Exactly one downstream step needed the old literal: cancelling the stride out of
     `src * ptr_size_Z >= Zlength source * ptr_size_Z`.  That is nonlinear once the
     stride is symbolic, so it takes `nia` plus the Arch signature's own positivity
     axiom `ptr_size_pos` instead of the 32-bit compat lemma. *)
  change (sizeof (PTR)) with ptr_size_Z in Hend, Hi, Hj.
  fold_arch.
  pose proof ptr_size_pos as Hptr_size_pos.
  assert (Hsrc_eq : src = Zlength source) by nia.
  assert (Hrawprefix : raw_prefix = kept ++ garbage).
  {
    assert (Hraw : sublist 0 ii words = raw_prefix).
    { rewrite Hwords. rewrite <- Hrawlen. apply sublist_app_exact1. }
    assert (Hphys : sublist 0 ii words = kept ++ garbage).
    { rewrite Hmemory, app_assoc. rewrite <- Hii.
      apply sublist_app_exact1. }
    congruence.
  }
  assert (Hcopy_rest_nil : copy_rest = nil).
  {
    assert (Hrest : rest = current :: suffix).
    {
      rewrite Hrawprefix in Hwords. rewrite Hmemory in Hwords.
      rewrite <- app_assoc in Hwords.
      apply app_inv_head in Hwords. apply app_inv_head in Hwords.
      exact Hwords.
    }
    assert (Hrestlen : Zlength rest = 1 + Zlength copied).
    {
      rewrite Hmemory in Hwatchlen.
      rewrite !Zlength_app in Hwatchlen.
      rewrite Zlength_app in Hii. rewrite Hsrc_eq in Hsrc. lia.
    }
    rewrite Hrest, Hsuffix, Zlength_cons, Zlength_app in Hrestlen.
    apply Zlength_nil_inv. lia.
  }
  subst copy_rest. rewrite app_nil_r in Hsuffix.
  assert (Hrestcopy : rest = current :: copied).
  {
    rewrite Hrawprefix in Hwords. rewrite Hmemory in Hwords.
    rewrite <- app_assoc in Hwords.
    apply app_inv_head in Hwords. apply app_inv_head in Hwords.
    rewrite Hsuffix in Hwords. exact Hwords.
  }
  assert (Hjjindex : 0 <= jj < Zlength words).
  { rewrite Hwatchlen. pose proof (Zlength_nonneg copied). lia. }
  assert (Hwatchprefix : sublist 0 jj words = kept).
  { rewrite Hmemory. rewrite <- Hjj. apply sublist_app_exact1. }
  assert (Hreplaceprefix :
    sublist 0 (jj + 1) (replace_Znth jj current words) =
      kept ++ (current :: nil)%list).
  {
    rewrite (replace_Znth_split 0 current jj words Hjjindex).
    rewrite Hwatchprefix.
    replace (kept ++ current :: sublist (jj + 1) (Zlength words) words)
      with ((kept ++ (current :: nil)%list) ++
        sublist (jj + 1) (Zlength words) words)
      by (rewrite <- app_assoc; reflexivity).
    replace (jj + 1) with
      (Zlength (kept ++ (current :: nil)%list)) by
      (rewrite Zlength_app, Zlength_cons, Zlength_nil, Hjj; lia).
    apply sublist_app_exact1.
  }
  destruct (binary_watch_write_prefix__propagate_dbu copied (replace_Znth jj current words)
    (kept ++ (current :: nil)%list) (jj + 1))
    as [garbage_route [Hwritten _]].
  - lia.
  - rewrite Zlength_replace_Znth, Hwatchlen. lia.
  - rewrite Zlength_app, Zlength_cons, Zlength_nil, Hjj. lia.
  - exact Hreplaceprefix.
  - assert (Hcopydecomp : memory = (kept ++ rest) ++ garbage_route).
    {
      rewrite Hcopy, Hwritten, Hrestcopy.
      rewrite <- !app_assoc. reflexivity.
    }
    assert (Hcopydst : dst = Zlength (kept ++ rest)).
    {
      rewrite Zlength_app, Hrestcopy, Zlength_cons.
      rewrite Hdst, Hjj. lia.
    }
    assert (Hcopyfront : sublist 0 dst memory = kept ++ rest).
    { rewrite Hcopydecomp, Hcopydst. apply sublist_app_exact1. }
    assert (Hdiv : (j - begin) ÷ sizeof(PTR) = dst).
    {
      (* Arch-generic - the stride stays
         `ptr_size_Z` on both sides and `Z.quot_mul` gets its nonzero side condition
         from `ptr_size_pos` rather than from a hardcoded 4. *)
      rewrite Hj, sizeof_ptr.
      fold_arch.
      replace (begin + dst * ptr_size_Z - begin) with (dst * ptr_size_Z) by lia.
      rewrite Z.quot_mul by (pose proof ptr_size_pos; lia). reflexivity.
    }
    exists copied.
    split; [exact Hrestcopy |].
    split; [exact Hdiv | exact Hcopyfront].
Qed.

(* The watcher-frontier half of
   [propagation_norm_clause_watcher_xport__propagate_dbu].  The
   database update rewrites exactly one entry, so every frontier obligation is
   either an untouched entry or the rewritten one, whose two watched literals
   are the same pair in the other order. *)
Lemma propagation_normalized_frontier_transport :
  forall (n : Z) (M : msolver) (p current : Z) (co : clause_obj)
    (a0 a1 watch0 false_lit : Z) (tail : list Z)
    (prob_after learnt_after : dbmap),
    db_wf n (msolver_db M) ->
    In (current, co) (msolver_db M) ->
    co_lits co = a0 :: a1 :: tail ->
    ((a0 = false_lit /\ watch0 = a1) \/ (a1 = false_lit /\ watch0 = a0)) ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current (a0 :: a1 :: tail)
      (propagation_normalized_clause watch0 false_lit (a0 :: a1 :: tail))
      prob_after learnt_after ->
    minisat_watch_frontier_except n (msolver_db M) (mt_assigns (ms_core M))
      (mt_trail (ms_core M)) (mt_qhead (ms_core M)) (lit_denote p) ->
    minisat_watch_frontier_except n (prob_after ++ learnt_after)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M)) (mt_qhead (ms_core M))
      (lit_denote p).
Proof.
  intros n M p current co a0 a1 watch0 false_lit tail prob_after learnt_after
    Hdbwf Hin Hco_lits Hwatchcases Hupdate Hfrontier.
  pose proof Hupdate as Hu.
  destruct Hu as
    [[co' [pre [post [Hprob [Hlits' [Hprob' Hlearnt']]]]]]
    |[co' [pre [post [Hlearnt [Hlits' [Hprob' Hlearnt']]]]]]].
  - assert (Hco : co' = co).
    {
      eapply db_wf_lookup_unique; [exact Hdbwf| |exact Hin].
      unfold msolver_db. apply in_or_app. left.
      rewrite Hprob. apply in_or_app. right. cbn. auto.
    }
    subst co'. subst prob_after learnt_after.
    unfold minisat_watch_frontier_except,
      minisat_watch_occurrences in Hfrontier |- *.
    unfold watch_frontier_except in Hfrontier |- *.
    rewrite Forall_forall in Hfrontier |- *.
    intros o Ho. apply in_map_iff in Ho as [[q obj] [<- Hentry]].
    destruct (in_app_or _ _ _ Hentry) as [Hnewprob | Hlearntold].
    + destruct (in_app_or _ _ _ Hnewprob) as [Hepre | Hecons].
      * apply Hfrontier. apply in_map. unfold msolver_db.
        apply in_or_app. left. rewrite Hprob.
        apply in_or_app. left. exact Hepre.
      * destruct Hecons as [Heq | Hepost].
        -- inversion Heq; subst q obj.
           specialize (Hfrontier
             (minisat_occurrence_of_entry (current, co))).
           specialize (Hfrontier ltac:(apply in_map; exact Hin)).
           destruct Hwatchcases as [[Ha0 Hw] | [Ha1 Hw]].
           ++ subst a0 watch0.
              unfold minisat_occurrence_of_entry, co_watch0, co_watch1,
                clause_obj_with_lits,
                propagation_normalized_clause in *.
              rewrite Hco_lits in Hfrontier. cbn in *. tauto.
           ++ subst a1 watch0.
              unfold minisat_occurrence_of_entry, co_watch0, co_watch1,
                clause_obj_with_lits,
                propagation_normalized_clause in *.
              rewrite Hco_lits in Hfrontier. cbn in *. exact Hfrontier.
        -- apply Hfrontier. apply in_map. unfold msolver_db.
           apply in_or_app. left. rewrite Hprob.
           apply in_or_app. right. cbn. right. exact Hepost.
    + apply Hfrontier. apply in_map. unfold msolver_db.
      apply in_or_app. right. exact Hlearntold.
  - assert (Hco : co' = co).
    {
      eapply db_wf_lookup_unique; [exact Hdbwf| |exact Hin].
      unfold msolver_db. apply in_or_app. right.
      rewrite Hlearnt. apply in_or_app. right. cbn. auto.
    }
    subst co'. subst prob_after learnt_after.
    unfold minisat_watch_frontier_except,
      minisat_watch_occurrences in Hfrontier |- *.
    unfold watch_frontier_except in Hfrontier |- *.
    rewrite Forall_forall in Hfrontier |- *.
    intros o Ho. apply in_map_iff in Ho as [[q obj] [<- Hentry]].
    destruct (in_app_or _ _ _ Hentry) as [Hprobold | Hnewlearnt].
    + apply Hfrontier. apply in_map. unfold msolver_db.
      apply in_or_app. left. exact Hprobold.
    + destruct (in_app_or _ _ _ Hnewlearnt) as [Hepre | Hecons].
      * apply Hfrontier. apply in_map. unfold msolver_db.
        apply in_or_app. right. rewrite Hlearnt.
        apply in_or_app. left. exact Hepre.
      * destruct Hecons as [Heq | Hepost].
        -- inversion Heq; subst q obj.
           specialize (Hfrontier
             (minisat_occurrence_of_entry (current, co))).
           specialize (Hfrontier ltac:(apply in_map; exact Hin)).
           destruct Hwatchcases as [[Ha0 Hw] | [Ha1 Hw]].
           ++ subst a0 watch0.
              unfold minisat_occurrence_of_entry, co_watch0, co_watch1,
                clause_obj_with_lits,
                propagation_normalized_clause in *.
              rewrite Hco_lits in Hfrontier. cbn in *. tauto.
           ++ subst a1 watch0.
              unfold minisat_occurrence_of_entry, co_watch0, co_watch1,
                clause_obj_with_lits,
                propagation_normalized_clause in *.
              rewrite Hco_lits in Hfrontier. cbn in *. exact Hfrontier.
        -- apply Hfrontier. apply in_map. unfold msolver_db.
           apply in_or_app. right. rewrite Hlearnt.
           apply in_or_app. right. cbn. right. exact Hepost.
Qed.

Lemma propagation_norm_clause_watcher_xport__propagate_dbu :
  forall (n : Z) (M : msolver) (P : literal -> Prop)
    (p current : Z) (suffix kept contents : list Z)
    (watch0 false_lit lits stop k offset candidate sig : Z)
    (prob_after learnt_after : dbmap),
    db_wf n (msolver_db M) ->
    propagation_scan_candidate_layout current lits stop k offset false_lit
      p candidate sig contents ->
    watch0 + false_lit = Znth 0 contents 0 + Znth 1 contents 0 ->
    minisat_focus_scan_carrier
      (msolver_db M) p P kept (current :: suffix) ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current contents
      (propagation_normalized_clause watch0 false_lit contents)
      prob_after learnt_after ->
    minisat_watch_frontier_except n (msolver_db M)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p) ->
    exists (co : clause_obj) (a0 a1 : Z) (tail : list Z),
      contents = a0 :: a1 :: tail /\
      In (current, co) (msolver_db M) /\
      co_lits co = a0 :: a1 :: tail /\
      sublist 2 (Zlength (a0 :: a1 :: tail)) (a0 :: a1 :: tail) = tail /\
      ((a0 = false_lit /\ watch0 = a1) \/
       (a1 = false_lit /\ watch0 = a0)) /\
      Permutation
        (propagation_normalized_clause watch0 false_lit (a0 :: a1 :: tail))
        (a0 :: a1 :: tail) /\
      (forall l,
        Permutation (expected_watchers (msolver_db M) l)
          (expected_watchers (prob_after ++ learnt_after) l)) /\
      minisat_watch_frontier_except n (prob_after ++ learnt_after)
        (mt_assigns (ms_core M)) (mt_trail (ms_core M))
        (mt_qhead (ms_core M)) (lit_denote p).
Proof.
  intros n M P p current suffix kept contents watch0 false_lit lits stop k
    offset candidate sig prob_after learnt_after Hdbwf Hlayout Hwatchsum
    Hscan Hupdate Hfrontier.
  pose proof Hlayout as Hlayout_fields.
  unfold propagation_scan_candidate_layout in Hlayout_fields.
  destruct Hlayout_fields as
    [Hlits [Hclauselen [Hfalse [Hstop [Hk
    [Hoffset [Hcandidate Hsig]]]]]]].
  assert (Hselected : exists co,
    In (current, co) (msolver_db M) /\ co_lits co = contents).
  {
    pose proof Hupdate as Hu.
    destruct Hu as
      [[co [pre [post [Hprob [Hlits0 [Hprob' Hlearnt']]]]]]
      |[co [pre [post [Hlearnt [Hlits0 [Hprob' Hlearnt']]]]]]].
    - exists co. split; [|exact Hlits0].
      unfold msolver_db. apply in_or_app. left.
      rewrite Hprob. apply in_or_app. right. cbn. auto.
    - exists co. split; [|exact Hlits0].
      unfold msolver_db. apply in_or_app. right.
      rewrite Hlearnt. apply in_or_app. right. cbn. auto.
  }
  destruct Hselected as [co [Hin Hco_lits]].
  pose proof (db_wf_obj n (msolver_db M) current co Hdbwf Hin) as Hobj.
  unfold obj_wf in Hobj. rewrite Hco_lits in Hobj.
  destruct Hobj as [Hobjlen [Hall Hnodup]].
  assert (Hcurrentreal : is_tag current = false).
  { apply even_not_tag. eapply db_wf_even; eassumption. }
  assert (Hrealwatch_co : real_watch_pair p (co_lits co)).
  {
    eapply focus_scan_current_real_watch_pair__propagate_dbu
      with (db := msolver_db M) (current := current) (co := co)
        (P := P) (kept := kept) (rest := suffix).
    - exact Hdbwf.
    - exact Hin.
    - exact Hcurrentreal.
    - rewrite Hco_lits. exact Hclauselen.
    - exact Hscan.
  }
  assert (Hrealwatch : real_watch_pair p contents).
  { rewrite <- Hco_lits. exact Hrealwatch_co. }
  destruct contents as [|a0 tail0]; cbn in Hobjlen; [lia|].
  destruct tail0 as [|a1 tail]; cbn in Hobjlen; [lia|].
  assert (Htail : sublist 2 (Zlength (a0 :: a1 :: tail))
      (a0 :: a1 :: tail) = tail).
  {
    replace (a0 :: a1 :: tail) with ((a0 :: a1 :: nil) ++ tail)
      by reflexivity.
    assert (Hrange : 2 <= 2 <= Zlength ((a0 :: a1 :: nil) ++ tail)).
    {
      split; [lia|]. rewrite Zlength_app.
      change (2 <= 2 + Zlength tail).
      pose proof (Zlength_nonneg tail). lia.
    }
    rewrite (sublist_split_app_r 2
      (Zlength ((a0 :: a1 :: nil) ++ tail)) 2
      (a0 :: a1 :: nil) tail ltac:(reflexivity) Hrange).
    replace (Zlength ((a0 :: a1 :: nil) ++ tail) - 2)
      with (Zlength tail) by
      (rewrite Zlength_app, !Zlength_cons, Zlength_nil; lia).
    apply sublist_self. reflexivity.
  }
  assert (Hwatchcases :
    (a0 = false_lit /\ watch0 = a1) \/
    (a1 = false_lit /\ watch0 = a0)).
  {
    unfold real_watch_pair in Hrealwatch.
    rewrite !Znth0_cons in Hrealwatch, Hwatchsum.
    rewrite !Znth_cons in Hrealwatch, Hwatchsum by lia.
    replace (1 - 1) with 0 in Hrealwatch, Hwatchsum by lia.
    rewrite !Znth0_cons in Hrealwatch, Hwatchsum.
    destruct Hrealwatch as [Hw | Hw].
    - left. rewrite <- Hfalse in Hw. split; [exact Hw|lia].
    - right. rewrite <- Hfalse in Hw. split; [exact Hw|lia].
  }
  assert (Hperm : Permutation
    (propagation_normalized_clause watch0 false_lit (a0 :: a1 :: tail))
    (a0 :: a1 :: tail)).
  {
    unfold propagation_normalized_clause. rewrite Htail.
    destruct Hwatchcases as [[Ha0 Hw] | [Ha1 Hw]].
    - subst a0 watch0. apply perm_swap.
    - subst a1 watch0. reflexivity.
  }
  set (new_lits := propagation_normalized_clause
    watch0 false_lit (a0 :: a1 :: tail)).
  set (co_new := clause_obj_with_lits co new_lits).
  assert (Hentryperm : forall l,
    Permutation (entry_watchers (current, co) l)
      (entry_watchers (current, co_new) l)).
  {
    intros l. destruct Hwatchcases as [[Ha0 Hw] | [Ha1 Hw]].
    - subst a0 watch0.
      unfold entry_watchers, co_watch0, co_watch1, co_new,
        clause_obj_with_lits, new_lits, propagation_normalized_clause.
      rewrite Hco_lits, Htail. cbn. apply Permutation_app_comm.
    - subst a1 watch0.
      unfold entry_watchers, co_watch0, co_watch1, co_new,
        clause_obj_with_lits, new_lits, propagation_normalized_clause.
      rewrite Hco_lits, Htail. cbn. reflexivity.
  }
  fold new_lits in Hupdate.
  assert (Hexpected : forall l,
    Permutation (expected_watchers (msolver_db M) l)
      (expected_watchers (prob_after ++ learnt_after) l)).
  {
    intros l. pose proof Hupdate as Hu.
    destruct Hu as
      [[co' [pre [post [Hprob [Hlits' [Hprob' Hlearnt']]]]]]
      |[co' [pre [post [Hlearnt [Hlits' [Hprob' Hlearnt']]]]]]].
    - assert (Hco : co' = co).
      {
        eapply db_wf_lookup_unique; [exact Hdbwf| |exact Hin].
        unfold msolver_db. apply in_or_app. left.
        rewrite Hprob. apply in_or_app. right. cbn. auto.
      }
      subst co'. subst prob_after learnt_after.
      unfold msolver_db. rewrite Hprob. unfold co_new.
      rewrite !expected_watchers_app.
      rewrite !expected_watchers_cons.
      apply Permutation_app_tail. apply Permutation_app_head.
      apply Permutation_app_tail. apply Hentryperm.
    - assert (Hco : co' = co).
      {
        eapply db_wf_lookup_unique; [exact Hdbwf| |exact Hin].
        unfold msolver_db. apply in_or_app. right.
        rewrite Hlearnt. apply in_or_app. right. cbn. auto.
      }
      subst co'. subst prob_after learnt_after.
      unfold msolver_db. rewrite Hlearnt. unfold co_new.
      rewrite !expected_watchers_app.
      rewrite !expected_watchers_cons.
      apply Permutation_app_head. apply Permutation_app_head.
      apply Permutation_app_tail. apply Hentryperm.
  }
  assert (Hfrontiernew : minisat_watch_frontier_except n
    (prob_after ++ learnt_after) (mt_assigns (ms_core M))
    (mt_trail (ms_core M)) (mt_qhead (ms_core M)) (lit_denote p))
    by (unfold new_lits in Hupdate;
        eapply propagation_normalized_frontier_transport; eassumption).
  exists co, a0, a1, tail.
  split; [reflexivity |].
  split; [exact Hin |].
  split; [exact Hco_lits |].
  split; [exact Htail |].
  split; [exact Hwatchcases |].
  split; [exact Hperm |].
  split; [exact Hexpected | exact Hfrontiernew].
Qed.

Lemma propagation_normalized_clause_weak_transport__propagate_dbu :
  forall (n : Z) (F : cnf) (A_arr : list literal)
    (K : solver_propagation_context) (M : msolver)
    (p current false_lit watch0 a0 a1 : Z) (tail : list Z)
    (co : clause_obj) (prob_after learnt_after : dbmap),
    solver_propagation_weak n F A_arr K M ->
    processed (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) p ->
    false_lit = lit_neg_c p ->
    In (current, co) (msolver_db M) ->
    co_lits co = a0 :: a1 :: tail ->
    sublist 2 (Zlength (a0 :: a1 :: tail)) (a0 :: a1 :: tail) = tail ->
    ((a0 = false_lit /\ watch0 = a1) \/
     (a1 = false_lit /\ watch0 = a0)) ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current
      (a0 :: a1 :: tail)
      (propagation_normalized_clause watch0 false_lit (a0 :: a1 :: tail))
      prob_after learnt_after ->
    Permutation
      (propagation_normalized_clause watch0 false_lit (a0 :: a1 :: tail))
      (a0 :: a1 :: tail) ->
    (forall l,
      Permutation (expected_watchers (msolver_db M) l)
        (expected_watchers (prob_after ++ learnt_after) l)) ->
    solver_propagation_weak n F A_arr K
      (msolver_propagation_db_wmap_update M prob_after learnt_after
        (ms_wm M) (ms_wcaps M)).
Proof.
  intros n F A_arr K M p current false_lit watch0 a0 a1 tail co
    prob_after learnt_after Hweak Hprocessed Hfalse Hin Hco_lits Htail
    Hwatchcases Hupdate Hperm Hexpected.
  assert (Hfalsefalse : lit_false (mt_assigns (ms_core M)) false_lit).
  {
    destruct Hprocessed as [Hptrue Hprocessed_rest].
    unfold lit_true in Hptrue. unfold lit_false.
    rewrite Hfalse, lit_var_c_neg, lit_sig_neg. lia.
  }
  set (new_lits := propagation_normalized_clause
    watch0 false_lit (a0 :: a1 :: tail)).
  fold new_lits in Hupdate, Hperm.
  destruct Hwatchcases as [[Ha0 Hw] | [Ha1 Hw]].
  - assert (Hheadfalse : lit_false (mt_assigns (ms_core M)) (co_watch0 co)).
    { unfold co_watch0. rewrite Hco_lits. subst a0. cbn. exact Hfalsefalse. }
    unfold solver_propagation_weak in Hweak |- *.
    destruct Hweak as [Hroot0 Hctx]. split.
    + unfold msolver_propagation_db_wmap_update,
        msolver_propagation_overlay, msolver_propagation_update. cbn. exact Hroot0.
    + eapply (ctx_db_pair_lits_no_owner__propagate_dbu n F A_arr K M).
      * exact Hctx.
      * exact Hupdate.
      * exact Hperm.
      * exact Hexpected.
      * eapply (ctx_no_live_reason_owner_head_false__propagate_dbu
          n F A_arr K M); eassumption.
  - assert (Hnewid : new_lits = a0 :: a1 :: tail).
    {
      unfold new_lits, propagation_normalized_clause. rewrite Htail.
      subst a1 watch0. reflexivity.
    }
    assert (Hdbid : prob_after = ms_prob M /\ learnt_after = ms_learnt M).
    {
      pose proof Hupdate as Hu.
      destruct Hu as
        [[co' [pre [post [Hprob [Hlits' [Hprob' Hlearnt']]]]]]
        |[co' [pre [post [Hlearnt [Hlits' [Hprob' Hlearnt']]]]]]].
      + subst prob_after learnt_after. split; [|reflexivity].
        rewrite Hnewid, <- Hlits'.
        replace (clause_obj_with_lits co' (co_lits co')) with co'
          by (destruct co'; reflexivity).
        symmetry. exact Hprob.
      + subst prob_after learnt_after. split; [reflexivity|].
        rewrite Hnewid, <- Hlits'.
        replace (clause_obj_with_lits co' (co_lits co')) with co'
          by (destruct co'; reflexivity).
        symmetry. exact Hlearnt.
    }
    destruct Hdbid as [Hprobid Hlearntid].
    rewrite Hprobid, Hlearntid.
    unfold msolver_propagation_db_wmap_update,
      msolver_propagation_overlay, msolver_propagation_update. destruct M. exact Hweak.
Qed.

(* The open watcher scan and the capacity-abort exit, in seven steps: the
   first three read facts out of an open scan, the last four build and then
   discharge the abort state the C capacity exit publishes. *)
(* ===== 1.  The open scan runs on a well-formed clause database. ===== *)
Lemma propagation_scan_open_db_wf__propagate_dbu :
  forall (n : Z) (F : cnf) (A_arr : list literal)
    (K : solver_propagation_context) (M0 Mentry M : msolver)
    (p confl : Z) (source kept moved rest garbage memory : list Z)
    (ii jj current : Z) (suffix : list Z),
    propagation_scan_open n F A_arr K M0 Mentry M p confl
      source kept moved rest garbage memory ii jj current suffix ->
    db_wf n (msolver_db M).
Proof.
  intros n F A_arr K M0 Mentry M p confl source kept moved rest garbage
    memory ii jj current suffix Hopen.
  destruct Hopen as [_ [_ [_ [_ [Hsem [_ [_ Hconfl]]]]]]].
  destruct Hsem as [Hlive | Hdead];
    [| destruct Hdead as [Hnz _]; lia].
  destruct Hlive as [_ [Hweak _]].
  destruct Hweak as [_ Hctx].
  destruct K as [A_inst | A_proc]; cbn in Hctx;
    [exact (msw_db_wf Hctx) | exact (msa_db_wf Hctx)].
Qed.

(* ===== 2.  Kept plus pending scan words permute the expected watchers. ===== *)
Lemma focus_scan_carrier_words_expected__propagate_dbu :
  forall (db : dbmap) (p : Z) (P : literal -> Prop) (kept rest : list Z),
    minisat_focus_scan_carrier db p P kept rest ->
    Permutation (kept ++ rest) (expected_watchers db p).
Proof.
  intros db p P kept rest Hscan.
  unfold minisat_focus_scan_carrier in Hscan.
  destruct Hscan as [scanned [pending [Hcover [Hkept [Hpending Hsafe]]]]].
  pose proof (Permutation_map snd Hcover) as Hcoverwords.
  change (Permutation
    (minisat_focus_words (scanned ++ pending))
    (minisat_focus_words (minisat_focus_contributions db p)))
    in Hcoverwords.
  unfold minisat_focus_words at 1 in Hcoverwords.
  rewrite map_app in Hcoverwords.
  change (Permutation
    (minisat_focus_words scanned ++ minisat_focus_words pending)
    (minisat_focus_words (minisat_focus_contributions db p)))
    in Hcoverwords.
  rewrite Hkept, Hpending in Hcoverwords.
  rewrite minisat_focus_words_expected in Hcoverwords.
  exact Hcoverwords.
Qed.

(* ===== 3.  Watcher-map exactness survives an update of the focused slot. ===== *)
Lemma propagation_scan_slot_wmap_exact_update__propagate_dbu :
  forall (n : Z) (M : msolver) (newdb : dbmap) (p : Z)
    (pre post : list (list Z)) (words newwords : list Z)
    (capspre : list Z) (cap : Z) (capspost : list Z),
    propagation_scan_slot M p pre words post capspre cap capspost ->
    wmap_exact n (msolver_db M) (ms_wm M) ->
    0 <= p < 2 * n ->
    (forall l,
      Permutation (expected_watchers (msolver_db M) l)
        (expected_watchers newdb l)) ->
    Permutation newwords (expected_watchers newdb p) ->
    Zlength (pre ++ newwords :: post) = Zlength (ms_wm M) /\
    capspre ++ cap :: capspost = ms_wcaps M /\
    wmap_exact n newdb (pre ++ newwords :: post).
Proof.
  intros n M newdb p pre post words newwords capspre cap capspost
    Hslot Hwmoldexact Hp Hexpected Hsourcenew.
  destruct Hslot as [Hwmold [Hwcapsold [Hprelen Hcapsprelen]]].
  assert (Hwm_after_len :
    Zlength (pre ++ newwords :: post) = Zlength (ms_wm M)).
  {
    rewrite Hwmold.
    rewrite !Zlength_app. rewrite !Zlength_cons. lia.
  }
  split; [exact Hwm_after_len |].
  split; [symmetry; exact Hwcapsold |].
  assert (Hwmreplace :
    pre ++ newwords :: post = replace_Znth p newwords (ms_wm M)).
  {
    rewrite Hwmold.
    rewrite replace_Znth_app_r by (rewrite Hprelen; lia).
    rewrite replace_Znth_nothing by (rewrite Hprelen; lia).
    rewrite Hprelen. replace (p - p) with 0 by lia. cbn. reflexivity.
  }
  split.
  - rewrite Hwm_after_len. exact (proj1 Hwmoldexact).
  - intros l Hl. destruct (Z.eq_dec l p) as [Heq | Hne].
    + subst l. rewrite Hwmreplace.
      rewrite Znth_replace_Znth_Same
        by (rewrite (proj1 Hwmoldexact); exact Hl).
      exact Hsourcenew.
    + rewrite Hwmreplace.
      rewrite Znth_replace_Znth_Diff.
      2: { rewrite (proj1 Hwmoldexact); exact Hp. }
      2: { rewrite (proj1 Hwmoldexact); exact Hl. }
      2: { congruence. }
      eapply Permutation_trans.
      * exact (proj2 Hwmoldexact l Hl).
      * apply Hexpected.
Qed.

(* ===== 4.  Ghost transport of the scan facts across a capacity abort. ===== *)
Lemma propagation_capacity_abort_ghost_transport__propagate_dbu :
  forall (n : Z) (F : cnf) (A_arr : list literal)
    (K : solver_propagation_context) (M : msolver)
    (p current : Z) (kept suffix contents : list Z)
    (watch0 false_lit lits stop k offset candidate sig : Z)
    (prob_after learnt_after : dbmap),
    solver_propagation_weak n F A_arr K M ->
    db_wf n (msolver_db M) ->
    processed (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) p ->
    propagation_scan_candidate_layout current lits stop k offset false_lit
      p candidate sig contents ->
    watch0 + false_lit = Znth 0 contents 0 + Znth 1 contents 0 ->
    minisat_focus_scan_carrier (msolver_db M) p
      (minisat_processed n (mt_assigns (ms_core M)) (mt_trail (ms_core M))
         (mt_qhead (ms_core M)))
      kept (current :: suffix) ->
    minisat_watch_frontier_except n (msolver_db M)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p) ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current contents
      (propagation_normalized_clause watch0 false_lit contents)
      prob_after learnt_after ->
    (forall l,
      Permutation (expected_watchers (msolver_db M) l)
        (expected_watchers (prob_after ++ learnt_after) l)) /\
    minisat_watch_frontier_except n (prob_after ++ learnt_after)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p) /\
    solver_propagation_weak n F A_arr K
      (msolver_propagation_db_wmap_update M prob_after learnt_after
        (ms_wm M) (ms_wcaps M)).
Proof.
  intros n F A_arr K M p current kept suffix contents watch0 false_lit
    lits stop k offset candidate sig prob_after learnt_after
    Hweak Hdbwf Hprocessed Hlayout Hsum Hscan Hfrontier Hupdate.
  destruct (propagation_norm_clause_watcher_xport__propagate_dbu
      n M _ p current suffix kept contents watch0 false_lit lits stop k
      offset candidate sig prob_after learnt_after
      Hdbwf Hlayout Hsum Hscan Hupdate Hfrontier)
    as [co [a0 [a1 [tail [Hcontents [Hin [Hcolits [Htail
       [Hcases [Hperm [Hexpected Hfrontiernew]]]]]]]]]]].
  subst contents.
  split; [exact Hexpected |].
  split; [exact Hfrontiernew |].
  eapply propagation_normalized_clause_weak_transport__propagate_dbu
    with (p := p) (current := current) (co := co)
         (a0 := a0) (a1 := a1) (tail := tail);
    try eassumption.
  destruct Hlayout as [_ [_ [Hfalse _]]]. exact Hfalse.
Qed.

(* ===== 5.  The propagation invariant holds at the capacity-abort state. ===== *)
Lemma propagation_capacity_abort_inv__propagate_dbu :
  forall (n : Z) (F : cnf) (A_arr : list literal)
    (K : solver_propagation_context) (M : msolver)
    (prob learnt : dbmap) (wm : wmap) (wcaps : list Z)
    (simp prop p : Z),
    solver_propagation_weak n F A_arr K
      (msolver_propagation_db_wmap_update M prob learnt wm wcaps) ->
    solver_shape M ->
    ms_capacity_root_propagation_pending M = 0 ->
    mtrail_wf n (ms_core M) ->
    heap_covers n (msolver_heap M) (mt_assigns (ms_core M))
      (mt_trail (ms_core M)) (mt_qhead (ms_core M)) ->
    level_of (msolver_view n M) (lit_var_c p) =
      Some (Zlength (mt_lim (ms_core M))) ->
    propagation_heap_rollback_ready M p ->
    current_reasonless_earliest n M ->
    minisat_watch_frontier_except n (prob ++ learnt)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p) ->
    Zlength wm = Zlength (ms_wm M) ->
    Zlength wcaps = Zlength (ms_wcaps M) ->
    solver_shape (msolver_propagation_abort M prob learnt wm wcaps simp prop) /\
    solver_propagation_inv n F A_arr K
      (msolver_propagation_abort M prob learnt wm wcaps simp prop) /\
    mt_qhead (ms_core (msolver_propagation_abort M prob learnt wm wcaps simp prop))
      < ms_qtail (msolver_propagation_abort M prob learnt wm wcaps simp prop).
Proof.
  intros n F A_arr K M prob learnt wm wcaps simp prop p
    Hweakwm Hshape Hroot Htrailwf Hheapcovers Hlevel Hrollback
    Hreasonless Hfrontiernew Hwmlen Hcapslen.
  assert (Hqtail_eq : ms_qtail M = Zlength (mt_trail (ms_core M))).
  {
    pose proof Hshape as Hsh. unfold solver_shape in Hsh.
    destruct Hsh as
      [_ [_ [_ [_ [_ [_ [_ [_ [_ [Hqt _]]]]]]]]]].
    symmetry. exact Hqt.
  }
  assert (Hqpos : 0 < mt_qhead (ms_core M)).
  { exact (proj1 Hrollback). }
  pose proof (propagation_abort_core_heap_ready
    n M p prob learnt wm wcaps simp prop
    Htrailwf Hqtail_eq Hheapcovers Hlevel Hrollback) as Hcoreafter.
  cbv zeta in Hcoreafter.
  destruct Hcoreafter as [Htrailafter [Hpropafter Hheapafter]].
  set (M_after := msolver_propagation_abort M prob learnt wm wcaps simp prop).
  assert (Hshapeafter : solver_shape M_after).
  {
    unfold M_after.
    eapply solver_shape_propagation_abort__propagate_dbu.
    - exact Hshape.
    - exact Hroot.
    - exact Hwmlen.
    - exact Hcapslen.
    - exact Hqpos.
  }
  assert (Hweakafter : solver_propagation_weak n F A_arr K M_after).
  {
    unfold M_after.
    eapply solver_propagation_weak_abort__propagate_dbu.
    - exact Hweakwm.
    - exact Htrailafter.
    - exact Hshapeafter.
  }
  assert (Hfrontierafter : minisat_watch_frontier n
    (msolver_db M_after) (mt_assigns (ms_core M_after))
    (mt_trail (ms_core M_after)) (mt_qhead (ms_core M_after))).
  {
    unfold M_after, msolver_propagation_abort, msolver_propagation_update, msolver_db.
    cbn [ms_prob ms_learnt ms_core mt_set_qhead mt_assigns mt_trail mt_qhead].
    eapply minisat_watch_frontier_rollback_current
      with (t := ms_core M)
        (q := mt_qhead (ms_core M) - 1) (p := p).
    - exact Htrailwf.
    - pose proof (mtw_qhead_range Htrailwf). lia.
    - exact (proj1 (proj2 Hrollback)).
    - replace (mt_qhead (ms_core M) - 1 + 1)
        with (mt_qhead (ms_core M)) by lia.
      exact Hfrontiernew.
  }
  assert (Hreasonafter : current_reasonless_earliest n M_after).
  { exact Hreasonless. }
  assert (Hqpending : mt_qhead (ms_core M_after) < ms_qtail M_after).
  {
    unfold M_after, msolver_propagation_abort, msolver_propagation_update.
    cbn [ms_core ms_qtail mt_set_qhead mt_qhead].
    pose proof (mtw_qhead_range Htrailwf). lia.
  }
  assert (Hinvafter : solver_propagation_inv n F A_arr K M_after).
  {
    pose proof Hweakafter as Hweakafter0.
    unfold solver_propagation_weak in Hweakafter0.
    destruct Hweakafter0 as [Hrootafter Hctxafter].
    unfold solver_propagation_inv. split; [exact Hrootafter |].
    destruct K as [A_inst | A_proc]; cbn in Hctxafter |- *.
    - constructor.
      + exact Hctxafter.
      + exact Hpropafter.
      + exact Hfrontierafter.
      + exact Hheapafter.
      + exact Hreasonafter.
    - constructor.
      + exact Hctxafter.
      + exact Hpropafter.
      + exact Hfrontierafter.
      + exact Hheapafter.
      + exact Hreasonafter.
  }
  split; [exact Hshapeafter |].
  split; [exact Hinvafter |].
  exact Hqpending.
Qed.

(* ===== 6.  Building the capacity-abort state from the scan slot layout. ===== *)
Lemma propagation_capacity_abort_state_intro__propagate_dbu :
  forall (n : Z) (F : cnf) (A_arr : list literal)
    (K : solver_propagation_context) (M : msolver)
    (prob learnt : dbmap)
    (pre post : list (list Z)) (words : list Z)
    (capspre capspost : list Z) (cap : Z)
    (simp prop hole target : Z),
    solver_propagation_inv n F A_arr K
      (msolver_propagation_abort M prob learnt
         (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop) ->
    solver_shape
      (msolver_propagation_abort M prob learnt
         (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop) ->
    mt_qhead (ms_core (msolver_propagation_abort M prob learnt
         (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop))
      < ms_qtail (msolver_propagation_abort M prob learnt
         (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop) ->
    msolver_seed_shadow M ->
    Zlength pre = hole ->
    Zlength capspre = hole ->
    Zlength pre + 1 + Zlength post = 2 * ms_size M ->
    Zlength capspre + 1 + Zlength capspost = 2 * ms_size M ->
    0 <= hole ->
    0 <= target < 2 * ms_size M ->
    target <> hole ->
    vector_capacity_exhausted
      (Zlength (wlists_split_target_words hole target pre post))
      (wlists_split_target_cap hole target capspre capspost) ->
    propagation_capacity_abort_state n F A_arr K M prob learnt
      (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop
      (msolver_propagation_abort M prob learnt
         (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop).
Proof.
  intros n F A_arr K M prob learnt pre post words capspre capspost cap
    simp prop hole target
    Hinvafter Hshapeafter Hqpending Hseed Hprelen Hcapsprelen
    Hwmtotal Hcapstotal Hholenonneg Htargetrange Htargetdistinct Hexh.
  assert (Htargetwords :
    Znth target (pre ++ words :: post) nil =
    wlists_split_target_words hole target pre post).
  {
    unfold wlists_split_target_words.
    destruct (Z.ltb target hole) eqn:Hside.
    - apply Z.ltb_lt in Hside.
      rewrite app_Znth1 by (rewrite Hprelen; lia). reflexivity.
    - apply Z.ltb_ge in Hside.
      rewrite app_Znth2 by (rewrite Hprelen; lia).
      rewrite Hprelen. rewrite Znth_cons by lia.
      reflexivity.
  }
  assert (Htargetcapword :
    Znth target (capspre ++ cap :: capspost) 0 =
    wlists_split_target_cap hole target capspre capspost).
  {
    unfold wlists_split_target_cap.
    destruct (Z.ltb target hole) eqn:Hside.
    - apply Z.ltb_lt in Hside.
      rewrite app_Znth1 by (rewrite Hcapsprelen; lia).
      apply Znth_indep. rewrite Hcapsprelen. lia.
    - apply Z.ltb_ge in Hside.
      rewrite app_Znth2 by (rewrite Hcapsprelen; lia).
      rewrite Hcapsprelen. rewrite Znth_cons by lia.
      apply Znth_indep. lia.
  }
  assert (Htargetrangeafter :
    0 <= target < Zlength (ms_wm (msolver_propagation_abort M prob learnt
      (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop))).
  {
    cbn [msolver_propagation_abort msolver_propagation_update ms_wm].
    rewrite Zlength_app, Zlength_cons. lia.
  }
  assert (Htargetcapafter : vector_capacity_exhausted
    (Zlength (Znth target (ms_wm (msolver_propagation_abort M prob learnt
       (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop)) nil))
    (Znth target (ms_wcaps (msolver_propagation_abort M prob learnt
       (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop)) 0)).
  {
    cbn [msolver_propagation_abort msolver_propagation_update ms_wm ms_wcaps].
    rewrite Htargetwords, Htargetcapword. exact Hexh.
  }
  assert (Hwatchcapacity : solver_watch_capacity_exhausted
    (msolver_propagation_abort M prob learnt
       (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop)).
  {
    exists target. split.
    - exact Htargetrangeafter.
    - exact Htargetcapafter.
  }
  assert (Hcapacity : solver_capacity_exhausted
    (msolver_propagation_abort M prob learnt
       (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop)).
  {
    eapply solver_capacity_exhausted_watch.
    - exact Htargetrangeafter.
    - exact Htargetcapafter.
  }
  assert (Hseedafter : msolver_seed_shadow
    (msolver_propagation_abort M prob learnt
       (pre ++ words :: post) (capspre ++ cap :: capspost) simp prop)).
  { exact Hseed. }
  unfold propagation_capacity_abort_state.
  split; [reflexivity |].
  split.
  {
    eapply propagation_capacity_abort_certified_intro.
    - eapply propagation_capacity_abort_transition_intro.
      + reflexivity.
      + exact Hinvafter.
    - exact Hcapacity.
  }
  split; [exact Hinvafter |].
  split; [exact Hseedafter |].
  split; [exact Hcapacity |].
  split; [exact Hwatchcapacity |].
  split; [exact Hqpending |].
  split; [exact Hshapeafter |].
  split; reflexivity.
Qed.

(* ===== 7.  The pure core of the capacity-abort obligation. ===== *)
Lemma propagation_capacity_abort_pure_core__propagate_dbu :
  forall (n : Z) (F : cnf) (A_arr : list literal)
    (K : solver_propagation_context) (M0 Mentry Mscan : msolver)
    (p confl : Z)
    (source_words retained moved rest garbage watch_memory : list Z)
    (ii jj scan_current : Z) (raw_suffix raw_prefix : list Z)
    (copy_src copy_dst : Z) (copy_memory : list Z)
    (scan_wm_pre scan_wm_post : list (list Z)) (logical_words : list Z)
    (scan_caps_pre scan_caps_post : list Z) (scan_wcap : Z)
    (wl destination candidate : Z)
    (lits stop k offset false_lit sig : Z) (clause_contents : list Z)
    (watch0 begin i j endvar simp_count prop_count : Z)
    (prob_after learnt_after : dbmap),
    propagation_scan_open n F A_arr K M0 Mentry Mscan p confl
      source_words retained moved rest garbage watch_memory ii jj
      scan_current raw_suffix ->
    binary_watch_copy_progress watch_memory raw_prefix scan_current raw_suffix
      ii jj copy_src copy_dst copy_memory ->
    endvar = begin + Zlength source_words * sizeof(PTR) ->
    i >= endvar ->
    i = begin + copy_src * sizeof(PTR) ->
    j = begin + copy_dst * sizeof(PTR) ->
    copy_src <= Zlength source_words ->
    propagation_scan_slot Mscan p scan_wm_pre logical_words scan_wm_post
      scan_caps_pre scan_wcap scan_caps_post ->
    propagation_capacity_target_facts Mscan wl destination candidate
      scan_wm_pre scan_wm_post scan_caps_pre scan_caps_post ->
    propagation_scan_candidate_layout scan_current lits stop k offset false_lit
      p candidate sig clause_contents ->
    watch0 + false_lit = Znth 0 clause_contents 0 + Znth 1 clause_contents 0 ->
    db_pair_lits_update (ms_prob Mscan) (ms_learnt Mscan) scan_current
      clause_contents
      (propagation_normalized_clause watch0 false_lit clause_contents)
      prob_after learnt_after ->
    propagation_capacity_abort_state n F A_arr K Mscan prob_after learnt_after
      (scan_wm_pre ++
         sublist 0 ((j - begin) ÷ sizeof(PTR)) copy_memory :: scan_wm_post)
      (scan_caps_pre ++ scan_wcap :: scan_caps_post)
      simp_count prop_count
      (msolver_propagation_abort Mscan prob_after learnt_after
         (scan_wm_pre ++
            sublist 0 ((j - begin) ÷ sizeof(PTR)) copy_memory :: scan_wm_post)
         (scan_caps_pre ++ scan_wcap :: scan_caps_post)
         simp_count prop_count) /\
    confl = 0 /\
    Zlength scan_wm_pre = p /\
    destination = vecp_slot wl (lit_neg_c candidate) /\
    map fst prob_after = map fst (ms_prob Mscan) /\
    map fst learnt_after = map fst (ms_learnt Mscan) /\
    Zlength (ms_stats Mscan) = 11.
Proof.
  intros n F A_arr K M0 Mentry Mscan p confl
    source_words retained moved rest garbage watch_memory ii jj
    scan_current raw_suffix raw_prefix copy_src copy_dst copy_memory
    scan_wm_pre scan_wm_post logical_words scan_caps_pre scan_caps_post
    scan_wcap wl destination candidate lits stop k offset false_lit sig
    clause_contents watch0 begin i j endvar simp_count prop_count
    prob_after learnt_after
    Hopen Hcopyprog Hend Hige Hi Hj Hsrcbound Hslot Htargetfacts
    Hlayout Hsum Hupdate.
  pose proof Hopen as Hopen0.
  destruct Hopen0 as
    [Hshape [Hseed [Hcaller [Hscanfrontier [Hsem
    [Hphysical [Hrest0 Hconfl]]]]]]].
  destruct Hsem as [Hlive | Hdead];
    [| destruct Hdead as [Hnz _]; lia].
  destruct Hlive as
    [_ [Hweak [_ [_ [Hheapcovers [Hreasonless
    [Hlevel [Hp [Hprocessed [Hfrontier Hscan]]]]]]]]]].
  pose proof Hweak as Hweak_fields.
  unfold solver_propagation_weak in Hweak_fields.
  destruct Hweak_fields as [Hroot Hweakctx].
  assert (Hdbwf : db_wf n (msolver_db Mscan)).
  {
    destruct K as [A_inst | A_proc]; cbn in Hweakctx;
      [exact (msw_db_wf Hweakctx) | exact (msa_db_wf Hweakctx)].
  }
  assert (Htrailwf : mtrail_wf n (ms_core Mscan)).
  {
    destruct K as [A_inst | A_proc]; cbn in Hweakctx;
      [exact (msw_trail_wf Hweakctx) | exact (msa_trail_wf Hweakctx)].
  }
  assert (Hwmoldexact : wmap_exact n (msolver_db Mscan) (ms_wm Mscan)).
  {
    destruct K as [A_inst | A_proc]; cbn in Hweakctx;
      [exact (msw_wmap_exact Hweakctx) | exact (msa_wmap_exact Hweakctx)].
  }
  unfold propagation_scan_frontier in Hscanfrontier.
  destruct Hscanfrontier as [_ [_ [_ [_ Hrollback]]]].
  pose proof Hslot as Hslot0.
  destruct Hslot0 as [Hwmold [Hwcapsold [Hprelen Hcapsprelen]]].
  pose proof Htargetfacts as Htf.
  destruct Htf as [Hdestination [Hdestindex Htargetcap]].
  destruct Hdestindex as [Hholenonneg [Htargetrange Htargetdistinct]].
  pose proof Hshape as Hsh.
  unfold solver_shape in Hsh.
  destruct Hsh as
    [_ [_ [_ [_ [_ [_ [_ [_ [_ [_ [_ [_ [_ [_ [_
    [Hwmtotal0 [Hwcapstotal0 [_ [Hstatslen _]]]]]]]]]]]]]]]]]]].
  assert (Hwmtotal :
    Zlength scan_wm_pre + 1 + Zlength scan_wm_post = 2 * ms_size Mscan).
  {
    rewrite Hwmold in Hwmtotal0.
    rewrite Zlength_app, Zlength_cons in Hwmtotal0. lia.
  }
  assert (Hcapstotal :
    Zlength scan_caps_pre + 1 + Zlength scan_caps_post = 2 * ms_size Mscan).
  {
    rewrite Hwcapsold in Hwcapstotal0.
    rewrite Zlength_app, Zlength_cons in Hwcapstotal0. lia.
  }
  destruct (propagation_copy_completion__propagate_dbu
      source_words retained moved rest garbage watch_memory raw_prefix
      scan_current raw_suffix copy_memory ii jj copy_src copy_dst
      endvar begin i j
      Hphysical Hcopyprog Hend Hige Hi Hj Hsrcbound)
    as [copied [Hrestcopy [Hdiv Hcopyfront]]].
  rewrite Hdiv, Hcopyfront.
  pose proof (focus_scan_carrier_words_expected__propagate_dbu
    _ _ _ _ _ Hscan) as Hsourceold.
  rewrite Hrest0 in Hscan.
  destruct (propagation_capacity_abort_ghost_transport__propagate_dbu
      n F A_arr K Mscan p scan_current retained raw_suffix clause_contents
      watch0 false_lit lits stop k offset candidate sig
      prob_after learnt_after
      Hweak Hdbwf Hprocessed Hlayout Hsum Hscan Hfrontier Hupdate)
    as [Hexpected [Hfrontiernew Hweakdb]].
  assert (Hsourcenew : Permutation (retained ++ rest)
    (expected_watchers (prob_after ++ learnt_after) p)).
  { eapply Permutation_trans; [exact Hsourceold | apply Hexpected]. }
  destruct (propagation_scan_slot_wmap_exact_update__propagate_dbu
      n Mscan (prob_after ++ learnt_after) p scan_wm_pre scan_wm_post
      logical_words (retained ++ rest) scan_caps_pre scan_wcap scan_caps_post
      Hslot Hwmoldexact Hp Hexpected Hsourcenew)
    as [Hwmlen [Hcapseq Hwmexactnew]].
  assert (Hcapslen :
    Zlength (scan_caps_pre ++ scan_wcap :: scan_caps_post) =
    Zlength (ms_wcaps Mscan)).
  { rewrite Hcapseq. reflexivity. }
  assert (Hweakwm : solver_propagation_weak n F A_arr K
    (msolver_propagation_db_wmap_update Mscan prob_after learnt_after
      (scan_wm_pre ++ (retained ++ rest) :: scan_wm_post)
      (scan_caps_pre ++ scan_wcap :: scan_caps_post))).
  {
    eapply solver_propagation_weak_rewatch__propagate_dbu.
    - exact Hweakdb.
    - exact Hwmlen.
    - exact Hcapslen.
    - exact Hwmexactnew.
  }
  destruct (propagation_capacity_abort_inv__propagate_dbu
      n F A_arr K Mscan prob_after learnt_after
      (scan_wm_pre ++ (retained ++ rest) :: scan_wm_post)
      (scan_caps_pre ++ scan_wcap :: scan_caps_post)
      simp_count prop_count p
      Hweakwm Hshape Hroot Htrailwf Hheapcovers Hlevel Hrollback
      Hreasonless Hfrontiernew Hwmlen Hcapslen)
    as [Hshapeafter [Hinvafter Hqpending]].
  rewrite Hprelen in Htargetcap.
  split.
  {
    eapply propagation_capacity_abort_state_intro__propagate_dbu
      with (hole := p).
    - exact Hinvafter.
    - exact Hshapeafter.
    - exact Hqpending.
    - exact Hseed.
    - exact Hprelen.
    - exact Hcapsprelen.
    - exact Hwmtotal.
    - exact Hcapstotal.
    - lia.
    - exact Htargetrange.
    - lia.
    - exact Htargetcap.
  }
  split; [exact Hconfl |].
  split; [exact Hprelen |].
  split; [exact Hdestination |].
  destruct (db_pair_lits_update_words__propagate
    _ _ _ _ _ _ _ Hupdate) as [Hpk Hlk].
  split; [exact Hpk |].
  split; [exact Hlk |].
  exact Hstatslen.
Qed.

(** ===== group: solver_propagate_db_update_unit_arm ===== *)
(** The UNIT arm.  The scan found a clause whose last unwatched literal is
    unassigned, so the entry's literal list is normalised in place and that
    literal is enqueued.  The five lemmas below do the first half: rebuild the
    clause database around the rewritten entry and carry watcher-map
    exactness, the weak bundle and the focus carrier across the rewrite,
    before anything is enqueued. *)
Lemma propagation_unit_normalized_clause_db_rebuild__propagate_dbu :
  forall (n : Z) (prob learnt : dbmap)
    (scan_current clause_lits watch0 false_lit : Z)
    (clause_contents : list Z),
    db_wf n (prob ++ learnt) ->
    2 <= Zlength clause_contents ->
    clause_lits_pointer scan_current clause_lits ->
    (clause_db_pair_frame
       prob learnt scan_current clause_contents **
     (clause_lits + 0 * sizeof(INT)) # Int |-> watch0 **
     (clause_lits + 1 * sizeof(INT)) # Int |-> false_lit **
     IntArray.seg clause_lits 2 (Zlength clause_contents)
       (sublist 2 (Zlength clause_contents) clause_contents))
    |-- EX prob_after learnt_after : dbmap,
      “ db_pair_lits_update prob learnt scan_current clause_contents
          (propagation_normalized_clause watch0 false_lit clause_contents)
          prob_after learnt_after ” &&
      (clause_db_rep prob_after ** clause_db_rep learnt_after).
Proof.
  intros n prob learnt scan_current clause_lits watch0 false_lit
    clause_contents Hdbwf Hlen Hlits.
  unfold clause_lits_pointer in Hlits. subst clause_lits.
  assert (Hnewlen :
    Zlength (propagation_normalized_clause watch0 false_lit clause_contents) =
      Zlength clause_contents).
  { apply propagation_normalized_clause_length. exact Hlen. }
  unfold clause_db_pair_frame. Intros is_learnt.
  sep_apply_l_atomic
    (IntArray.seg_single (clause_lits_addr scan_current) 0 watch0).
  sep_apply_l_atomic
    (IntArray.seg_single (clause_lits_addr scan_current) 1 false_lit).
  sepcon_lift
    (IntArray.seg (clause_lits_addr scan_current) 0 (0 + 1)
      (watch0 :: nil)).
  replace (0 + 1) with 1 by lia.
  replace (1 + 1) with 2 by lia.
  sep_apply_l_atomic
    (IntArray.seg_merge_to_seg (clause_lits_addr scan_current)
      0 1 2 (watch0 :: nil) (false_lit :: nil)).
  - dump_pre_spatial. lia.
  - cbn [app].
    sep_apply_l_atomic
      (IntArray.seg_merge_to_seg (clause_lits_addr scan_current)
        0 2 (Zlength clause_contents) (watch0 :: false_lit :: nil)
        (sublist 2 (Zlength clause_contents) clause_contents)).
    + dump_pre_spatial. lia.
    + cbn [app].
      fold (propagation_normalized_clause
        watch0 false_lit clause_contents).
      unfold clause_db_pair_remainder. Split.
      * Intros co pre post. coq_prop_lift.
        destruct H as [Hprob [Hco_lits Hco_learnt]].
        assert (Hin : In (scan_current, co) (prob ++ learnt)).
        { rewrite Hprob, !in_app_iff. cbn. tauto. }
        assert (Hpos : 0 < scan_current).
        { eapply db_wf_ptr_pos; [exact Hdbwf | exact Hin]. }
        assert (Hmod : scan_current mod 2 = 0).
        { apply clause_ptr_mod2.
          eapply db_wf_even; [exact Hdbwf | exact Hin]. }
        set (new_lits := propagation_normalized_clause
          watch0 false_lit clause_contents).
        set (co_new := clause_obj_with_lits co new_lits).
        set (prob_after := pre ++ (scan_current, co_new) :: post).
        Exists prob_after learnt.
        split_pure_spatial.
        -- unfold prob_after.
           assert (Hdbapp :
             clause_db_rep (pre ++ (scan_current, co_new) :: post) --||--
             clause_db_rep pre **
               clause_db_rep ((scan_current, co_new) :: post)).
           { split; [apply clause_db_rep_app_elim |
                     apply clause_db_rep_app_intro]. }
           rewrite Hdbapp, clause_db_rep_cons.
           unfold MiniSatClause.rep, co_new, clause_obj_with_lits,
             new_lits.
           cbn [fst snd co_lits co_learnt].
           rewrite Hco_learnt, Hnewlen. entailer_with lia.
        -- apply derivable1s_coq_prop_r. left. exists co, pre, post.
           split; [exact Hprob |]. split; [exact Hco_lits |].
           split; reflexivity.
      * Intros co pre post. coq_prop_lift.
        destruct H as [Hlearnt [Hco_lits Hco_learnt]].
        assert (Hin : In (scan_current, co) (prob ++ learnt)).
        { rewrite Hlearnt, !in_app_iff. cbn. tauto. }
        assert (Hpos : 0 < scan_current).
        { eapply db_wf_ptr_pos; [exact Hdbwf | exact Hin]. }
        assert (Hmod : scan_current mod 2 = 0).
        { apply clause_ptr_mod2.
          eapply db_wf_even; [exact Hdbwf | exact Hin]. }
        set (new_lits := propagation_normalized_clause
          watch0 false_lit clause_contents).
        set (co_new := clause_obj_with_lits co new_lits).
        set (learnt_after := pre ++ (scan_current, co_new) :: post).
        Exists prob learnt_after.
        split_pure_spatial.
        -- unfold learnt_after.
           assert (Hdbapp :
             clause_db_rep (pre ++ (scan_current, co_new) :: post) --||--
             clause_db_rep pre **
               clause_db_rep ((scan_current, co_new) :: post)).
           { split; [apply clause_db_rep_app_elim |
                     apply clause_db_rep_app_intro]. }
           rewrite Hdbapp, clause_db_rep_cons.
           unfold MiniSatClause.rep, co_new, clause_obj_with_lits,
             new_lits.
           cbn [fst snd co_lits co_learnt].
           rewrite Hco_learnt, Hnewlen. entailer_with lia.
        -- apply derivable1s_coq_prop_r. right. exists co, pre, post.
           split; [exact Hlearnt |]. split; [exact Hco_lits |].
           split; reflexivity.
Qed.

Lemma propagation_unit_normalized_watcher_transport__propagate_dbu :
  forall (n : Z) (M : msolver) (P : literal -> Prop)
    (p current : Z) (suffix kept contents : list Z)
    (watch0 false_lit clause_lits : Z)
    (prob_after learnt_after : dbmap),
    db_wf n (msolver_db M) ->
    clause_lits_pointer current clause_lits ->
    false_lit = lit_neg_c p ->
    watch0 + false_lit = Znth 0 contents 0 + Znth 1 contents 0 ->
    minisat_focus_scan_carrier
      (msolver_db M) p P kept (current :: suffix) ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current contents
      (propagation_normalized_clause watch0 false_lit contents)
      prob_after learnt_after ->
    minisat_watch_frontier_except n (msolver_db M)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p) ->
    exists (co : clause_obj) (a0 a1 : Z) (tail : list Z),
      contents = a0 :: a1 :: tail /\
      3 <= Zlength contents /\
      In (current, co) (msolver_db M) /\
      co_lits co = a0 :: a1 :: tail /\
      sublist 2 (Zlength (a0 :: a1 :: tail)) (a0 :: a1 :: tail) = tail /\
      ((a0 = false_lit /\ watch0 = a1) \/
       (a1 = false_lit /\ watch0 = a0)) /\
      Permutation
        (propagation_normalized_clause watch0 false_lit (a0 :: a1 :: tail))
        (a0 :: a1 :: tail) /\
      (forall l,
        Permutation (expected_watchers (msolver_db M) l)
          (expected_watchers (prob_after ++ learnt_after) l)) /\
      minisat_watch_frontier_except n (prob_after ++ learnt_after)
        (mt_assigns (ms_core M)) (mt_trail (ms_core M))
        (mt_qhead (ms_core M)) (lit_denote p).
Proof.
  intros n M P p current suffix kept contents watch0 false_lit clause_lits
    prob_after learnt_after Hdbwf Hlits Hfalse Hwatchsum
    Hscan Hupdate Hfrontier.
  assert (Hselected : exists co,
    In (current, co) (msolver_db M) /\ co_lits co = contents).
  {
    pose proof Hupdate as Hu.
    destruct Hu as
      [[co [pre [post [Hprob [Hco_lits [Hprob' Hlearnt']]]]]]
      |[co [pre [post [Hlearnt [Hco_lits [Hprob' Hlearnt']]]]]]].
    - exists co. split; [|exact Hco_lits]. unfold msolver_db.
      apply in_or_app. left. rewrite Hprob.
      apply in_or_app. right. cbn. auto.
    - exists co. split; [|exact Hco_lits]. unfold msolver_db.
      apply in_or_app. right. rewrite Hlearnt.
      apply in_or_app. right. cbn. auto.
  }
  destruct Hselected as [co [Hin Hco_lits]].
  assert (Hcurrentreal : is_tag current = false).
  { apply even_not_tag. eapply db_wf_even; eassumption. }
  assert (Hlong : 3 <= Zlength contents).
  {
    pose proof Hscan as Hscan0.
    unfold minisat_focus_scan_carrier in Hscan0.
    destruct Hscan0 as
      [scanned [pending [Hcover [Hkept [Hpending Hsafe]]]]].
    destruct pending as [|[o w] pending]; cbn in Hpending;
      [discriminate|].
    inversion Hpending; subst w.
    assert (Hinold :
      In (o, current) (minisat_focus_contributions (msolver_db M) p)).
    { eapply Permutation_in; [exact Hcover|].
      apply in_or_app. right. cbn. auto. }
    destruct (minisat_focus_real_word_owner__propagate_dbu
      n (msolver_db M) p o current Hdbwf Hinold Hcurrentreal)
      as [co_owner [Hin_owner Ho]].
    unfold minisat_focus_contributions in Hinold.
    apply in_flat_map in Hinold as [[q co_source] [Hin_source Hentry]].
    unfold minisat_entry_focus_contributions in Hentry.
    apply in_map_iff in Hentry as [w0 [Hpair Hword]].
    injection Hpair as Hocc Hw0. subst w0.
    assert (Hsource_long : 3 <= Zlength (co_lits co_source)).
    {
      unfold entry_watchers in Hword. cbn in Hword.
      apply in_app_or in Hword.
      destruct ((3 <=? Zlength (co_lits co_source))%Z) eqn:Hbig.
      - apply Z.leb_le. exact Hbig.
      - exfalso. destruct Hword as [Hword | Hword].
        + destruct ((lit_neg_c (co_watch0 co_source) =? p)%Z) eqn:Hwatch0;
            cbn in Hword.
          * destruct Hword as [Heq | []]. subst current.
            rewrite is_tag_of in Hcurrentreal. discriminate.
          * contradiction.
        + destruct ((lit_neg_c (co_watch1 co_source) =? p)%Z) eqn:Hwatch1;
            cbn in Hword.
          * destruct Hword as [Heq | []]. subst current.
            rewrite is_tag_of in Hcurrentreal. discriminate.
          * contradiction.
    }
    assert (Hq : q = current).
    {
      rewrite Ho in Hocc.
      pose proof (f_equal watch_owner Hocc) as Howner.
      exact Howner.
    }
    subst q.
    assert (Hsource_owner : co_source = co_owner).
    { eapply db_wf_lookup_unique; eassumption. }
    subst co_source.
    assert (Howner_selected : co_owner = co).
    { eapply db_wf_lookup_unique; eassumption. }
    subst co_owner. rewrite <- Hco_lits. exact Hsource_long.
  }
  assert (Hrealwatchp : real_watch_pair p contents).
  { rewrite <- Hco_lits.
    eapply focus_scan_current_real_watch_pair__propagate_dbu
      with (co := co) (P := P) (kept := kept) (rest := suffix).
    - exact Hdbwf.
    - exact Hin.
    - exact Hcurrentreal.
    - rewrite Hco_lits. exact Hlong.
    - exact Hscan. }
  assert (Hlayout : propagation_scan_candidate_layout current clause_lits
    (clause_lits + Zlength contents * sizeof(INT))
    (clause_lits + 2 * sizeof(INT)) 2 false_lit p
    (Znth 0 (sublist 2 (Zlength contents) contents) 0)
    (2 * lit_sign_c
       (Znth 0 (sublist 2 (Zlength contents) contents) 0) - 1)
    contents).
  {
    unfold propagation_scan_candidate_layout.
    split; [exact Hlits|]. split; [exact Hlong|].
    split; [exact Hfalse|]. split; [reflexivity|].
    split; [reflexivity|]. split; [lia|]. split; reflexivity.
  }
  assert (Htransport :
    exists (co' : clause_obj) (a0 a1 : Z) (tail : list Z),
      contents = a0 :: a1 :: tail /\
      In (current, co') (msolver_db M) /\
      co_lits co' = a0 :: a1 :: tail /\
      sublist 2 (Zlength (a0 :: a1 :: tail)) (a0 :: a1 :: tail) = tail /\
      ((a0 = false_lit /\ watch0 = a1) \/
       (a1 = false_lit /\ watch0 = a0)) /\
      Permutation
        (propagation_normalized_clause watch0 false_lit (a0 :: a1 :: tail))
        (a0 :: a1 :: tail) /\
      (forall l,
        Permutation (expected_watchers (msolver_db M) l)
          (expected_watchers (prob_after ++ learnt_after) l)) /\
      minisat_watch_frontier_except n (prob_after ++ learnt_after)
        (mt_assigns (ms_core M)) (mt_trail (ms_core M))
        (mt_qhead (ms_core M)) (lit_denote p)).
  {
    eapply propagation_norm_clause_watcher_xport__propagate_dbu
      with (lits := clause_lits)
        (stop := clause_lits + Zlength contents * sizeof(INT))
        (k := clause_lits + 2 * sizeof(INT)) (offset := 2)
        (candidate := Znth 0 (sublist 2 (Zlength contents) contents) 0)
        (sig := 2 * lit_sign_c
          (Znth 0 (sublist 2 (Zlength contents) contents) 0) - 1);
      eassumption.
  }
  destruct Htransport as
    [co' [a0 [a1 [tail [Hcontents' [Hin' [Hco_lits'
    [Htail' [Hwatchcases' [Hperm' [Hexpected' Hfrontier']]]]]]]]]]].
  exists co', a0, a1, tail.
  split; [exact Hcontents'|].
  split; [exact Hlong|].
  split; [exact Hin'|].
  split; [exact Hco_lits'|].
  split; [exact Htail'|].
  split; [exact Hwatchcases'|].
  split; [exact Hperm'|].
  split; [exact Hexpected'|exact Hfrontier'].
Qed.

Lemma propagation_unit_db_weak_transport__propagate_dbu :
  forall (n : Z) (F : cnf) (A_arr : list literal)
    (K : solver_propagation_context) (M : msolver)
    (p current false_lit watch0 a0 a1 : Z) (tail contents : list Z)
    (co : clause_obj) (prob_after learnt_after : dbmap),
    solver_propagation_weak n F A_arr K M ->
    processed (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) p ->
    false_lit = lit_neg_c p ->
    contents = a0 :: a1 :: tail ->
    In (current, co) (msolver_db M) ->
    co_lits co = a0 :: a1 :: tail ->
    sublist 2 (Zlength (a0 :: a1 :: tail)) (a0 :: a1 :: tail) = tail ->
    ((a0 = false_lit /\ watch0 = a1) \/
     (a1 = false_lit /\ watch0 = a0)) ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current contents
      (propagation_normalized_clause watch0 false_lit contents)
      prob_after learnt_after ->
    Permutation
      (propagation_normalized_clause watch0 false_lit (a0 :: a1 :: tail))
      (a0 :: a1 :: tail) ->
    (forall l,
      Permutation (expected_watchers (msolver_db M) l)
        (expected_watchers (prob_after ++ learnt_after) l)) ->
    solver_propagation_weak n F A_arr K
      (msolver_propagation_db_wmap_update M prob_after learnt_after
        (ms_wm M) (ms_wcaps M)).
Proof.
  intros n F A_arr K M p current false_lit watch0 a0 a1 tail contents
    co prob_after learnt_after Hweak Hprocessed Hfalse Hcontents Hin
    Hco_lits Htail Hwatchcases Hupdate Hperm Hexpected.
  subst contents.
  eapply propagation_normalized_clause_weak_transport__propagate_dbu
    with (p := p) (current := current) (false_lit := false_lit)
      (watch0 := watch0) (a0 := a0) (a1 := a1) (tail := tail)
      (co := co); eassumption.
Qed.

Lemma enqueue_transition_nonzero_cases__propagate_dbu :
  forall (l reason qtail ret qtail' : Z)
    (assigns levels reasons trail lim
     assigns' levels' reasons' trail' : list Z),
    enqueue_transition l reason qtail ret qtail'
      assigns levels reasons trail lim
      assigns' levels' reasons' trail' ->
    ret <> 0 ->
    ret = 1 /\
    ((Znth (lit_var_c l) assigns 0 = lit_sig l /\
      assigns' = assigns /\ levels' = levels /\ reasons' = reasons /\
      trail' = trail /\ qtail' = qtail) \/
     (Znth (lit_var_c l) assigns 0 = 0 /\
      assigns' = replace_Znth (lit_var_c l) (lit_sig l) assigns /\
      levels' = replace_Znth (lit_var_c l) (Zlength lim) levels /\
      reasons' = replace_Znth (lit_var_c l) reason reasons /\
      trail' = trail ++ (l :: nil) /\ qtail' = qtail + 1)).
Proof.
  intros l reason qtail ret qtail' assigns levels reasons trail lim
    assigns' levels' reasons' trail' Htransition Hnonzero.
  unfold enqueue_transition in Htransition.
  destruct Htransition as [Hsame | [Hconflict | Hfresh]].
  - destruct Hsame as
      [Hcell [Hret [Hassigns [Hlevels [Hreasons [Htrail Hqtail]]]]]].
    split; [exact Hret|]. left.
    repeat split; assumption.
  - destruct Hconflict as [_ [_ [Hret _]]]. contradiction.
  - destruct Hfresh as
      [Hcell [Hret [Hassigns [Hlevels [Hreasons [Htrail Hqtail]]]]]].
    split; [exact Hret|]. right.
    repeat split; assumption.
Qed.

Lemma propagation_unit_focus_keep_transport__propagate_dbu :
  forall (n : Z) (M : msolver) (P : literal -> Prop)
    (p current false_lit watch0 a0 a1 : Z)
    (tail contents kept suffix : list Z) (co : clause_obj)
    (prob_after learnt_after : dbmap),
    db_wf n (msolver_db M) ->
    lit_wf_c n p ->
    false_lit = lit_neg_c p ->
    contents = a0 :: a1 :: tail ->
    3 <= Zlength contents ->
    In (current, co) (msolver_db M) ->
    co_lits co = a0 :: a1 :: tail ->
    sublist 2 (Zlength (a0 :: a1 :: tail)) (a0 :: a1 :: tail) = tail ->
    ((a0 = false_lit /\ watch0 = a1) \/
     (a1 = false_lit /\ watch0 = a0)) ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current contents
      (propagation_normalized_clause watch0 false_lit contents)
      prob_after learnt_after ->
    minisat_focus_scan_carrier
      (msolver_db M) p P kept (current :: suffix) ->
    ~ P (literal_neg (lit_denote watch0)) ->
    minisat_focus_scan_carrier (prob_after ++ learnt_after) p P
      (kept ++ (current :: nil)) suffix.
Proof.
  intros n M P p current false_lit watch0 a0 a1 tail contents kept suffix
    co prob_after learnt_after Hdb Hp Hfalse Hcontents Hlong Hselected
    Hco_lits Htail Hwatchcases Hupdate Hscan Hwatchsafe.
  subst contents.
  pose proof (db_wf_obj n (msolver_db M) current co Hdb Hselected) as Hobj.
  unfold obj_wf in Hobj. rewrite Hco_lits in Hobj.
  destruct Hobj as [Hobjlen [Hall Hnodup]].
  cbn [map] in Hnodup.
  apply NoDup_cons_iff in Hnodup as [Ha0not Hnodup].
  apply NoDup_cons_iff in Hnodup as [Ha1not Hnodup].
  assert (Hvarneq : lit_var_c a0 <> lit_var_c a1).
  { intro Heq. apply Ha0not. left. symmetry. exact Heq. }
  assert (Hnewlen : 3 <= Zlength
      (propagation_normalized_clause watch0 false_lit (a0 :: a1 :: tail))).
  {
    rewrite propagation_normalized_clause_length;
      [exact Hlong|lia].
  }
  assert (Hlongb :
    (3 <=? Zlength (a0 :: a1 :: tail))%Z = true).
  { apply Z.leb_le. exact Hlong. }
  assert (Hnewlenb :
    (3 <=? Zlength (propagation_normalized_clause watch0 false_lit
      (a0 :: a1 :: tail)))%Z = true).
  { apply Z.leb_le. exact Hnewlen. }
  unfold propagation_normalized_clause in Hnewlenb.
  rewrite Htail in Hnewlenb.
  set (oold := minisat_occurrence_of_entry (current, co)).
  set (onew := minisat_occurrence_of_entry
    (current, clause_obj_with_lits co
      (propagation_normalized_clause watch0 false_lit
        (a0 :: a1 :: tail)))).
  assert (Hmatch : (lit_neg_c false_lit =? p)%Z = true).
  { apply Z.eqb_eq. rewrite Hfalse.
    apply lit_neg_c_involutive. }
  assert (Hfocus : exists pre post,
      minisat_focus_contributions (msolver_db M) p =
        pre ++ (oold, current) :: post /\
      minisat_focus_contributions (prob_after ++ learnt_after) p =
        pre ++ (onew, current) :: post).
  {
    unfold msolver_db.
    eapply db_pair_lits_update_focus_single__propagate_dbu.
    - exact Hupdate.
    - intros co' Hco_lits'.
      unfold minisat_entry_focus_contributions, entry_watchers.
      destruct Hwatchcases as [[Ha0 Hw] | [Ha1 Hw]].
      + subst a0 watch0.
        assert (Hmiss : (lit_neg_c a1 =? p)%Z = false).
        { apply Z.eqb_neq. intro Heq. apply Hvarneq.
          rewrite Hfalse, <- Heq, !lit_var_c_neg. reflexivity. }
        unfold oold, minisat_occurrence_of_entry, co_watch0, co_watch1,
          denote_obj. rewrite Hco_lits', Hco_lits.
        rewrite !Znth0_cons.
        rewrite !Znth_cons by lia.
        replace (1 - 1) with 0 by lia. rewrite !Znth0_cons.
        rewrite Hmatch, Hmiss.
        rewrite Hlongb. cbn. reflexivity.
      + subst a1 watch0.
        assert (Hmiss : (lit_neg_c a0 =? p)%Z = false).
        { apply Z.eqb_neq. intro Heq. apply Hvarneq.
          rewrite Hfalse, <- Heq, !lit_var_c_neg. reflexivity. }
        unfold oold, minisat_occurrence_of_entry, co_watch0, co_watch1,
          denote_obj. rewrite Hco_lits', Hco_lits.
        rewrite !Znth0_cons.
        rewrite !Znth_cons by lia.
        replace (1 - 1) with 0 by lia. rewrite !Znth0_cons.
        rewrite Hmiss, Hmatch.
        rewrite Hlongb. cbn. reflexivity.
    - intros co' Hco_lits'.
      unfold minisat_entry_focus_contributions, entry_watchers.
      destruct Hwatchcases as [[Ha0 Hw] | [Ha1 Hw]].
      + subst a0 watch0.
        assert (Hmiss : (lit_neg_c a1 =? p)%Z = false).
        { apply Z.eqb_neq. intro Heq. apply Hvarneq.
          rewrite Hfalse, <- Heq, !lit_var_c_neg. reflexivity. }
        unfold onew, minisat_occurrence_of_entry, clause_obj_with_lits,
          propagation_normalized_clause, co_watch0, co_watch1, denote_obj.
        rewrite Htail. cbn [co_lits].
        rewrite !Znth0_cons.
        rewrite !Znth_cons by lia.
        replace (1 - 1) with 0 by lia. rewrite !Znth0_cons.
        rewrite Hmiss, Hmatch.
        rewrite Hnewlenb. cbn. reflexivity.
      + subst a1 watch0.
        assert (Hmiss : (lit_neg_c a0 =? p)%Z = false).
        { apply Z.eqb_neq. intro Heq. apply Hvarneq.
          rewrite Hfalse, <- Heq, !lit_var_c_neg. reflexivity. }
        unfold onew, minisat_occurrence_of_entry, clause_obj_with_lits,
          propagation_normalized_clause, co_watch0, co_watch1, denote_obj.
        rewrite Htail. cbn [co_lits].
        rewrite !Znth0_cons.
        rewrite !Znth_cons by lia.
        replace (1 - 1) with 0 by lia. rewrite !Znth0_cons.
        rewrite Hmiss, Hmatch.
        rewrite Hnewlenb. cbn. reflexivity.
  }
  destruct Hfocus as [pre [post [Hold Hnew]]].
  assert (Hreal : is_tag current = false).
  { apply even_not_tag. eapply db_wf_even; eassumption. }
  assert (Honesafe : minisat_occurrence_safe P onew).
  {
    unfold minisat_occurrence_safe, onew, minisat_occurrence_of_entry,
      clause_obj_with_lits, propagation_normalized_clause, co_watch0,
      co_watch1. cbn. intro Hboth. apply Hwatchsafe. exact (proj1 Hboth).
  }
  eapply focus_scan_carrier_db_pair_token_replace__propagate_dbu
    with (co := co) (pre := pre) (post := post) (onew := onew).
  - exact Hdb.
  - exact Hselected.
  - exact Hreal.
  - exact Hold.
  - exact Hnew.
  - exact Honesafe.
  - exact Hscan.
Qed.

(** Two facts about the entry the scan is holding when the unit arm fires:
    its first watched literal is still unprocessed, and permuting the literal
    list alone leaves the scan semantics unchanged. *)
Lemma propagation_unit_watch0_unprocessed__propagate_dbu :
  forall (n : Z) (assigns trail : list Z) (qhead watch0 : Z),
    lit_wf_c n watch0 ->
    (Znth (lit_var_c watch0) assigns 0 = lit_sig watch0 \/
     Znth (lit_var_c watch0) assigns 0 = 0) ->
    ~ minisat_processed n assigns trail qhead
        (literal_neg (lit_denote watch0)).
Proof.
  intros n assigns trail qhead watch0 Hwf Hcell Hprocessed.
  assert (Hnegwf : lit_wf_c n (lit_neg_c watch0)).
  { apply lit_neg_c_wf. exact Hwf. }
  assert (Hdenote : literal_neg (lit_denote watch0) =
      lit_denote (lit_neg_c watch0)).
  { symmetry. apply lit_denote_neg. destruct Hwf; lia. }
  rewrite Hdenote in Hprocessed.
  apply (proj1 (minisat_processed_denote n assigns trail qhead
    (lit_neg_c watch0) Hnegwf)) in Hprocessed.
  destruct Hprocessed as [Htrue Hposition].
  unfold lit_true in Htrue.
  rewrite lit_var_c_neg, lit_sig_neg in Htrue.
  destruct Hcell as [Hcell | Hcell]; rewrite Hcell in Htrue.
  - destruct (lit_sig_values watch0) as [Hsig | Hsig];
      rewrite Hsig in Htrue; lia.
  - destruct (lit_sig_values watch0) as [Hsig | Hsig];
      rewrite Hsig in Htrue; lia.
Qed.

Lemma propagation_unit_scan_semantics_unchanged__propagate_dbu :
  forall (n : Z) (F : cnf) (A_arr : list literal)
    (K : solver_propagation_context) (M : msolver)
    (p watch0 current : Z) (new_lits kept suffix : list Z)
    (prob_after learnt_after : dbmap),
    solver_propagation_scan_semantics n F A_arr K M p 0
      kept (current :: suffix) ->
    solver_propagation_weak n F A_arr K
      (msolver_propagation_db_wmap_update M prob_after learnt_after
        (ms_wm M) (ms_wcaps M)) ->
    minisat_watch_frontier_except n (prob_after ++ learnt_after)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p) ->
    minisat_focus_scan_carrier (prob_after ++ learnt_after) p
      (minisat_processed n (mt_assigns (ms_core M))
        (mt_trail (ms_core M)) (mt_qhead (ms_core M)))
      (kept ++ (current :: nil)) suffix ->
    Znth (lit_var_c watch0) (mt_assigns (ms_core M)) 0 =
      lit_sig watch0 ->
    solver_propagation_scan_semantics n F A_arr K
      (msolver_propagation_enqueue_success
        (msolver_propagation_db_wmap_update M prob_after learnt_after
          (ms_wm M) (ms_wcaps M))
        watch0 current (lits_denote new_lits))
      p 0 (kept ++ (current :: nil)) suffix.
Proof.
  intros n F A_arr K M p watch0 current new_lits kept suffix
    prob_after learnt_after Hsem Hweakdb Hfrontier Hcarrier Hcell.
  destruct Hsem as [Hlive | Hdead].
  2: { destruct Hdead as [Hnz _]. lia. }
  destruct Hlive as
    [Hconfl [Hweak [Hlevel [Hheap [Hcovers [Hreasonless
    [Hp_level [Hp_wf [Hprocessed [Hfrontier_old Hcarrier_old]]]]]]]]]].
  set (Mdb := msolver_propagation_db_wmap_update M prob_after learnt_after
    (ms_wm M) (ms_wcaps M)).
  assert (Hpost : msolver_propagation_enqueue_success Mdb watch0 current
      (lits_denote new_lits) = Mdb).
  {
    unfold Mdb, msolver_propagation_db_wmap_update,
      msolver_propagation_enqueue_success, msolver_propagation_overlay, msolver_propagation_update.
    cbn [ms_core mt_assigns].
    rewrite Hcell.
    destruct (lit_sig watch0 =? 0)%Z eqn:Hz; [|reflexivity].
    apply Z.eqb_eq in Hz. exfalso. exact (lit_sig_nonzero watch0 Hz).
  }
  rewrite Hpost.
  left. split; [reflexivity|].
  exact (conj Hweakdb (conj Hlevel (conj Hheap (conj Hcovers (conj Hreasonless
    (conj Hp_level (conj Hp_wf (conj Hprocessed (conj Hfrontier Hcarrier))))))))).
Qed.

(** The view-level assignment step behind every fresh enqueue below. *)
Lemma stable_view_assigns_one__propagate_dbu :
  forall old new x b d reason,
    stable_view old ->
    assigns_one old new x b d reason ->
    current_level new = current_level old ->
    (0 <= d /\ d <= current_level old) ->
    (reason = None \/
      exists c, reason = Some c /\ reason_valid new x c) ->
    stable_view new.
Proof. exact stable_view_assigns_one__record. Qed.

(** ===== group: solver_propagate_db_update_enqueue_fresh ===== *)
(** The fresh enqueue itself.  Each lemma from here re-establishes ONE field
    of the weak bundle at [msolver_enqueue_fresh]: the assignment cell, the
    reason word and its validity, the reason-map properties, trail
    implication, and finally the assembled weak/stable bundle. *)
Lemma propagation_enqueue_success_fresh__propagate_dbu :
  forall M l reason_word reason_clause,
    Znth (lit_var_c l) (mt_assigns (ms_core M)) 0 = 0 ->
    msolver_propagation_enqueue_success M l reason_word reason_clause =
      msolver_enqueue_fresh M l reason_word (Some reason_clause).
Proof.
  intros M l reason_word reason_clause Hfresh.
  unfold msolver_propagation_enqueue_success, msolver_enqueue_fresh.
  rewrite Hfresh. reflexivity.
Qed.

Lemma propagation_unit_assigns_one_fresh__propagate_dbu :
  forall n M l reason_word words,
    mtrail_wf n (ms_core M) ->
    lit_wf_c n l ->
    Znth (lit_var_c l) (mt_assigns (ms_core M)) 0 = 0 ->
    Forall (lit_wf_c n) words ->
    assigns_one (msolver_view n M)
      (msolver_view n
        (msolver_enqueue_fresh M l reason_word (Some (lits_denote words))))
      (lit_var_c l) (lit_pol l) (Zlength (mt_lim (ms_core M)))
      (Some (lits_denote words)).
Proof.
  intros n M l reason_word words Htrailwf Hl Hfresh Hwords.
  unfold msolver_view, msolver_enqueue_fresh,
    msolver_propagation_overlay, msolver_propagation_update, msolver_db.
  cbn [ms_core ms_reason_of ms_prob ms_learnt].
  eapply view_of_assign.
  - exact Htrailwf.
  - exact Hl.
  - exact Hfresh.
  - intros y Hy. apply sat_function_update_neq.
    intro E. apply Hy. symmetry. exact E.
  - apply sat_function_update_eq.
  - intros C k HC Hk. inversion HC; subst C.
    apply lits_denote_in_inv in Hk.
    destruct Hk as [kw [Hkw <-]].
    apply lit_denote_wf.
    rewrite Forall_forall in Hwords. exact (Hwords kw Hkw).
Qed.

Lemma propagation_unit_reason_valid_fresh__propagate_dbu :
  forall n M l reason_word words,
    stable_view (msolver_view n M) ->
    mtrail_wf n (ms_core M) ->
    lit_wf_c n l ->
    Znth (lit_var_c l) (mt_assigns (ms_core M)) 0 = 0 ->
    Forall (lit_wf_c n) words ->
    2 <= Zlength words ->
    Znth 0 words 0 = l ->
    lit_false (mt_assigns (ms_core M)) (Znth 1 words 0) ->
    (forall j, 2 <= j < Zlength words ->
      lit_false (mt_assigns (ms_core M)) (Znth j words 0)) ->
    reason_valid
      (msolver_view n
        (msolver_enqueue_fresh M l reason_word (Some (lits_denote words))))
      (lit_var_c l) (lits_denote words).
Proof.
  intros n M l reason_word words Hstable Htrailwf Hl Hfresh Hwords
    Hlen Hhead Hfalse1 Hfalse_tail.
  pose proof
    (propagation_unit_assigns_one_fresh__propagate_dbu
      n M l reason_word words Htrailwf Hl Hfresh Hwords) as Hassign.
  eapply reason_valid_assigns_one__record.
  - exact Hstable.
  - exact Hassign.
  - reflexivity.
  - rewrite <- lit_denote_satisfying.
    apply lits_denote_in. rewrite <- Hhead. apply Znth_In. lia.
  - intros k Hk Hkne.
    apply lits_denote_in_inv in Hk.
    destruct Hk as [kw [Hkw Hden]]. subst k.
    rewrite lit_var_c_denote in Hkne.
    destruct (In_Znth_index words kw Hkw) as [j [Hj Hjval]].
    rewrite Forall_forall in Hwords.
    pose proof (Hwords kw Hkw) as Hkwf.
    assert (Hkw0 : 0 <= kw) by (destruct Hkwf; lia).
    assert (Hkwfalse : lit_false (mt_assigns (ms_core M)) kw).
    { destruct (Z.eq_dec j 0) as [->|Hj0].
      - rewrite Hhead in Hjval. subst kw. contradiction.
      - destruct (Z.eq_dec j 1) as [->|Hj1].
        + rewrite Hjval in Hfalse1. exact Hfalse1.
        + pose proof (Hfalse_tail j ltac:(lia)) as Hjfalse.
          rewrite Hjval in Hjfalse. exact Hjfalse. }
    pose proof (proj1 (lit_false_iff
      (mt_assigns (ms_core M)) kw Hkw0) Hkwfalse) as Heval.
    change (eval_partial_literal (mt_pv (ms_core M))
      (lit_denote kw) = Some false).
    unfold eval_partial_literal in Heval |- *.
    rewrite lit_var_c_denote in Heval |- *.
    rewrite mt_pv_nonneg by
      (apply lit_var_c_nonneg with (n := n); exact Hkwf).
    exact Heval.
Qed.

Lemma propagation_unit_normalized_reason_properties__propagate_dbu :
  forall n F co new_words,
    obj_wf n co ->
    entails_clause F (denote_obj co) ->
    Permutation new_words (co_lits co) ->
    entails_clause F (lits_denote new_words) /\
    clause_var_injective (lits_denote new_words).
Proof.
  intros n F co new_words Hobj Hent Hperm.
  assert (Hpermden :
    Permutation (lits_denote new_words) (denote_obj co)).
  { unfold denote_obj. apply lits_denote_perm. exact Hperm. }
  split.
  - eapply entails_clause_perm.
    + apply Permutation_sym. exact Hpermden.
    + exact Hent.
  - apply NoDup_map_var_injective.
    rewrite map_literal_var_lits_denote.
    destruct Hobj as [Hlen [Hwf Hnodup]].
    eapply Permutation_NoDup.
    + apply Permutation_map. apply Permutation_sym. exact Hperm.
    + exact Hnodup.
Qed.

Lemma propagation_unit_trail_implied_fresh__propagate_dbu :
  forall n F t l words,
    mtrail_wf n t ->
    trail_implied F t ->
    entails_clause F (lits_denote words) ->
    Forall (lit_wf_c n) words ->
    2 <= Zlength words ->
    Znth 0 words 0 = l ->
    lit_false (mt_assigns t) (Znth 1 words 0) ->
    (forall j, 2 <= j < Zlength words ->
      lit_false (mt_assigns t) (Znth j words 0)) ->
    trail_implied F (mt_enqueue t l).
Proof.
  intros n F t l words Hwf Htrail Hent Hwords Hlen Hhead
    Hfalse1 Hfalse_tail.
  eapply trail_implied_unit with (rc := lits_denote words).
  - exact Hwf.
  - exact Htrail.
  - exact Hent.
  - apply lits_denote_in. rewrite <- Hhead. apply Znth_In. lia.
  - intros k Hk Hne.
    apply lits_denote_in_inv in Hk.
    destruct Hk as [kw [Hkw Hden]]. subst k.
    destruct (In_Znth_index words kw Hkw) as [j [Hj Hjval]].
    rewrite Forall_forall in Hwords.
    pose proof (Hwords kw Hkw) as Hkwf.
    assert (Hkw0 : 0 <= kw) by (destruct Hkwf; lia).
    assert (Hkwfalse : lit_false (mt_assigns t) kw).
    { destruct (Z.eq_dec j 0) as [->|Hj0].
      - rewrite Hhead in Hjval. subst kw. contradiction.
      - destruct (Z.eq_dec j 1) as [->|Hj1].
        + rewrite Hjval in Hfalse1. exact Hfalse1.
        + pose proof (Hfalse_tail j ltac:(lia)) as Hjfalse.
          rewrite Hjval in Hjfalse. exact Hjfalse. }
    assert (Heval :
      eval_partial_literal (assigns_pv (mt_assigns t))
        (lit_denote kw) = Some false).
    { apply (proj1 (lit_false_iff (mt_assigns t) kw Hkw0)).
      exact Hkwfalse. }
    assert (Hnegtrue :
      eval_partial_literal (assigns_pv (mt_assigns t))
        (lit_denote (lit_neg_c kw)) = Some true).
    { apply (proj2 (lit_neg_true_iff_false (mt_assigns t) kw Hkw0)).
      exact Heval. }
    pose proof (lit_neg_c_wf n kw Hkwf) as Hnegwf.
    assert (Hlittrue : lit_true (mt_assigns t) (lit_neg_c kw)).
    { assert (Hneg0 : 0 <= lit_neg_c kw) by (destruct Hnegwf; lia).
      apply (proj2 (lit_true_iff
        (mt_assigns t) (lit_neg_c kw) Hneg0)). exact Hnegtrue. }
    destruct (mtrail_wf_trail_covers n t Hwf (lit_neg_c kw)
      Hnegwf Hlittrue) as [j' [Hj' Hjlit]].
    exists j'. split; [exact Hj'|]. rewrite Hjlit.
    apply lit_denote_neg. exact Hkw0.
Qed.

(** The [db_complete] transport for the assuming bundle: kept as its own
    lemma because [solver_qcp_proof_manual_part3.v] applies it directly. *)
Lemma db_complete_enqueue_fresh_assuming__propagate_dbu :
  forall n F A_arr A_proc M l c reason,
    msolver_inv_assuming n F A_arr A_proc M ->
    lit_wf_c n l ->
    Znth (lit_var_c l) (mt_assigns (ms_core M)) 0 = 0 ->
    db_complete F (msolver_enqueue_fresh M l c reason).
Proof.
  intros n F A_arr A_proc M l c reason Hinv Hl Hfresh.
  exact (db_complete_enqueue_fresh_core n F M l c reason
    (msa_db_complete Hinv) (msa_trail_wf Hinv) Hl Hfresh).
Qed.

(** A fresh enqueue with a genuine reason clause rebuilds the stable-point
    bundle of EITHER propagation view.  The two carriers differ only in how
    the processed assumption prefix is indexed -- a plain equation for the
    stable view, an existential for the assuming one -- so the thirty field
    arms are dispatched once by goal head instead of being transcribed
    twice.  [destruct Hinv] puts the fields in scope under the record's own
    names, which is what lets one script serve both records. *)
Lemma propagation_unit_ctx_enqueue_fresh__propagate_dbu :
  forall n F A_arr K M l reason_word reason_clause,
    msolver_inv_ctx n F A_arr K M ->
    ms_capacity_root_propagation_pending M = 0 ->
    ms_qtail M < ms_cap M ->
    lit_wf_c n l ->
    Znth (lit_var_c l) (mt_assigns (ms_core M)) 0 = 0 ->
    assigns_one (msolver_view n M)
      (msolver_view n
        (msolver_enqueue_fresh M l reason_word (Some reason_clause)))
      (lit_var_c l) (lit_pol l) (Zlength (mt_lim (ms_core M)))
      (Some reason_clause) ->
    reason_valid
      (msolver_view n
        (msolver_enqueue_fresh M l reason_word (Some reason_clause)))
      (lit_var_c l) reason_clause ->
    entails_clause F reason_clause ->
    clause_var_injective reason_clause ->
    trail_implied F (mt_enqueue (ms_core M) l) ->
    (exists co,
      reason_word <> 0 /\ Z.even reason_word = true /\
      List.In (reason_word, co) (msolver_db M) /\
      reason_clause = denote_obj co /\
      lit_var_c (co_watch0 co) = lit_var_c l) ->
    msolver_inv_ctx n F A_arr K
      (msolver_enqueue_fresh M l reason_word (Some reason_clause)).
Proof.
  intros n F A_arr K M l reason_word reason_clause Hinv Hpending
    Hroom Hl Hfresh Hassign Hvalid Hreasonent Hreasoninj Htrailimpl Hco.
  destruct Hco as [co [Hnz [Heven [Hin [Hclause Hwatch]]]]].
  assert (Hreasoncases :
    (reason_word = 0 /\ Some reason_clause = None) \/
    exists co', reason_word <> 0 /\ Z.even reason_word = true /\
      List.In (reason_word, co') (msolver_db M) /\
      Some reason_clause = Some (denote_obj co')).
  { right. exists co. split; [exact Hnz|]. split; [exact Heven|].
    split; [exact Hin|]. rewrite Hclause. reflexivity. }
  assert (Hheadcases : reason_word = 0 \/
    exists co', reason_word <> 0 /\ Z.even reason_word = true /\
      List.In (reason_word, co') (msolver_db M) /\
      lit_var_c (co_watch0 co') = lit_var_c l).
  { right. exists co. split; [exact Hnz|]. split; [exact Heven|].
    split; [exact Hin|exact Hwatch]. }
  destruct K as [A_inst|A_proc]; cbn [msolver_inv_ctx] in Hinv |- *;
    destruct Hinv; constructor.
  all: lazymatch goal with
       | |- solver_shape _ =>
           eapply solver_shape_enqueue_fresh__record;
             [assumption|exact Hroom|exact Hpending]
       | |- mtrail_wf _ _ =>
           cbn; eapply (mtrail_wf_enqueue n); [assumption|exact Hl|exact Hfresh]
       | |- trail_implied _ _ => cbn; exact Htrailimpl
       | |- stable_view _ =>
           eapply (stable_view_assigns_one__propagate_dbu (msolver_view n M));
             [assumption|exact Hassign|reflexivity
             |split; [apply Zlength_nonneg|reflexivity]
             |right; exists reason_clause; split; [reflexivity|exact Hvalid]]
       | _ => idtac
       end.
  all: lazymatch goal with
       | |- reasons_entailed _ _ =>
           eapply reasons_entailed_assigns_one__record;
             [exact Hassign|assumption
             |right; exists reason_clause; split; [reflexivity|exact Hreasonent]]
       | |- reasons_var_injective _ =>
           eapply reasons_var_injective_assigns_one__record;
             [exact Hassign|assumption
             |right; exists reason_clause; split; [reflexivity|exact Hreasoninj]]
       | _ => idtac
       end.
  all: lazymatch goal with
       | |- db_complete _ _ =>
           eapply (db_complete_enqueue_fresh_core n);
             [assumption|assumption|exact Hl|exact Hfresh]
       | |- reasons_match _ _ _ _ _ =>
           eapply (reasons_match_enqueue_fresh_core n);
             [assumption|assumption|assumption|exact Hl|exact Hfresh
             |exact Hreasoncases]
       | _ => idtac
       end.
  all: lazymatch goal with
       | |- reason_head_ok _ =>
           eapply (reason_head_ok_enqueue_fresh_core n);
             [assumption|assumption|assumption|assumption|exact Hl
             |exact Hheadcases]
       | |- binary_reason_same_level _ =>
           eapply (binary_reason_same_level_enqueue_fresh_core n);
             [assumption|assumption|assumption|assumption|assumption
             |assumption|exact Hl|exact Hfresh|right; exact Heven]
       | _ => idtac
       end.
  all: lazymatch goal with
       | |- decisions_upto _ _ = _ =>
           cbn; rewrite (decisions_upto_enqueue n (ms_core M) l) by assumption;
           assumption
       | |- (exists _, _) =>
           lazymatch goal with
           | H : (exists _, _) |- _ => destruct H as [A_x [Hdec Hincl]]
           end;
           exists A_x; split; [|exact Hincl];
           cbn; rewrite (decisions_upto_enqueue n (ms_core M) l) by assumption;
           exact Hdec
       | _ => idtac
       end.
  all: lazymatch goal with
       | |- Forall (assump_true_at_root _ _) _ =>
           cbn; rewrite List.Forall_forall; intros a Ha;
           eapply (assump_true_at_root_enqueue__record n);
             [assumption|exact Hl|exact Hfresh|];
           lazymatch goal with
           | H : Forall (assump_true_at_root _ _) _ |- _ =>
               rewrite List.Forall_forall in H; exact (H a Ha)
           end
       | _ => idtac
       end.
  all: cbn; assumption.
Qed.

(** What the surrounding scan still owns after the fresh enqueue: the
    processed-prefix equivalence, the watch frontier away from the focused
    literal, the focus scan carrier, the reason-freedom of the current word,
    and the scan semantics. *)
Lemma processed_enqueue_fresh_equiv__propagate_dbu :
  forall n t q,
    mtrail_wf n t ->
    lit_wf_c n q ->
    Znth (lit_var_c q) (mt_assigns t) 0 = 0 ->
    (forall w, lit_wf_c n w ->
      processed (mt_assigns (mt_enqueue t q))
        (mt_trail (mt_enqueue t q)) (mt_qhead (mt_enqueue t q)) w ->
      processed (mt_assigns t) (mt_trail t) (mt_qhead t) w) /\
    (forall w, lit_wf_c n w ->
      processed (mt_assigns t) (mt_trail t) (mt_qhead t) w ->
      processed (mt_assigns (mt_enqueue t q))
        (mt_trail (mt_enqueue t q)) (mt_qhead (mt_enqueue t q)) w).
Proof.
  intros n t q Hwf Hqwf Hfresh.
  assert (Hqrange : 0 <= lit_var_c q < n).
  { apply lit_var_c_in_range. exact Hqwf. }
  split.
  - intros w Hwwf [Hwtrue [i [Hi Hiw]]].
    unfold mt_enqueue, mt_push in Hwtrue, Hi, Hiw.
    cbn [mt_assigns mt_trail mt_qhead] in Hwtrue, Hi, Hiw.
    assert (Hiold : 0 <= i < Zlength (mt_trail t)).
    { split; [exact (proj1 Hi)|].
      eapply Z.lt_le_trans; [exact (proj2 Hi)|].
      exact (proj2 (mtw_qhead_range Hwf)). }
    rewrite app_Znth1 in Hiw by exact Hiold.
    assert (Hwq : lit_var_c w <> lit_var_c q).
    { intro E.
      assert (Hinw : In w (mt_trail t)).
      { rewrite <- Hiw. apply Znth_In. exact Hiold. }
      pose proof (mtw_trail_true Hwf) as Htruecells.
      rewrite List.Forall_forall in Htruecells.
      specialize (Htruecells w Hinw).
      rewrite E, Hfresh in Htruecells.
      apply (lit_sig_nonzero w). symmetry. exact Htruecells. }
    split.
    + unfold lit_true in *.
      rewrite Znth_replace_Znth_Diff in Hwtrue.
      * exact Hwtrue.
      * rewrite (mtw_assigns_len Hwf). exact Hqrange.
      * rewrite (mtw_assigns_len Hwf).
        exact (lit_var_c_in_range n w Hwwf).
      * intro E. apply Hwq. symmetry. exact E.
    + exists i. split; [exact Hi|exact Hiw].
  - intros w Hwwf [Hwtrue [i [Hi Hiw]]].
    assert (Hiold : 0 <= i < Zlength (mt_trail t)).
    { split; [exact (proj1 Hi)|].
      eapply Z.lt_le_trans; [exact (proj2 Hi)|].
      exact (proj2 (mtw_qhead_range Hwf)). }
    assert (Hwq : lit_var_c w <> lit_var_c q).
    { intro E.
      assert (Hinw : In w (mt_trail t)).
      { rewrite <- Hiw. apply Znth_In. exact Hiold. }
      pose proof (mtw_trail_true Hwf) as Htruecells.
      rewrite List.Forall_forall in Htruecells.
      specialize (Htruecells w Hinw).
      rewrite E, Hfresh in Htruecells.
      apply (lit_sig_nonzero w). symmetry. exact Htruecells. }
    unfold mt_enqueue, mt_push.
    cbn [mt_assigns mt_trail mt_qhead].
    split.
    + unfold lit_true in *.
      rewrite Znth_replace_Znth_Diff.
      * exact Hwtrue.
      * rewrite (mtw_assigns_len Hwf). exact Hqrange.
      * rewrite (mtw_assigns_len Hwf).
        exact (lit_var_c_in_range n w Hwwf).
      * intro E. apply Hwq. symmetry. exact E.
    + exists i. split; [exact Hi|].
      rewrite app_Znth1; [exact Hiw|exact Hiold].
Qed.

Lemma minisat_watch_frontier_except_enqueue_fresh__propagate_dbu :
  forall n db t q focus,
    mtrail_wf n t ->
    lit_wf_c n q ->
    Znth (lit_var_c q) (mt_assigns t) 0 = 0 ->
    minisat_watch_frontier_except n db
      (mt_assigns t) (mt_trail t) (mt_qhead t) focus ->
    minisat_watch_frontier_except n db
      (mt_assigns (mt_enqueue t q))
      (mt_trail (mt_enqueue t q)) (mt_qhead (mt_enqueue t q)) focus.
Proof.
  intros n db t q focus Hwf Hqwf Hfresh Hfrontier.
  destruct (processed_enqueue_fresh_equiv__propagate_dbu
    n t q Hwf Hqwf Hfresh) as [Hreverse Hforward].
  assert (Hmini_reverse : forall l,
    minisat_processed n (mt_assigns (mt_enqueue t q))
      (mt_trail (mt_enqueue t q)) (mt_qhead (mt_enqueue t q)) l ->
    minisat_processed n (mt_assigns t) (mt_trail t) (mt_qhead t) l).
  { intros l [w [Hwwf [Hden Hproc]]].
    exists w. split; [exact Hwwf|]. split; [exact Hden|].
    apply Hreverse; assumption. }
  unfold minisat_watch_frontier_except in *.
  unfold watch_frontier_except in *.
  rewrite Forall_forall in Hfrontier |- *.
  intros o Ho. specialize (Hfrontier o Ho).
  destruct Hfrontier as [Hsafe | Hfocus].
  - left. intros [Hleft Hright]. apply Hsafe. split;
      apply Hmini_reverse; assumption.
  - right. exact Hfocus.
Qed.

Lemma minisat_focus_scan_carrier_enqueue_fresh__propagate_dbu :
  forall n db t q p kept suffix,
    mtrail_wf n t ->
    lit_wf_c n q ->
    Znth (lit_var_c q) (mt_assigns t) 0 = 0 ->
    minisat_focus_scan_carrier db p
      (minisat_processed n (mt_assigns t) (mt_trail t) (mt_qhead t))
      kept suffix ->
    minisat_focus_scan_carrier db p
      (minisat_processed n (mt_assigns (mt_enqueue t q))
        (mt_trail (mt_enqueue t q)) (mt_qhead (mt_enqueue t q)))
      kept suffix.
Proof.
  intros n db t q p kept suffix Hwf Hqwf Hfresh Hcarrier.
  destruct (processed_enqueue_fresh_equiv__propagate_dbu
    n t q Hwf Hqwf Hfresh) as [Hreverse Hforward].
  assert (Hmini_reverse : forall l,
    minisat_processed n (mt_assigns (mt_enqueue t q))
      (mt_trail (mt_enqueue t q)) (mt_qhead (mt_enqueue t q)) l ->
    minisat_processed n (mt_assigns t) (mt_trail t) (mt_qhead t) l).
  { intros l [w [Hwwf [Hden Hproc]]].
    exists w. split; [exact Hwwf|]. split; [exact Hden|].
    apply Hreverse; assumption. }
  unfold minisat_focus_scan_carrier in Hcarrier |- *.
  destruct Hcarrier as [scanned [pending [Hperm [Hscanned [Hpending Hsafe]]]]].
  exists scanned, pending. split; [exact Hperm|].
  split; [exact Hscanned|]. split; [exact Hpending|].
  revert Hsafe. apply Forall_impl.
  intros occurrence Hsafe Hboth. apply Hsafe.
  split.
  - apply Hmini_reverse. exact (proj1 Hboth).
  - apply Hmini_reverse. exact (proj2 Hboth).
Qed.

Lemma current_reasonless_enqueue_fresh__propagate_dbu :
  forall n M l reason_word reason_clause,
    solver_shape M ->
    mtrail_wf n (ms_core M) ->
    lit_wf_c n l ->
    reason_word <> 0 ->
    current_reasonless_earliest n M ->
    assigns_one (msolver_view n M)
      (msolver_view n
        (msolver_enqueue_fresh M l reason_word (Some reason_clause)))
      (lit_var_c l) (lit_pol l) (Zlength (mt_lim (ms_core M)))
      (Some reason_clause) ->
    current_reasonless_earliest n
      (msolver_enqueue_fresh M l reason_word (Some reason_clause)).
Proof.
  intros n M l reason_word reason_clause Hshape Htrailwf Hl Hwordnz Hold
    Hassign.
  unfold current_reasonless_earliest in Hold |- *.
  intros d Hrange v Hlevel Hwordzero.
  destruct Hassign as [_ [_ [_ [_ [_ [Hother _]]]]]].
  pose proof (mtw_assigns_len Htrailwf) as Hassignlen.
  change (ms_root_level M < d <= Zlength (mt_lim (ms_core M))) in Hrange.
  destruct (Z.eq_dec v (lit_var_c l)) as [->|Hvne].
  - assert (Htarget :
      0 <= lit_var_c l < Zlength (ms_reason_words M)).
    { apply lit_var_c_in_range in Hl. unfold solver_shape in Hshape. lia. }
    unfold msolver_enqueue_fresh, msolver_propagation_overlay, msolver_propagation_update in Hwordzero.
    cbn [ms_reason_words] in Hwordzero.
    rewrite Znth_replace_Znth_Same in Hwordzero by exact Htarget.
    contradiction.
  - destruct (Hother v Hvne) as [Ha [Hlev [Hreason Hrankeq]]].
    rewrite Hlev in Hlevel.
    assert (Hv : 0 <= v < n).
    { unfold msolver_view, view_of in Hlevel.
      cbn [level_of] in Hlevel.
      destruct (trail_pos (ms_core M) v) as [k|] eqn:Hpos;
        cbn [option_map] in Hlevel; [|discriminate].
      apply find_var_pos_some_in in Hpos.
      apply trail_var_range with (t := ms_core M); assumption. }
    assert (Htarget :
      0 <= lit_var_c l < Zlength (ms_reason_words M)).
    { apply lit_var_c_in_range in Hl. unfold solver_shape in Hshape. lia. }
    assert (Hvr : 0 <= v < Zlength (ms_reason_words M)).
    { unfold solver_shape in Hshape. lia. }
    unfold msolver_enqueue_fresh, msolver_propagation_overlay, msolver_propagation_update in Hwordzero.
    cbn [ms_reason_words] in Hwordzero.
    rewrite Znth_replace_Znth_Diff in Hwordzero.
    2: { exact Htarget. } 2: { exact Hvr. } 2: { congruence. }
    destruct (Hold d Hrange v Hlevel Hwordzero) as [Hr Hrank].
    split.
    + unfold msolver_enqueue_fresh, msolver_propagation_overlay, msolver_propagation_update.
      cbn [ms_reason_of]. rewrite sat_function_update_neq.
      * exact Hr.
      * intro E. apply Hvne. symmetry. exact E.
    + rewrite Hrankeq. exact Hrank.
Qed.

Lemma propagation_unit_scan_semantics_fresh__propagate_dbu :
  forall n F A_arr K M Mdb Mpost p q current reason_clause
    retained suffix retained_after prob_after learnt_after,
    Mdb = msolver_propagation_db_wmap_update M prob_after learnt_after
      (ms_wm M) (ms_wcaps M) ->
    Mpost = msolver_enqueue_fresh Mdb q current (Some reason_clause) ->
    solver_propagation_scan_semantics n F A_arr K M p 0
      retained (current :: suffix) ->
    solver_propagation_weak n F A_arr K Mdb ->
    minisat_watch_frontier_except n (prob_after ++ learnt_after)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p) ->
    minisat_focus_scan_carrier (prob_after ++ learnt_after) p
      (minisat_processed n (mt_assigns (ms_core M))
        (mt_trail (ms_core M)) (mt_qhead (ms_core M)))
      retained_after suffix ->
    lit_wf_c n q ->
    Znth (lit_var_c q) (mt_assigns (ms_core M)) 0 = 0 ->
    assigns_one (msolver_view n Mdb) (msolver_view n Mpost)
      (lit_var_c q) (lit_pol q) (Zlength (mt_lim (ms_core Mdb)))
      (Some reason_clause) ->
    solver_propagation_weak n F A_arr K Mpost ->
    current_reasonless_earliest n Mpost ->
    solver_propagation_scan_semantics n F A_arr K Mpost p 0
      retained_after suffix.
Proof.
  intros n F A_arr K M Mdb Mpost p q current reason_clause retained suffix
    retained_after prob_after learnt_after HMdb HMpost Hsem Hweakdb Hfrontier
    Hcarrier Hqwf Hfresh Hassign Hweakpost Hreasonlesspost.
  destruct Hsem as [Hlive | Hdead].
  2: { destruct Hdead as [Hnz _]. lia. }
  destruct Hlive as
    [Hzero [Hweak [Hlevel [Hheap [Hcovers [Hreasonless
    [Hp_level [Hp_wf [Hprocessed [Hfrontier_old Hcarrier_old]]]]]]]]]].
  assert (Htrailwf : mtrail_wf n (ms_core M)).
  { unfold solver_propagation_weak in Hweak.
    destruct K as [A_inst | A_proc]; cbn in Hweak.
    - exact (msw_trail_wf (proj2 Hweak)).
    - exact (msa_trail_wf (proj2 Hweak)). }
  assert (Hprocessed_new : processed
    (mt_assigns (ms_core Mpost)) (mt_trail (ms_core Mpost))
    (mt_qhead (ms_core Mpost)) p).
  { subst Mpost Mdb.
    destruct (processed_enqueue_fresh_equiv__propagate_dbu
      n (ms_core M) q Htrailwf Hqwf Hfresh) as [Hreverse Hforward].
    apply Hforward; [exact Hp_wf|exact Hprocessed]. }
  assert (Hfrontier_new : minisat_watch_frontier_except n
    (msolver_db Mpost) (mt_assigns (ms_core Mpost))
    (mt_trail (ms_core Mpost)) (mt_qhead (ms_core Mpost)) (lit_denote p)).
  { subst Mpost Mdb.
    change (minisat_watch_frontier_except n (prob_after ++ learnt_after)
      (mt_assigns (mt_enqueue (ms_core M) q))
      (mt_trail (mt_enqueue (ms_core M) q))
      (mt_qhead (mt_enqueue (ms_core M) q)) (lit_denote p)).
    eapply minisat_watch_frontier_except_enqueue_fresh__propagate_dbu;
      eassumption. }
  assert (Hcarrier_new : minisat_focus_scan_carrier
    (msolver_db Mpost) p
    (minisat_processed n (mt_assigns (ms_core Mpost))
      (mt_trail (ms_core Mpost)) (mt_qhead (ms_core Mpost)))
    retained_after suffix).
  { subst Mpost Mdb.
    change (minisat_focus_scan_carrier (prob_after ++ learnt_after) p
      (minisat_processed n (mt_assigns (mt_enqueue (ms_core M) q))
        (mt_trail (mt_enqueue (ms_core M) q))
        (mt_qhead (mt_enqueue (ms_core M) q))) retained_after suffix).
    eapply minisat_focus_scan_carrier_enqueue_fresh__propagate_dbu;
      eassumption. }
  assert (Hcovers_new : heap_covers n (msolver_heap Mpost)
    (mt_assigns (ms_core Mpost)) (mt_trail (ms_core Mpost))
    (mt_qhead (ms_core Mpost))).
  { subst Mpost Mdb.
    change (heap_covers n (msolver_heap M)
      (mt_assigns (mt_enqueue (ms_core M) q))
      (mt_trail (mt_enqueue (ms_core M) q))
      (mt_qhead (mt_enqueue (ms_core M) q))).
    eapply heap_covers_enqueue_fresh__record;
      [exact Htrailwf|exact Hqwf|exact Hcovers]. }
  assert (Hp_level_new : level_of (msolver_view n Mpost) (lit_var_c p) =
    Some (Zlength (mt_lim (ms_core Mpost)))).
  { destruct Hassign as [_ [_ [_ [_ [_ [Hother _]]]]]].
    assert (Hqneq : lit_var_c q <> lit_var_c p).
    { exact (processed_fresh_target_different
        (mt_assigns (ms_core M)) (mt_trail (ms_core M))
        (mt_qhead (ms_core M)) p q Hprocessed Hfresh). }
    destruct (Hother (lit_var_c p) (fun E => Hqneq (eq_sym E)))
      as [_ [Hlevelp _]].
    assert (Hp_level_db : level_of (msolver_view n Mdb) (lit_var_c p) =
      Some (Zlength (mt_lim (ms_core Mdb)))).
    { subst Mdb. exact Hp_level. }
    rewrite Hlevelp, Hp_level_db. subst Mpost. reflexivity. }
  left. split; [reflexivity|].
  split; [exact Hweakpost|].
  split.
  - subst Mpost Mdb. change (prop_level (mt_enqueue (ms_core M) q)).
    apply prop_level_enqueue. exact Hlevel.
  - split.
    + left. exact Hcovers_new.
    + split; [exact Hcovers_new|].
      split; [exact Hreasonlesspost|].
      split; [exact Hp_level_new|].
      split; [exact Hp_wf|].
      split; [exact Hprocessed_new|].
      split; [exact Hfrontier_new|exact Hcarrier_new].
Qed.

(** The keep step of the unit arm -- the entry stays on this watch list --
    and the whole success exit, assembled from the pieces above. *)
Lemma solver_propagation_weak_selected_entailed__propagate_dbu :
  forall n F A_arr K M current co,
    solver_propagation_weak n F A_arr K M ->
    In (current, co) (msolver_db M) ->
    entails_clause F (denote_obj co).
Proof.
  intros n F A_arr K M current co Hweak Hin.
  unfold solver_propagation_weak in Hweak.
  destruct K as [A_inst | A_proc]; destruct Hweak as [Hpending Hinv].
  - eapply (msolver_inv_db_entailed n F A_arr A_inst M Hinv).
    rewrite msolver_view_installed.
    unfold msolver_clauses.
    apply db_clauses_in with (p := current). exact Hin.
  - unfold msolver_db in Hin. apply in_app_or in Hin.
    destruct Hin as [Hprob | Hlearnt].
    + pose proof (msa_db_matches Hinv) as Hmatches.
      unfold db_matches_cnf in Hmatches.
      rewrite Forall_forall in Hmatches.
      assert (Hclause : In (denote_obj co) (db_clauses (ms_prob M))).
      { apply db_clauses_in with (p := current). exact Hprob. }
      destruct (Hmatches (denote_obj co) Hclause) as [c0 [Hin0 Hperm]].
      eapply entails_clause_perm.
      * apply Permutation_sym. exact Hperm.
      * apply entails_clause_in. exact Hin0.
    + pose proof (msa_db_implied Hinv) as Himplied.
      unfold db_implied in Himplied. rewrite Forall_forall in Himplied.
      apply Himplied. apply db_clauses_in with (p := current). exact Hlearnt.
Qed.

Lemma db_pair_lits_update_selected_owner__propagate_dbu :
  forall prob learnt current old_lits new_lits prob_after learnt_after,
    db_pair_lits_update prob learnt current old_lits new_lits
      prob_after learnt_after ->
    exists co_after,
      In (current, co_after) (prob_after ++ learnt_after) /\
      co_lits co_after = new_lits.
Proof.
  intros prob learnt current old_lits new_lits prob_after learnt_after Hupdate.
  destruct Hupdate as
    [[co [pre [post [Hprob [Hold [Hprob_after Hlearnt_after]]]]]]
    |[co [pre [post [Hlearnt [Hold [Hprob_after Hlearnt_after]]]]]]].
  - subst prob_after learnt_after.
    exists (clause_obj_with_lits co new_lits). split.
    + apply in_or_app. left.
      apply in_or_app. right. left. reflexivity.
    + reflexivity.
  - subst prob_after learnt_after.
    exists (clause_obj_with_lits co new_lits). split.
    + apply in_or_app. right.
      apply in_or_app. right. left. reflexivity.
    + reflexivity.
Qed.

Lemma propagation_unit_keep_step__propagate_dbu :
  forall source retained moved rest garbage memory ii jj current suffix,
    rest = current :: suffix ->
    propagation_watch_scan_physical source retained moved rest garbage memory
      ii jj ->
    exists garbage_after memory_after,
      propagation_scan_keep_step source retained moved rest memory ii jj current
        (retained ++ current :: nil) suffix garbage_after memory_after.
Proof.
  intros source retained moved rest garbage memory ii jj current suffix Hrest
    Hphysical.
  unfold propagation_watch_scan_physical in Hphysical.
  destruct Hphysical as
    [Hscan [Hmemory [Hretlen [Hprefixlen Hmemorylen]]]].
  subst rest.
  destruct garbage as [|g gs].
  - exists nil, memory.
    unfold propagation_scan_keep_step.
    split; [reflexivity|]. split; [reflexivity|]. split.
    + assert (Hnth : Znth jj memory 0 = current).
      { rewrite Hmemory.
        rewrite app_Znth2 by (rewrite Hretlen; lia).
        replace (jj - Zlength retained) with 0 by lia. reflexivity. }
      rewrite <- Hnth. symmetry. apply replace_Znth_Znth.
    + unfold propagation_watch_scan_physical.
      split; [apply wlist_scan_keep; exact Hscan|]. split.
      * rewrite Hmemory.
        change (retained ++ (current :: suffix) =
          (retained ++ (current :: nil)) ++ suffix).
        rewrite <- app_assoc. reflexivity.
      * split.
        -- rewrite Zlength_app, Zlength_cons, Zlength_nil, Hretlen. lia.
        -- split.
           ++ rewrite app_nil_r in Hprefixlen.
              rewrite !Zlength_app. cbn. rewrite Hretlen. lia.
           ++ exact Hmemorylen.
  - exists (gs ++ current :: nil), (replace_Znth jj current memory).
    unfold propagation_scan_keep_step.
    split; [reflexivity|]. split; [reflexivity|]. split; [reflexivity|].
    unfold propagation_watch_scan_physical.
    split; [apply wlist_scan_keep; exact Hscan|]. split.
    + rewrite Hmemory.
      rewrite replace_Znth_app_r by (rewrite Hretlen; lia).
      rewrite replace_Znth_nothing by lia.
      replace (jj - Zlength retained) with 0 by lia. cbn.
      rewrite <- !app_assoc. reflexivity.
    + split.
      * rewrite Zlength_app, Zlength_cons, Zlength_nil, Hretlen. lia.
      * split.
        -- rewrite !Zlength_app in Hprefixlen |- *.
           rewrite !Zlength_app_cons. rewrite Zlength_cons in Hprefixlen. lia.
        -- rewrite Zlength_replace_Znth. exact Hmemorylen.
Qed.

Lemma propagation_unit_fresh_success_semantics__propagate_dbu :
  forall n F A_arr K M Mdb p watch0 current old_lits new_lits retained suffix
    prob_after learnt_after co,
    Mdb = msolver_propagation_db_wmap_update M prob_after learnt_after
      (ms_wm M) (ms_wcaps M) ->
    solver_propagation_scan_semantics n F A_arr K M p 0
      retained (current :: suffix) ->
    solver_propagation_weak n F A_arr K M ->
    solver_propagation_weak n F A_arr K Mdb ->
    db_wf n (msolver_db M) ->
    In (current, co) (msolver_db M) ->
    Permutation new_lits (co_lits co) ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current old_lits new_lits
      prob_after learnt_after ->
    Forall (lit_wf_c n) new_lits ->
    3 <= Zlength new_lits ->
    Znth 0 new_lits 0 = watch0 ->
    lit_false (mt_assigns (ms_core M)) (Znth 1 new_lits 0) ->
    (forall j, 2 <= j < Zlength new_lits ->
      lit_false (mt_assigns (ms_core M)) (Znth j new_lits 0)) ->
    minisat_watch_frontier_except n (prob_after ++ learnt_after)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p) ->
    minisat_focus_scan_carrier (prob_after ++ learnt_after) p
      (minisat_processed n (mt_assigns (ms_core M))
        (mt_trail (ms_core M)) (mt_qhead (ms_core M)))
      (retained ++ current :: nil) suffix ->
    lit_wf_c n watch0 ->
    Znth (lit_var_c watch0) (mt_assigns (ms_core M)) 0 = 0 ->
    ms_qtail Mdb < ms_cap Mdb ->
    solver_propagation_scan_semantics n F A_arr K
      (msolver_propagation_enqueue_success Mdb watch0 current
        (lits_denote new_lits)) p 0 (retained ++ current :: nil) suffix.
Proof.
  intros n F A_arr K M Mdb p watch0 current old_lits new_lits retained
    suffix prob_after learnt_after co HMdb Hsem Hweak Hweakdb Hdbwf Hin
    Hperm Hupdate Hwords Hlong Hhead Hfalse1 Hfalse_tail Hfrontier Hcarrier
    Hwatchwf Hfresh Hroom.
  pose proof Hsem as Hsem0.
  destruct Hsem0 as [Hlive | Hdead].
  2: { destruct Hdead as [Hnz _]. lia. }
  destruct Hlive as
    [Hzero [Hweak0 [Hlevel [Hheap [Hcovers [Hreasonless
    [Hp_level [Hp_wf [Hprocessed [Hfrontier0 Hcarrier0]]]]]]]]]].
  assert (Hcore : solver_shape Mdb /\ mtrail_wf n (ms_core Mdb) /\
    stable_view (msolver_view n Mdb) /\ trail_implied F (ms_core Mdb)).
  { unfold solver_propagation_weak in Hweakdb.
    destruct K as [A_inst | A_proc]; cbn in Hweakdb.
    - destruct Hweakdb as [_ Hinv].
      split; [exact (msw_shape Hinv)|]. split; [exact (msw_trail_wf Hinv)|].
      split; [exact (msw_stable Hinv)|exact (msw_trail_impl Hinv)].
    - destruct Hweakdb as [_ Hinv].
      split; [exact (msa_shape Hinv)|]. split; [exact (msa_trail_wf Hinv)|].
      split; [exact (msa_stable Hinv)|exact (msa_trail_impl Hinv)]. }
  destruct Hcore as [Hshape [Htrailwf [Hstable Htrailimpl]]].
  assert (Hdbwfdb : db_wf n (msolver_db Mdb)).
  { unfold solver_propagation_weak in Hweakdb.
    destruct K as [A_inst | A_proc]; cbn in Hweakdb.
    - exact (msw_db_wf (proj2 Hweakdb)).
    - exact (msa_db_wf (proj2 Hweakdb)). }
  set (Mpost := msolver_enqueue_fresh Mdb watch0 current
    (Some (lits_denote new_lits))).
  assert (Hfreshdb :
    Znth (lit_var_c watch0) (mt_assigns (ms_core Mdb)) 0 = 0).
  { rewrite HMdb. unfold msolver_propagation_db_wmap_update,
      msolver_propagation_overlay, msolver_propagation_update. cbn. exact Hfresh. }
  assert (Hassign : assigns_one (msolver_view n Mdb) (msolver_view n Mpost)
    (lit_var_c watch0) (lit_pol watch0) (Zlength (mt_lim (ms_core Mdb)))
    (Some (lits_denote new_lits))).
  { unfold Mpost. eapply propagation_unit_assigns_one_fresh__propagate_dbu;
      [exact Htrailwf|exact Hwatchwf|exact Hfreshdb|exact Hwords]. }
  assert (Hselectedent : entails_clause F (denote_obj co)).
  { eapply solver_propagation_weak_selected_entailed__propagate_dbu;
      [exact Hweak|exact Hin]. }
  destruct (propagation_unit_normalized_reason_properties__propagate_dbu
    n F co new_lits (db_wf_obj n (msolver_db M) current co Hdbwf Hin)
    Hselectedent Hperm) as [Hreasonent Hreasoninj].
  assert (Hfalse1db :
    lit_false (mt_assigns (ms_core Mdb)) (Znth 1 new_lits 0)).
  { rewrite HMdb. unfold msolver_propagation_db_wmap_update,
      msolver_propagation_overlay, msolver_propagation_update. cbn. exact Hfalse1. }
  assert (Hfalse_taildb : forall j, 2 <= j < Zlength new_lits ->
    lit_false (mt_assigns (ms_core Mdb)) (Znth j new_lits 0)).
  { intros j Hj. rewrite HMdb. unfold msolver_propagation_db_wmap_update,
      msolver_propagation_overlay, msolver_propagation_update. cbn. apply Hfalse_tail. exact Hj. }
  assert (Hvalid : reason_valid (msolver_view n Mpost)
    (lit_var_c watch0) (lits_denote new_lits)).
  { unfold Mpost. eapply propagation_unit_reason_valid_fresh__propagate_dbu;
      [exact Hstable|exact Htrailwf|exact Hwatchwf|exact Hfreshdb|exact Hwords|
       lia|exact Hhead|exact Hfalse1db|exact Hfalse_taildb]. }
  assert (Htrailimpl' : trail_implied F (mt_enqueue (ms_core Mdb) watch0)).
  { eapply propagation_unit_trail_implied_fresh__propagate_dbu;
      [exact Htrailwf|exact Htrailimpl|exact Hreasonent|exact Hwords|lia|
       exact Hhead|exact Hfalse1db|exact Hfalse_taildb]. }
  destruct (db_pair_lits_update_selected_owner__propagate_dbu
    _ _ _ _ _ _ _ Hupdate) as [co_after [Hin_after Hco_after]].
  assert (Hin_after_db : In (current, co_after) (msolver_db Mdb)).
  { rewrite HMdb. unfold msolver_propagation_db_wmap_update,
      msolver_propagation_overlay, msolver_propagation_update, msolver_db. cbn. exact Hin_after. }
  assert (Hcurrentpos : 0 < current).
  { eapply db_wf_ptr_pos; [exact Hdbwfdb|exact Hin_after_db]. }
  assert (Hcurrenteven : Z.even current = true).
  { eapply db_wf_even; [exact Hdbwfdb|exact Hin_after_db]. }
  assert (Howner : exists co', current <> 0 /\ Z.even current = true /\
    In (current, co') (msolver_db Mdb) /\ lits_denote new_lits = denote_obj co' /\
    lit_var_c (co_watch0 co') = lit_var_c watch0).
  { exists co_after. split; [lia|].
    split; [exact Hcurrenteven|]. split.
    - exact Hin_after_db.
    - split.
      + unfold denote_obj. rewrite Hco_after. reflexivity.
      + unfold co_watch0. rewrite Hco_after, Hhead. reflexivity. }
  assert (Hweakpost : solver_propagation_weak n F A_arr K Mpost).
  { unfold solver_propagation_weak in Hweakdb |- *.
    split; [unfold Mpost, msolver_enqueue_fresh, msolver_propagation_overlay, msolver_propagation_update;
      cbn; exact (proj1 Hweakdb)|].
    eapply (propagation_unit_ctx_enqueue_fresh__propagate_dbu n F A_arr K Mdb);
      [exact (proj2 Hweakdb)|exact (proj1 Hweakdb)|exact Hroom|exact Hwatchwf|
       exact Hfreshdb|exact Hassign|exact Hvalid|exact Hreasonent|exact Hreasoninj|
       exact Htrailimpl'|exact Howner]. }
  assert (Hreasonlessdb : current_reasonless_earliest n Mdb).
  { subst Mdb. exact Hreasonless. }
  assert (Hreasonlesspost : current_reasonless_earliest n Mpost).
  { unfold Mpost. eapply current_reasonless_enqueue_fresh__propagate_dbu;
      [exact Hshape|exact Htrailwf|exact Hwatchwf|
       lia|exact Hreasonlessdb|exact Hassign]. }
  assert (Hfreshsem : solver_propagation_scan_semantics n F A_arr K Mpost p 0
    (retained ++ current :: nil) suffix).
  { eapply propagation_unit_scan_semantics_fresh__propagate_dbu
      with (M := M) (Mdb := Mdb) (q := watch0) (current := current)
        (reason_clause := lits_denote new_lits) (retained := retained)
        (prob_after := prob_after) (learnt_after := learnt_after).
    - exact HMdb.
    - reflexivity.
    - exact Hsem.
    - exact Hweakdb.
    - exact Hfrontier.
    - exact Hcarrier.
    - exact Hwatchwf.
    - exact Hfresh.
    - exact Hassign.
    - exact Hweakpost.
    - exact Hreasonlesspost. }
  unfold Mpost in Hfreshsem.
  rewrite <- propagation_enqueue_success_fresh__propagate_dbu
    in Hfreshsem by exact Hfreshdb. exact Hfreshsem.
Qed.

(** ===== group: solver_propagate_db_update_migrated_arm ===== *)
(** The MIGRATED arm.  The scan found a new literal to watch, so the entry
    leaves this watch list for another one.  These lemmas carry the physical
    scan layout, the watch frontier, the focus contributions and the scan
    semantics across that move. *)
Lemma focus_scan_carrier_db_pair_token_remove__propagate_dbu :
  forall n olddb newdb p P kept rest current co pre post,
    db_wf n olddb ->
    In (current, co) olddb ->
    is_tag current = false ->
    minisat_focus_contributions olddb p =
      pre ++ (minisat_occurrence_of_entry (current, co), current) :: post ->
    minisat_focus_contributions newdb p = pre ++ post ->
    minisat_focus_scan_carrier olddb p P kept (current :: rest) ->
    minisat_focus_scan_carrier newdb p P kept rest.
Proof.
  intros n olddb newdb p P kept rest current co pre post
    Hdb Hselected Hreal Hold Hnew Hscan.
  unfold minisat_focus_scan_carrier in Hscan |- *.
  destruct Hscan as [scanned [pending [Hcover [Hkept [Hrest Hsafe]]]]].
  destruct pending as [|[o w] pending]; cbn in Hrest; [discriminate|].
  inversion Hrest; subst w.
  assert (Hinold : In (o, current) (minisat_focus_contributions olddb p)).
  { eapply Permutation_in; [exact Hcover|].
    apply in_or_app. right. cbn. auto. }
  destruct (minisat_focus_real_word_owner__propagate_dbu
    n olddb p o current Hdb Hinold Hreal) as [co' [Hco' Ho]].
  assert (Hco : co' = co).
  { eapply db_wf_lookup_unique; [exact Hdb|exact Hco'|exact Hselected]. }
  subst co'. subst o.
  assert (Hbase : Permutation (scanned ++ pending) (pre ++ post)).
  { apply (Permutation_cons_inv
      (a := (minisat_occurrence_of_entry (current, co), current))).
    eapply Permutation_trans.
    - apply Permutation_middle.
    - eapply Permutation_trans; [exact Hcover|].
      rewrite Hold. apply Permutation_sym. apply Permutation_middle. }
  exists scanned, pending. rewrite Hnew.
  repeat split; assumption.
Qed.

Lemma propagation_real_migrated_exit_intro__propagate_dbu :
  forall n F A_arr K M0 Mentry M Mroute p prob learnt wm_pre wm_post
    caps_pre caps_post source_cap destination_cap candidate current source
    retained moved rest memory ii jj moved' rest' garbage' memory'
    simp_count prop_count,
    Mroute = msolver_propagation_db_wmap_update M prob learnt
      (propagation_move_wmap (Zlength wm_pre) (lit_neg_c candidate) wm_pre
        (retained ++ rest') wm_post current)
      (propagation_move_wcaps (lit_neg_c candidate) caps_pre source_cap
        caps_post destination_cap) ->
    propagation_scan_move_step source retained moved rest memory ii jj current
      moved' rest' garbage' ->
    solver_shape Mroute ->
    msolver_seed_shadow Mroute ->
    propagation_caller_frame M0 Mroute ->
    propagation_scan_frontier Mentry Mroute p ->
    solver_propagation_scan_semantics n F A_arr K Mroute p 0 retained rest' ->
    simp_count = ms_simpdb_props Mroute ->
    prop_count = stats_propagations (ms_stats Mroute) ->
    memory' = memory ->
    propagation_watch_scan_physical source retained moved' rest' garbage'
      memory' (ii + 1) jj ->
    ms_wm Mroute =
      propagation_split_pre_words (Zlength wm_pre) (lit_neg_c candidate)
        wm_pre (wlists_split_target_words (Zlength wm_pre)
          (lit_neg_c candidate) wm_pre wm_post ++ (current :: nil)) ++
      (retained ++ rest') ::
      propagation_split_post_words (Zlength wm_pre) (lit_neg_c candidate)
        wm_post (wlists_split_target_words (Zlength wm_pre)
          (lit_neg_c candidate) wm_pre wm_post ++ (current :: nil)) ->
    ms_wcaps Mroute =
      propagation_split_pre_caps (Zlength wm_pre) (lit_neg_c candidate)
        caps_pre destination_cap ++ source_cap ::
      propagation_split_post_caps (Zlength wm_pre) (lit_neg_c candidate)
        caps_post destination_cap ->
    Zlength (propagation_split_pre_words (Zlength wm_pre)
      (lit_neg_c candidate) wm_pre (wlists_split_target_words
        (Zlength wm_pre) (lit_neg_c candidate) wm_pre wm_post ++
        (current :: nil))) = p ->
    Zlength (propagation_split_pre_caps (Zlength wm_pre)
      (lit_neg_c candidate) caps_pre destination_cap) = p ->
    propagation_real_migrated_exit_carrier n F A_arr K M0 Mentry M Mroute p
      prob learnt wm_pre wm_post caps_pre caps_post source_cap destination_cap
      candidate current source retained moved rest memory ii jj moved' rest'
      garbage' memory' simp_count prop_count.
Proof.
  intros n F A_arr K M0 Mentry M Mroute p prob learnt wm_pre wm_post
    caps_pre caps_post source_cap destination_cap candidate current source
    retained moved rest memory ii jj moved' rest' garbage' memory'
    simp_count prop_count HMroute Hstep Hshape Hseed Hcaller Hfrontier Hsem
    Hsimp Hprop Hmemory Hphysical Hwm Hcaps Hpre Hcapspre.
  unfold propagation_real_migrated_exit_carrier.
  split; [exact HMroute|]. split.
  - unfold propagation_real_migrated_transition. split; assumption.
  - split; [exact Hstep|]. split; [exact Hshape|]. split; [exact Hseed|].
    split; [exact Hcaller|]. split; [exact Hfrontier|]. split; [exact Hsem|].
    split; [exact Hsimp|]. split; [exact Hprop|]. split; [exact Hmemory|].
    split; [exact Hphysical|]. split; [exact Hwm|]. split; [exact Hcaps|].
    split; assumption.
Qed.

Lemma propagation_migrated_physical_step__propagate_dbu :
  forall source retained moved rest garbage memory candidate_memory
    migration_memory raw ii jj current,
    rest = current :: raw ->
    propagation_watch_scan_physical source retained moved rest garbage
      memory ii jj ->
    candidate_memory = memory ->
    Znth ii candidate_memory 0 = current ->
    migration_memory = replace_Znth ii (Znth ii candidate_memory 0)
      candidate_memory ->
    migration_memory = memory /\
    propagation_scan_move_step source retained moved rest memory ii jj current
      (moved ++ [current]) raw (garbage ++ [current]) /\
    propagation_watch_scan_physical source retained (moved ++ [current]) raw
      (garbage ++ [current]) migration_memory (ii + 1) jj.
Proof.
  intros source retained moved rest garbage memory candidate_memory
    migration_memory raw ii jj current Hrest Hphysical Hcandidate Hnth
    Hmigration.
  assert (Hmemory : migration_memory = memory).
  { subst candidate_memory. rewrite Hnth in Hmigration.
    rewrite <- Hnth in Hmigration.
    rewrite replace_Znth_Znth in Hmigration. exact Hmigration. }
  assert (Hstep : propagation_scan_move_step source retained moved rest memory
      ii jj current (moved ++ [current]) raw (garbage ++ [current])).
  { unfold propagation_scan_move_step. split; [exact Hrest|].
    split; [reflexivity|]. subst rest.
    unfold propagation_watch_scan_physical in Hphysical |- *.
    destruct Hphysical as [Hscan [Hmem [Hkept [Hgap Hlen]]]].
    split; [eapply wlist_scan_move; exact Hscan|].
    split.
    - rewrite Hmem. rewrite <- !app_assoc. reflexivity.
    - split; [exact Hkept|]. split.
      + assert (Hsum : Zlength retained + Zlength garbage = ii).
        { rewrite <- Zlength_app. exact Hgap. }
        rewrite !Zlength_app. cbn. lia.
      + exact Hlen. }
  split; [exact Hmemory|]. split; [exact Hstep|].
  rewrite Hmemory. exact (proj2 (proj2 Hstep)).
Qed.

Lemma propagation_move_split_shape__propagate_dbu :
  forall bound hole target pre source post capspre source_cap capspost
    current destination_cap,
    Zlength pre = hole ->
    Zlength capspre = hole ->
    Zlength (pre ++ source :: post) = bound ->
    Zlength (capspre ++ source_cap :: capspost) = bound ->
    propagation_destination_index bound hole target ->
    let destination :=
      wlists_split_target_words hole target pre post ++ [current] in
    propagation_move_wmap hole target pre source post current =
      propagation_split_pre_words hole target pre destination ++
      source :: propagation_split_post_words hole target post destination /\
    propagation_move_wcaps target capspre source_cap capspost destination_cap =
      propagation_split_pre_caps hole target capspre destination_cap ++
      source_cap :: propagation_split_post_caps hole target capspost
        destination_cap /\
    Zlength (propagation_split_pre_words hole target pre destination) = hole /\
    Zlength (propagation_split_pre_caps hole target capspre destination_cap) = hole.
Proof.
  intros bound hole target pre source post capspre source_cap capspost current
    destination_cap Hpre Hcapspre Hwm_len Hcaps_len Htarget destination.
  unfold propagation_destination_index in Htarget.
  destruct Htarget as [Hhole [Htarget Hdistinct]].
  unfold propagation_move_wmap, propagation_move_wcaps,
    propagation_split_pre_words, propagation_split_post_words,
    propagation_split_pre_caps, propagation_split_post_caps.
  destruct (Z.ltb target hole) eqn:Hside.
  - apply Z.ltb_lt in Hside.
    rewrite replace_Znth_app_l by lia.
    rewrite (replace_Znth_app_l target destination_cap capspre
      (source_cap :: capspost)) by lia.
    split; [reflexivity|]. split; [reflexivity|]. split;
      rewrite Zlength_replace_Znth; assumption.
  - apply Z.ltb_ge in Hside. assert (Hstrict : hole < target) by lia.
    rewrite replace_Znth_app_r by lia.
    rewrite (replace_Znth_app_r target destination_cap capspre
      (source_cap :: capspost)) by lia.
    rewrite Hpre, Hcapspre. rewrite !replace_Znth_cons by lia.
    rewrite replace_Znth_nothing by lia.
    rewrite (replace_Znth_nothing target capspre destination_cap) by lia.
    split; [reflexivity|]. split; [reflexivity|]. split; reflexivity.
Qed.

Lemma candidate_not_processed_neg__propagate_dbu :
  forall n assigns trail qhead candidate,
    lit_wf_c n candidate ->
    Znth (lit_var_c candidate) assigns 0 <>
      2 * lit_sign_c candidate - 1 ->
    ~ minisat_processed n assigns trail qhead
        (literal_neg (lit_denote candidate)).
Proof.
  intros n assigns trail qhead candidate Hwf Hcell Hprocessed.
  assert (Hnegwf : lit_wf_c n (lit_neg_c candidate)).
  { apply lit_neg_c_wf. exact Hwf. }
  assert (Hdenote : literal_neg (lit_denote candidate) =
      lit_denote (lit_neg_c candidate)).
  { symmetry. apply lit_denote_neg. destruct Hwf. lia. }
  rewrite Hdenote in Hprocessed.
  apply (proj1 (minisat_processed_denote n assigns trail qhead
    (lit_neg_c candidate) Hnegwf)) in Hprocessed.
  destruct Hprocessed as [Htrue Hposition]. unfold lit_true in Htrue.
  rewrite lit_var_c_neg, lit_sig_neg in Htrue.
  apply Hcell. rewrite Htrue. unfold lit_sig, lit_sign_c.
  destruct (Z.odd candidate); lia.
Qed.

Lemma propagation_migrated_frontier_transport__propagate_dbu :
  forall n M p current co a0 a1 tail watch0 false_lit candidate offset
    prob_after learnt_after,
    db_wf n (msolver_db M) ->
    In (current, co) (msolver_db M) ->
    co_lits co = a0 :: a1 :: tail ->
    2 <= offset < Zlength (a0 :: a1 :: tail) ->
    lit_wf_c n candidate ->
    Znth (lit_var_c candidate) (mt_assigns (ms_core M)) 0 <>
      2 * lit_sign_c candidate - 1 ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current
      (a0 :: a1 :: tail)
      (propagation_migrated_clause watch0 candidate false_lit offset
        (a0 :: a1 :: tail)) prob_after learnt_after ->
    minisat_watch_frontier_except n (msolver_db M)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p) ->
    minisat_watch_frontier_except n (prob_after ++ learnt_after)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p).
Proof.
  intros n M p current co a0 a1 tail watch0 false_lit candidate offset
    prob_after learnt_after Hdb Hin Hco Hoffset Hcandwf Hcandidate Hupdate
    Hfrontier.
  assert (Hnotprocessed : ~ minisat_processed n (mt_assigns (ms_core M))
      (mt_trail (ms_core M)) (mt_qhead (ms_core M))
      (literal_neg (lit_denote candidate))).
  { eapply candidate_not_processed_neg__propagate_dbu;
      eassumption. }
  pose proof Hupdate as Hu.
  destruct Hu as
    [[co' [pre [post [Hprob [Hlits [Hprob' Hlearnt']]]]]]
    |[co' [pre [post [Hlearnt [Hlits [Hprob' Hlearnt']]]]]]].
  - assert (Hcoeq : co' = co).
    { eapply db_wf_lookup_unique; [exact Hdb| |exact Hin].
      unfold msolver_db. apply in_or_app. left. rewrite Hprob.
      apply in_or_app. right. cbn. auto. }
    subst co'. subst prob_after learnt_after.
    unfold minisat_watch_frontier_except, minisat_watch_occurrences in Hfrontier |- *.
    unfold watch_frontier_except in Hfrontier |- *.
    rewrite Forall_forall in Hfrontier |- *.
    intros o Ho. apply in_map_iff in Ho as [[q obj] [<- Hentry]].
    destruct (in_app_or _ _ _ Hentry) as [Hnewprob|Hlearntold].
    + destruct (in_app_or _ _ _ Hnewprob) as [Hepre|Hecons].
      * apply Hfrontier. apply in_map. unfold msolver_db.
        apply in_or_app. left. rewrite Hprob. apply in_or_app. left. exact Hepre.
      * destruct Hecons as [Heq|Hepost].
        -- inversion Heq; subst q obj. left. intro Hboth.
           unfold minisat_occurrence_of_entry, clause_obj_with_lits,
             co_watch0, co_watch1, propagation_migrated_clause in Hboth.
           rewrite !replace_Znth_cons in Hboth by lia. cbn in Hboth.
           apply Hnotprocessed.
           change (minisat_processed n (mt_assigns (ms_core M))
             (mt_trail (ms_core M)) (mt_qhead (ms_core M))
             (literal_neg (lit_denote candidate))).
           exact (proj2 Hboth).
        -- apply Hfrontier. apply in_map. unfold msolver_db.
           apply in_or_app. left. rewrite Hprob. apply in_or_app. right.
           cbn. right. exact Hepost.
    + apply Hfrontier. apply in_map. unfold msolver_db.
      apply in_or_app. right. exact Hlearntold.
  - assert (Hcoeq : co' = co).
    { eapply db_wf_lookup_unique; [exact Hdb| |exact Hin].
      unfold msolver_db. apply in_or_app. right. rewrite Hlearnt.
      apply in_or_app. right. cbn. auto. }
    subst co'. subst prob_after learnt_after.
    unfold minisat_watch_frontier_except, minisat_watch_occurrences in Hfrontier |- *.
    unfold watch_frontier_except in Hfrontier |- *.
    rewrite Forall_forall in Hfrontier |- *.
    intros o Ho. apply in_map_iff in Ho as [[q obj] [<- Hentry]].
    destruct (in_app_or _ _ _ Hentry) as [Hprobold|Hnewlearnt].
    + apply Hfrontier. apply in_map. unfold msolver_db.
      apply in_or_app. left. exact Hprobold.
    + destruct (in_app_or _ _ _ Hnewlearnt) as [Hepre|Hecons].
      * apply Hfrontier. apply in_map. unfold msolver_db.
        apply in_or_app. right. rewrite Hlearnt. apply in_or_app. left. exact Hepre.
      * destruct Hecons as [Heq|Hepost].
        -- inversion Heq; subst q obj. left. intro Hboth.
           unfold minisat_occurrence_of_entry, clause_obj_with_lits,
             co_watch0, co_watch1, propagation_migrated_clause in Hboth.
           rewrite !replace_Znth_cons in Hboth by lia. cbn in Hboth.
           apply Hnotprocessed.
           change (minisat_processed n (mt_assigns (ms_core M))
             (mt_trail (ms_core M)) (mt_qhead (ms_core M))
             (literal_neg (lit_denote candidate))).
           exact (proj2 Hboth).
        -- apply Hfrontier. apply in_map. unfold msolver_db.
           apply in_or_app. right. rewrite Hlearnt. apply in_or_app. right.
           cbn. right. exact Hepost.
Qed.

Lemma db_pair_lits_update_focus_remove__propagate_dbu :
  forall prob learnt current old_lits new_lits prob_after learnt_after p oold,
    db_pair_lits_update prob learnt current old_lits new_lits
      prob_after learnt_after ->
    (forall co, co_lits co = old_lits ->
      minisat_entry_focus_contributions p (current, co) = [(oold, current)]) ->
    (forall co, co_lits co = old_lits ->
      minisat_entry_focus_contributions p
        (current, clause_obj_with_lits co new_lits) = []) ->
    exists pre post,
      minisat_focus_contributions (prob ++ learnt) p =
        pre ++ (oold, current) :: post /\
      minisat_focus_contributions (prob_after ++ learnt_after) p = pre ++ post.
Proof.
  intros prob learnt current old_lits new_lits prob_after learnt_after p
    oold Hupdate Hold Hnew.
  destruct Hupdate as
    [[co [pre [post [Hprob [Hlits [Hprob' Hlearnt']]]]]]
    |[co [pre [post [Hlearnt [Hlits [Hprob' Hlearnt']]]]]]].
  - subst prob prob_after learnt_after.
    exists (minisat_focus_contributions pre p),
      (minisat_focus_contributions post p ++
       minisat_focus_contributions learnt p).
    rewrite !minisat_focus_contributions_app__propagate_dbu.
    rewrite !minisat_focus_contributions_cons__propagate_dbu.
    rewrite (Hold co Hlits), (Hnew co Hlits). cbn.
    split; rewrite <- app_assoc; reflexivity.
  - subst learnt prob_after learnt_after.
    exists (minisat_focus_contributions prob p ++
      minisat_focus_contributions pre p),
      (minisat_focus_contributions post p).
    rewrite !minisat_focus_contributions_app__propagate_dbu.
    rewrite !minisat_focus_contributions_cons__propagate_dbu.
    rewrite (Hold co Hlits), (Hnew co Hlits). cbn.
    split; rewrite <- app_assoc; reflexivity.
Qed.

Lemma propagation_migrated_focus_transport__propagate_dbu :
  forall n M p current co a0 a1 tail watch0 false_lit candidate offset
    prob_after learnt_after P kept rest,
    db_wf n (msolver_db M) ->
    In (current, co) (msolver_db M) ->
    co_lits co = a0 :: a1 :: tail ->
    ((a0 = false_lit /\ watch0 = a1) \/
     (a1 = false_lit /\ watch0 = a0)) ->
    lit_wf_c n p ->
    false_lit = lit_neg_c p ->
    2 <= offset < Zlength (a0 :: a1 :: tail) ->
    lit_neg_c watch0 <> p ->
    lit_neg_c candidate <> p ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current
      (a0 :: a1 :: tail)
      (propagation_migrated_clause watch0 candidate false_lit offset
        (a0 :: a1 :: tail)) prob_after learnt_after ->
    minisat_focus_scan_carrier (msolver_db M) p P kept (current :: rest) ->
    minisat_focus_scan_carrier (prob_after ++ learnt_after) p P kept rest.
Proof.
  intros n M p current co a0 a1 tail watch0 false_lit candidate offset
    prob_after learnt_after P kept rest Hdb Hin Hco Hcases Hp Hfalse Hoffset
    Hwatchneq Hcandneq Hupdate Hscan.
  assert (Hnegfalse : lit_neg_c false_lit = p).
  { rewrite Hfalse. apply lit_neg_c_involutive. }
  assert (Holdlen : (3 <=? Zlength (a0 :: a1 :: tail))%Z = true).
  { apply Z.leb_le. lia. }
  assert (Hnewlen :
      (3 <=? Zlength (propagation_migrated_clause watch0 candidate false_lit
        offset (a0 :: a1 :: tail)))%Z = true).
  { apply Z.leb_le. rewrite propagation_migrated_clause_length by lia. lia. }
  set (oold := minisat_occurrence_of_entry (current, co)).
  assert (Hold : forall co', co_lits co' = a0 :: a1 :: tail ->
      minisat_entry_focus_contributions p (current, co') = [(oold, current)]).
  { intros co' Hco'. unfold minisat_entry_focus_contributions, entry_watchers.
    unfold oold, minisat_occurrence_of_entry, denote_obj, co_watch0, co_watch1.
    rewrite Hco', Hco, Holdlen.
    rewrite !Znth0_cons.
    rewrite !Znth_cons by lia.
    replace (1 - 1) with 0 by lia. rewrite !Znth0_cons.
    cbn [fst snd].
    destruct Hcases as [[Ha0 Hw]|[Ha1 Hw]]; subst.
    - cbn. rewrite Hnegfalse.
      destruct (lit_neg_c a1 =? p)%Z eqn:Hb; cbn.
      + apply Z.eqb_eq in Hb. contradiction.
      + rewrite Z.eqb_refl. reflexivity.
    - cbn. rewrite Hnegfalse.
      destruct (lit_neg_c a0 =? p)%Z eqn:Hb; cbn.
      + apply Z.eqb_eq in Hb. contradiction.
      + rewrite Z.eqb_refl. reflexivity. }
  assert (Hnew : forall co', co_lits co' = a0 :: a1 :: tail ->
      minisat_entry_focus_contributions p
        (current, clause_obj_with_lits co'
          (propagation_migrated_clause watch0 candidate false_lit offset
            (a0 :: a1 :: tail))) = []).
  { intros co' Hco'.
    set (new_lits := propagation_migrated_clause watch0 candidate false_lit
      offset (a0 :: a1 :: tail)).
    assert (Hwatch0new :
      co_watch0 (clause_obj_with_lits co' new_lits) = watch0).
    { unfold co_watch0, clause_obj_with_lits, new_lits,
        propagation_migrated_clause.
      rewrite replace_Znth_cons by lia. reflexivity. }
    assert (Hwatch1new :
      co_watch1 (clause_obj_with_lits co' new_lits) = candidate).
    { unfold co_watch1, clause_obj_with_lits, new_lits,
        propagation_migrated_clause.
      rewrite !replace_Znth_cons by lia. cbn [Pos.to_nat]. reflexivity. }
    change (minisat_entry_focus_contributions p
      (current, clause_obj_with_lits co' new_lits) = []).
    unfold minisat_entry_focus_contributions, entry_watchers. cbn [fst snd].
    rewrite Hwatch0new, Hwatch1new.
    destruct (lit_neg_c watch0 =? p)%Z eqn:Hwb; cbn.
    - apply Z.eqb_eq in Hwb. contradiction.
    - destruct (lit_neg_c candidate =? p)%Z eqn:Hcb; cbn.
      + apply Z.eqb_eq in Hcb. contradiction.
      + reflexivity. }
  destruct (db_pair_lits_update_focus_remove__propagate_dbu
    (ms_prob M) (ms_learnt M) current (a0 :: a1 :: tail)
    (propagation_migrated_clause watch0 candidate false_lit offset
      (a0 :: a1 :: tail)) prob_after learnt_after p oold Hupdate Hold Hnew)
    as [pre [post [Hfocusold Hfocusnew]]].
  eapply focus_scan_carrier_db_pair_token_remove__propagate_dbu
    with (current := current) (co := co) (pre := pre) (post := post).
  - exact Hdb.
  - exact Hin.
  - apply even_not_tag. eapply db_wf_even; eassumption.
  - exact Hfocusold.
  - exact Hfocusnew.
  - exact Hscan.
Qed.

Lemma propagation_migrated_scan_semantics__propagate_dbu :
  forall n F A_arr K M p kept current rest prob_after learnt_after wm_after
    wcaps_after,
    solver_propagation_scan_semantics n F A_arr K M p 0 kept (current :: rest) ->
    solver_propagation_weak n F A_arr K
      (msolver_propagation_db_wmap_update
        M prob_after learnt_after wm_after wcaps_after) ->
    minisat_watch_frontier_except n (prob_after ++ learnt_after)
      (mt_assigns (ms_core M)) (mt_trail (ms_core M))
      (mt_qhead (ms_core M)) (lit_denote p) ->
    minisat_focus_scan_carrier (prob_after ++ learnt_after) p
      (minisat_processed n (mt_assigns (ms_core M))
        (mt_trail (ms_core M)) (mt_qhead (ms_core M))) kept rest ->
    solver_propagation_scan_semantics n F A_arr K
      (msolver_propagation_db_wmap_update
        M prob_after learnt_after wm_after wcaps_after) p 0 kept rest.
Proof.
  intros n F A_arr K M p kept current rest prob_after learnt_after wm_after
    wcaps_after Hsem Hweak Hfrontier Hcarrier.
  destruct Hsem as [Hlive|Hdead].
  2: { destruct Hdead as [Hnz Hnil]. lia. }
  destruct Hlive as [Hzero [Hweakold [Hlevel [Hheap [Hcovers [Hreasonless
    [Hlevelp [Hpwf [Hprocessed [Hfrontierold Hcarrierold]]]]]]]]]].
  left. split; [reflexivity|].
  exact (conj Hweak (conj Hlevel (conj Hheap (conj Hcovers (conj Hreasonless
    (conj Hlevelp (conj Hpwf (conj Hprocessed (conj Hfrontier Hcarrier))))))))).
Qed.

Lemma solver_propagation_weak_db_wmap_move__propagate_dbu :
  forall n F A_arr K M current old_lits new_lits prob_after learnt_after
    wm_after wcaps_after,
    solver_propagation_weak n F A_arr K M ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current old_lits new_lits
      prob_after learnt_after ->
    Permutation new_lits old_lits ->
    (forall v, 0 <= v < n -> Znth v (ms_reason_words M) 0 <> current) ->
    Zlength wm_after = Zlength (ms_wm M) ->
    Zlength wcaps_after = Zlength (ms_wcaps M) ->
    wmap_exact n (prob_after ++ learnt_after) wm_after ->
    solver_propagation_weak n F A_arr K
      (msolver_propagation_db_wmap_update
        M prob_after learnt_after wm_after wcaps_after).
Proof.
  intros n F A_arr K M current old_lits new_lits prob_after learnt_after
    wm_after wcaps_after [Hpending Hweak] Hupdate Hperm Hnoowner Hwmlen
    Hcapslen Hwmap.
  split; [exact Hpending|]. clear Hpending.
  revert Hweak Hupdate Hperm Hnoowner Hwmlen Hcapslen Hwmap.
  revert M current old_lits new_lits prob_after learnt_after wm_after
    wcaps_after.
  destruct K as [A_x|A_x]; cbn; revert n F A_arr A_x.
  - msat_inv_db_wmap_move msw_db_wf msw_db_matches msw_db_implied
      msw_db_complete msw_prob_db msw_learnt_db msw_binary_out msw_reasons_mem
      msw_reason_head msw_size msw_shape.
  - msat_inv_db_wmap_move msa_db_wf msa_db_matches msa_db_implied
      msa_db_complete msa_prob_db msa_learnt_db msa_binary_out msa_reasons_mem
      msa_reason_head msa_size msa_shape.
Qed.

(** ===== group: solver_propagate_db_update_reason_owner ===== *)
(** The shared core of the two [no_live_reason_owner_*] lemmas below.  If [v]
    names [current] as its reason word then [current] is a real (non-tag)
    clause pointer, so [reason_word_ok] resolves it -- uniquely, by
    [db_wf_lookup_unique] -- to [co], [v] is assigned and on the trail, and
    [stable_view]'s ground component hands back [co]'s denotation as a valid
    reason for [v].  Both callers refute that [reason_valid] payload; they
    differ only in which part of it they contradict. *)
Lemma reason_owner_valid__propagate_dbu :
  forall n M current co v,
    db_wf n (msolver_db M) ->
    mtrail_wf n (ms_core M) ->
    stable_view (msolver_view n M) ->
    reasons_match n (ms_core M) (msolver_db M)
      (ms_reason_words M) (ms_reason_of M) ->
    In (current, co) (msolver_db M) ->
    0 <= v < n ->
    Znth v (ms_reason_words M) 0 = current ->
    exists b,
      mt_pv (ms_core M) v = Some b /\
      reason_valid (msolver_view n M) v (denote_obj co).
Proof.
  intros n M current co v Hdbwf Htrail Hstable Hreasons Hin Hv Heq.
  pose proof (db_wf_ptr_pos n (msolver_db M) current co Hdbwf Hin) as Hpos.
  pose proof (db_wf_even n (msolver_db M) current co Hdbwf Hin) as Heven.
  assert (Hreal : is_tag current = false).
  { apply even_not_tag. exact Heven. }
  specialize (Hreasons v Hv).
  unfold reason_word_ok in Hreasons. rewrite Heq in Hreasons.
  assert (Hnz : (current =? 0)%Z = false) by (apply Z.eqb_neq; lia).
  rewrite Hnz, Hreal in Hreasons.
  destruct Hreasons as [Hvassigned [co' [Hlookup Hr]]].
  assert (Hcoeq : co' = co).
  { unfold db_lookup in Hlookup.
    eapply db_wf_lookup_unique; [exact Hdbwf|exact Hlookup|exact Hin]. }
  subst co'.
  assert (Hpv : exists b, mt_pv (ms_core M) v = Some b).
  { pose proof (Forall_Znth_elim Z lbool_cell
      (mt_assigns (ms_core M)) 0 v (mtw_cells Htrail)
      ltac:(rewrite (mtw_assigns_len Htrail); exact Hv)) as Hcell.
    unfold lbool_cell in Hcell.
    destruct Hcell as [Hcell|[Hcell|Hcell]].
    - exists false. rewrite mt_pv_nonneg by lia. rewrite Hcell. reflexivity.
    - contradiction.
    - exists true. rewrite mt_pv_nonneg by lia. rewrite Hcell. reflexivity. }
  destruct Hpv as [b Hpv].
  assert (Htp : exists pos, trail_pos (ms_core M) v = Some pos).
  { destruct (trail_pos (ms_core M) v) as [pos|] eqn:Htp.
    - exists pos. reflexivity.
    - exfalso. apply trail_pos_none_iff in Htp. apply Htp.
      apply (proj1 (mtw_assigned_iff Htrail v Hv)). exact Hvassigned. }
  destruct Htp as [pos Htp].
  unfold stable_view in Hstable. destruct Hstable as [Hground _].
  specialize (Hground v b Hpv).
  destruct Hground as [d [rx [_ [_ [Hnone|[C [HC Hvalid]]]]]]].
  - unfold msolver_view, view_of in Hnone; cbn in Hnone.
    rewrite Htp, Hr in Hnone. discriminate.
  - unfold msolver_view, view_of in HC; cbn in HC.
    rewrite Htp, Hr in HC. inversion HC; subst C.
    exists b. split; [exact Hpv|exact Hvalid].
Qed.

(** First consumer of the core: the reason clause of [v] has every literal
    other than [v]'s own false under the trail, so a literal that is NOT
    false cannot belong to it. *)
Lemma no_live_reason_owner_candidate_not_false__propagate_dbu :
  forall n M current co candidate,
    n = ms_size M ->
    db_wf n (msolver_db M) ->
    mtrail_wf n (ms_core M) ->
    stable_view (msolver_view n M) ->
    reasons_match n (ms_core M) (msolver_db M)
      (ms_reason_words M) (ms_reason_of M) ->
    reason_head_ok M ->
    In (current, co) (msolver_db M) ->
    In candidate (co_lits co) ->
    lit_wf_c n candidate ->
    lit_var_c candidate <> lit_var_c (co_watch0 co) ->
    Znth (lit_var_c candidate) (mt_assigns (ms_core M)) 0 <>
      2 * lit_sign_c candidate - 1 ->
    forall v, 0 <= v < n -> Znth v (ms_reason_words M) 0 <> current.
Proof.
  intros n M current co candidate Hsize Hdbwf Htrail Hstable Hreasons Hhead
    Hin Hcandin Hcandwf Hvardiff Hcandidate v Hv Heq.
  pose proof (db_wf_ptr_pos n (msolver_db M) current co Hdbwf Hin) as Hpos.
  assert (Hreal : is_tag current = false).
  { apply even_not_tag.
    exact (db_wf_even n (msolver_db M) current co Hdbwf Hin). }
  assert (Hheadvar : lit_var_c (co_watch0 co) = v).
  { apply (Hhead v co).
    - rewrite <- Hsize. exact Hv.
    - rewrite Heq. exact Hreal.
    - rewrite Heq. lia.
    - rewrite Heq. exact Hin. }
  destruct (reason_owner_valid__propagate_dbu
    n M current co v Hdbwf Htrail Hstable Hreasons Hin Hv Heq)
    as [b [Hpv Hvalid]].
  destruct Hvalid as [b' [d' [rx' [Hpv' [Hlevel' [Hrank' [Hsat Hside]]]]]]].
  change (mt_pv (ms_core M) v = Some b') in Hpv'.
  rewrite Hpv in Hpv'. inversion Hpv'; subst b'.
  assert (Hlitin : In (lit_denote candidate) (denote_obj co)).
  { unfold denote_obj. apply lits_denote_in. exact Hcandin. }
  specialize (Hside (lit_denote candidate) Hlitin).
  assert (Hvarneq : literal_var (lit_denote candidate) <> v).
  { rewrite lit_var_c_denote, <- Hheadvar. exact Hvardiff. }
  specialize (Hside Hvarneq). destruct Hside as [Heval Hrankside].
  unfold msolver_view, view_of in Heval. cbn in Heval.
  assert (Hvarnonneg : 0 <= lit_var_c candidate).
  { eapply lit_var_c_nonneg. exact Hcandwf. }
  assert (Heqeval :
    eval_partial_literal (mt_pv (ms_core M)) (lit_denote candidate) =
    eval_partial_literal (assigns_pv (mt_assigns (ms_core M)))
      (lit_denote candidate)).
  { unfold eval_partial_literal. rewrite lit_var_c_denote.
    rewrite mt_pv_nonneg by exact Hvarnonneg. reflexivity. }
  rewrite Heqeval in Heval.
  assert (Hcandnonneg : 0 <= candidate) by (destruct Hcandwf; lia).
  apply (proj2 (lit_false_iff (mt_assigns (ms_core M)) candidate
    Hcandnonneg)) in Heval.
  apply Hcandidate. rewrite Heval.
  unfold lit_sig, lit_sign_c. destruct (Z.odd candidate); lia.
Qed.

(** Second consumer of the core, and the sibling of the lemma above: same
    conclusion, different context.  There the clause holds a candidate literal
    that is not (yet) false; here the whole clause is already false under the
    trail.  The contradiction is with [reason_valid]'s satisfying literal
    rather than with its side condition: [v]'s own satisfying literal belongs
    to [denote_obj co], so the hypothesis makes it [Some false] while
    [eval_satisfying_literal_true] makes it [Some true].  The two contexts are
    not inter-derivable -- a false clause has no not-false candidate to feed
    the lemma above -- which is why this is a separate statement and not an
    instance.  Consumed by [propagation_normalized_conflict_scan_facts] in this file. *)
Lemma no_live_reason_owner_false_clause__propagate_dbu :
  forall n M current co,
    db_wf n (msolver_db M) ->
    mtrail_wf n (ms_core M) ->
    stable_view (msolver_view n M) ->
    reasons_match n (ms_core M) (msolver_db M)
      (ms_reason_words M) (ms_reason_of M) ->
    In (current, co) (msolver_db M) ->
    Forall (fun l => eval_partial_literal (mt_pv (ms_core M)) l = Some false)
      (denote_obj co) ->
    forall v, 0 <= v < n -> Znth v (ms_reason_words M) 0 <> current.
Proof.
  intros n M current co Hdbwf Htrail Hstable Hreasons Hin Hden_false v Hv Heq.
  destruct (reason_owner_valid__propagate_dbu
    n M current co v Hdbwf Htrail Hstable Hreasons Hin Hv Heq)
    as [b [Hpv Hvalid]].
  destruct Hvalid as [b' [d' [rx' [Hpv' [_ [_ [Hsat _]]]]]]].
  change (mt_pv (ms_core M) v = Some b') in Hpv'.
  rewrite Hpv in Hpv'. inversion Hpv'; subst b'.
  rewrite Forall_forall in Hden_false.
  pose proof (Hden_false (satisfying_literal v b) Hsat) as Hfalse.
  pose proof (eval_satisfying_literal_true (mt_pv (ms_core M)) v b Hpv)
    as Htrue.
  congruence.
Qed.

Lemma db_pair_lits_update_wmap_move__propagate_dbu :
  forall n prob learnt current old_lits new_lits prob_after learnt_after
    oldwm newwm co,
    db_wf n (prob ++ learnt) ->
    In (current, co) (prob ++ learnt) ->
    co_lits co = old_lits ->
    db_pair_lits_update prob learnt current old_lits new_lits
      prob_after learnt_after ->
    wmap_exact n (prob ++ learnt) oldwm ->
    Zlength newwm = 2 * n ->
    (forall l, 0 <= l < 2 * n ->
      Permutation
        (Znth l newwm nil ++ entry_watchers (current, co) l)
        (Znth l oldwm nil ++ entry_watchers
          (current, clause_obj_with_lits co new_lits) l)) ->
    wmap_exact n (prob_after ++ learnt_after) newwm.
Proof.
  intros n prob learnt current old_lits new_lits prob_after learnt_after
    oldwm newwm co Hdbwf Hin Hco Hupdate Hold Hlen Hdiff.
  destruct Hupdate as
    [[co' [pre [post [Hprob [Hco' [Hprob' Hlearnt']]]]]]
    |[co' [pre [post [Hlearnt [Hco' [Hprob' Hlearnt']]]]]]].
  - assert (Heq : co' = co).
    { eapply db_wf_lookup_unique; [exact Hdbwf| |exact Hin].
      rewrite Hprob. apply in_or_app. left. apply in_or_app. right. cbn. auto. }
    subst co'. subst prob prob_after learnt_after. rewrite Hco in Hco'.
    rewrite <- app_assoc in Hold |- *.
    eapply wmap_move; [exact Hold|exact Hlen|].
    intros l Hl. apply Hdiff. exact Hl.
  - assert (Heq : co' = co).
    { eapply db_wf_lookup_unique; [exact Hdbwf| |exact Hin].
      rewrite Hlearnt. apply in_or_app. right.
      apply in_or_app. right. cbn. auto. }
    subst co'. subst learnt prob_after learnt_after. rewrite Hco in Hco'.
    rewrite !app_assoc in Hold |- *.
    eapply wmap_move; [exact Hold|exact Hlen|].
    intros l Hl. apply Hdiff. exact Hl.
Qed.

Lemma propagation_move_wmap_cells__propagate_dbu :
  forall n M hole target pre source post capspre source_cap capspost
    newsource current co new_lits,
    propagation_scan_slot M hole pre source post
      capspre source_cap capspost ->
    0 <= hole < 2 * n ->
    propagation_destination_index (2 * n) hole target ->
    Permutation (newsource ++ [current]) source ->
    (forall l,
      Permutation
        (entry_watchers (current, co) l ++
         (if (l =? target)%Z then [current] else []))
        (entry_watchers (current, clause_obj_with_lits co new_lits) l ++
         (if (l =? hole)%Z then [current] else []))) ->
    Zlength (ms_wm M) = 2 * n ->
    Zlength (propagation_move_wmap hole target pre newsource post current) =
      2 * n /\
    forall l, 0 <= l < 2 * n ->
      Permutation
        (Znth l (propagation_move_wmap hole target pre newsource post current)
           nil ++ entry_watchers (current, co) l)
        (Znth l (ms_wm M) nil ++
         entry_watchers (current, clause_obj_with_lits co new_lits) l).
Proof.
  intros n M hole target pre source post capspre source_cap capspost
    newsource current co new_lits Hslot Hhole Htarget Hsource Hentry Hlen.
  destruct Hslot as [Hwm [Hcaps [Hpre Hcapspre]]].
  unfold propagation_destination_index in Htarget.
  destruct Htarget as [Hholenonneg [Htargetrange Hdistinct]].
  assert (Hbase : pre ++ newsource :: post =
      replace_Znth hole newsource (ms_wm M)).
  { rewrite Hwm. rewrite replace_Znth_app_r by (rewrite Hpre; lia).
    rewrite replace_Znth_nothing by (rewrite Hpre; lia).
    rewrite Hpre. replace (hole - hole) with 0 by lia. cbn. reflexivity. }
  assert (Htargetold : Znth target (ms_wm M) nil =
      wlists_split_target_words hole target pre post).
  { rewrite Hwm. unfold wlists_split_target_words.
    destruct (Z.ltb target hole) eqn:Hside.
    - apply Z.ltb_lt in Hside. rewrite app_Znth1 by (rewrite Hpre; lia).
      reflexivity.
    - apply Z.ltb_ge in Hside. assert (hole < target) by lia.
      rewrite app_Znth2 by (rewrite Hpre; lia).
      rewrite Hpre. replace (target - hole) with
        ((target - hole - 1) + 1) by lia.
      rewrite Znth_cons by lia. reflexivity. }
  assert (Hnewlen : Zlength
      (propagation_move_wmap hole target pre newsource post current) = 2 * n).
  { unfold propagation_move_wmap. rewrite !Zlength_replace_Znth.
    rewrite Hbase. rewrite Zlength_replace_Znth. exact Hlen. }
  split; [exact Hnewlen|]. intros l Hl.
  unfold propagation_move_wmap.
  destruct (Z.eq_dec l target) as [Hltarget|Hltarget].
  - subst l. rewrite Znth_replace_Znth_Same by
      (rewrite Hbase, Zlength_replace_Znth, Hlen; exact Htargetrange).
    rewrite Htargetold.
    specialize (Hentry target).
    rewrite Z.eqb_refl in Hentry.
    assert (Hth : (target =? hole)%Z = false)
      by (apply Z.eqb_neq; exact Hdistinct).
    rewrite Hth, app_nil_r in Hentry.
    rewrite <- app_assoc. apply Permutation_app_head.
    eapply Permutation_trans.
    + apply Permutation_app_comm.
    + exact Hentry.
  - rewrite Znth_replace_Znth_Diff.
    2: { rewrite Hbase, Zlength_replace_Znth, Hlen. exact Htargetrange. }
    2: { rewrite Hbase, Zlength_replace_Znth, Hlen. exact Hl. }
    2: { congruence. }
    destruct (Z.eq_dec l hole) as [Hlholes|Hlholes].
    + subst l. rewrite Hbase.
      rewrite Znth_replace_Znth_Same by (rewrite Hlen; exact Hhole).
      rewrite Hwm. rewrite app_Znth2 by (rewrite Hpre; lia).
      rewrite Hpre. replace (hole - hole) with 0 by lia. cbn.
      specialize (Hentry hole).
      assert (Hht : (hole =? target)%Z = false)
        by (apply Z.eqb_neq; congruence).
      rewrite Hht, Z.eqb_refl, app_nil_r in Hentry.
      eapply Permutation_trans.
      * apply Permutation_app_head. exact Hentry.
      * eapply Permutation_trans.
        -- apply Permutation_app_head. apply Permutation_app_comm.
        -- rewrite app_assoc. apply Permutation_app_tail. exact Hsource.
    + rewrite Hbase.
      rewrite Znth_replace_Znth_Diff.
      2: { rewrite Hlen. exact Hhole. }
      2: { rewrite Hlen. exact Hl. }
      2: { congruence. }
      specialize (Hentry l).
      assert (Hlt : (l =? target)%Z = false)
        by (apply Z.eqb_neq; exact Hltarget).
      assert (Hlh : (l =? hole)%Z = false)
        by (apply Z.eqb_neq; exact Hlholes).
      rewrite Hlt, Hlh, !app_nil_r in Hentry.
      apply Permutation_app_head. exact Hentry.
Qed.

Lemma propagation_migrated_entry_watchers_delta__propagate_dbu :
  forall n p current co a0 a1 tail watch0 false_lit candidate offset,
    lit_wf_c n p ->
    false_lit = lit_neg_c p ->
    co_lits co = a0 :: a1 :: tail ->
    ((a0 = false_lit /\ watch0 = a1) \/
     (a1 = false_lit /\ watch0 = a0)) ->
    2 <= offset < Zlength (a0 :: a1 :: tail) ->
    forall l,
      Permutation
        (entry_watchers (current, co) l ++
         (if (l =? lit_neg_c candidate)%Z then [current] else []))
        (entry_watchers
           (current, clause_obj_with_lits co
             (propagation_migrated_clause watch0 candidate false_lit offset
               (a0 :: a1 :: tail))) l ++
         (if (l =? p)%Z then [current] else [])).
Proof.
  intros n p current co a0 a1 tail watch0 false_lit candidate offset
    Hp Hfalse Hco Hcases Hoffset l.
  assert (Hnegfalse : lit_neg_c false_lit = p).
  { rewrite Hfalse. apply lit_neg_c_involutive. }
  assert (Hnewlen :
      (3 <=? Zlength (propagation_migrated_clause watch0 candidate false_lit
        offset (a0 :: a1 :: tail)))%Z = true).
  { apply Z.leb_le. rewrite propagation_migrated_clause_length by lia. lia. }
  assert (Holdlen : (3 <=? Zlength (a0 :: a1 :: tail))%Z = true).
  { apply Z.leb_le. lia. }
  unfold entry_watchers, co_watch0, co_watch1.
  cbn [fst snd]. rewrite Hco, Holdlen.
  unfold clause_obj_with_lits. cbn [co_lits]. rewrite Hnewlen.
  unfold propagation_migrated_clause.
  rewrite !replace_Znth_cons by lia.
  rewrite !Znth0_cons.
  rewrite !Znth_cons by lia.
  replace (1 - 1) with 0 by lia. rewrite !Znth0_cons.
  destruct Hcases as [[Ha0 Hw]|[Ha1 Hw]].
  - subst a0. subst a1. rewrite Hnegfalse. change (Permutation
      (((if (p =? l)%Z then [current] else []) ++
        (if (lit_neg_c watch0 =? l)%Z then [current] else [])) ++
       (if (l =? lit_neg_c candidate)%Z then [current] else []))
      (((if (lit_neg_c watch0 =? l)%Z then [current] else []) ++
        (if (lit_neg_c candidate =? l)%Z then [current] else [])) ++
       (if (l =? p)%Z then [current] else []))).
    rewrite Z.eqb_sym with (x := l) (y := lit_neg_c candidate).
    rewrite Z.eqb_sym with (x := l) (y := p).
    rewrite <- app_assoc. apply Permutation_app_comm.
  - subst a1. subst a0. rewrite Hnegfalse. change (Permutation
      (((if (lit_neg_c watch0 =? l)%Z then [current] else []) ++
        (if (p =? l)%Z then [current] else [])) ++
       (if (l =? lit_neg_c candidate)%Z then [current] else []))
      (((if (lit_neg_c watch0 =? l)%Z then [current] else []) ++
        (if (lit_neg_c candidate =? l)%Z then [current] else [])) ++
       (if (l =? p)%Z then [current] else []))).
    rewrite Z.eqb_sym with (x := l) (y := lit_neg_c candidate).
    rewrite Z.eqb_sym with (x := l) (y := p).
    rewrite <- app_assoc. rewrite <- app_assoc. apply Permutation_app_head.
    apply Permutation_app_comm.
Qed.

Lemma propagation_migrated_clause_structure__propagate_dbu :
  forall n M p current contents watch0 false_lit lits stop k offset candidate sig
    prob_after learnt_after,
    db_wf n (msolver_db M) ->
    propagation_scan_candidate_layout current lits stop k offset false_lit p
      candidate sig contents ->
    real_watch_pair p contents ->
    watch0 + false_lit = Znth 0 contents 0 + Znth 1 contents 0 ->
    db_pair_lits_update (ms_prob M) (ms_learnt M) current contents
      (propagation_migrated_clause watch0 candidate false_lit offset contents)
      prob_after learnt_after ->
    exists co a0 a1 tail,
      contents = a0 :: a1 :: tail /\
      In (current, co) (msolver_db M) /\
      co_lits co = a0 :: a1 :: tail /\
      sublist 2 (Zlength contents) contents = tail /\
      ((a0 = false_lit /\ watch0 = a1) \/
       (a1 = false_lit /\ watch0 = a0)) /\
      candidate = Znth (offset - 2) tail 0 /\
      In candidate (co_lits co) /\
      lit_wf_c n candidate /\
      lit_var_c candidate <> lit_var_c (co_watch0 co) /\
      lit_neg_c watch0 <> p /\
      lit_neg_c candidate <> p /\
      Permutation
        (propagation_migrated_clause watch0 candidate false_lit offset contents)
        contents.
Proof.
  intros n M p current contents watch0 false_lit lits stop k offset candidate
    sig prob_after learnt_after Hdbwf Hlayout Hreal Hsum Hupdate.
  unfold propagation_scan_candidate_layout in Hlayout.
  destruct Hlayout as
    [Hlits [Hlen [Hfalse [Hstop [Hk [Hoffset [Hcandidate Hsig]]]]]]].
  assert (Hselected : exists co,
      In (current, co) (msolver_db M) /\ co_lits co = contents).
  { pose proof Hupdate as Hu.
    destruct Hu as
      [[co [pre [post [Hprob [Hco [Hp Hl]]]]]]
      |[co [pre [post [Hlearnt [Hco [Hp Hl]]]]]]].
    - exists co. split; [|exact Hco]. unfold msolver_db.
      apply in_or_app. left. rewrite Hprob. apply in_or_app. right. cbn. auto.
    - exists co. split; [|exact Hco]. unfold msolver_db.
      apply in_or_app. right. rewrite Hlearnt. apply in_or_app. right. cbn. auto. }
  destruct Hselected as [co [Hin Hco]].
  pose proof (db_wf_obj n (msolver_db M) current co Hdbwf Hin) as Hobj.
  unfold obj_wf in Hobj. rewrite Hco in Hobj.
  destruct Hobj as [Hobjlen [Hall Hnodup]].
  destruct contents as [|a0 tail0]; cbn in Hobjlen; [lia|].
  destruct tail0 as [|a1 tail]; cbn in Hobjlen; [lia|].
  assert (Htail : sublist 2 (Zlength (a0 :: a1 :: tail))
      (a0 :: a1 :: tail) = tail).
  { replace (a0 :: a1 :: tail) with ((a0 :: a1 :: nil) ++ tail)
      by reflexivity.
    rewrite (sublist_split_app_r 2
      (Zlength ((a0 :: a1 :: nil) ++ tail)) 2
      (a0 :: a1 :: nil) tail ltac:(reflexivity)) by
      (split; [lia|rewrite Zlength_app, !Zlength_cons, Zlength_nil;
        pose proof (Zlength_nonneg tail); lia]).
    replace (Zlength ((a0 :: a1 :: nil) ++ tail) - 2)
      with (Zlength tail) by
      (rewrite Zlength_app, !Zlength_cons, Zlength_nil; lia).
    apply sublist_self. reflexivity. }
  rewrite Htail in Hcandidate.
  assert (Hwatchcases :
      (a0 = false_lit /\ watch0 = a1) \/
      (a1 = false_lit /\ watch0 = a0)).
  { unfold real_watch_pair in Hreal.
    rewrite !Znth0_cons in Hreal, Hsum.
    rewrite !Znth_cons in Hreal, Hsum by lia.
    replace (1 - 1) with 0 in Hreal, Hsum by lia.
    rewrite !Znth0_cons in Hreal, Hsum.
    destruct Hreal as [Hw|Hw].
    - left. rewrite <- Hfalse in Hw. split; [exact Hw|lia].
    - right. rewrite <- Hfalse in Hw. split; [exact Hw|lia]. }
  inversion Hnodup as [|v0 vars0 Hnot0 Hnd0]; subst v0 vars0.
  inversion Hnd0 as [|v1 vars1 Hnot1 Hndtail]; subst v1 vars1.
  assert (Hcandrange : 0 <= offset - 2 < Zlength tail).
  { rewrite <- Htail, Zlength_sublist by lia. lia. }
  assert (Hcandin : In candidate tail).
  { rewrite Hcandidate. apply Znth_In. exact Hcandrange. }
  assert (Hcandvarin : In (lit_var_c candidate) (map lit_var_c tail)).
  { apply in_map. exact Hcandin. }
  assert (Hcandinco : In candidate (co_lits co)).
  { rewrite Hco. cbn. right. right. exact Hcandin. }
  assert (Hcandwf : lit_wf_c n candidate).
  { rewrite Forall_forall in Hall. apply Hall.
    cbn. right. right. exact Hcandin. }
  assert (Hvardiff01 : lit_var_c a0 <> lit_var_c a1).
  { intro Heq. apply Hnot0. cbn. left. symmetry. exact Heq. }
  assert (Hvardiff0c : lit_var_c a0 <> lit_var_c candidate).
  { intro Heq. apply Hnot0. cbn. right. rewrite Heq. exact Hcandvarin. }
  assert (Hvardiff1c : lit_var_c a1 <> lit_var_c candidate).
  { intro Heq. apply Hnot1. rewrite Heq. exact Hcandvarin. }
  assert (Hwatchneq : lit_neg_c watch0 <> p).
  { intro Heq. apply Hvardiff01.
    pose proof (f_equal lit_var_c Heq) as Hv.
    rewrite lit_var_c_neg in Hv.
    assert (Hfv : lit_var_c false_lit = lit_var_c p).
    { rewrite Hfalse, lit_var_c_neg. reflexivity. }
    destruct Hwatchcases as [[Ha Hw]|[Ha Hw]]; subst; lia. }
  assert (Hcandneq : lit_neg_c candidate <> p).
  { intro Heq. pose proof (f_equal lit_var_c Heq) as Hv.
    rewrite lit_var_c_neg in Hv.
    assert (Hfv : lit_var_c false_lit = lit_var_c p).
    { rewrite Hfalse, lit_var_c_neg. reflexivity. }
    destruct Hwatchcases as [[Ha Hw]|[Ha Hw]]; subst;
      [apply Hvardiff0c|apply Hvardiff1c]; lia. }
  assert (Hcandhead : lit_var_c candidate <> lit_var_c (co_watch0 co)).
  { unfold co_watch0. rewrite Hco. cbn. congruence. }
  assert (Hpermnorm : Permutation (watch0 :: false_lit :: tail)
      (a0 :: a1 :: tail)).
  { destruct Hwatchcases as [[Ha Hw]|[Ha Hw]]; subst.
    - apply perm_swap. - reflexivity. }
  assert (Hperm_move : Permutation
      (propagation_migrated_clause watch0 candidate false_lit offset
        (a0 :: a1 :: tail))
      (watch0 :: false_lit :: tail)).
  { unfold propagation_migrated_clause. rewrite Htail.
    rewrite !replace_Znth_cons by lia.
    apply perm_skip.
    eapply Permutation_trans.
    - apply perm_skip.
      replace (offset - 1 - 1) with (offset - 2) by lia.
      apply (list_without_Znth_replace_perm 0 false_lit
        (offset - 2) tail Hcandrange).
    - eapply Permutation_trans.
      + apply perm_swap.
      + apply perm_skip. apply Permutation_sym.
        rewrite Hcandidate.
        apply (list_without_Znth_perm 0 (offset - 2) tail Hcandrange). }
  exists co, a0, a1, tail.
  split; [reflexivity|]. split; [exact Hin|]. split; [exact Hco|].
  split; [exact Htail|]. split; [exact Hwatchcases|].
  split; [exact Hcandidate|]. split; [exact Hcandinco|].
  split; [exact Hcandwf|]. split; [exact Hcandhead|].
  split; [exact Hwatchneq|]. split; [exact Hcandneq|].
  eapply Permutation_trans; [exact Hperm_move|exact Hpermnorm].
Qed.

Lemma wlists_destination_update_to_source_hole__propagate_dbu :
  forall s base hole target pre post capspre capspost destination destination_cap,
    hole = Zlength pre ->
    Zlength pre = Zlength capspre ->
    Zlength post = Zlength capspost ->
    0 <= target < Zlength (pre ++ (@nil Z) :: post) ->
    target <> hole ->
    (solver_wlists_handle s base **
     wlists_split_except_two base hole target pre post capspre capspost **
     vecp_rep (vecp_slot base target) destination destination_cap)
    |-- wlists_source_hole_handle s base hole
      (propagation_split_pre_words hole target pre destination)
      (propagation_split_post_words hole target post destination)
      (propagation_split_pre_caps hole target capspre destination_cap)
      (propagation_split_post_caps hole target capspost destination_cap).
Proof.
  intros s base hole target pre post capspre capspost destination
    destination_cap Hhole Hpre Hpost Htarget Hdistinct.
  unfold wlists_source_hole_handle, wlists_split_except_two,
    propagation_split_pre_words, propagation_split_post_words,
    propagation_split_pre_caps, propagation_split_post_caps.
  destruct (Z.ltb target hole) eqn:Hside.
  - apply Z.ltb_lt in Hside.
    assert (Htrange : 0 <= target < Zlength pre) by lia.
    assert (Hcaprange : 0 <= target < Zlength capspre) by lia.
    assert (Hprefix : Zlength (sublist 0 target pre) =
      Zlength (sublist 0 target capspre)).
    { rewrite !Zlength_sublist by lia. lia. }
    transitivity
      ((((wlists_rep_from base 0
            (sublist 0 target pre) (sublist 0 target capspre) **
          vecp_rep (vecp_slot base target) destination destination_cap) **
         wlists_rep_from base (target + 1)
           (sublist (target + 1) hole pre)
           (sublist (target + 1) hole capspre)) **
        solver_wlists_handle s base) **
       wlists_rep_from base (hole + 1) post capspost).
    { entailer_with lia. }
    sep_apply (wlists_rep_from_insert_at base 0 target
      (sublist 0 target pre) destination (sublist (target + 1) hole pre)
      (sublist 0 target capspre) destination_cap
      (sublist (target + 1) hole capspre) Hprefix ltac:(
        rewrite Zlength_sublist by lia; lia)).
    assert (Hpre_replace : replace_Znth target destination pre =
      sublist 0 target pre ++ destination ::
        sublist (target + 1) (Zlength pre) pre).
    { pose proof (list_Znth_split nil pre target Htrange) as E.
      rewrite E at 1.
      rewrite replace_Znth_app_r by (rewrite Zlength_sublist by lia; lia).
      rewrite replace_Znth_nothing by (rewrite Zlength_sublist by lia; lia).
      rewrite Zlength_sublist by lia.
      replace (target - (target - 0)) with 0 by lia. cbn. reflexivity. }
    rewrite Hpre_replace.
    rewrite (replace_Znth_split 1 destination_cap target capspre Hcaprange).
    rewrite Hhole, <- Hpre. entailer_with lia.
  - apply Z.ltb_ge in Hside.
    assert (Hstrict : hole < target) by lia.
    set (q := target - hole - 1).
    assert (Hqrange : 0 <= q < Zlength post).
    { subst q. rewrite Zlength_app, Zlength_cons in Htarget.
      lia. }
    assert (Hqcap : 0 <= q < Zlength capspost) by (rewrite <- Hpost; exact Hqrange).
    assert (Hprefix : Zlength (sublist 0 q post) =
      Zlength (sublist 0 q capspost)).
    { rewrite !Zlength_sublist by (rewrite ?Hpost; lia). lia. }
    replace (target - hole) with (q + 1) by (subst q; lia).
    transitivity
      (solver_wlists_handle s base **
       (wlists_rep_from base 0 pre capspre **
        ((wlists_rep_from base (hole + 1)
            (sublist 0 q post) (sublist 0 q capspost) **
          vecp_rep (vecp_slot base target) destination destination_cap) **
         wlists_rep_from base (target + 1)
           (sublist (q + 1) (Zlength post) post)
           (sublist (q + 1) (Zlength capspost) capspost)))).
    { entailer_with lia. }
    sep_apply (wlists_rep_from_insert_at base (hole + 1) target
      (sublist 0 q post) destination
      (sublist (q + 1) (Zlength post) post)
      (sublist 0 q capspost) destination_cap
      (sublist (q + 1) (Zlength capspost) capspost) Hprefix ltac:(
        rewrite Zlength_sublist by lia; subst q; lia)).
    assert (Hpost_replace : replace_Znth q destination post =
      sublist 0 q post ++ destination ::
        sublist (q + 1) (Zlength post) post).
    { pose proof (list_Znth_split nil post q Hqrange) as E.
      rewrite E at 1.
      rewrite replace_Znth_app_r by (rewrite Zlength_sublist by lia; lia).
      rewrite replace_Znth_nothing by (rewrite Zlength_sublist by lia; lia).
      rewrite Zlength_sublist by lia.
      replace (q - (q - 0)) with 0 by lia. cbn. reflexivity. }
    rewrite Hpost_replace.
    rewrite (replace_Znth_split 1 destination_cap q capspost Hqcap).
    msat_entailer_with lia.
Qed.

Lemma propagation_migrated_clause_db_rebuild__propagate_dbu :
  forall n prob learnt current lits stop k offset false_lit p candidate sig
    watch0 contents,
    db_wf n (prob ++ learnt) ->
    propagation_scan_candidate_layout current lits stop k offset false_lit p
      candidate sig contents ->
    (clause_db_pair_frame prob learnt current contents **
     (lits + 0 * sizeof(INT)) # Int |-> watch0 **
     (lits + 1 * sizeof(INT)) # Int |-> candidate **
     IntArray.seg lits 2 (Zlength contents)
       (replace_Znth (offset - 2) false_lit
         (replace_Znth (offset - 2) candidate
           (sublist 2 (Zlength contents) contents))))
    |-- EX prob_after learnt_after : dbmap,
      “ db_pair_lits_update prob learnt current contents
          (propagation_migrated_clause watch0 candidate false_lit offset contents)
          prob_after learnt_after ” &&
      (clause_db_rep prob_after ** clause_db_rep learnt_after).
Proof.
  intros n prob learnt current lits stop k offset false_lit p candidate sig
    watch0 contents Hdbwf Hlayout.
  unfold propagation_scan_candidate_layout in Hlayout.
  destruct Hlayout as
    [Hlits [Hlen [Hfalse [Hstop [Hk [Hoffset [Hcandidate Hsig]]]]]]].
  unfold clause_lits_pointer in Hlits. subst lits.
  assert (Htailrange : 0 <= offset - 2 <
      Zlength (sublist 2 (Zlength contents) contents)).
  { rewrite Zlength_sublist by lia. lia. }
  assert (Htailrestore : replace_Znth (offset - 2) candidate
      (sublist 2 (Zlength contents) contents) =
      sublist 2 (Zlength contents) contents).
  { rewrite Hcandidate. apply replace_Znth_Znth. }
  assert (Hnewlen : Zlength
      (propagation_migrated_clause watch0 candidate false_lit offset contents) =
      Zlength contents).
  { apply propagation_migrated_clause_length. lia. }
  unfold clause_db_pair_frame. Intros is_learnt.
  sep_apply_l_atomic
    (IntArray.seg_single (clause_lits_addr current) 0 watch0).
  sep_apply_l_atomic
    (IntArray.seg_single (clause_lits_addr current) 1 candidate).
  sepcon_lift (IntArray.seg (clause_lits_addr current) 0 (0 + 1)
    (watch0 :: nil)).
  replace (0 + 1) with 1 by lia. replace (1 + 1) with 2 by lia.
  sep_apply_l_atomic
    (IntArray.seg_merge_to_seg (clause_lits_addr current)
      0 1 2 (watch0 :: nil) (candidate :: nil)).
  - dump_pre_spatial. lia.
  - cbn [app].
    sep_apply_l_atomic
      (IntArray.seg_merge_to_seg (clause_lits_addr current)
        0 2 (Zlength contents) (watch0 :: candidate :: nil)
        (replace_Znth (offset - 2) false_lit
          (replace_Znth (offset - 2) candidate
            (sublist 2 (Zlength contents) contents)))).
    + dump_pre_spatial. lia.
    + cbn [app]. rewrite Htailrestore.
      assert (Hfold : watch0 :: candidate ::
          replace_Znth (offset - 2) false_lit
            (sublist 2 (Zlength contents) contents) =
          propagation_migrated_clause watch0 candidate false_lit offset contents).
      { unfold propagation_migrated_clause.
        rewrite !replace_Znth_cons by lia.
        replace (offset - 1 - 1) with (offset - 2) by lia. reflexivity. }
      rewrite Hfold. unfold clause_db_pair_remainder. Split.
      * Intros co pre post. coq_prop_lift.
        destruct H as [Hprob [Hco_lits Hco_learnt]].
        assert (Hin : In (current, co) (prob ++ learnt)).
        { rewrite Hprob, !in_app_iff. cbn. tauto. }
        assert (Hpos : 0 < current).
        { eapply db_wf_ptr_pos; [exact Hdbwf|exact Hin]. }
        assert (Hmod : current mod 2 = 0).
        { apply clause_ptr_mod2. eapply db_wf_even; eassumption. }
        set (new_lits := propagation_migrated_clause
          watch0 candidate false_lit offset contents).
        set (co_new := clause_obj_with_lits co new_lits).
        set (prob_after := pre ++ (current, co_new) :: post).
        Exists prob_after learnt. split_pure_spatial.
        -- unfold prob_after.
           assert (Hdbapp :
             clause_db_rep (pre ++ (current, co_new) :: post) --||--
             clause_db_rep pre ** clause_db_rep ((current, co_new) :: post)).
           { split; [apply clause_db_rep_app_elim|apply clause_db_rep_app_intro]. }
           rewrite Hdbapp, clause_db_rep_cons.
           unfold MiniSatClause.rep, co_new, clause_obj_with_lits, new_lits.
           cbn [fst snd co_lits co_learnt]. rewrite Hco_learnt, Hnewlen.
           entailer_with lia.
        -- apply derivable1s_coq_prop_r. left. exists co, pre, post.
           split; [exact Hprob|]. split; [exact Hco_lits|].
           split; reflexivity.
      * Intros co pre post. coq_prop_lift.
        destruct H as [Hlearnt [Hco_lits Hco_learnt]].
        assert (Hin : In (current, co) (prob ++ learnt)).
        { rewrite Hlearnt, !in_app_iff. cbn. tauto. }
        assert (Hpos : 0 < current).
        { eapply db_wf_ptr_pos; [exact Hdbwf|exact Hin]. }
        assert (Hmod : current mod 2 = 0).
        { apply clause_ptr_mod2. eapply db_wf_even; eassumption. }
        set (new_lits := propagation_migrated_clause
          watch0 candidate false_lit offset contents).
        set (co_new := clause_obj_with_lits co new_lits).
        set (learnt_after := pre ++ (current, co_new) :: post).
        Exists prob learnt_after. split_pure_spatial.
        -- unfold learnt_after.
           assert (Hdbapp :
             clause_db_rep (pre ++ (current, co_new) :: post) --||--
             clause_db_rep pre ** clause_db_rep ((current, co_new) :: post)).
           { split; [apply clause_db_rep_app_elim|apply clause_db_rep_app_intro]. }
           rewrite Hdbapp, clause_db_rep_cons.
           unfold MiniSatClause.rep, co_new, clause_obj_with_lits, new_lits.
           cbn [fst snd co_lits co_learnt]. rewrite Hco_learnt, Hnewlen.
           entailer_with lia.
        -- apply derivable1s_coq_prop_r. right. exists co, pre, post.
           split; [exact Hlearnt|]. split; [exact Hco_lits|].
           split; reflexivity.
Qed.

(* ================= SECTION msat_propagate_scan_steps ================= *)

(** * The shared [solver_propagate] scan steps, and the frame folds.

    Three kinds of declaration.  First, the two step lemmas that stand in for
    whole clusters of byte-identical VCs of [solver_propagate] -- the
    real-satisfied step, the finish step, and the same/move pair whose shared
    conclusion is written once as a transparent [Definition].  Second, the
    nested-address bridges that let a [vecp] field be read through
    [&( s # "solver_t" ->s f )] without unfolding the whole solver record.
    Third, the fold/join lemmas that re-associate a solver frame into the two
    halves an analyze or capacity-publication site hands out. *)

(** ---------------------------------------------------------------------- *)
(** Shared step lemma for the [solver_propagate_entail_wit_*_real_satisfied]
    verification conditions of [solver_propagate].

    The shared entailment below records the scan-step hypotheses and conclusion;
    they differ only in the case-analysis facts about which watch slot holds
    [lit_neg_c p], the sign/value of the other watched literal, whether
    [jj = ii] or [jj < ii], and whether [ii <> 0] or [Mscan] is still the scan
    entry state.  None of those facts is used by the proof, so the whole
    cluster factors through this one lemma. *)
Lemma propagation_scan_real_satisfied_step__shared_propagate :
forall (conflict_out_pre: Z) (s_pre: Z) (levels_entry: Z) (assigns_entry: Z) (M0: msolver) (K:
  solver_propagation_context) (A_arr: (@list literal)) (F: cnf) (n: Z) (j: Z) (i: Z) (begin: Z) (endvar: Z)
  (ws: Z) (confl: Z) (p: Z) (Mscan: msolver) (watch_memory: (@list Z)) (logical_words: (@list Z))
  (scan_wm_pre: (@list (@list Z))) (scan_wm_post: (@list (@list Z))) (scan_caps_pre: (@list Z))
  (scan_caps_post: (@list Z)) (scan_wcap: Z) (retained: (@list Z)) (moved: (@list Z)) (rest: (@list Z))
  (garbage: (@list Z)) (ii: Z) (jj: Z) (prop_count: Z) (simp_count: Z) (rsn_scan: Z) (trl_scan: Z) (wl: Z)
  (Mentry: msolver) (source_words: (@list Z)) (raw_prefix: (@list Z)) (scan_current: Z) (raw_suffix: (@list
  Z)) (retval: Z) (clause_contents: (@list Z)) (retval_2: Z) (retval_3: Z) (retval_4: Z) (retval_5: Z)
  (satisfied_memory: (@list Z)) (garbage_route: (@list Z)) (memory_route: (@list Z)) (watch0: Z) (prob_route:
  dbmap) (learnt_route: dbmap) (Mroute: msolver) (retained_route: (@list Z)) (rest_route: (@list Z)) (Hscan_addr_lt_endvar_addr :
  ((begin + (ii * sizeof(PTR))) < (begin + ((Zlength (source_words)) * sizeof(PTR))))) (Hdb_update_normalized_clause :
  (db_pair_lits_update (ms_prob (Mscan)) (ms_learnt (Mscan)) scan_current clause_contents
  (propagation_normalized_clause (watch0) ((lit_neg_c (p))) (clause_contents)) prob_route learnt_route ))
  (Hretained_route_snoc : (retained_route = (app (retained) ((cons (scan_current) ((@nil Z))))))) (Hrest_route_tail : (rest_route =
  raw_suffix)) (Hreal_satisfied_transition : (propagation_real_satisfied_transition n F A_arr K Mscan p prob_route learnt_route
  retained_route rest_route Mroute )) (Hscan_keep_step : (propagation_scan_keep_step source_words retained moved rest
  watch_memory ii jj scan_current retained_route rest_route garbage_route memory_route )) (Hsatisfied_memory_write :
  (satisfied_memory = (replace_Znth (jj) (scan_current) (watch_memory)))) (Hone_ne_zero : (1 <> 0)) (Hneg_lit_eq_retval3 :
  ((lit_neg_c (p)) = retval_3)) (Hclause_lit1_nonneg : (0 <= (Znth (1) (clause_contents) (0)))) (Hclause_lit1_bound : ((Znth (1)
  (clause_contents) (0)) < (2 * n ))) (Hreal_watch_pair : (real_watch_pair (Zlength (scan_wm_pre)) clause_contents ))
  (Hretval3_eq_neg_lit : (retval_3 = (lit_neg_c (p)))) (Hrest_cons_scan_current : (rest = (cons (scan_current) (raw_suffix)))) (Hconfl_zero : (confl = 0)) (Hscan_semantics_at_zero :
  (solver_propagation_scan_semantics n F A_arr K Mscan p 0 retained rest )) (Hclause_lits_pointer : (clause_lits_pointer
  scan_current retval_2 )) (Hretval2_eq_lits_addr : (retval_2 = (clause_lits_addr (scan_current)))) (Hclause_len_ge_3 : (3 <= (Zlength
  (clause_contents)))) (Hclause_lits_wf : (Forall (lit_wf_c (n)) clause_contents )) (Hclause_lit0_nonneg : (0 <= (Znth (0)
  (clause_contents) (0)))) (Hclause_lit0_bound : ((Znth (0) (clause_contents) (0)) < (2 * n ))) (Hclause_var0_nonneg : (0 <= (lit_var_c
  ((Znth (0) (clause_contents) (0)))))) (Hclause_var0_bound : ((lit_var_c ((Znth (0) (clause_contents) (0)))) < (ms_size
  (Mscan)))) (Hclause_var1_nonneg : (0 <= (lit_var_c ((Znth (1) (clause_contents) (0)))))) (Hclause_var1_bound : ((lit_var_c ((Znth (1)
  (clause_contents) (0)))) < (ms_size (Mscan)))) (Hclause_db_pair_contents : (clause_db_pair_contents (ms_prob (Mscan))
  (ms_learnt (Mscan)) scan_current clause_contents )) (Hclause_is_lit_result : (clause_is_lit_result scan_current retval ))
  (Hretval_zero : (retval = 0)) (Htag_scan_current_false : ((is_tag (scan_current)) = msat_false)) (Hretain_index_nonnegative : (0 <= jj)) (Hretain_index_le_scan : (jj
  <= ii)) (Hscan_index_nonnegative : (0 <= ii)) (Hscan_index_lt_len : (ii < (Zlength (source_words)))) (Hscan_current_nonneg : (0 <= scan_current))
  (Hwatch_memory_split : (watch_memory = (app (raw_prefix) ((cons (scan_current) (raw_suffix)))))) (Hraw_prefix_len : ((Zlength
  (raw_prefix)) = ii)) (Hscan_pointer_lt_end : (i < endvar)) (Hshape : (solver_shape Mscan )) (Hseed : (msolver_seed_shadow
  Mscan )) (Hcaller : (propagation_caller_frame M0 Mscan )) (Hfrontier : (propagation_scan_frontier Mentry Mscan p
  )) (Hscan_open : (solver_propagation_scan_semantics n F A_arr K Mscan p confl retained rest )) (Hphysical_open :
  (propagation_watch_scan_physical source_words retained moved rest garbage watch_memory ii jj )) (Hlogical_words :
  (logical_words = (app (retained) (rest)))) (Hwatch_map_open : ((ms_wm (Mscan)) = (app (scan_wm_pre) ((cons
  (logical_words) (scan_wm_post)))))) (Hwatch_caps : ((ms_wcaps (Mscan)) = (app (scan_caps_pre) ((cons (scan_wcap)
  (scan_caps_post)))))) (Hwatch_prefix_length : ((Zlength (scan_wm_pre)) = p)) (Hcap_prefix_length : ((Zlength (scan_caps_pre)) = p))
  (Hwatch_slot : (ws = (vecp_slot (wl) (p)))) (Hend_pointer : (endvar = (begin + ((Zlength (source_words)) *
  sizeof(PTR))))) (Hmemory_source_length : ((Zlength (watch_memory)) = (Zlength (source_words)))) (Hscan_pointer : (i = (begin + (ii
  * sizeof(PTR))))) (Hretain_pointer : (j = (begin + (jj * sizeof(PTR)))))
   (Hscan_index_bound : (ii <= (Zlength (source_words)))) (Hsimp_count : (simp_count = (ms_simpdb_props
  (Mscan)))) (Hprop_count : (prop_count = (stats_propagations ((ms_stats (Mscan)))))) (Hsource_len_nonneg : (0 <= (Zlength
  (source_words)))) (Hsource_within_cap : ((Zlength (source_words)) <= scan_wcap)) (Hcap_positive : (0 < scan_wcap)) (Hcap_max :
  (scan_wcap <= INT_MAX))
  (Hreuse_route : minisat_propagation_reuse_scan M0 Mroute p 0 rest_route),
  (clause_db_rep prob_route )
  **  (clause_db_rep learnt_route )
  **  (PtrArray.full begin (Zlength (source_words)) satisfied_memory )
  **  (CharArray.seg assigns_entry 0 (ms_size (Mscan)) (mt_assigns ((ms_core (Mscan)))) )
  **  ((&((ws)  # "vecp_t" ->ₛ "size")) # Int  |-> (Zlength (source_words)))
  **  ((&((ws)  # "vecp_t" ->ₛ "cap")) # Int  |-> scan_wcap)
  **  ((&((ws)  # "vecp_t" ->ₛ "ptr")) # Ptr  |-> begin)
  **  (PtrArray.undef_seg begin (Zlength (source_words)) scan_wcap )
  **  (wlists_source_hole_handle s_pre wl (Zlength (scan_wm_pre)) scan_wm_pre scan_wm_post scan_caps_pre
    scan_caps_post )
  **  (CharArray.undef_seg assigns_entry (ms_size (Mscan)) (ms_cap (Mscan)) )
  **  ((&((s_pre)  # "solver_t" ->ₛ "reasons")) # Ptr  |-> rsn_scan)
  **  ((&((s_pre)  # "solver_t" ->ₛ "levels")) # Ptr  |-> levels_entry)
  **  ((&((s_pre)  # "solver_t" ->ₛ "trail")) # Ptr  |-> trl_scan)
  **  (PtrArray.seg rsn_scan 0 (ms_size (Mscan)) (ms_reason_words (Mscan)) )
  **  (PtrArray.undef_seg rsn_scan (ms_size (Mscan)) (ms_cap (Mscan)) )
  **  (IntArray.seg levels_entry 0 (ms_size (Mscan)) (mt_levels ((ms_core (Mscan)))) )
  **  (IntArray.undef_seg levels_entry (ms_size (Mscan)) (ms_cap (Mscan)) )
  **  (IntArray.seg trl_scan 0 (ms_qtail (Mscan)) (mt_trail ((ms_core (Mscan)))) )
  **  (IntArray.undef_seg trl_scan (ms_qtail (Mscan)) (ms_cap (Mscan)) )
  **  (veci_rep &((s_pre)  # "solver_t" ->ₛ "trail_lim") (mt_lim ((ms_core (Mscan)))) (ms_lim_cap (Mscan)) )
  **  ((&((s_pre)  # "solver_t" ->ₛ "qhead")) # Int  |-> (mt_qhead ((ms_core (Mscan)))))
  **  ((&((s_pre)  # "solver_t" ->ₛ "qtail")) # Int  |-> (ms_qtail (Mscan)))
  **  ((&((s_pre)  # "solver_t" ->ₛ "simpdb_props")) # Int  |-> simp_count)
  **  ((&((s_pre)  # "solver_t" ->ₛ "assigns")) # Ptr  |-> assigns_entry)
  **  ((&((s_pre)  # "solver_t" ->ₛ "binary")) # Ptr  |-> (ms_binary (Mscan)))
  **  (solver_binary_rep Mscan )
  **  ((&((s_pre)  # "solver_t" ->ₛ "stats" .ₛ "propagations")) # UInt64  |-> prop_count)
  **  ((&((s_pre)  # "solver_t" ->ₛ "stats" .ₛ "inspects")) # UInt64  |-> (stats_inspects ((ms_stats (Mscan)))))
  **  (solver_propagate_frame s_pre Mscan )
  **  ((conflict_out_pre) # Ptr  |-> 0)
|--
  (EX (trl_next: Z)  (rsn_next: Z)  (prop_count_next: Z)  (simp_count_next: Z)  (next_caps_pre:
    (@list Z))  (next_wcap: Z)  (next_caps_post: (@list Z))  (next_wm_pre: (@list (@list Z)))  (next_wm_post:
    (@list (@list Z)))  (logical_next: (@list Z))  (source_words_next: (@list Z))  (moved_next: (@list Z))
    (garbage_next: (@list Z))  (memory_next: (@list Z))  (ii_next: Z)  (jj_next: Z)  (retained_next: (@list
    Z))  (rest_next: (@list Z))  (Mentry_next: msolver)  (Mnext: msolver)  (lvl_next: Z) ,
  “ (lvl_next = levels_entry) ”
  &&  “ (solver_shape Mnext ) ”
  &&  “ (msolver_seed_shadow Mnext ) ”
  &&  “ (propagation_caller_frame M0 Mnext ) ”
  &&  “ (propagation_scan_frontier Mentry_next Mnext p ) ”
  &&  “ (solver_propagation_scan_semantics n F A_arr K Mnext p confl retained_next rest_next ) ”
  &&  “ minisat_propagation_reuse_scan M0 Mnext p confl rest_next ”
  &&  “ (propagation_watch_scan_physical source_words_next retained_next moved_next rest_next garbage_next
    memory_next ii_next jj_next ) ”
  &&  “ (logical_next = (app (retained_next) (rest_next))) ”
  &&  “ ((ms_wm (Mnext)) = (app (next_wm_pre) ((cons (logical_next) (next_wm_post))))) ”
  &&  “ ((ms_wcaps (Mnext)) = (app (next_caps_pre) ((cons (next_wcap) (next_caps_post))))) ”
  &&  “ ((Zlength (next_wm_pre)) = p) ”
  &&  “ ((Zlength (next_caps_pre)) = p) ”
  &&  “ (ws = (vecp_slot (wl) (p))) ”
  &&  “ ((begin + ((Zlength (source_words)) * sizeof(PTR))) = (begin + ((Zlength (source_words_next)) * sizeof(PTR)))) ”
  &&  “ ((Zlength (memory_next)) = (Zlength (source_words_next))) ”
  &&  “ ((begin + ((ii + 1 ) * sizeof(PTR))) = (begin + (ii_next * sizeof(PTR)))) ”
  &&  “ ((begin + ((jj + 1 ) * sizeof(PTR))) = (begin + (jj_next * sizeof(PTR)))) ”
  &&  “ (0 <= jj_next) ”
  &&  “ (jj_next <= ii_next) ”
  &&  “ (0 <= ii_next) ”
  &&  “ (ii_next <= (Zlength (source_words_next))) ”
  &&  “ (ii_next <> 0) ”
  &&  “ (simp_count_next = (ms_simpdb_props (Mnext))) ”
  &&  “ (prop_count_next = (stats_propagations ((ms_stats (Mnext))))) ”
  &&  “ (0 <= (Zlength (source_words_next))) ”
  &&  “ ((Zlength (source_words_next)) <= next_wcap) ”
  &&  “ (0 < next_wcap) ”
  &&  “ (next_wcap <= INT_MAX) ”
  &&  ((&((ws)  # "vecp_t" ->ₛ "size")) # Int  |-> (Zlength (source_words_next)))
  **  ((&((ws)  # "vecp_t" ->ₛ "cap")) # Int  |-> next_wcap)
  **  ((&((ws)  # "vecp_t" ->ₛ "ptr")) # Ptr  |-> begin)
  **  (PtrArray.full begin (Zlength (source_words_next)) memory_next )
  **  (PtrArray.undef_seg begin (Zlength (source_words_next)) next_wcap )
  **  (wlists_source_hole_handle s_pre wl (Zlength (next_wm_pre)) next_wm_pre next_wm_post next_caps_pre
    next_caps_post )
  **  (clause_db_rep (ms_prob (Mnext)) )
  **  (clause_db_rep (ms_learnt (Mnext)) )
  **  ((&((s_pre)  # "solver_t" ->ₛ "reasons")) # Ptr  |-> rsn_next)
  **  ((&((s_pre)  # "solver_t" ->ₛ "levels")) # Ptr  |-> lvl_next)
  **  ((&((s_pre)  # "solver_t" ->ₛ "trail")) # Ptr  |-> trl_next)
  **  (CharArray.seg assigns_entry 0 (ms_size (Mnext)) (mt_assigns ((ms_core (Mnext)))) )
  **  (CharArray.undef_seg assigns_entry (ms_size (Mnext)) (ms_cap (Mnext)) )
  **  ((&((s_pre)  # "solver_t" ->ₛ "qhead")) # Int  |-> (mt_qhead ((ms_core (Mnext)))))
  **  (solver_propagation_scan_core_at s_pre Mnext assigns_entry rsn_next lvl_next trl_next simp_count_next
    prop_count_next )
  **  ((conflict_out_pre) # Ptr  |-> 0))
  ||
  (EX (trl_next: Z)  (rsn_next: Z)  (simp_count_next: Z)  (prop_count_next: Z)  (next_caps_pre:
    (@list Z))  (next_wcap: Z)  (next_caps_post: (@list Z))  (next_wm_pre: (@list (@list Z)))  (next_wm_post:
    (@list (@list Z)))  (logical_next: (@list Z))  (source_words_next: (@list Z))  (moved_next: (@list Z))
    (garbage_next: (@list Z))  (memory_next: (@list Z))  (ii_next: Z)  (jj_next: Z)  (retained_next: (@list
    Z))  (rest_next: (@list Z))  (Mentry_next: msolver)  (Mnext: msolver)  (lvl_next: Z) ,
  “ (lvl_next = levels_entry) ”
  &&  “ (solver_shape Mnext ) ”
  &&  “ (msolver_seed_shadow Mnext ) ”
  &&  “ (propagation_caller_frame M0 Mnext ) ”
  &&  “ (propagation_scan_frontier Mentry_next Mnext p ) ”
  &&  “ (solver_propagation_scan_semantics n F A_arr K Mnext p confl retained_next rest_next ) ”
  &&  “ minisat_propagation_reuse_scan M0 Mnext p confl rest_next ”
  &&  “ (propagation_watch_scan_physical source_words_next retained_next moved_next rest_next garbage_next
    memory_next ii_next jj_next ) ”
  &&  “ (logical_next = (app (retained_next) (rest_next))) ”
  &&  “ ((ms_wm (Mnext)) = (app (next_wm_pre) ((cons (logical_next) (next_wm_post))))) ”
  &&  “ ((ms_wcaps (Mnext)) = (app (next_caps_pre) ((cons (next_wcap) (next_caps_post))))) ”
  &&  “ ((Zlength (next_wm_pre)) = p) ”
  &&  “ ((Zlength (next_caps_pre)) = p) ”
  &&  “ (ws = (vecp_slot (wl) (p))) ”
  &&  “ ((begin + ((Zlength (source_words)) * sizeof(PTR))) = (begin + ((Zlength (source_words_next)) * sizeof(PTR)))) ”
  &&  “ ((Zlength (memory_next)) = (Zlength (source_words_next))) ”
  &&  “ ((begin + ((ii + 1 ) * sizeof(PTR))) = (begin + (ii_next * sizeof(PTR)))) ”
  &&  “ ((begin + ((jj + 1 ) * sizeof(PTR))) = (begin + (jj_next * sizeof(PTR)))) ”
  &&  “ (0 <= jj_next) ”
  &&  “ (jj_next <= ii_next) ”
  &&  “ (0 <= ii_next) ”
  &&  “ (ii_next <= (Zlength (source_words_next))) ”
  &&  “ (Mnext = (msolver_propagation_scan_begin (Mentry_next) (simp_count_next) (prop_count_next))) ”
  &&  “ (simp_count_next = (ms_simpdb_props (Mnext))) ”
  &&  “ (prop_count_next = (stats_propagations ((ms_stats (Mnext))))) ”
  &&  “ (0 <= (Zlength (source_words_next))) ”
  &&  “ ((Zlength (source_words_next)) <= next_wcap) ”
  &&  “ (0 < next_wcap) ”
  &&  “ (next_wcap <= INT_MAX) ”
  &&  ((&((ws)  # "vecp_t" ->ₛ "size")) # Int  |-> (Zlength (source_words_next)))
  **  ((&((ws)  # "vecp_t" ->ₛ "cap")) # Int  |-> next_wcap)
  **  ((&((ws)  # "vecp_t" ->ₛ "ptr")) # Ptr  |-> begin)
  **  (PtrArray.full begin (Zlength (source_words_next)) memory_next )
  **  (PtrArray.undef_seg begin (Zlength (source_words_next)) next_wcap )
  **  (wlists_source_hole_handle s_pre wl (Zlength (next_wm_pre)) next_wm_pre next_wm_post next_caps_pre
    next_caps_post )
  **  (clause_db_rep (ms_prob (Mnext)) )
  **  (clause_db_rep (ms_learnt (Mnext)) )
  **  ((&((s_pre)  # "solver_t" ->ₛ "reasons")) # Ptr  |-> rsn_next)
  **  ((&((s_pre)  # "solver_t" ->ₛ "levels")) # Ptr  |-> lvl_next)
  **  ((&((s_pre)  # "solver_t" ->ₛ "trail")) # Ptr  |-> trl_next)
  **  (CharArray.seg assigns_entry 0 (ms_size (Mnext)) (mt_assigns ((ms_core (Mnext)))) )
  **  (CharArray.undef_seg assigns_entry (ms_size (Mnext)) (ms_cap (Mnext)) )
  **  ((&((s_pre)  # "solver_t" ->ₛ "qhead")) # Int  |-> (mt_qhead ((ms_core (Mnext)))))
  **  (solver_propagation_scan_core_at s_pre Mnext assigns_entry rsn_next lvl_next trl_next simp_count_next
    prop_count_next )
  **  ((conflict_out_pre) # Ptr  |-> 0))
.
Proof.
  aggressive_pre_process.
  unfold propagation_real_satisfied_transition in Hreal_satisfied_transition.
  destruct Hreal_satisfied_transition as [HMroute Hsem].
  unfold propagation_scan_keep_step in Hscan_keep_step.
  destruct Hscan_keep_step as [Hrest [Hretained [Hmemory Hphysical]]].
  assert (Hmemory_eq : memory_route = satisfied_memory) by congruence.
  assert (Hphysical_sat : propagation_watch_scan_physical source_words
      retained_route moved rest_route garbage_route satisfied_memory
      (ii + 1) (jj + 1)).
  { rewrite <- Hmemory_eq. exact Hphysical. }
  assert (Hmemory_length : Zlength satisfied_memory = Zlength source_words).
  { unfold propagation_watch_scan_physical in Hphysical_sat. intuition. }
  assert (Hsem_confl : solver_propagation_scan_semantics n F A_arr K
      Mroute p confl retained_route rest_route).
  { rewrite Hconfl_zero. exact Hsem. }
  assert (Hreuse_confl : minisat_propagation_reuse_scan M0 Mroute p confl rest_route).
  { rewrite Hconfl_zero. exact Hreuse_route. }
  assert (Hlogical : logical_words = retained_route ++ rest_route).
  { rewrite Hlogical_words, Hretained, Hrest. rewrite <- app_assoc. reflexivity. }
  assert (Hshape_route : solver_shape Mroute).
  { rewrite HMroute. unfold solver_shape in Hshape |- *. exact Hshape. }
  assert (Hseed_route : msolver_seed_shadow Mroute).
  { rewrite HMroute. exact Hseed. }
  assert (Hcaller_route : propagation_caller_frame M0 Mroute).
  { rewrite HMroute. exact Hcaller. }
  assert (Hfrontier_route : propagation_scan_frontier Mentry Mroute p).
  { rewrite HMroute. exact Hfrontier. }
  assert (Hbinary : solver_binary_rep Mroute = solver_binary_rep Mscan).
  { rewrite HMroute. unfold solver_binary_rep. reflexivity. }
  assert (Hframe : solver_propagate_frame s_pre Mroute =
      solver_propagate_frame s_pre Mscan).
  { destruct (db_pair_lits_update_words__propagate
      _ _ _ _ _ _ _ Hdb_update_normalized_clause) as [Hprob_words Hlearnt_words].
    rewrite HMroute.
    unfold msolver_propagation_db_wmap_update,
      msolver_propagation_overlay, msolver_propagation_update, solver_propagate_frame.
    cbn. rewrite Hprob_words, Hlearnt_words. reflexivity. }
  Left.
  Exists trl_scan rsn_scan prop_count simp_count
    scan_caps_pre scan_wcap scan_caps_post scan_wm_pre scan_wm_post
    logical_words source_words moved garbage_route satisfied_memory
    (ii + 1) (jj + 1) retained_route rest_route Mentry.
  Exists Mroute levels_entry.
  split_pure_spatial.
  - unfold solver_propagation_scan_core_at.
    rewrite Hbinary, Hframe, HMroute.
    unfold msolver_propagation_db_wmap_update,
      msolver_propagation_overlay, msolver_propagation_update.
    (* `ptr_size_Z` and `addr_max_unsigned` reach goals through the Arch functor
       parameter.  A bare `cbn` reduces the pointer stride to the 32-bit literal on the right of this
       entailment, while the `unfold PtrArray.seg` reintroduces the symbolic `ptr_size_Z`
       on the left - and nothing folds a literal back into a constant.  Blocking delta on
       the arch constant keeps both sides spelled the same way, with NO pointer width
       named anywhere.  `Znth` is blocked for the same reason: reducing it to
       `nth (Pos.to_nat 3)` on one side only would break the closing `exact`.  The second
       `cbn` re-normalises what the unfolds reintroduce. *)
    cbn -[ptr_size_Z Znth]. unfold PtrArray.seg, stats_propagate_scan.
    cbn -[ptr_size_Z Znth].
    set_String_name. sepcon_assoc_change. sepcon_cancel.
    subst_all_strings.
    exact (stats_propagate_scan_refold__propagate
      s_pre prop_count (ms_stats Mscan)).
  - split_pures; dump_pre_spatial.
    (* Preserve the named semantic packages. The remaining goals are field
       read-backs or arithmetic bounds of the explicit route update. *)
    all: lazymatch goal with
        | |- solver_shape _ => exact Hshape_route
        | |- msolver_seed_shadow _ => exact Hseed_route
        | |- propagation_caller_frame _ _ => exact Hcaller_route
        | |- propagation_scan_frontier _ _ _ => exact Hfrontier_route
        | |- solver_propagation_scan_semantics _ _ _ _ _ _ _ _ _ => exact Hsem_confl
        | |- minisat_propagation_reuse_scan _ _ _ _ _ => exact Hreuse_confl
        | |- propagation_watch_scan_physical _ _ _ _ _ _ _ _ => exact Hphysical_sat
        | _ =>
            rewrite ?HMroute;
            cbn [msolver_propagation_db_wmap_update
              msolver_propagation_overlay msolver_propagation_update];
            lazymatch goal with
            | Hfact : ?P |- ?P => exact Hfact
            | |- ?x = ?x => reflexivity
            | |- _ = _ => lia
            | |- _ <= _ => lia
            | |- _ < _ => lia
            | |- _ <> _ => lia
            | |- _ /\ _ => lia
            end
        end.
Qed.


(* ---- section key: psolve_pure ---- *)
(* ===== psolve pure-header section: shared conclusion of the
   solver_propagate watcher-scan header-word side conditions.  Consumers
   in parts 3 and 8 use [msat_clause_hdr_word_nonneg_scan_pure].
   The VC's whole content is the pure
   fact [0 <= clause_hdr_word learnt (Zlength lits)] under an arbitrary
   spatial context, so the heap plays no role and the fact is
   unconditional: [Zlength] is non-negative.  Applying this lemma replaces
   repeated case analysis and entailment automation at each consumer.  It
   uses [clause_hdr_word] from [solver_qcp_model.v],
   [clause_hdr_word_nonneg] proved earlier in this file, and the imported
   [derivable1s_coq_prop_r] and [Zlength_nonneg] lemmas.
   It introduces no new Require, Import, notation or axiom.
   ===== *)
Lemma clause_hdr_word_nonneg_entail :
  forall (A : Type) (H : Assertion) (learnt : bool) (lits : list A),
    H |-- “ 0 <= clause_hdr_word learnt (Zlength lits) ”.
Proof.
  intros A H learnt lits.
  apply derivable1s_coq_prop_r.
  apply clause_hdr_word_nonneg.
  apply Zlength_nonneg.
Qed.

(* ---- section key: csimpl ---- *)
(* ===================================================================== *)
(* csimpl reconciliation section.                                        *)
(*                                                                       *)
(* WHY.  Every remaining expensive [csimpl] in this development          *)
(* reconciles the SAME shape: a nested struct-field address written in   *)
(* the C dot form                                                        *)
(*     &( s # "solver_t" ->ₛ fld .ₛ sub)                                *)
(* against the arrow form that the vector accessors                      *)
(* ([veci_size_addr] / [vecp_size_addr] / a [set] alias) produce         *)
(*     &( v # tag ->ₛ sub)      where  v = &( s # "solver_t" ->ₛ fld).  *)
(*                                                                       *)
(* [csimpl] is [repeat progress rewrite ?eval_addr at 1; ...] -- setoid  *)
(* rewriting over the WHOLE goal.  Its cost is driven by the size of the *)
(* separation-logic goal it is run on, not by the address it fixes: it   *)
(* is cheap on the bare address equality below and expensive on a        *)
(* multi-atom entailment.                                                *)
(*                                                                       *)
(* So the address normalisation is paid ONCE, on a bare equality, and    *)
(* every call site becomes a [rewrite] / [sep_apply].                    *)
(* ===================================================================== *)

(** The one address fact.  [tag] is a parameter because [eval_addr]
    discards the front-end type ascription of the intermediate pointer,
    so the SAME equation serves "veci_t", "vecp_t" and "stats_t". *)
Lemma solver_dot_addr : forall (s v : Z) (fld sub tag : string),
  v = &( s # "solver_t" ->ₛ fld) ->
  &( s # "solver_t" ->ₛ fld .ₛ sub) = &( v # tag ->ₛ sub).
Proof. intros s v fld sub tag Hv. subst v. csimpl. reflexivity. Qed.

(** The three [vecp_t] accessors, in the orientation the call sites need
    (arrow form -> dot form, i.e. accessor -> the spelling of the VC). *)
Lemma vecp_size_addr_nested : forall (s : Z) (fld : string),
  vecp_size_addr &( s # "solver_t" ->ₛ fld) =
  &( s # "solver_t" ->ₛ fld .ₛ "size").
Proof.
  intros. unfold vecp_size_addr. symmetry.
  apply solver_dot_addr. reflexivity.
Qed.

Lemma vecp_cap_addr_nested : forall (s : Z) (fld : string),
  vecp_cap_addr &( s # "solver_t" ->ₛ fld) =
  &( s # "solver_t" ->ₛ fld .ₛ "cap").
Proof.
  intros. unfold vecp_cap_addr. symmetry.
  apply solver_dot_addr. reflexivity.
Qed.

Lemma vecp_ptr_addr_nested : forall (s : Z) (fld : string),
  vecp_ptr_addr &( s # "solver_t" ->ₛ fld) =
  &( s # "solver_t" ->ₛ fld .ₛ "ptr").
Proof.
  intros. unfold vecp_ptr_addr. symmetry.
  apply solver_dot_addr. reflexivity.
Qed.

(** The [vecp] counterpart of [solver_nested_veci_from_cells__canceluntil_cap],
    at [vecp_rep_at] (explicit payload pointer). *)
Lemma solver_nested_vecp_rep_at_from_cells :
  forall (s : Z) (fld : string) (p : Z) (l : list Z) (cap : Z),
  0 <= Zlength l <= cap -> 0 < cap <= INT_MAX ->
  (&( s # "solver_t" ->ₛ fld .ₛ "size") # Int |-> Zlength l **
   &( s # "solver_t" ->ₛ fld .ₛ "cap") # Int |-> cap **
   &( s # "solver_t" ->ₛ fld .ₛ "ptr") # Ptr |-> p **
   PtrArray.seg p 0 (Zlength l) l **
   PtrArray.undef_seg p (Zlength l) cap) |--
  vecp_rep_at &( s # "solver_t" ->ₛ fld) p l cap.
Proof.
  intros s fld p l cap Hlen Hcap.
  unfold vecp_rep_at.
  rewrite vecp_size_addr_nested, vecp_cap_addr_nested,
    vecp_ptr_addr_nested.
  msat_entailer_with lia.
Qed.

(* ---- section key: small_families ---- *)
(** ---------------------------------------------------------------------- *)
(** [propagation_scan_finish_step__shared_solver_propagate] serves
    [proof_of_solver_propagate_entail_wit_32_1] and [..._wit_32_2] in
    solver_qcp_proof_manual_part7.v (solver_propagate scan-finish step).
    The two members' goal.v Definitions are byte-identical except one
    hypothesis (PreH44: "ii <> 0" vs "Mscan =
    msolver_propagation_scan_begin (...)"), and the original proof bodies
    (moved here unchanged, from wit_32_1) do not reference PreH44 at all --
    so it is simply dropped from the shared forall, following the
    propagation_scan_real_satisfied_step precedent above in this file. *)

(* Scan completion preserves this common physical state in both the live and conflict exits. *)
Lemma minisat_base_watch_completed_same_fields__api_reentry : forall M M',
  msolver_db M' = msolver_db M ->
  mt_assigns (ms_core M') = mt_assigns (ms_core M) ->
  mt_levels (ms_core M') = mt_levels (ms_core M) ->
  mt_trail (ms_core M') = mt_trail (ms_core M) ->
  mt_qhead (ms_core M') = mt_qhead (ms_core M) ->
  minisat_base_watch_completed M -> minisat_base_watch_completed M'.
Proof.
  intros M M' Hdb Ha Hl Ht Hq.
  unfold minisat_base_watch_completed. rewrite Hdb, Ha, Hl, Ht, Hq. trivial.
Qed.

Lemma minisat_base_watch_completed_except_same_fields__api_reentry : forall M M' p,
  msolver_db M' = msolver_db M ->
  mt_assigns (ms_core M') = mt_assigns (ms_core M) ->
  mt_levels (ms_core M') = mt_levels (ms_core M) ->
  mt_trail (ms_core M') = mt_trail (ms_core M) ->
  mt_qhead (ms_core M') = mt_qhead (ms_core M) ->
  minisat_base_watch_completed_except M p -> minisat_base_watch_completed_except M' p.
Proof.
  intros M M' p Hdb Ha Hl Ht Hq.
  unfold minisat_base_watch_completed_except. rewrite Hdb, Ha, Hl, Ht, Hq. trivial.
Qed.

Lemma minisat_base_scan_completed_close__api_reentry : forall M focus,
  minisat_base_watch_completed_except M focus ->
  minisat_base_scan_completed M focus nil ->
  minisat_base_watch_completed M.
Proof.
  intros M focus Hexcept Hscan owner co Hin.
  destruct (Hexcept owner co Hin) as [Hleft Hright].
  split; intros Hprocessed Hzero.
  - destruct (Z.eq_dec (lit_neg_c (co_watch0 co)) focus) as [Heq|Hneq].
    + assert (Hfocuszero : Znth (lit_var_c focus) (mt_levels (ms_core M)) 0 = 0).
      { rewrite <- Heq, lit_var_c_neg. exact Hzero. }
      exact (proj1 (Hscan
        (if 3 <=? Zlength (co_lits co) then owner else tag_of_lit (co_watch1 co))
        ltac:(intro H; inversion H) Hfocuszero owner co Hin) Heq eq_refl).
    + exact (Hleft Hneq Hprocessed Hzero).
  - destruct (Z.eq_dec (lit_neg_c (co_watch1 co)) focus) as [Heq|Hneq].
    + assert (Hfocuszero : Znth (lit_var_c focus) (mt_levels (ms_core M)) 0 = 0).
      { rewrite <- Heq, lit_var_c_neg. exact Hzero. }
      exact (proj2 (Hscan
        (if 3 <=? Zlength (co_lits co) then owner else tag_of_lit (co_watch0 co))
        ltac:(intro H; inversion H) Hfocuszero owner co Hin) Heq eq_refl).
    + exact (Hright Hneq Hprocessed Hzero).
Qed.

Lemma minisat_resident_false_same_fields__api_reentry : forall M M',
  msolver_db M' = msolver_db M ->
  mt_assigns (ms_core M') = mt_assigns (ms_core M) ->
  minisat_resident_false_clause M -> minisat_resident_false_clause M'.
Proof.
  intros M M' Hdb Hassign [owner [co [Hin Hfalse]]].
  exists owner, co. rewrite Hdb, Hassign. auto.
Qed.

Lemma minisat_resident_false_scan_finish__api_reentry : forall M inspect,
  minisat_resident_false_clause M ->
  minisat_resident_false_clause (msolver_propagation_scan_finish M inspect).
Proof.
  intros M inspect. apply minisat_resident_false_same_fields__api_reentry;
    reflexivity.
Qed.

Lemma minisat_propagation_reuse_scan_finish__api_reentry :
  forall n entry M p confl inspect,
    minisat_propagation_reuse_scan entry M p confl nil ->
    (confl <> 0 -> level_of (msolver_view n M) (lit_var_c p) =
      Some (Zlength (mt_lim (ms_core M)))) ->
    minisat_propagation_reuse_loop n entry
      (msolver_propagation_scan_finish M inspect) confl.
Proof.
  intros n entry M p confl inspect [Hcomplete [Hresident Hconflict]] Hlevel.
  split.
  - intro Hentry. destruct (Hcomplete Hentry) as [Hexcept Hpending]. split.
    + intro Hzero.
      eapply minisat_base_watch_completed_same_fields__api_reentry;
        try reflexivity.
      apply minisat_base_scan_completed_close__api_reentry with (focus:=p);
        [exact Hexcept|exact (Hpending Hzero)].
    + intro Hnonzero. exists p. split.
      * exact (Hlevel Hnonzero).
      * eapply minisat_base_watch_completed_except_same_fields__api_reentry;
          try reflexivity; exact Hexcept.
  - split; intro H.
    + apply minisat_resident_false_scan_finish__api_reentry. exact (Hresident H).
    + apply minisat_resident_false_scan_finish__api_reentry. exact (Hconflict H).
Qed.

Definition propagation_scan_finish_arm (condition finalized : Prop)
    (trl_finish rsn_finish : Z) (Mfinish : msolver) (lvl_finish levels_entry : Z)
    (n : Z) (F : cnf) (A_arr : list literal) (K : solver_propagation_context)
    (M0 : msolver) (confl jj : Z) (watch_memory retained : list Z)
    (scan_wm_pre scan_wm_post : list (list Z)) (scan_caps_pre scan_caps_post : list Z)
    (scan_wcap s_pre wl assigns_entry conflict_out_pre : Z) : Assertion :=
  “ (lvl_finish = levels_entry) ”
  &&  “ (solver_shape Mfinish ) ”
  &&  “ (msolver_seed_shadow Mfinish ) ”
  &&  “ condition ”
  &&  “ finalized ”
  &&  “ (solver_propagation_loop_inv n F A_arr K M0 Mfinish confl ) ”
  &&  “ minisat_propagation_reuse_loop n M0 Mfinish confl ”
  &&  “ ((sublist (0) (jj) (watch_memory)) = retained) ”
  &&  “ ((ms_wm (Mfinish)) = (app (scan_wm_pre) ((cons (retained) (scan_wm_post))))) ”
  &&  “ ((ms_wcaps (Mfinish)) = (app (scan_caps_pre) ((cons (scan_wcap) (scan_caps_post))))) ”
  &&  “ (0 <= (mt_qhead ((ms_core (Mfinish))))) ”
  &&  “ ((mt_qhead ((ms_core (Mfinish)))) <= (ms_qtail (Mfinish))) ”
  &&  “ ((ms_qtail (Mfinish)) <= (ms_size (Mfinish))) ”
  &&  “ ((ms_size (Mfinish)) <= (ms_cap (Mfinish))) ”
  &&  “ ((Zlength ((mt_trail ((ms_core (Mfinish)))))) = (ms_qtail (Mfinish))) ”
  &&  ((&((s_pre)  # "solver_t" ->ₛ "qhead")) # Int  |-> (mt_qhead ((ms_core (Mfinish)))))
  **  ((&((s_pre)  # "solver_t" ->ₛ "qtail")) # Int  |-> (ms_qtail (Mfinish)))
  **  ((&((s_pre)  # "solver_t" ->ₛ "simpdb_props")) # Int  |-> (ms_simpdb_props (Mfinish)))
  **  ((&((s_pre)  # "solver_t" ->ₛ "wlists")) # Ptr  |-> wl)
  **  ((&((s_pre)  # "solver_t" ->ₛ "assigns")) # Ptr  |-> assigns_entry)
  **  ((&((s_pre)  # "solver_t" ->ₛ "reasons")) # Ptr  |-> rsn_finish)
  **  ((&((s_pre)  # "solver_t" ->ₛ "levels")) # Ptr  |-> lvl_finish)
  **  ((&((s_pre)  # "solver_t" ->ₛ "trail")) # Ptr  |-> trl_finish)
  **  ((&((s_pre)  # "solver_t" ->ₛ "binary")) # Ptr  |-> (ms_binary (Mfinish)))
  **  (CharArray.seg assigns_entry 0 (ms_size (Mfinish)) (mt_assigns ((ms_core (Mfinish)))) )
  **  (CharArray.undef_seg assigns_entry (ms_size (Mfinish)) (ms_cap (Mfinish)) )
  **  (PtrArray.seg rsn_finish 0 (ms_size (Mfinish)) (ms_reason_words (Mfinish)) )
  **  (PtrArray.undef_seg rsn_finish (ms_size (Mfinish)) (ms_cap (Mfinish)) )
  **  (IntArray.seg lvl_finish 0 (ms_size (Mfinish)) (mt_levels ((ms_core (Mfinish)))) )
  **  (IntArray.undef_seg lvl_finish (ms_size (Mfinish)) (ms_cap (Mfinish)) )
  **  (IntArray.seg trl_finish 0 (ms_qtail (Mfinish)) (mt_trail ((ms_core (Mfinish)))) )
  **  (IntArray.undef_seg trl_finish (ms_qtail (Mfinish)) (ms_cap (Mfinish)) )
  **  (veci_rep &((s_pre)  # "solver_t" ->ₛ "trail_lim") (mt_lim ((ms_core (Mfinish)))) (ms_lim_cap (Mfinish)) )
  **  (wlists_rep wl (ms_size (Mfinish)) (ms_wm (Mfinish)) (ms_wcaps (Mfinish)) )
  **  (clause_db_rep (ms_prob (Mfinish)) )
  **  (clause_db_rep (ms_learnt (Mfinish)) )
  **  (solver_binary_rep Mfinish )
  **  ((&((s_pre)  # "solver_t" ->ₛ "stats" .ₛ "propagations")) # UInt64  |-> (stats_propagations ((ms_stats
  (Mfinish)))))
  **  ((&((s_pre)  # "solver_t" ->ₛ "stats" .ₛ "inspects")) # UInt64  |-> (stats_inspects ((ms_stats (Mfinish)))))
  **  (solver_propagate_frame s_pre Mfinish )
  **  ((conflict_out_pre) # Ptr  |-> 0)
  **  ((( &( "begin" ) )) # Ptr  |->_)
  **  ((( &( "endvar" ) )) # Ptr  |->_)
  **  ((( &( "i" ) )) # Ptr  |->_)
  **  ((( &( "j" ) )) # Ptr  |->_)
  **  ((( &( "ws" ) )) # Ptr  |->_).
Lemma propagation_scan_finish_step__shared_solver_propagate :
  forall (conflict_out_pre: Z) (s_pre: Z) (levels_entry: Z) (assigns_entry: Z) (M0: msolver) (K:
    solver_propagation_context) (A_arr: (@list literal)) (F: cnf) (n: Z) (i: Z) (endvar: Z) (p:
    Z) (confl: Z) (ws: Z) (begin: Z) (j: Z) (Mscan: msolver) (watch_memory: (@list Z))
    (logical_words: (@list Z)) (scan_wm_pre: (@list (@list Z))) (scan_wm_post: (@list (@list
    Z))) (scan_caps_pre: (@list Z)) (scan_caps_post: (@list Z)) (scan_wcap: Z) (retained: (@list
    Z)) (moved: (@list Z)) (rest: (@list Z)) (garbage: (@list Z)) (ii: Z) (jj: Z) (prop_count:
    Z) (simp_count: Z) (rsn_scan: Z) (trl_scan: Z) (wl: Z) (Mentry: msolver) (source_words:
    (@list Z)) (retval: Z) (retval_2: Z)
    (Hwritten_prefix_length : ((Zlength ((sublist (0) ((((begin + (jj * sizeof(PTR))) - retval_2
      ) ÷ sizeof(PTR) )) (watch_memory)))) = (((begin + (jj * sizeof(PTR))) - retval_2 ) ÷
      sizeof(PTR) )))
    (Hgetter_alias : (retval_2 = retval))
    (Hretained_index : ((((begin + (jj * sizeof(PTR))) - begin ) ÷ sizeof(PTR) ) = jj))
    (Hgetter_base : (retval = begin))
    (Hcap_max : (scan_wcap <= INT_MAX))
    (Hcap_positive : (0 < scan_wcap))
    (Hmemory_within_cap : ((Zlength (watch_memory)) <= scan_wcap))
    (Hshape : (solver_shape Mscan ))
    (Hseed : (msolver_seed_shadow Mscan ))
    (Hcaller : (propagation_caller_frame M0 Mscan ))
    (Hfrontier : (propagation_scan_frontier Mentry Mscan p ))
    (Hscan_finished : (solver_propagation_scan_semantics n F A_arr K Mscan p confl retained
      (@nil Z) ))
    (Hreuse_scan : minisat_propagation_reuse_scan M0 Mscan p confl nil)
    (Hphysical_finished : (propagation_watch_scan_physical source_words retained moved (@nil Z)
      garbage watch_memory ii jj ))
    (Hscan_index_at_end : (ii = (Zlength (source_words))))
    (Hretained_length : (jj = (Zlength (retained))))
    (Hwatch_map_finished : ((ms_wm (Mscan)) = (app (scan_wm_pre) ((cons (retained)
      (scan_wm_post))))))
    (Hwatch_caps : ((ms_wcaps (Mscan)) = (app (scan_caps_pre) ((cons (scan_wcap)
      (scan_caps_post))))))
    (Hwatch_prefix_length : ((Zlength (scan_wm_pre)) = p))
    (Hcap_prefix_length : ((Zlength (scan_caps_pre)) = p))
    (Hwatch_slot : (ws = (vecp_slot (wl) (p))))
    (Hscan_pointer_at_end : ((begin + (ii * sizeof(PTR))) = (begin + ((Zlength (source_words)) *
      sizeof(PTR)))))
    (Hscan_pointer_ge_end : (i >= endvar))
    (Hscan_open : (solver_propagation_scan_semantics n F A_arr K Mscan p confl retained rest ))
    (Hphysical_open : (propagation_watch_scan_physical source_words retained moved rest garbage
      watch_memory ii jj ))
    (Hlogical_words : (logical_words = (app (retained) (rest))))
    (Hwatch_map_open : ((ms_wm (Mscan)) = (app (scan_wm_pre) ((cons (logical_words)
      (scan_wm_post))))))
    (Hend_pointer : (endvar = (begin + ((Zlength (source_words)) * sizeof(PTR)))))
    (Hmemory_source_length : ((Zlength (watch_memory)) = (Zlength (source_words))))
    (Hscan_pointer : (i = (begin + (ii * sizeof(PTR)))))
    (Hretain_pointer : (j = (begin + (jj * sizeof(PTR)))))
    (Hretain_index_nonnegative : (0 <= jj))
    (Hretain_index_le_scan : (jj <= ii))
    (Hscan_index_nonnegative : (0 <= ii))
    (Hscan_index_bound : (ii <= (Zlength (source_words))))
    (Hsimp_count : (simp_count = (ms_simpdb_props (Mscan))))
    (Hprop_count : (prop_count = (stats_propagations ((ms_stats (Mscan))))))
    (Hsource_within_cap : ((Zlength (source_words)) <= scan_wcap)),
  ((&((ws)  # "vecp_t" ->ₛ "size")) # Int  |-> (Zlength ((sublist (0) ((((begin + (jj * sizeof(PTR))) -
    retval_2 ) ÷ sizeof(PTR) )) (watch_memory)))))
  **  ((&((ws)  # "vecp_t" ->ₛ "cap")) # Int  |-> scan_wcap)
  **  ((&((ws)  # "vecp_t" ->ₛ "ptr")) # Ptr  |-> retval_2)
  **  (PtrArray.seg retval_2 0 (Zlength ((sublist (0) ((((begin + (jj * sizeof(PTR))) - retval_2 ) ÷
    sizeof(PTR) )) (watch_memory)))) (sublist (0) ((((begin + (jj * sizeof(PTR))) - retval_2 ) ÷ sizeof(PTR)
    )) (watch_memory)) )
  **  (PtrArray.undef_seg retval_2 (Zlength ((sublist (0) ((((begin + (jj * sizeof(PTR))) - retval_2 ) ÷
    sizeof(PTR) )) (watch_memory)))) scan_wcap )
  **  ((( &( "j" ) )) # Ptr  |-> (begin + (jj * sizeof(PTR))))
  **  ((( &( "begin" ) )) # Ptr  |-> begin)
  **  ((( &( "ws" ) )) # Ptr  |-> ws)
  **  ((( &( "endvar" ) )) # Ptr  |-> (begin + ((Zlength (source_words)) * sizeof(PTR))))
  **  ((( &( "i" ) )) # Ptr  |-> (begin + (ii * sizeof(PTR))))
  **  (wlists_source_hole_handle s_pre wl (Zlength (scan_wm_pre)) scan_wm_pre scan_wm_post scan_caps_pre
    scan_caps_post )
  **  (clause_db_rep (ms_prob (Mscan)) )
  **  (clause_db_rep (ms_learnt (Mscan)) )
  **  (CharArray.seg assigns_entry 0 (ms_size (Mscan)) (mt_assigns ((ms_core (Mscan)))) )
  **  (CharArray.undef_seg assigns_entry (ms_size (Mscan)) (ms_cap (Mscan)) )
  **  ((&((s_pre)  # "solver_t" ->ₛ "reasons")) # Ptr  |-> rsn_scan)
  **  ((&((s_pre)  # "solver_t" ->ₛ "levels")) # Ptr  |-> levels_entry)
  **  ((&((s_pre)  # "solver_t" ->ₛ "trail")) # Ptr  |-> trl_scan)
  **  (PtrArray.seg rsn_scan 0 (ms_size (Mscan)) (ms_reason_words (Mscan)) )
  **  (PtrArray.undef_seg rsn_scan (ms_size (Mscan)) (ms_cap (Mscan)) )
  **  (IntArray.seg levels_entry 0 (ms_size (Mscan)) (mt_levels ((ms_core (Mscan)))) )
  **  (IntArray.undef_seg levels_entry (ms_size (Mscan)) (ms_cap (Mscan)) )
  **  (IntArray.seg trl_scan 0 (ms_qtail (Mscan)) (mt_trail ((ms_core (Mscan)))) )
  **  (IntArray.undef_seg trl_scan (ms_qtail (Mscan)) (ms_cap (Mscan)) )
  **  (veci_rep &((s_pre)  # "solver_t" ->ₛ "trail_lim") (mt_lim ((ms_core (Mscan)))) (ms_lim_cap (Mscan)) )
  **  ((&((s_pre)  # "solver_t" ->ₛ "qhead")) # Int  |-> (mt_qhead ((ms_core (Mscan)))))
  **  ((&((s_pre)  # "solver_t" ->ₛ "qtail")) # Int  |-> (ms_qtail (Mscan)))
  **  ((&((s_pre)  # "solver_t" ->ₛ "simpdb_props")) # Int  |-> simp_count)
  **  ((&((s_pre)  # "solver_t" ->ₛ "assigns")) # Ptr  |-> assigns_entry)
  **  ((&((s_pre)  # "solver_t" ->ₛ "binary")) # Ptr  |-> (ms_binary (Mscan)))
  **  (solver_binary_rep Mscan )
  **  ((&((s_pre)  # "solver_t" ->ₛ "stats" .ₛ "propagations")) # UInt64  |-> prop_count)
  **  ((&((s_pre)  # "solver_t" ->ₛ "stats" .ₛ "inspects")) # UInt64  |-> (unsigned_last_nbits (((stats_inspects
  ((ms_stats (Mscan)))) + (unsigned_last_nbits ((((begin + (jj * sizeof(PTR))) - retval ) ÷ sizeof(PTR)
    )) (64)) )) (64)))
  **  (solver_propagate_frame s_pre Mscan )
  **  ((conflict_out_pre) # Ptr  |-> 0)
|--
  (EX (trl_finish: Z)  (rsn_finish: Z)  (Mfinish: msolver)  (lvl_finish: Z) ,
  propagation_scan_finish_arm (confl <> 0)
    (propagation_scan_conflict_finalize n F A_arr K M0 Mscan p confl jj retained Mfinish )
    trl_finish rsn_finish Mfinish lvl_finish levels_entry n F A_arr K M0 confl jj
    watch_memory retained scan_wm_pre scan_wm_post scan_caps_pre scan_caps_post
    scan_wcap s_pre wl assigns_entry conflict_out_pre)
  ||
  (EX (trl_finish: Z)  (rsn_finish: Z)  (Mfinish: msolver)  (lvl_finish: Z) ,
  propagation_scan_finish_arm (confl = 0)
    (propagation_scan_live_finalize n F A_arr K M0 Mscan p jj retained Mfinish)
    trl_finish rsn_finish Mfinish lvl_finish levels_entry n F A_arr K M0 confl jj
    watch_memory retained scan_wm_pre scan_wm_post scan_caps_pre scan_caps_post
    scan_wcap s_pre wl assigns_entry conflict_out_pre).
Proof.
  unfold propagation_scan_finish_arm.
  aggressive_pre_process.
  assert (Hfocus_level : confl <> 0 ->
    level_of (msolver_view n Mscan) (lit_var_c p) =
      Some (Zlength (mt_lim (ms_core Mscan)))).
  { intro Hnonzero.
    destruct Hscan_finished as [[Hzero Hlive]|[Hconflict [Hempty [Hready Hcert]]]].
    - contradiction.
    - unfold propagation_cancel_ready in Hready. tauto. }
  pose proof (minisat_propagation_reuse_scan_finish__api_reentry
    n M0 Mscan p confl jj Hreuse_scan Hfocus_level) as Hreuse_finish.
  pose proof (Zlength_nonneg watch_memory) as Hmemory_length_nonnegative.
  pose proof (Zlength_nonneg source_words) as Hsource_length_nonnegative.
  subst retval_2. subst retval. subst ws.
  assert (Hprefix : sublist 0 jj watch_memory = retained).
  { unfold propagation_watch_scan_physical in Hphysical_finished.
    destruct Hphysical_finished as [_ [Hmemory [Hretained _]]].
    rewrite Hmemory, app_nil_r, <- Hretained.
    rewrite sublist_app_exact1. reflexivity. }
  assert (Hshape_finish : solver_shape
    (msolver_propagation_scan_finish Mscan jj)).
  { apply solver_shape_scan_finish__propagate. exact Hshape. }
  assert (Hseed_finish : msolver_seed_shadow
    (msolver_propagation_scan_finish Mscan jj)).
  { change (msolver_seed_shadow Mscan). exact Hseed. }
  assert (Hloop_finish : solver_propagation_loop_inv n F A_arr K M0
    (msolver_propagation_scan_finish Mscan jj) confl).
  { eapply solver_propagation_scan_finish_loop__propagate;
      [exact Hcaller | exact Hscan_finished]. }
  assert (Hwm : Zlength (scan_wm_pre ++ retained :: scan_wm_post) =
    2 * ms_size Mscan).
  { pose proof Hshape as Hshape_wm.
    unfold solver_shape in Hshape_wm. rewrite <- Hwatch_map_finished. tauto. }
  assert (Hcaps : Zlength (scan_caps_pre ++ scan_wcap :: scan_caps_post) =
    2 * ms_size Mscan).
  { pose proof Hshape as Hshape_caps.
    unfold solver_shape in Hshape_caps. rewrite <- Hwatch_caps. tauto. }
  assert (Hdelta : 0 <= jj < 2 ^ 64) by lia.
  assert (Hqtail_size : ms_qtail Mscan <= ms_size Mscan).
  { eapply propagation_scan_semantics_qtail_size__propagate.
    exact Hscan_finished. }
  destruct (Z.eq_dec confl 0) as [Hconfl | Hconfl].
  - Right.
    Exists trl_scan rsn_scan (msolver_propagation_scan_finish Mscan jj)
      levels_entry.
    split_pure_spatial.
    + rewrite Hretained_index, Hprefix.
      sep_apply (vecp_raw_refold__propagate
        (vecp_slot wl p) begin retained scan_wcap ltac:(lia) ltac:(lia)).
      rewrite <- Hwatch_prefix_length.
      sep_apply (wlists_source_hole_refold__propagate
        s_pre wl (Zlength scan_wm_pre) scan_wm_pre retained scan_wm_post
        scan_caps_pre scan_wcap scan_caps_post (ms_size Mscan)
        ltac:(lia) eq_refl Hwm Hcaps).
      sep_apply (solver_propagate_frame_scan_finish__propagate
        s_pre Mscan jj Hshape).
      rewrite scan_finish_stats2__propagate by exact Hshape.
      rewrite scan_finish_stats3__propagate by assumption.
      rewrite solver_binary_rep_scan_finish__propagate.
      unfold solver_wlists_handle, PtrArray.seg.
      unfold msolver_propagation_scan_finish, msolver_propagation_overlay, msolver_propagation_update.
      cbn. rewrite Hsimp_count, Hprop_count, Hwatch_map_finished, Hwatch_caps.
      set_String_name. sepcon_assoc_change. sepcon_cancel.
      repeat sep_apply store_ptr_undef_store_ptr. entailer_with lia.
    + split_pures; dump_pre_spatial;
        try assumption; try reflexivity; try lia.
      * unfold propagation_scan_live_finalize.
        split; [reflexivity|]. split.
        -- rewrite <- Hconfl. exact Hscan_finished.
        -- rewrite <- Hconfl. exact Hloop_finish.
      * pose proof Hshape_finish as Hsf. unfold solver_shape in Hsf. tauto.
      * pose proof Hshape_finish as Hsf. unfold solver_shape in Hsf. tauto.
      * pose proof Hshape_finish as Hsf. unfold solver_shape in Hsf. tauto.
      * pose proof Hshape_finish as Hsf. unfold solver_shape in Hsf. tauto.
  - Left.
    Exists trl_scan rsn_scan (msolver_propagation_scan_finish Mscan jj)
      levels_entry.
    split_pure_spatial.
    + rewrite Hretained_index, Hprefix.
      sep_apply (vecp_raw_refold__propagate
        (vecp_slot wl p) begin retained scan_wcap ltac:(lia) ltac:(lia)).
      rewrite <- Hwatch_prefix_length.
      sep_apply (wlists_source_hole_refold__propagate
        s_pre wl (Zlength scan_wm_pre) scan_wm_pre retained scan_wm_post
        scan_caps_pre scan_wcap scan_caps_post (ms_size Mscan)
        ltac:(lia) eq_refl Hwm Hcaps).
      sep_apply (solver_propagate_frame_scan_finish__propagate
        s_pre Mscan jj Hshape).
      rewrite scan_finish_stats2__propagate by exact Hshape.
      rewrite scan_finish_stats3__propagate by assumption.
      rewrite solver_binary_rep_scan_finish__propagate.
      unfold solver_wlists_handle, PtrArray.seg.
      unfold msolver_propagation_scan_finish, msolver_propagation_overlay, msolver_propagation_update.
      cbn. rewrite Hsimp_count, Hprop_count, Hwatch_map_finished, Hwatch_caps.
      set_String_name. sepcon_assoc_change. sepcon_cancel.
      repeat sep_apply store_ptr_undef_store_ptr. entailer_with lia.
    + split_pures; dump_pre_spatial;
        try assumption; try reflexivity; try lia.
      * unfold propagation_scan_conflict_finalize.
        split; [exact Hconfl|]. split; [reflexivity|].
        split; [exact Hscan_finished|exact Hloop_finish].
      * pose proof Hshape_finish as Hsf. unfold solver_shape in Hsf. tauto.
      * pose proof Hshape_finish as Hsf. unfold solver_shape in Hsf. tauto.
      * pose proof Hshape_finish as Hsf. unfold solver_shape in Hsf. tauto.
      * pose proof Hshape_finish as Hsf. unfold solver_shape in Hsf. tauto.
Qed.


(* ===================================================================== *)
(* Non-[proof_of_] helpers hoisted out of the manual proof files.         *)
(*                                                                       *)
(* V2.0.4's structural checklist forbids a manual part from holding any   *)
(* lemma that is not a [proof_of_<obligation>].  Wrapping in a [Section]  *)
(* does NOT exempt them: a [Section] with no [Variable] generalises       *)
(* nothing, so every lemma below survived its [End] as a top-level name   *)
(* in the part.  They are moved here verbatim -- statements, proofs and   *)
(* rationale comments unchanged -- which is also what makes the parts     *)
(* prefix-free: each is reachable from [solver_qcp_lib.vo] rather         *)
(* than from a predecessor inside the same file.                         *)
(*                                                                       *)
(* Provenance: part1 x6, part2 x1, part7 x1, part8 x1.                    *)
(* ===================================================================== *)


(* ---- hoisted from solver_qcp_proof_manual_part1.v ---- *)

(* ---------------------------------------------------------------------- *)
(* Fold helpers used by the [solver_search] and [solver_solve]
   which-implies proofs in [solver_qcp_proof_manual_part1.v].  Search there
   for [scalars_rep_cla_inc_stats_eq] and [join_scalars_set_root] to locate
   the current consumers.  These conversion equalities and joins live here
   beside the shared peel/join bundle lemmas. *)
(** * Folding the solver bundles across a re-spelled entailment.

    Peel/join lemmas that let the expensive sites keep [solver_scalars_rep],
    [solver_fp_rep] and [solver_vecs_rep] FOLDED across an entailment whose two
    sides spell the same bundle differently (source: the [..._without_X_rep]
    companion plus a separate leaf; destination: the full bundle).  Unfolding
    both spellings into raw leaves increases the work of entailment
    automation: [Rename] poses and [change]s EVERY atom of BOTH sides over the
    whole goal, so the cost is (atoms x goal size), on top of [sepcon_cancel']'s
    O(atoms^2) bubbling.  Keeping the bundles folded turns ~25 leaves per side
    into 3 atoms per side. *)

(** [msolver_with_cla_inc_stats] touches only [cla_inc] and [stats], so it is
    invisible to the scalar and vector bundles, and invisible to the fp bundle
    when the new [cla_inc] is the old one.  All three hold by conversion. *)
Lemma scalars_rep_cla_inc_stats_eq : forall s M ci st,
  solver_scalars_rep s (msolver_with_cla_inc_stats M ci st)
  = solver_scalars_rep s M.
Proof. intros. reflexivity. Qed.

Lemma vecs_rep_cla_inc_stats_eq : forall s M ci st,
  solver_vecs_rep s (msolver_with_cla_inc_stats M ci st)
  = solver_vecs_rep s M.
Proof. intros. reflexivity. Qed.

Lemma fp_rep_cla_inc_stats_eq : forall s M st,
  solver_fp_rep s (msolver_with_cla_inc_stats M (ms_cla_inc M) st)
  = solver_fp_rep s M.
Proof. intros. reflexivity. Qed.

(** [msolver_set_root] rewrites only [root_level] (its other arguments are
    supplied as the record's own fields at every call site), so
    the fp and vector bundles are literally unchanged, and the scalar bundle
    is the [..._without_root_rep] companion plus the new root cell. *)
Lemma fp_rep_set_root_eq : forall s M r,
  solver_fp_rep s (msolver_set_root M r) = solver_fp_rep s M.
Proof. intros. reflexivity. Qed.

Lemma vecs_rep_set_root_eq : forall s M r,
  solver_vecs_rep s (msolver_set_root M r) = solver_vecs_rep s M.
Proof. intros. reflexivity. Qed.

Lemma join_scalars_set_root : forall s M r,
  &( s # "solver_t" ->ₛ "root_level") # Int |-> r **
  solver_scalars_without_root_rep s M
  |-- solver_scalars_rep s (msolver_set_root M r).
Proof.
  intros. unfold solver_scalars_rep, solver_scalars_without_root_rep,
    msolver_set_root, msolver_core_heap_update. cbn. msat_entailer_with lia.
Qed.

(** [solver_analyze_frame] is the tagging-stable view: it holds 8 of the 10
    scalar cells, 4 of the 6 fp cells, 2 of the 7 vectors and 9 of the 11
    statistics.  The analyze sites carry the missing cells as separate atoms, so
    discharging the entailment by unfolding BOTH spellings would take ~60 leaves
    per side.  This single join rebuilds the four bundles in one [sep_apply],
    leaving 4 folded atoms per side for the final cancellation step. *)
Lemma analyze_frame_join : forall s M wl,
  &( s # "solver_t" ->ₛ "size") # Int |-> ms_size M **
  &( s # "solver_t" ->ₛ "qtail") # Int |-> ms_qtail M **
  &( s # "solver_t" ->ₛ "var_inc") # Double |-> ms_var_inc M **
  &( s # "solver_t" ->ₛ "cla_inc") # Float |-> ms_cla_inc M **
  vecp_rep &( s # "solver_t" ->ₛ "learnts")
           (db_words (ms_learnt M)) (ms_learnt_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "tagged") (ms_tagged M) (ms_tagged_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "stack") (ms_stack M) (ms_stack_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "order") (ms_order M) (ms_order_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "trail_lim")
           (mt_lim (ms_core M)) (ms_lim_cap M) **
  &( s # "solver_t" ->ₛ "stats" .ₛ "max_literals")
    # UInt64 |-> stats_max_literals (ms_stats M) **
  &( s # "solver_t" ->ₛ "stats" .ₛ "tot_literals")
    # UInt64 |-> stats_tot_literals (ms_stats M) **
  solver_analyze_frame s M wl
  |-- solver_scalars_rep s M ** solver_fp_rep s M ** solver_vecs_rep s M **
      stats_rep &( s # "solver_t" ->ₛ "stats") (ms_stats M) **
      &( s # "solver_t" ->ₛ "binary") # Ptr |-> ms_binary M **
      (EX asg : Z,
         &( s # "solver_t" ->ₛ "wlists") # Ptr |-> wl **
         &( s # "solver_t" ->ₛ "assigns") # Ptr |-> asg **
         CharArray.seg asg 0 (ms_size M) (mt_assigns (ms_core M)) **
         CharArray.undef_seg asg (ms_size M) (ms_cap M) **
         wlists_rep wl (ms_size M) (ms_wm M) (ms_wcaps M)).
Proof. msat_analyze_frame_bridge p wl asg. Qed.

(* ---------------------------------------------------------------------- *)


(* ---- hoisted from solver_qcp_proof_manual_part7.v ---- *)

(** Normalizing a fully scanned conflict clause preserves its watcher
    occurrences, makes every literal false, and excludes any live reason
    pointer to the clause.  These facts are shared by the problem-clause and
    learnt-clause branches; their separate database updates use the same
    normalization result. *)
Lemma propagation_normalized_conflict_scan_facts :
  forall (n : Z) (F : cnf) (A_arr : list literal)
         (K : solver_propagation_context) (Mscan : msolver) (co : clause_obj)
         (scan_current p wm_len watch0 false_lit a0 a1 : Z) (tail : list Z),
  solver_propagation_weak n F A_arr K Mscan ->
  In (scan_current, co) (msolver_db Mscan) ->
  co_lits co = a0 :: a1 :: tail ->
  Forall (lit_wf_c n) (a0 :: a1 :: tail) ->
  (* the two enqueue-conflict facts, destructed once above the Split *)
  Znth (lit_var_c watch0) (mt_assigns (ms_core Mscan)) 0 <> 0 ->
  Znth (lit_var_c watch0) (mt_assigns (ms_core Mscan)) 0 <> lit_sig watch0 ->
  propagation_replacement_scan_inv n Mscan false_lit
    (propagation_normalized_clause watch0 false_lit (a0 :: a1 :: tail))
    (Zlength (propagation_normalized_clause watch0 false_lit
       (a0 :: a1 :: tail))) ->
  false_lit = lit_neg_c p ->
  real_watch_pair wm_len (a0 :: a1 :: tail) ->
  wm_len = p ->
  watch0 + false_lit =
    Znth 0 (a0 :: a1 :: tail) 0 + Znth 1 (a0 :: a1 :: tail) 0 ->
  sublist 2 (Zlength (a0 :: a1 :: tail)) (a0 :: a1 :: tail) = tail
  /\ Permutation (watch0 :: false_lit :: tail) (a0 :: a1 :: tail)
  /\ ((a0 = false_lit /\ watch0 = a1) \/ (a1 = false_lit /\ watch0 = a0))
  /\ lit_false (mt_assigns (ms_core Mscan)) watch0
  /\ Forall (lit_false (mt_assigns (ms_core Mscan)))
       (watch0 :: false_lit :: tail)
  /\ Forall (lit_false (mt_assigns (ms_core Mscan))) (a0 :: a1 :: tail)
  /\ Forall (fun l => eval_partial_literal (mt_pv (ms_core Mscan)) l =
       Some false) (denote_obj co)
  /\ (forall v, 0 <= v < n ->
       Znth v (ms_reason_words Mscan) 0 <> scan_current)
  /\ (forall l,
       Permutation (entry_watchers (scan_current, co) l)
         (entry_watchers
            (scan_current, clause_obj_with_lits co
               (watch0 :: false_lit :: tail)) l)).
Proof.
  intros n F A_arr K Mscan co scan_current p wm_len watch0 false_lit a0 a1 tail.
  intros Hweak Hin Hlits Hall Hassigned Hnotsig.
  intros Hscan_inv Hfalse_lit Hwatch_pair Hwatch_index Hwatch_sum.
  assert (Hdbwf : db_wf n (msolver_db Mscan)).
  { unfold solver_propagation_weak in Hweak.
    destruct Hweak as [_ Hweak]. destruct K.
    - exact (msw_db_wf Hweak).
    - exact (msa_db_wf Hweak). }
  assert (Htrailwf_old : mtrail_wf n (ms_core Mscan)).
  { unfold solver_propagation_weak in Hweak.
    destruct Hweak as [_ Hweak]. destruct K;
      [exact (msw_trail_wf Hweak)|exact (msa_trail_wf Hweak)]. }
  assert (Hstable_old : stable_view (msolver_view n Mscan)).
  { unfold solver_propagation_weak in Hweak.
    destruct Hweak as [_ Hweak]. destruct K;
      [exact (msw_stable Hweak)|exact (msa_stable Hweak)]. }
  assert (Hreasons_old : reasons_match n (ms_core Mscan)
      (msolver_db Mscan) (ms_reason_words Mscan) (ms_reason_of Mscan)).
  { unfold solver_propagation_weak in Hweak.
    destruct Hweak as [_ Hweak]. destruct K;
      [exact (msw_reasons_mem Hweak)|exact (msa_reasons_mem Hweak)]. }
  assert (Htail : sublist 2 (Zlength (a0 :: a1 :: tail))
      (a0 :: a1 :: tail) = tail).
  { replace (a0 :: a1 :: tail) with ((a0 :: a1 :: nil) ++ tail)
      by reflexivity.
    assert (Hrange : 2 <= 2 <=
        Zlength ((a0 :: a1 :: nil) ++ tail)).
    { split; [lia|]. rewrite Zlength_app.
      change (2 <= 2 + Zlength tail).
      pose proof (Zlength_nonneg tail). lia. }
    rewrite (sublist_split_app_r 2
      (Zlength ((a0 :: a1 :: nil) ++ tail)) 2
      (a0 :: a1 :: nil) tail ltac:(reflexivity) Hrange).
    replace (Zlength ((a0 :: a1 :: nil) ++ tail) - 2)
      with (Zlength tail) by
      (rewrite Zlength_app, !Zlength_cons, Zlength_nil; lia).
    apply sublist_self. reflexivity. }
  assert (Hwatchcases :
      (a0 = false_lit /\ watch0 = a1) \/
      (a1 = false_lit /\ watch0 = a0)).
  { unfold real_watch_pair in Hwatch_pair.
    rewrite !Znth0_cons in Hwatch_pair, Hwatch_sum.
    rewrite !Znth_cons in Hwatch_pair, Hwatch_sum by lia.
    replace (1 - 1) with 0 in Hwatch_pair, Hwatch_sum by lia.
    rewrite !Znth0_cons in Hwatch_pair, Hwatch_sum.
    destruct Hwatch_pair as [Hw | Hw].
    - left. rewrite Hwatch_index, <- Hfalse_lit in Hw. split; [exact Hw|lia].
    - right. rewrite Hwatch_index, <- Hfalse_lit in Hw. split; [exact Hw|lia]. }
  assert (Hperm : Permutation
      (propagation_normalized_clause watch0 false_lit
        (a0 :: a1 :: tail)) (a0 :: a1 :: tail)).
  { unfold propagation_normalized_clause. rewrite Htail.
    destruct Hwatchcases as [[Ha0 Hw] | [Ha1 Hw]].
    - subst a0 watch0. apply perm_swap.
    - subst a1 watch0. reflexivity. }
  unfold propagation_normalized_clause in Hperm. rewrite Htail in Hperm.
  assert (Hnew_eq : propagation_normalized_clause watch0 false_lit
      (a0 :: a1 :: tail) = watch0 :: false_lit :: tail).
  { unfold propagation_normalized_clause. rewrite Htail. reflexivity. }
  assert (Hwatch0_false :
      lit_false (mt_assigns (ms_core Mscan)) watch0).
  { assert (Hwatchwf : lit_wf_c n watch0).
    { (* the branch read this off Hobjnew, which is only available
         AFTER Hperm at the call site; Hwatchcases gives it here. *)
      rewrite Forall_forall in Hall.
      destruct Hwatchcases as [[_ Hw] | [_ Hw]]; rewrite Hw;
        apply Hall; simpl; auto. }
    pose proof (lit_var_c_in_range n watch0 Hwatchwf) as Hvr.
    pose proof (Forall_Znth_elim Z lbool_cell
      (mt_assigns (ms_core Mscan)) 0 (lit_var_c watch0)
      (mtw_cells Htrailwf_old) ltac:(rewrite (mtw_assigns_len
        Htrailwf_old); exact Hvr)) as Hcell.
    unfold lit_false. unfold lbool_cell in Hcell.
    destruct Hcell as [Hcell | [Hcell | Hcell]];
      destruct (lit_sig_values watch0) as [Hsig | Hsig];
      rewrite Hcell, Hsig in *; lia. }
  assert (Hnew_false : Forall (lit_false (mt_assigns (ms_core Mscan)))
      (watch0 :: false_lit :: tail)).
  { unfold propagation_replacement_scan_inv in Hscan_inv.
    destruct Hscan_inv as [Hkrange [Hnewwf [Hslot [Hfalse Hrestfalse]]]].
    rewrite Hnew_eq in Hkrange, Hnewwf, Hslot, Hrestfalse.
    constructor; [exact Hwatch0_false|].
    constructor; [exact Hfalse|].
    rewrite Forall_forall. intros x Hx.
    destruct (In_Znth_index tail x Hx) as [j [Hj Hval]].
    rewrite <- Hval.
    specialize (Hrestfalse (j + 2)).
    assert (Hjr : 2 <= j + 2 <
        Zlength (watch0 :: false_lit :: tail)).
    { rewrite !Zlength_cons. lia. }
    specialize (Hrestfalse Hjr).
    rewrite !Znth_cons in Hrestfalse by lia.
    replace (j + 2 - 1 - 1) with j in Hrestfalse by lia.
    exact Hrestfalse. }
  assert (Hold_false :
      Forall (lit_false (mt_assigns (ms_core Mscan)))
        (a0 :: a1 :: tail)).
  { eapply Forall_of_perm; [exact Hperm|exact Hnew_false]. }
  assert (Hden_false :
      Forall (fun l => eval_partial_literal (mt_pv (ms_core Mscan)) l =
        Some false) (denote_obj co)).
  { unfold denote_obj. rewrite Hlits.
    rewrite Forall_forall. intros l Hl.
    unfold lits_denote in Hl.
    apply in_map_iff in Hl as [x [<- Hx]].
    assert (Hx0 : 0 <= x).
    { rewrite Forall_forall in Hall. specialize (Hall x Hx).
      destruct Hall. lia. }
    rewrite Forall_forall in Hold_false.
    pose proof (proj1 (lit_false_iff (mt_assigns (ms_core Mscan)) x Hx0)
      (Hold_false x Hx)) as Heval.
    unfold eval_partial_literal in Heval |- *.
    rewrite lit_var_c_denote.
    rewrite mt_pv_nonneg by
      (apply lit_var_c_nonneg with (n := n);
       rewrite Forall_forall in Hall; exact (Hall x Hx)).
    unfold assigns_pv, assigns_val in Heval.
    rewrite lit_var_c_denote in Heval.
    exact Heval. }
  (* The lib lemma [no_live_reason_owner_false_clause__propagate_dbu]
     states this once, so it is not replayed by hand here. *)
  assert (Hno_reason_ptr : forall v, 0 <= v < n ->
      Znth v (ms_reason_words Mscan) 0 <> scan_current).
  { eapply no_live_reason_owner_false_clause__propagate_dbu;
      [ exact Hdbwf | exact Htrailwf_old | exact Hstable_old
      | exact Hreasons_old | exact Hin | exact Hden_false ]. }
  assert (Hentry_perm : forall l,
      Permutation (entry_watchers (scan_current, co) l)
        (entry_watchers (scan_current,
           clause_obj_with_lits co (watch0 :: false_lit :: tail)) l)).
  { intros l. destruct Hwatchcases as [[Ha0 Hw] | [Ha1 Hw]].
    - subst a0. subst watch0.
      unfold entry_watchers, co_watch0, co_watch1,
        clause_obj_with_lits. rewrite Hlits. cbn.
      apply Permutation_app_comm.
    - subst a1. subst watch0.
      unfold entry_watchers, co_watch0, co_watch1,
        clause_obj_with_lits. rewrite Hlits. cbn.
      reflexivity. }
  repeat split;
    [ exact Htail | exact Hperm | exact Hwatchcases | exact Hwatch0_false
    | exact Hnew_false | exact Hold_false | exact Hden_false
    | exact Hno_reason_ptr | exact Hentry_perm ].
Qed.

(* ---- hoisted from solver_qcp_proof_manual_part8.v ---- *)

(** * One join for the two capacity-publication exits.

    [proof_of_solver_prepare_public_capacity_exit_entail_wit_1_1] and [..._1_2]
    reach byte-identical goals apart from the publication flag:

      <7 peeled leaves> ** solver_public_capacity_frame s M
        |-- solver_rep s (msolver_publish_capacity M b)

    and each would otherwise discharge it by unfolding ELEVEN definitions on
    both sides (~50 leaves per side) before entailment automation. [Rename]
    is [pose; change] over the whole goal once per atom per side, so
    that work is quadratic in what the unfolds expose -- and it would be paid
    TWICE for the same entailment.  Proving it once here and closing each site
    with a search-free [apply] pays it once. *)
Lemma publish_capacity_join : forall s M b q wl,
  (** [q] is the value the [qhead] cell already carries: [ms_qtail M] on the
      [qh < qt] exit, and [mt_qhead (ms_core M)] on the [qh >= qt] exit, where
      the two are equal.  Parameterising is what lets ONE lemma serve both
      twins; rewriting instead would also hit [capacity_pending_qhead], which
      must keep the OLD qhead. *)
  q = ms_qtail M ->
  solver_shape (msolver_publish_capacity M b) ->
  (** NOTE: [**] is LEFT-associative, and the goal these two sites reach is
      RIGHT-nested; the parentheses below are what make the closer a
      search-free [apply] rather than a [sep_apply] pattern search. *)
  veci_rep &( s # "solver_t" ->ₛ "tagged") (@nil Z) (ms_tagged_cap M) **
  (veci_rep &( s # "solver_t" ->ₛ "stack") (@nil Z) (ms_stack_cap M) **
   (&( s # "solver_t" ->ₛ "qhead") # Int |-> q **
    (&( s # "solver_t" ->ₛ "qtail") # Int |-> ms_qtail M **
     (&( s # "solver_t" ->ₛ "capacity_pending_qhead")
      # Int |-> mt_qhead (ms_core M) **
      (&( s # "solver_t" ->ₛ "capacity_root_propagation_pending")
       # Int |-> b **
       (&( s # "solver_t" ->ₛ "root_level") # Int |-> 0 **
        solver_public_capacity_frame s M wl))))))
  |-- solver_rep_wl s (msolver_publish_capacity M b) wl.
Proof.
  intros s M b q wl Hq Hpublished_shape. subst q.
  (* [Intros]/[Exists] run BEFORE the leaf unfolds.  Both are whole-goal
     traversals, so opening only the three wrappers that carry the binders
     (solver_rep, solver_nonlevel_rep, solver_public_capacity_frame) and
     unfolding the leaves afterwards is strictly cheaper. *)
  unfold solver_rep_wl, solver_rep_levels_wl_at, solver_public_capacity_frame.
  Intros act asg opos rsn lvl trl tgs.
  Exists lvl act asg opos rsn trl tgs.
  unfold solver_nonlevel_rep_at, solver_nonlevel_rep_nostats_at, solver_scalars_rep, solver_vecs_rep,
  solver_trail_array_rep,
    solver_ptrs_rep, solver_var_arrays_rep,
    solver_levels_slice_at, msolver_publish_capacity, mt_set_qhead.
  unfold solver_fp_rep, solver_trail_array_rep.
  simpl.
  msat_entailer_with lia.
Qed.

(* ================= SECTION msat_variable_count_growth ================= *)

(** * Raising the variable count.

    Every [msolver_with_*] operation in this file keeps [ms_size] fixed:
    nothing here could describe MiniSat's [solver_setnvars], which grows the
    variable dimension.  This section supplies the model-side algebra for
    that growth.  It is organised by HOW each invariant field depends on
    the variable count [n], which turns out to be the whole difficulty:

    - the CDCL view does not read [n] at all: [view_of] takes it and ignores
      it, so every view-indexed field transports across a change of the
      variable count definitionally, with no lemma to state;
    - "every literal is in range" is monotone in [n] (B);
    - but [mtrail_wf] and [heap_wf] pin array LENGTHS to [n] exactly, so
      those need real extension operations, not monotonicity (C, D).
 *)


(* ================================================================= *)
(* B.  Genuinely MONOTONE well-formedness: "every literal is in      *)
(*     range" survives the range growing.                            *)
(* ================================================================= *)

Lemma lit_wf_c_mono : forall n n' l,
  n <= n' -> lit_wf_c n l -> lit_wf_c n' l.
Proof. unfold lit_wf_c. intros. lia. Qed.

Lemma obj_wf_mono : forall n n' co,
  n <= n' -> obj_wf n co -> obj_wf n' co.
Proof.
  intros n n' co Hle [Hlen [Hall Hnd]].
  split; [exact Hlen | split; [| exact Hnd]].
  eapply Forall_impl; [| exact Hall].
  intros a Ha. eapply lit_wf_c_mono; eauto.
Qed.

Lemma db_wf_mono : forall n n' db,
  n <= n' -> db_wf n db -> db_wf n' db.
Proof.
  intros n n' db Hle [Hnd [Heven Hall]].
  split; [exact Hnd | split; [exact Heven |]].
  eapply Forall_impl; [| exact Hall].
  intros e He. eapply obj_wf_mono; eauto.
Qed.

Lemma literal_wf_mono : forall n n' l,
  n <= n' -> literal_wf n l -> literal_wf n' l.
Proof. unfold literal_wf, var_in_range. intros. lia. Qed.

Lemma cnf_wf_mono : forall n n' F,
  n <= n' -> cnf_wf n F -> cnf_wf n' F.
Proof.
  intros n n' F Hle [Hn Hall].
  split; [lia |].
  eapply Forall_impl; [| exact Hall].
  intros c Hc. eapply Forall_impl; [| exact Hc].
  intros l Hl. eapply literal_wf_mono; eauto.
Qed.

(* ================================================================= *)
(* C.  NOT monotone: mtrail_wf pins Zlength (mt_assigns t) = n        *)
(*     exactly, so raising n needs a real EXTENSION operation --      *)
(*     which is what solver_setnvars' realloc+initialise loop does.   *)
(* ================================================================= *)

Definition mtrail_add_var (t : mtrail) : mtrail :=
  {| mt_assigns := mt_assigns t ++ (0 :: nil);
     mt_levels  := mt_levels t ++ (0 :: nil);
     mt_trail   := mt_trail t;
     mt_lim     := mt_lim t;
     mt_qhead   := mt_qhead t |}.

(* A trail literal names a variable strictly below the variable count.  The
   library already proves this: see [trail_var_range] and
   [lit_var_c_in_range] in [solver_qcp_model.v].  Reuse them rather than restating. *)
Lemma trail_var_lt : forall n t l,
  mtrail_wf n t -> In l (mt_trail t) -> 0 <= lit_var_c l < n.
Proof.
  intros n t l H Hin.
  apply (trail_var_range n t). exact H. apply in_map. exact Hin.
Qed.

(* Hence the freshly added variable [n] cannot already occur on the trail. *)
Lemma new_var_not_on_trail : forall n t,
  mtrail_wf n t -> ~ In n (map lit_var_c (mt_trail t)).
Proof.
  intros n t H Hin.
  pose proof (trail_var_range n t n H Hin). lia.
Qed.

Lemma mtrail_wf_add_var : forall n t,
  mtrail_wf n t -> mtrail_wf (n + 1) (mtrail_add_var t).
Proof.
  intros n t H.
  pose proof (mtw_n_nonneg H)     as Hn.
  pose proof (mtw_assigns_len H)  as Hal.
  pose proof (mtw_levels_len H)   as Hll.
  pose proof (mtw_cells H)        as Hce.
  pose proof (mtw_qhead_range H)  as Hqh.
  pose proof (mtw_trail_bound H)  as Htb.
  pose proof (mtw_trail_lits H)   as Htl.
  pose proof (mtw_trail_nodup H)  as Hnd.
  pose proof (mtw_trail_true H)   as Htt.
  pose proof (mtw_lim_sorted H)   as Hls.
  pose proof (mtw_lim_range H)    as Hlr.
  pose proof (mtw_levels_agree H) as Hla.
  pose proof (mtw_assigned_iff H) as Hai.
  constructor; simpl.
  - lia.
  - rewrite Zlength_app, Hal. rewrite Zlength_cons, Zlength_nil. lia.
  - rewrite Zlength_app, Hll. rewrite Zlength_cons, Zlength_nil. lia.
  - apply Forall_app. split; [exact Hce |].
    constructor; [| constructor]. unfold lbool_cell. right; left; reflexivity.
  - exact Hqh.
  - lia.
  - eapply Forall_impl; [| exact Htl].
    intros a Ha. eapply lit_wf_c_mono; [| exact Ha]. lia.
  - exact Hnd.
  - rewrite Forall_forall. intros l Hin.
    rewrite Forall_forall in Htt. specialize (Htt l Hin).
    pose proof (trail_var_lt n t l H Hin) as Hv.
    rewrite app_Znth1 by lia. exact Htt.
  - exact Hls.
  - exact Hlr.
  - intros i Hi. unfold trail_var. simpl.
    assert (Hin : In (Znth i (mt_trail t) 0) (mt_trail t))
      by (apply Znth_In; lia).
    pose proof (trail_var_lt n t _ H Hin) as Hv.
    rewrite app_Znth1 by lia.
    apply Hla. exact Hi.
  - intros v Hv.
    destruct (Z_lt_dec v n) as [Hlt | Hge].
    + rewrite app_Znth1 by lia. apply Hai. lia.
    + assert (v = n) by lia. subst v.
      rewrite app_Znth2 by lia.
      rewrite Hal, Z.sub_diag, Znth0_cons.
      split; [intros Hc; exfalso; apply Hc; reflexivity |].
      intros Hc. exfalso. eapply new_var_not_on_trail; eauto.
Qed.

(* ================================================================= *)
(* D.  The order heap.  [heap_wf] is purely STRUCTURAL -- NoDup,      *)
(*     bounds, and the heap/orderpos index inverse.  It says nothing  *)
(*     about activity ordering, so appending the new variable at the  *)
(*     end of the heap array (what veci_push does, before             *)
(*     order_update percolates it) preserves every conjunct.          *)
(* ================================================================= *)

Definition heap_add_var (n : Z) (h : mheap) : mheap :=
  {| mh_heap    := mh_heap h ++ (n :: nil);
     mh_orderpos := mh_orderpos h ++ (Zlength (mh_heap h) :: nil) |}.

Lemma heap_wf_add_var : forall n h,
  0 <= n -> heap_wf n h -> heap_wf (n + 1) (heap_add_var n h).
Proof.
  intros n h Hn [Hlen [Hnd [Hbnd [Hpos Hinv]]]].
  pose proof (Zlength_nonneg (mh_heap h)) as Hhn.
  assert (Hnotin : ~ In n (mh_heap h)).
  { rewrite Forall_forall in Hbnd. intros Hc. specialize (Hbnd n Hc). lia. }
  unfold heap_add_var, heap_wf. cbn [mh_heap mh_orderpos]. repeat split.
  - rewrite Zlength_app, Hlen, Zlength_cons, Zlength_nil. lia.
  - apply NoDup_snoc; assumption.
  - apply Forall_app. split.
    + eapply Forall_impl; [| exact Hbnd].
      intros a Ha. cbv beta in Ha |- *. lia.
    + constructor; [lia | constructor].
  - (* orderpos entry is absent, or points at its own heap slot *)
    intros v Hv. rewrite Zlength_app, Zlength_cons, Zlength_nil.
    destruct (Z_lt_dec v n) as [Hlt | Hge].
    + rewrite app_Znth1 by lia.
      destruct (Hpos v ltac:(lia)) as [Habs | [Hr Hh]].
      * left. exact Habs.
      * right. split; [lia |]. rewrite app_Znth1 by lia. exact Hh.
    + assert (v = n) by lia. subst v.
      rewrite app_Znth2 by lia. rewrite Hlen, Z.sub_diag, Znth0_cons.
      right. split; [lia |].
      rewrite app_Znth2 by lia. rewrite Z.sub_diag, Znth0_cons. reflexivity.
  - (* the heap/orderpos inverse, at every slot including the new one *)
    intros i Hi. rewrite Zlength_app, Zlength_cons, Zlength_nil in Hi.
    destruct (Z_lt_dec i (Zlength (mh_heap h))) as [Hlt | Hge].
    + (* resolve the INNER heap lookup first, or rewrite targets the outer one *)
      assert (Hin1 : Znth i (mh_heap h ++ (n :: nil)) (-1)
                     = Znth i (mh_heap h) (-1))
        by (apply app_Znth1; lia).
      rewrite Hin1.
      assert (Hin : In (Znth i (mh_heap h) (-1)) (mh_heap h))
        by (apply Znth_In; lia).
      rewrite Forall_forall in Hbnd. specialize (Hbnd _ Hin).
      rewrite app_Znth1 by lia. apply Hinv. lia.
    + assert (i = Zlength (mh_heap h)) by lia. subst i.
      assert (Hin2 : Znth (Zlength (mh_heap h)) (mh_heap h ++ (n :: nil)) (-1) = n).
      { rewrite app_Znth2 by lia. rewrite Z.sub_diag. apply Znth0_cons. }
      rewrite Hin2.
      rewrite app_Znth2 by lia. rewrite Hlen, Z.sub_diag, Znth0_cons.
      reflexivity.
Qed.

(* ==================================================================== *)
(* The solver_setnvars model layer.  It comes before the clause_new and  *)
(* solver_addclause layers below: addclause's annotation calls           *)
(* clause_new's _gen predicates and setnvars' [setnvars_core_equiv].     *)
(* ==================================================================== *)

(* ==================================================================== *)
(* Growth-side list algebra used by the layers below.                    *)
(* ==================================================================== *)


Lemma Znth_zero_singleton : forall i, Znth i (0 :: nil) 0 = 0.
Proof.
  intros i. unfold Znth. destruct (Z.to_nat i) as [|k]; [reflexivity |].
  destruct k; reflexivity.
Qed.

(* THE KEYSTONE.  Appending an unassigned cell does not change the partial
   valuation, so every assignment-indexed fact transports unchanged. *)

Lemma mt_pv_add_var : forall t, mt_pv (mtrail_add_var t) = mt_pv t.
Proof.
  intros t. apply functional_extensionality. intros v.
  unfold mt_pv, assigns_pv, assigns_val, mtrail_add_var.
  cbn [mt_assigns].
  destruct (0 <=? v)%Z eqn:Hv; [| reflexivity].
  apply Z.leb_le in Hv.
  destruct (Z_lt_dec v (Zlength (mt_assigns t))) as [Hlt | Hge].
  - rewrite app_Znth1 by lia. reflexivity.
  - rewrite app_Znth2 by lia. rewrite Znth_zero_singleton.
    rewrite (Znth_zero_past_end__order_select (mt_assigns t) v) by lia.
    reflexivity.
Qed.

Lemma trail_pos_add_var : forall t v,
  trail_pos (mtrail_add_var t) v = trail_pos t v.
Proof. reflexivity. Qed.

Lemma co_watch_wf : forall n co,
  obj_wf n co ->
  lit_wf_c n (co_watch0 co) /\ lit_wf_c n (co_watch1 co).
Proof.
  intros n co [Hlen [Hall _]].
  unfold co_watch0, co_watch1.
  rewrite Forall_forall in Hall.
  split; apply Hall; apply Znth_In; lia.
Qed.

Lemma entry_watchers_out_of_range : forall n e l,
  obj_wf n (snd e) -> 2 * n <= l -> entry_watchers e l = nil.
Proof.
  intros n [p co] l Hwf Hl. simpl in Hwf.
  destruct (co_watch_wf n co Hwf) as [Hw0 Hw1].
  apply lit_neg_c_wf in Hw0. apply lit_neg_c_wf in Hw1.
  unfold lit_wf_c in Hw0, Hw1.
  unfold entry_watchers.
  destruct (lit_neg_c (co_watch0 co) =? l)%Z eqn:E0.
  { apply Z.eqb_eq in E0. lia. }
  destruct (lit_neg_c (co_watch1 co) =? l)%Z eqn:E1.
  { apply Z.eqb_eq in E1. lia. }
  reflexivity.
Qed.

(* The two literals of a fresh variable watch nothing: no installed clause
   can mention them, because every clause is well-formed below the OLD
   variable count.  This is what makes the two fresh vecp_new buckets
   satisfy wmap_exact. *)

Lemma expected_watchers_out_of_range : forall n db l,
  db_wf n db -> 2 * n <= l -> expected_watchers db l = nil.
Proof.
  intros n db l [_ [_ Hall]] Hl.
  unfold expected_watchers.
  induction db as [| e db IH]; [reflexivity |].
  inversion Hall as [| e' db' He Hdb]; subst.
  simpl. rewrite (entry_watchers_out_of_range n e l He Hl). simpl.
  apply IH. exact Hdb.
Qed.

(* ==================================================================== *)
(* The msolver-level operation.                                          *)
(* ==================================================================== *)

(** One iteration of [solver_setnvars]' inner loop, as a ghost operation.

    Mirrors [solver_setnvars]' inner loop body in solver_qcp.c, for the
    variable [v := ms_size M]:

      vecp_new(&s->wlists[2*var]); vecp_new(&s->wlists[2*var+1]);
      s->activity[var] = 0;  s->assigns[var] = 0;
      s->orderpos[var] = veci_size(&s->order);
      s->reasons[var]  = 0;  s->levels[var] = 0;  s->tags[var] = 0;
      veci_push(&s->order, var);   order_update(s, var);   s->size = var + 1;

    [orderpos] is read BEFORE the push, so it names the slot the push then
    fills -- exactly [heap_add_var].  [order_update]'s sift is NOT modelled
    here: [heap_wf] is purely structural, so the existing order_update lemma
    composes on top of this.

    [ms_cap] is deliberately unchanged: the capacity loop and its eight
    reallocs run first, so growth happens with capacity already in hand.  The
    caller must therefore supply [ms_size M < ms_cap M]. *)

Definition msolver_add_var (M : msolver) (order_cap : Z) (a0 : fp64) : msolver := {|
  ms_size           := ms_size M + 1;
  ms_cap            := ms_cap M;
  ms_qtail          := ms_qtail M;
  ms_capacity_pending_qhead := ms_capacity_pending_qhead M;
  ms_capacity_root_propagation_pending :=
    ms_capacity_root_propagation_pending M;
  ms_core           := mtrail_add_var (ms_core M);
  ms_root_level     := ms_root_level M;
  ms_reason_words   := ms_reason_words M ++ (0 :: nil);
  ms_reason_of      := fun x => if Z.eqb x (ms_size M)
                                then None else ms_reason_of M x;
  ms_prob           := ms_prob M;
  ms_learnt         := ms_learnt M;
  ms_prob_cap       := ms_prob_cap M;
  ms_learnt_cap     := ms_learnt_cap M;
  ms_binary         := ms_binary M;
  ms_binary_lits    := ms_binary_lits M;
  ms_wm             := ms_wm M ++ (nil :: nil :: nil);
  ms_wcaps          := ms_wcaps M ++ (4 :: 4 :: nil);
  ms_activity       := ms_activity M ++ (a0 :: nil);
  ms_orderpos       := ms_orderpos M ++ (Zlength (ms_order M) :: nil);
  ms_order          := ms_order M ++ (ms_size M :: nil);
  ms_order_cap      := order_cap;
  ms_lim_cap        := ms_lim_cap M;
  ms_model          := ms_model M;
  ms_model_cap      := ms_model_cap M;
  ms_tags           := ms_tags M ++ (0 :: nil);
  ms_tagged         := ms_tagged M;
  ms_tagged_cap     := ms_tagged_cap M;
  ms_stack          := ms_stack M;
  ms_stack_cap      := ms_stack_cap M;
  ms_var_inc        := ms_var_inc M;
  ms_var_decay      := ms_var_decay M;
  ms_cla_inc        := ms_cla_inc M;
  ms_cla_decay      := ms_cla_decay M;
  ms_random_seed    := ms_random_seed M;
  ms_progress       := ms_progress M;
  ms_simpdb_assigns := ms_simpdb_assigns M;
  ms_simpdb_props   := ms_simpdb_props M;
  ms_verbosity      := ms_verbosity M;
  ms_stats          := ms_stats M
|}.

(* ---- projections: what the operation does to each derived structure ---- *)

Lemma msolver_add_var_core : forall M order_cap a0,
  ms_core (msolver_add_var M order_cap a0) = mtrail_add_var (ms_core M).
Proof. reflexivity. Qed.

Lemma msolver_add_var_heap : forall M order_cap a0,
  msolver_heap (msolver_add_var M order_cap a0) = heap_add_var (ms_size M) (msolver_heap M).
Proof. reflexivity. Qed.

Lemma msolver_add_var_db : forall M order_cap a0,
  msolver_db (msolver_add_var M order_cap a0) = msolver_db M.
Proof. reflexivity. Qed.

Lemma msolver_add_var_clauses : forall M order_cap a0,
  msolver_clauses (msolver_add_var M order_cap a0) = msolver_clauses M.
Proof. reflexivity. Qed.

Lemma msolver_add_var_size : forall M order_cap a0,
  ms_size (msolver_add_var M order_cap a0) = ms_size M + 1.
Proof. reflexivity. Qed.

(** [ms_order_cap] is a PARAMETER, not inherited.  No field of [solver_shape]
    or [msolver_inv_weak] constrains it -- the heap is well formed whatever
    slack its backing array carries -- but the SPATIAL layer projects it out of
    this same record ([veci_rep &(s->order) (ms_order M) (ms_order_cap M)]), and
    the [veci_reserve] that opens each loop iteration may grow it.  Pinning it
    to [ms_order_cap M] would describe an array of the wrong size at the post
    state.  Same treatment as [msolver_core_heap_update]. *)

Lemma msolver_view_add_var : forall n n' M order_cap a0,
  mtrail_wf (ms_size M) (ms_core M) ->
  msolver_view n (msolver_add_var M order_cap a0) = msolver_view n' M.
Proof.
  intros n n' M order_cap a0 Hwf.
  unfold msolver_view. rewrite msolver_add_var_core, msolver_add_var_clauses.
  cbn [ms_reason_of msolver_add_var].
  unfold view_of. f_equal.
  - apply mt_pv_add_var.
  - apply functional_extensionality. intros x.
    rewrite trail_pos_add_var.
    destruct (trail_pos (ms_core M) x) eqn:Ex; [| reflexivity].
    destruct (Z.eqb x (ms_size M)) eqn:Ev; [| reflexivity].
    apply Z.eqb_eq in Ev. subst x.
    exfalso.
    assert (Hnone : trail_pos (ms_core M) (ms_size M) = None).
    { apply trail_pos_none_iff.
      apply (new_var_not_on_trail (ms_size M) (ms_core M) Hwf). }
    rewrite Ex in Hnone. discriminate.
Qed.

(* ---- solver_shape: the eight length fields the C reallocs ------------- *)

(** [ms_cap] is untouched, so growth needs capacity already in hand -- which
    is exactly what the capacity loop and its eight reallocs establish before
    the per-variable loop runs.  The [2*(size+1) <= INT_MAX] side condition
    cannot be derived from [ms_cap <= INT_MAX] and must be supplied; in the C
    it follows from the caller's [maxvar+1] bound. *)

Lemma solver_shape_add_var : forall M order_cap a0,
  solver_shape M ->
  ms_size M < ms_cap M ->
  2 * (ms_size M + 1) <= INT_MAX ->
  solver_shape (msolver_add_var M order_cap a0).
Proof.
  intros M order_cap a0 Hsh Hcap Hint.
  unfold solver_shape in *.
  cbn [ms_size ms_cap ms_qtail ms_capacity_pending_qhead
       ms_capacity_root_propagation_pending ms_core ms_root_level
       ms_reason_words ms_orderpos ms_activity ms_tags ms_wm ms_wcaps
       ms_binary ms_binary_lits ms_stats msolver_add_var] in *.
  cbn [mt_assigns mt_levels mt_trail mt_qhead mt_lim mtrail_add_var] in *.
  rewrite !Zlength_app.
  change (Zlength (0 :: nil)) with 1.
  change (Zlength (a0 :: nil)) with 1.
  change (Zlength (Zlength (ms_order M) :: nil)) with 1.
  change (Zlength (@nil Z :: @nil Z :: nil)) with 2.
  change (Zlength (4 :: 4 :: nil)) with 2.
  repeat split; try tauto; try lia.
Qed.

(* ---- facts that read only the trail and the level boundaries ---------- *)

(** [decisions_upto] and [trail_implied] mention [mt_trail] and [mt_lim] only,
    and growth touches neither, so both are preserved DEFINITIONALLY. *)

Lemma decisions_upto_add_var : forall t d,
  decisions_upto (mtrail_add_var t) d = decisions_upto t d.
Proof. reflexivity. Qed.

Lemma trail_implied_add_var : forall F t,
  trail_implied F t -> trail_implied F (mtrail_add_var t).
Proof. intros F t H. exact H. Qed.

(* ---- the analysis scratch --------------------------------------------- *)

Lemma solver_tags_clear_add_var : forall M order_cap a0,
  solver_tags_clear M -> solver_tags_clear (msolver_add_var M order_cap a0).
Proof.
  intros M order_cap a0 [Htags Htagged]. unfold solver_tags_clear.
  cbn [ms_tags ms_tagged msolver_add_var]. split; [| exact Htagged].
  rewrite Forall_app. split; [exact Htags |].
  constructor; constructor.
Qed.

(* ---- the watcher table ------------------------------------------------- *)

(** The two fresh buckets are correct because nothing can watch the literals
    of a variable that did not exist: every installed clause is well formed
    below the OLD count, so [expected_watchers] is [nil] at 2n and 2n+1. *)

Lemma wmap_exact_add_var : forall n db wm,
  0 <= n ->
  db_wf n db ->
  wmap_exact n db wm ->
  wmap_exact (n + 1) db (wm ++ (nil :: nil :: nil)).
Proof.
  intros n db wm Hn Hdb [Hlen Hperm].
  unfold wmap_exact. split.
  - rewrite Zlength_app. change (Zlength (@nil Z :: @nil Z :: nil)) with 2. lia.
  - intros l Hl.
    destruct (Z_lt_dec l (2 * n)) as [Hlt | Hge].
    + rewrite app_Znth1 by lia. apply Hperm. lia.
    + rewrite app_Znth2 by lia.
      rewrite (expected_watchers_out_of_range n db l Hdb) by lia.
      assert (Hcase : l - Zlength wm = 0 \/ l - Zlength wm = 1) by lia.
      destruct Hcase as [E | E]; rewrite E; apply Permutation_refl.
Qed.

(* ---- level-indexed facts: unchanged below the old count --------------- *)

Lemma assump_true_at_root_add_var : forall n t root a,
  Zlength (mt_levels t) = n ->
  literal_wf n a ->
  assump_true_at_root t root a ->
  assump_true_at_root (mtrail_add_var t) root a.
Proof.
  intros n t root a Hlen Hwf [Hev Hlev].
  unfold assump_true_at_root in *.
  rewrite mt_pv_add_var.
  split; [exact Hev |].
  cbn [mt_levels mtrail_add_var].
  rewrite app_Znth1 by (unfold literal_wf, var_in_range in Hwf; lia).
  exact Hlev.
Qed.

Lemma root_satisfied_add_var : forall n t c,
  Zlength (mt_levels t) = n ->
  Forall (literal_wf n) c ->
  root_satisfied t c ->
  root_satisfied (mtrail_add_var t) c.
Proof.
  intros n t c Hlen Hwf [l [Hin [Hev Hlev]]].
  unfold root_satisfied. exists l.
  rewrite mt_pv_add_var.
  split; [exact Hin |]. split; [exact Hev |].
  cbn [mt_levels mtrail_add_var].
  rewrite Forall_forall in Hwf. specialize (Hwf l Hin).
  rewrite app_Znth1 by (unfold literal_wf, var_in_range in Hwf; lia).
  exact Hlev.
Qed.

(* ---- reasons ----------------------------------------------------------- *)

(** [reason_word_ok] reads the assignment cell of [v] (directly, and again
    inside [trail_lit_of]); both are below the old count, so appending leaves
    them alone. *)

Lemma reason_word_ok_add_var : forall t v db w r,
  0 <= v < Zlength (mt_assigns t) ->
  reason_word_ok t v db w r ->
  reason_word_ok (mtrail_add_var t) v db w r.
Proof.
  intros t v db w r Hv H.
  unfold reason_word_ok, trail_lit_of in *.
  cbn [mt_assigns mtrail_add_var].
  assert (Heq : Znth v (mt_assigns t ++ (0 :: nil)) 0 = Znth v (mt_assigns t) 0)
    by (apply app_Znth1; lia).
  rewrite Heq. exact H.
Qed.

(** Below the old count nothing moved; AT the new variable the reason word is
    the appended 0 and the ghost reason is [None], which is exactly what
    [reason_word_ok] demands of a null word. *)

Lemma reasons_match_add_var : forall n t db words r,
  Zlength words = n ->
  Zlength (mt_assigns t) = n ->
  reasons_match n t db words r ->
  reasons_match (n + 1) (mtrail_add_var t) db (words ++ (0 :: nil))
                (fun x => if Z.eqb x n then None else r x).
Proof.
  intros n t db words r Hw Ha H v Hv.
  destruct (Z.eq_dec v n) as [-> | Hne].
  - rewrite app_Znth2 by lia. rewrite Znth_zero_singleton.
    rewrite Z.eqb_refl. unfold reason_word_ok. cbn. reflexivity.
  - rewrite app_Znth1 by lia.
    assert (Hb : (v =? n)%Z = false) by (apply Z.eqb_neq; exact Hne).
    rewrite Hb.
    apply reason_word_ok_add_var; [lia |].
    apply H. lia.
Qed.

(** At the new variable the reason word is 0, so the "not null" hypothesis is
    false and the obligation is vacuous. *)

Lemma reason_head_ok_add_var : forall M order_cap a0,
  Zlength (ms_reason_words M) = ms_size M ->
  reason_head_ok M -> reason_head_ok (msolver_add_var M order_cap a0).
Proof.
  intros M order_cap a0 Hlen H v co Hv Htag Hnz Hin.
  cbn [ms_size ms_reason_words msolver_add_var] in Hv, Htag, Hnz, Hin |- *.
  destruct (Z.eq_dec v (ms_size M)) as [-> | Hne].
  - rewrite app_Znth2 in Hnz by lia. rewrite Znth_zero_singleton in Hnz.
    exfalso. apply Hnz. reflexivity.
  - rewrite app_Znth1 in Htag, Hnz, Hin by lia.
    apply (H v co); [lia | exact Htag | exact Hnz | exact Hin].
Qed.

(** Same vacuity, via [is_tag 0 = Z.odd 0 = false]. *)

Lemma binary_reason_same_level_add_var : forall M order_cap a0,
  Zlength (ms_reason_words M) = ms_size M ->
  Zlength (mt_levels (ms_core M)) = ms_size M ->
  binary_reason_same_level M ->
  binary_reason_same_level (msolver_add_var M order_cap a0).
Proof.
  intros M order_cap a0 Hw Hl H v Hv Htag.
  cbn [ms_size ms_reason_words ms_core msolver_add_var] in Hv, Htag |- *.
  destruct (Z.eq_dec v (ms_size M)) as [-> | Hne].
  - rewrite app_Znth2 in Htag by lia. rewrite Znth_zero_singleton in Htag.
    unfold is_tag in Htag. cbn in Htag. discriminate.
  - rewrite app_Znth1 in Htag |- * by lia.
    destruct (H v ltac:(lia) Htag) as (Hwf & Hlev & Hne2).
    split; [| split].
    + apply (lit_wf_c_mono (ms_size M)); [lia | exact Hwf].
    + cbn [mt_levels mtrail_add_var].
      pose proof (lit_var_c_in_range _ _ Hwf) as Hr.
      rewrite app_Znth1 by lia.
      rewrite app_Znth1 by lia.
      exact Hlev.
    + exact Hne2.
Qed.

(* ==================================================================== *)
(* THE ASSEMBLY: all 30 fields of msolver_inv_weak survive one growth    *)
(* step.  This is the loop invariant of solver_setnvars' inner loop.     *)
(* ==================================================================== *)

Theorem msolver_inv_weak_add_var : forall n F A_arr A_inst M order_cap a0,
  msolver_inv_weak n F A_arr A_inst M ->
  ms_size M < ms_cap M ->
  2 * (n + 1) <= INT_MAX ->
  msolver_inv_weak (n + 1) F A_arr A_inst (msolver_add_var M order_cap a0).
Proof.
  intros n F A_arr A_inst M order_cap a0 HI Hcap Hint.
  pose proof (msw_size HI) as Hsize. subst n.
  pose proof (msw_n_range HI) as Hn.
  pose proof (msw_shape HI) as Hsh.
  pose proof (msw_trail_wf HI) as Htw.
  pose proof (msw_F_wf HI) as HF.
  pose proof (msw_db_wf HI) as Hdb.
  assert (Hal : Zlength (mt_assigns (ms_core M)) = ms_size M)
    by exact (mtw_assigns_len Htw).
  assert (Hll : Zlength (mt_levels (ms_core M)) = ms_size M)
    by exact (mtw_levels_len Htw).
  assert (Hrw : Zlength (ms_reason_words M) = ms_size M)
    by (unfold solver_shape in Hsh; tauto).
  constructor.
  - (* msw_size *) reflexivity.
  - (* msw_n_range *) lia.
  - (* msw_shape *) apply solver_shape_add_var; assumption.
  - (* msw_F_wf *) apply (cnf_wf_mono (ms_size M)); [lia | exact HF].
  - (* msw_A_wf *)
    pose proof (msw_A_wf HI) as HA. rewrite Forall_forall in HA |- *.
    intros a Hin. apply (literal_wf_mono (ms_size M)); [lia | apply HA; exact Hin].
  - (* msw_trail_wf *) apply mtrail_wf_add_var. exact Htw.
  - (* msw_level_bound *) pose proof (msw_level_bound HI). cbn. lia.
  - (* msw_root_range *) exact (msw_root_range HI).
  - (* msw_assumptions *)
    rewrite msolver_add_var_core, decisions_upto_add_var.
    exact (msw_assumptions HI).
  - (* msw_assump_incl *) exact (msw_assump_incl HI).
  - (* msw_assump_sat *)
    pose proof (msw_A_wf HI) as HA. pose proof (msw_assump_sat HI) as HS.
    rewrite Forall_forall in HA, HS |- *. intros a Hin.
    rewrite msolver_add_var_core.
    apply (assump_true_at_root_add_var (ms_size M));
      [exact Hll | apply HA; exact Hin | apply HS; exact Hin].
  - (* msw_stable *)
    rewrite (msolver_view_add_var (ms_size M + 1) (ms_size M) M order_cap a0 Htw).
    exact (msw_stable HI).
  - (* msw_reasons_ent *)
    rewrite (msolver_view_add_var (ms_size M + 1) (ms_size M) M order_cap a0 Htw).
    exact (msw_reasons_ent HI).
  - (* msw_reasons_inj *)
    rewrite (msolver_view_add_var (ms_size M + 1) (ms_size M) M order_cap a0 Htw).
    exact (msw_reasons_inj HI).
  - (* msw_trail_impl *)
    rewrite msolver_add_var_core.
    apply trail_implied_add_var. exact (msw_trail_impl HI).
  - (* msw_db_wf *)
    rewrite msolver_add_var_db.
    apply (db_wf_mono (ms_size M)); [lia | exact Hdb].
  - (* msw_db_matches *) exact (msw_db_matches HI).
  - (* msw_db_implied *) exact (msw_db_implied HI).
  - (* msw_db_complete *)
    pose proof (msw_db_complete HI) as HC. intros c HcF.
    destruct (HC c HcF) as [Hleft | Hright]; [left; exact Hleft |].
    right. rewrite msolver_add_var_core.
    apply (root_satisfied_add_var (ms_size M)); [exact Hll | | exact Hright].
    destruct HF as [_ HFf]. rewrite Forall_forall in HFf. apply HFf. exact HcF.
  - (* msw_learnt_db *) exact (msw_learnt_db HI).
  - (* msw_prob_db *) exact (msw_prob_db HI).
  - (* msw_binary_out *) exact (msw_binary_out HI).
  - (* msw_reasons_mem *)
    rewrite msolver_add_var_core, msolver_add_var_db.
    apply (reasons_match_add_var (ms_size M)); [exact Hrw | exact Hal |].
    exact (msw_reasons_mem HI).
  - (* msw_reason_head *) apply reason_head_ok_add_var;
      [exact Hrw | exact (msw_reason_head HI)].
  - (* msw_reason_bin *) apply binary_reason_same_level_add_var;
      [exact Hrw | exact Hll | exact (msw_reason_bin HI)].
  - (* msw_wmap_exact *)
    rewrite msolver_add_var_db.
    apply wmap_exact_add_var; [lia | exact Hdb | exact (msw_wmap_exact HI)].
  - (* msw_tags_clear *) apply solver_tags_clear_add_var.
    exact (msw_tags_clear HI).
  - (* msw_heap_wf *)
    rewrite msolver_add_var_heap.
    apply heap_wf_add_var; [lia | exact (msw_heap_wf HI)].
  - (* msw_cla_inc_nonnegative *) exact (msw_cla_inc_nonnegative HI).
  - (* msw_seed *) exact (msw_seed HI).
Qed.

(* ==================================================================== *)
(*  The four fields the STRONG bundle adds over the weak one.            *)
(*                                                                      *)
(*  [solver_addclause] calls [clause_new], whose Require names           *)
(*  [msolver_inv], so [solver_setnvars] must hand back the strong        *)
(*  bundle, not just [msolver_inv_weak].                                 *)
(* ==================================================================== *)

(** [mtrail_add_var] appends to [mt_assigns] and [mt_levels] and touches
    NOTHING else -- [mt_trail], [mt_lim] and [mt_qhead] are inherited.  A
    property reading only the sequential fields is therefore literally the
    same proposition before and after. *)

Lemma prop_level_add_var : forall t,
  prop_level t -> prop_level (mtrail_add_var t).
Proof. intros t H. exact H. Qed.

(** A processed literal sits on the trail below [qhead], and every trail
    literal is [lit_wf_c n] -- so the fresh variable can never be processed
    and the processed set does not grow with the count.  Only this direction
    is needed: [watch_frontier] is a NEGATED conjunction, so shrinking the
    set it is stated over preserves it. *)

Lemma minisat_processed_add_var : forall n t l,
  mtrail_wf n t ->
  minisat_processed (n + 1) (mt_assigns t ++ (0 :: nil))
                    (mt_trail t) (mt_qhead t) l ->
  minisat_processed n (mt_assigns t) (mt_trail t) (mt_qhead t) l.
Proof.
  intros n t l Hwf [packed [Hwfp [Hden [Htrue [i [Hi Hidx]]]]]].
  assert (Hin : In packed (mt_trail t)).
  { rewrite <- Hidx. apply Znth_In.
    pose proof (mtw_qhead_range Hwf). lia. }
  pose proof (proj1 (Forall_forall _ _) (mtw_trail_lits Hwf) _ Hin) as Hn.
  pose proof (lit_var_c_in_range n packed Hn) as Hvr.
  exists packed. split; [exact Hn | split; [exact Hden | split]].
  - unfold lit_true in *. rewrite app_Znth1 in Htrue;
      [exact Htrue | rewrite (mtw_assigns_len Hwf); lia].
  - exists i. split; [exact Hi | exact Hidx].
Qed.

Lemma minisat_watch_frontier_add_var : forall n db t,
  mtrail_wf n t ->
  minisat_watch_frontier n db (mt_assigns t) (mt_trail t) (mt_qhead t) ->
  minisat_watch_frontier (n + 1) db (mt_assigns t ++ (0 :: nil))
                         (mt_trail t) (mt_qhead t).
Proof.
  intros n db t Hwf H.
  unfold minisat_watch_frontier, watch_frontier in *.
  eapply Forall_impl; [| exact H].
  intros o Ho [H1 H2]. apply Ho.
  split; eapply minisat_processed_add_var; eauto.
Qed.

(** The fresh variable IS pushed into the heap, so its [orderpos] entry is a
    real index and the "not in the heap" hypothesis is false there.  Below the
    old count both lists are read through [app_Znth1]. *)

Lemma heap_covers_add_var : forall n h assigns trail qhead,
  Zlength (mh_orderpos h) = n ->
  Zlength assigns = n ->
  heap_covers n h assigns trail qhead ->
  heap_covers (n + 1) (heap_add_var n h) (assigns ++ (0 :: nil)) trail qhead.
Proof.
  intros n h assigns trail qhead Hlo Hla H v Hv Hpos.
  cbn [mh_orderpos heap_add_var] in Hpos.
  destruct (Z.eq_dec v n) as [-> | Hne].
  - exfalso. rewrite app_Znth2 in Hpos by lia.
    rewrite Hlo, Z.sub_diag in Hpos.
    rewrite Znth0_cons in Hpos.
    pose proof (Zlength_nonneg (mh_heap h)). lia.
  - rewrite app_Znth1 in Hpos by lia.
    rewrite app_Znth1 by lia.
    apply H; [lia | exact Hpos].
Qed.

(** [level_of] is [option_map _ (trail_pos ...)], so [Some d] means the
    variable is ON THE TRAIL -- which bounds it below the OLD count.  The view
    itself is unchanged, so both the hypothesis and the rank conclusion are
    literally the old ones. *)

Lemma current_reasonless_earliest_add_var : forall n M order_cap a0,
  mtrail_wf (ms_size M) (ms_core M) ->
  Zlength (ms_reason_words M) = ms_size M ->
  current_reasonless_earliest n M ->
  current_reasonless_earliest (n + 1) (msolver_add_var M order_cap a0).
Proof.
  intros n M order_cap a0 Hwf Hrw H d Hd v Hlev Hword.
  cbn [ms_root_level ms_core ms_reason_words ms_reason_of
       msolver_add_var] in Hd, Hlev, Hword |- *.
  cbn [mt_lim mtrail_add_var] in Hd |- *.
  rewrite (msolver_view_add_var (n + 1) n M order_cap a0 Hwf) in Hlev |- *.
  assert (Hk : exists k, trail_pos (ms_core M) v = Some k).
  { unfold msolver_view, view_of in Hlev. cbn in Hlev.
    destruct (trail_pos (ms_core M) v) as [k |] eqn:E;
      [exists k; reflexivity | discriminate Hlev]. }
  destruct Hk as [k Hk].
  pose proof (trail_pos_some_var_range__search
                _ _ _ _ Hwf Hk) as Hvr.
  rewrite app_Znth1 in Hword by lia.
  destruct (H d Hd v Hlev Hword) as [Hr Hrank].
  split; [| exact Hrank].
  replace (v =? ms_size M)%Z with false
    by (symmetry; apply Z.eqb_neq; lia).
  exact Hr.
Qed.

(* ==================================================================== *)
(*  The strong step: one variable added, [msolver_inv] preserved.        *)
(*  This is the loop invariant [solver_setnvars]'s per-variable loop      *)
(*  actually needs, because [solver_addclause] goes on to call            *)
(*  [clause_new], whose Require names the strong bundle.                  *)
(* ==================================================================== *)

Theorem msolver_inv_add_var : forall n F A_arr A_inst M order_cap a0,
  msolver_inv n F A_arr A_inst M ->
  ms_size M < ms_cap M ->
  2 * (n + 1) <= INT_MAX ->
  msolver_inv (n + 1) F A_arr A_inst (msolver_add_var M order_cap a0).
Proof.
  intros n F A_arr A_inst M order_cap a0 HI Hcap Hint.
  pose proof (msi_size HI) as Hsize. subst n.
  pose proof (msi_trail_wf HI) as Htw.
  pose proof (msi_shape HI) as Hsh.
  assert (Hop : Zlength (ms_orderpos M) = ms_size M)
    by (unfold solver_shape in Hsh; tauto).
  assert (Hal : Zlength (mt_assigns (ms_core M)) = ms_size M)
    by exact (mtw_assigns_len Htw).
  assert (Hrw : Zlength (ms_reason_words M) = ms_size M)
    by (unfold solver_shape in Hsh; tauto).
  constructor.
  - exact (msolver_inv_weak_add_var _ _ _ _ _ order_cap a0
             (msi_weak HI) Hcap Hint).
  - cbn [ms_core msolver_add_var].
    exact (prop_level_add_var _ (msi_prop_level HI)).
  - rewrite msolver_add_var_db.
    cbn [ms_core msolver_add_var].
    cbn [mt_assigns mt_trail mt_qhead mtrail_add_var].
    exact (minisat_watch_frontier_add_var _ _ _ Htw (msi_watch_frontier HI)).
  - rewrite msolver_add_var_heap.
    cbn [ms_core msolver_add_var].
    cbn [mt_assigns mt_trail mt_qhead mtrail_add_var].
    apply heap_covers_add_var;
      [ cbn [mh_orderpos msolver_heap]; exact Hop
      | exact Hal
      | exact (msi_heap_covers HI) ].
  - exact (current_reasonless_earliest_add_var _ _ order_cap a0 Htw Hrw
             (msi_reasonless_current HI)).
Qed.

(* ==================================================================== *)
(*  The [order_update] sift, composed on top of the push.                *)
(*                                                                      *)
(*  The C ends each iteration with                                       *)
(*      check(veci_push(&s->order, var) == 1);   <- [msolver_add_var]     *)
(*      order_update(s, var);                    <- the sift, HERE        *)
(*  and [order_update]'s Ensure hands back exactly [order_update_post],   *)
(*  whose four components are precisely what the heap-indexed fields of   *)
(*  [msolver_inv] consume.                                               *)
(* ==================================================================== *)

(** [heap_covers] asks only whether a variable is ABSENT from the heap.
    [order_update_post]'s fourth component says the sift preserves exactly
    that, so coverage rides across unchanged. *)

Lemma heap_covers_membership_transport :
  forall n h1 h2 assigns trail qhead,
  (forall u, 0 <= u < n ->
     (Znth u (mh_orderpos h1) (-1) = -1 <-> Znth u (mh_orderpos h2) (-1) = -1)) ->
  heap_covers n h1 assigns trail qhead ->
  heap_covers n h2 assigns trail qhead.
Proof.
  intros n h1 h2 assigns trail qhead Hiff H v Hv Hpos.
  apply H; [exact Hv | exact (proj2 (Hiff v Hv) Hpos)].
Qed.

(** The strong-bundle analogue of the corpus's
    [solver_propagation_inv_heap_project__canceluntil_cap].
    [msolver_heap_project] rewrites only [ms_orderpos] / [ms_order] /
    [ms_order_cap]; every other field is inherited, so the 30 weak fields
    close by [assumption] once [solver_shape] and [heap_wf] are in hand. *)

Lemma msolver_inv_heap_project :
  forall n F A_arr A_inst M orderpos order order_cap,
  msolver_inv n F A_arr A_inst M ->
  heap_wf (ms_size M) (heap_of_lists order orderpos) ->
  heap_covers (ms_size M) (heap_of_lists order orderpos)
    (mt_assigns (ms_core M)) (mt_trail (ms_core M)) (mt_qhead (ms_core M)) ->
  msolver_inv n F A_arr A_inst
    (msolver_heap_project M orderpos order order_cap).
Proof.
  intros n F A_arr A_inst M orderpos order order_cap HI Hwf Hcovers.
  pose proof (msi_size HI) as Hsize.
  assert (Hwf_n : heap_wf n (heap_of_lists order orderpos))
    by (rewrite Hsize; exact Hwf).
  assert (Hcovers_n : heap_covers n (heap_of_lists order orderpos)
    (mt_assigns (ms_core M)) (mt_trail (ms_core M)) (mt_qhead (ms_core M)))
    by (rewrite Hsize; exact Hcovers).
  assert (Hshape1 : solver_shape
    (msolver_heap_project M orderpos order order_cap)).
  { apply solver_shape_heap_project__canceluntil_cap.
    - exact (msi_shape HI).
    - exact (heap_wf_orderpos_length (ms_size M)
               (heap_of_lists order orderpos) Hwf). }
  pose proof (msi_weak HI) as Hweak.
  assert (Hweak1 : msolver_inv_weak n F A_arr A_inst
    (msolver_heap_project M orderpos order order_cap)).
  { destruct Hweak.
    constructor;
      unfold msolver_heap_project, msolver_core_heap_update in *;
      simpl in *; try assumption. }
  constructor.
  - exact Hweak1.
  - unfold msolver_heap_project, msolver_core_heap_update. simpl.
    exact (msi_prop_level HI).
  - unfold msolver_heap_project, msolver_core_heap_update. simpl.
    exact (msi_watch_frontier HI).
  - unfold msolver_heap_project, msolver_core_heap_update. simpl.
    exact Hcovers_n.
  - unfold msolver_heap_project, msolver_core_heap_update. simpl.
    exact (msi_reasonless_current HI).
Qed.

(** ONE ITERATION of [solver_setnvars]'s per-variable loop, model side:
    the seven fresh cells and the heap push ([msolver_add_var]) followed by
    the sift ([msolver_heap_project] with whatever pair [order_update]
    returns).  The [order_cap] is the same on both sides because
    [order_update]'s own contract carries [veci_rep(&(s->order), _, order_cap)]
    unchanged across the call -- only the [veci_reserve] that OPENS the
    iteration may grow it. *)

Theorem msolver_inv_add_var_sift :
  forall n F A_arr A_inst M order_cap a0 order1 orderpos1,
  msolver_inv n F A_arr A_inst M ->
  ms_size M < ms_cap M ->
  2 * (n + 1) <= INT_MAX ->
  order_update_post (n + 1) (ms_size M)
    (ms_order M ++ (ms_size M :: nil))
    (ms_orderpos M ++ (Zlength (ms_order M) :: nil))
    order1 orderpos1 ->
  msolver_inv (n + 1) F A_arr A_inst
    (msolver_heap_project (msolver_add_var M order_cap a0)
                          orderpos1 order1 order_cap).
Proof.
  intros n F A_arr A_inst M order_cap a0 order1 orderpos1 HI Hcap Hint Hupd.
  pose proof (msi_size HI) as Hsize.
  pose proof (msolver_inv_add_var _ _ _ _ _ order_cap a0 HI Hcap Hint) as HI1.
  destruct Hupd as (Hpre & Hwf1 & Hperm & Hsame).
  apply msolver_inv_heap_project.
  - exact HI1.
  - rewrite msolver_add_var_size, <- Hsize. exact Hwf1.
  - rewrite msolver_add_var_size, <- Hsize.
    apply (heap_covers_membership_transport _
             (heap_of_lists (ms_order M ++ (ms_size M :: nil))
                            (ms_orderpos M ++ (Zlength (ms_order M) :: nil)))).
    + cbn [mh_orderpos heap_of_lists]. exact Hsame.
    + pose proof (msi_heap_covers HI1) as Hc.
      rewrite msolver_add_var_heap in Hc.
      cbn [ms_core msolver_add_var] in Hc |- *.
      exact Hc.
Qed.

(* The CAPACITY half of solver_setnvars' model transition.

   solver_setnvars does two independent things: it grows the storage capacity
   (the realloc block) and it appends variables (the per-variable loop).
   msolver_add_var covers the second and deliberately leaves ms_cap alone.
   This file covers the first.

   A corpus-wide grep establishes that ms_cap is load-bearing in exactly THREE
   pure conjuncts, all inside [solver_shape]:
       0 <= ms_size M <= ms_cap M
       ms_cap M <= INT_MAX
       0 <= ms_qtail M <= ms_cap M
   Every other occurrence is a spatial undef_seg span or a copy-through in a
   record update.  All three are monotone upward in ms_cap, so raising the
   capacity is a pure WEAKENING of the invariant -- the whole cost of growth
   is spatial, which is what the realloc shims pay. *)

Definition msolver_set_cap (M : msolver) (c : Z) : msolver :=
  msolver_propagation_update M (c) (ms_qtail M) (ms_capacity_root_propagation_pending M) (ms_core M)
    (ms_reason_words M) (ms_reason_of M) (ms_prob M) (ms_learnt M) (ms_binary_lits M) (ms_wm M) (ms_wcaps M)
    (ms_simpdb_props M) (ms_stats M).

Lemma msolver_set_cap_size : forall M c, ms_size (msolver_set_cap M c) = ms_size M.
Proof. reflexivity. Qed.

Lemma msolver_set_cap_cap : forall M c, ms_cap (msolver_set_cap M c) = c.
Proof. reflexivity. Qed.

Lemma msolver_set_cap_core : forall M c, ms_core (msolver_set_cap M c) = ms_core M.
Proof. reflexivity. Qed.

Lemma solver_shape_set_cap : forall M c,
  solver_shape M -> ms_cap M <= c -> c <= INT_MAX ->
  solver_shape (msolver_set_cap M c).
Proof.
  intros M c Hsh Hle Hmax.
  unfold solver_shape, msolver_set_cap, msolver_propagation_update in *; cbn in *.
  repeat match goal with H : _ /\ _ |- _ => destruct H end.
  repeat split; try assumption; try lia.
Qed.

Theorem msolver_inv_set_cap : forall n F A_arr A_inst M c,
  msolver_inv n F A_arr A_inst M ->
  ms_cap M <= c -> c <= INT_MAX ->
  msolver_inv n F A_arr A_inst (msolver_set_cap M c).
Proof.
  intros n F A_arr A_inst M c HI Hle Hmax.
  destruct HI as [Hw Hpl Hwf Hhc Hrc].
  constructor; [ | exact Hpl | exact Hwf | exact Hhc | exact Hrc ].
  destruct Hw. constructor; try assumption.
  apply solver_shape_set_cap; assumption.
Qed.

(* ==================================================================== *)
(* Uninitialized watcher-table slots.                                   *)
(* ==================================================================== *)

(* QCP names the ownership of an uninitialized struct by its C tag; lib.v
   already does this for [veci_t] ([UndefStructPredveci_t], which symexec
   emits into goal.v 30 times).  This is the [vecp_t] counterpart, and it is
   EXACTLY the three field cells [vecp_new]'s Require consumes. *)

Definition UndefStructPredvecp_t (v : Z) : Assertion :=
  vecp_size_addr v # Int |->_ **
  vecp_cap_addr  v # Int |->_ **
  vecp_ptr_addr  v # Ptr |->_.

(* Mirrors [wlists_rep_from]'s shape -- same [vecp_slot base i] addresses,
   same [i + 1] step -- but there is no list to recurse on, so the count is a
   nat.  Only the Z-indexed [wlists_undef] below is exposed to the C layer. *)

Fixpoint wlists_undef_count (base i : Z) (k : nat) : Assertion :=
  match k with
  | O => emp
  | S k' =>
      UndefStructPredvecp_t (vecp_slot base i) **
      wlists_undef_count base (i + 1) k'
  end.

Definition wlists_undef (base lo hi : Z) : Assertion :=
  wlists_undef_count base lo (Z.to_nat (hi - lo)).

(* An EQUATION, not an entailment: the degenerate region has to be rewritten
   away under the right-hand side of a split, where [sep_apply] cannot reach. *)

Lemma wlists_undef_peel : forall base lo hi,
  lo < hi ->
  wlists_undef base lo hi
  |-- UndefStructPredvecp_t (vecp_slot base lo) ** wlists_undef base (lo + 1) hi.
Proof.
  intros base lo hi H. unfold wlists_undef.
  replace (Z.to_nat (hi - lo)) with (S (Z.to_nat (hi - (lo + 1)))).
  2: { rewrite <- Z2Nat.inj_succ by lia. f_equal. lia. }
  simpl. msat_entailer_with lia.
Qed.

Lemma wlists_rep_from_two : forall base i,
  vecp_rep (vecp_slot base i) nil 4 **
  vecp_rep (vecp_slot base (i + 1)) nil 4
  |-- wlists_rep_from base i (nil :: nil :: nil) (4 :: 4 :: nil).
Proof. intros. simpl. msat_entailer_with lia. Qed.

Lemma wlists_rep_add_var : forall base n wm caps,
  0 <= n ->
  wlists_rep base n wm caps **
  vecp_rep (vecp_slot base (2 * n)) nil 4 **
  vecp_rep (vecp_slot base (2 * n + 1)) nil 4
  |-- wlists_rep base (n + 1) (wm ++ (nil :: nil :: nil)) (caps ++ (4 :: 4 :: nil)).
Proof.
  intros base n wm caps Hn. unfold wlists_rep. Intros.
  repeat match goal with H : _ /\ _ |- _ => destruct H end.
  assert (Hwm : Zlength (wm ++ (nil :: nil :: nil)) = 2 * (n + 1))
    by (rewrite Zlength_app, !Zlength_cons, Zlength_nil; lia).
  assert (Hcaps : Zlength (caps ++ (4 :: 4 :: nil)) = 2 * (n + 1))
    by (rewrite Zlength_app, !Zlength_cons, Zlength_nil; lia).
  (* Re-spell the fresh slots' index as [wlists_rep_from_app_join] wants it:
     the appended block sits at [0 + Zlength wm], not at [2 * n]. *)
  replace (2 * n) with (0 + Zlength wm) by lia.
  sep_apply (wlists_rep_from_two base (0 + Zlength wm)).
  sep_apply (wlists_rep_from_app_join base 0 wm
               (nil :: nil :: nil) caps (4 :: 4 :: nil) ltac:(lia)).
  msat_entailer_with lia.
Qed.

(* ==================================================================== *)
(* The growth-path representation.                                      *)
(* ==================================================================== *)

(** [solver_rep] does not own the unbuilt part of the watcher table, so a
    function that GROWS the variable count needs a representation that does.

    The load-bearing detail is that ONE existential scopes both the live
    table (inside [solver_rep_at]) and its tail.  A free-floating
    [wlists_undef] conjunct beside [solver_rep] would not do: [solver_rep]
    hides [wl], so every call that re-hides it severs the tail from the
    table it belongs to.  Here nothing can sever them.

    This is purely additive -- [solver_rep_at] and [solver_rep] are used
    unchanged, so no existing VC changes meaning. *)

Definition solver_rep_growable (s : Z) (M : msolver) : Assertion :=
  EX wl act asg opos rsn lvl trl tgs : Z,
    solver_rep_at s M wl act asg opos rsn lvl trl tgs **
    wlists_undef wl (2 * ms_size M) (2 * ms_cap M).

(* ==================================================================== *)
(* Opening the growth bundle.                                           *)
(* ==================================================================== *)

(** Everything [solver_setnvars] does NOT touch.  It grows the eight
    variable-indexed arrays and the order heap; every other component is
    inherited unchanged, so it is collected once here.  This is the corpus's
    residual-frame idiom ([clause_new_frame_at], [solver_cancel_frame]).

    NOTE the two splits: [size]/[cap] live inside [solver_scalars_rep] and
    [order] lives inside [solver_vecs_rep], so neither bundle can be reused
    whole -- their untouched members are re-spelled here. *)

Definition setnvars_frame_at (s : Z) (M : msolver) : Assertion :=
  (&( s # "solver_t" ->ₛ "qhead")          # Int |-> mt_qhead (ms_core M) **
   &( s # "solver_t" ->ₛ "capacity_pending_qhead")
                                 # Int |-> ms_capacity_pending_qhead M **
   &( s # "solver_t" ->ₛ "capacity_root_propagation_pending")
                       # Int |-> ms_capacity_root_propagation_pending M **
   &( s # "solver_t" ->ₛ "root_level")     # Int |-> ms_root_level M **
   &( s # "solver_t" ->ₛ "simpdb_assigns") # Int |-> ms_simpdb_assigns M **
   &( s # "solver_t" ->ₛ "simpdb_props")   # Int |-> ms_simpdb_props M **
   &( s # "solver_t" ->ₛ "verbosity")      # Int |-> ms_verbosity M) **
  (* [solver_fp_rep] is INLINED rather than reused: it takes the whole record,
     and [setnvars_frame_at_congr] below needs every field to appear as a
     PROJECTION so the 28 equalities can rewrite through it. *)
  (&( s # "solver_t" ->ₛ "var_inc")           # Double |-> ms_var_inc M **
   &( s # "solver_t" ->ₛ "var_decay")         # Double |-> ms_var_decay M **
   &( s # "solver_t" ->ₛ "cla_inc")           # Float  |-> ms_cla_inc M **
   &( s # "solver_t" ->ₛ "cla_decay")         # Float  |-> ms_cla_decay M **
   &( s # "solver_t" ->ₛ "random_seed")       # Double |-> ms_random_seed M **
   &( s # "solver_t" ->ₛ "progress_estimate") # Double |-> ms_progress M) **
  (vecp_rep &( s # "solver_t" ->ₛ "clauses")
            (map fst (ms_prob M)) (ms_prob_cap M) **
   vecp_rep &( s # "solver_t" ->ₛ "learnts")
            (map fst (ms_learnt M)) (ms_learnt_cap M) **
   veci_rep &( s # "solver_t" ->ₛ "tagged")    (ms_tagged M) (ms_tagged_cap M) **
   veci_rep &( s # "solver_t" ->ₛ "stack")     (ms_stack M)  (ms_stack_cap M) **
   veci_rep &( s # "solver_t" ->ₛ "trail_lim")
            (mt_lim (ms_core M)) (ms_lim_cap M) **
   veci_rep &( s # "solver_t" ->ₛ "model")     (ms_model M)  (ms_model_cap M)) **
  &( s # "solver_t" ->ₛ "binary") # Ptr |-> ms_binary M **
  MiniSatClause.rep (ms_binary M) false (ms_binary_lits M) **
  clause_db_rep (ms_prob M) **
  clause_db_rep (ms_learnt M) **
  stats_rep &( s # "solver_t" ->ₛ "stats") (ms_stats M).

(** What the growth loop actually works on: the size/cap cells, the eight
    array pointers, every variable-indexed array as a live prefix plus an
    undefined tail, the watcher table WITH its undefined tail, and the order
    heap. *)

Definition setnvars_open_at (s : Z) (M : msolver)
    (wl act asg opos rsn lvl trl tgs : Z) : Assertion :=
  &( s # "solver_t" ->ₛ "size")  # Int |-> ms_size M **
  &( s # "solver_t" ->ₛ "cap")   # Int |-> ms_cap M **
  (* qtail is READ (not written): the trail realloc shim takes it as its live-prefix
     argument, and QCP cannot read through the opaque frame. *)
  &( s # "solver_t" ->ₛ "qtail") # Int |-> ms_qtail M **
  (&( s # "solver_t" ->ₛ "wlists")   # Ptr |-> wl **
   &( s # "solver_t" ->ₛ "activity") # Ptr |-> act **
   &( s # "solver_t" ->ₛ "assigns")  # Ptr |-> asg **
   &( s # "solver_t" ->ₛ "orderpos") # Ptr |-> opos **
   &( s # "solver_t" ->ₛ "reasons")  # Ptr |-> rsn **
   &( s # "solver_t" ->ₛ "levels")   # Ptr |-> lvl **
   &( s # "solver_t" ->ₛ "trail")    # Ptr |-> trl **
   &( s # "solver_t" ->ₛ "tags")     # Ptr |-> tgs) **
  (DoubleArray.seg act 0 (ms_size M) (ms_activity M) **
   DoubleArray.undef_seg act (ms_size M) (ms_cap M) **
   CharArray.seg asg 0 (ms_size M) (mt_assigns (ms_core M)) **
   CharArray.undef_seg asg (ms_size M) (ms_cap M) **
   IntArray.seg opos 0 (ms_size M) (ms_orderpos M) **
   IntArray.undef_seg opos (ms_size M) (ms_cap M) **
   PtrArray.seg rsn 0 (ms_size M) (ms_reason_words M) **
   PtrArray.undef_seg rsn (ms_size M) (ms_cap M) **
   IntArray.seg lvl 0 (ms_size M) (mt_levels (ms_core M)) **
   IntArray.undef_seg lvl (ms_size M) (ms_cap M) **
   CharArray.seg tgs 0 (ms_size M) (ms_tags M) **
   CharArray.undef_seg tgs (ms_size M) (ms_cap M)) **
  solver_trail_array_rep M trl **
  wlists_rep wl (ms_size M) (ms_wm M) (ms_wcaps M) **
  wlists_undef wl (2 * ms_size M) (2 * ms_cap M) **
  veci_rep &( s # "solver_t" ->ₛ "order") (ms_order M) (ms_order_cap M).

Lemma setnvars_open : forall s Mg,
  solver_rep_growable s Mg
  |-- EX wl act asg opos rsn lvl trl tgs : Z,
        “ solver_shape Mg ” &&
        (setnvars_open_at s Mg wl act asg opos rsn lvl trl tgs **
         setnvars_frame_at s Mg).
Proof.
  intros s Mg. unfold solver_rep_growable.
  Intros wl act asg opos rsn lvl trl tgs.
  Exists wl act asg opos rsn lvl trl tgs.
  unfold solver_rep_at, solver_nonlevel_rep_at, solver_nonlevel_rep_nostats_at, solver_levels_slice_at,
         solver_scalars_rep, solver_vecs_rep, solver_fp_rep,
         setnvars_open_at, setnvars_frame_at.
  msat_entailer_with lia.
Qed.

(** The nine field cells -- the [qtail] counter and the eight array base
    pointers -- and the sixteen array/watch-list atoms that the three
    bundle-carrying cuts of [solver_setnvars] name: the entry which-implies,
    the growth-loop invariant and the initialising-loop invariant.  [size] and
    [cap] stay outside: the body reads them in its prologue, in the
    growth-shim arguments and at the initialising loop's head, and writes
    [cap] after the growth step and [size] at the end of each initialising
    iteration and on the capacity-abort path.  The size bound is an explicit
    argument ([sz]) so the initialising loop -- which writes one index of each
    of the six size-indexed arrays and the two watch-list entries of the new
    variable per iteration, and leaves the [qtail]-indexed trail pair
    untouched -- can spell it as the loop counter [var]; the shared undef
    write rules match the write index against that argument syntactically.
    The trail pair is spelled inline (not via [solver_trail_array_rep]) so that
    strategy rule 62 emits exactly the atoms the loop-body cuts name. *)
Definition setnvars_arrays_at (s : Z) (M : msolver) (sz : Z)
    (wl act asg opos rsn lvl trl tgs : Z) : Assertion :=
  &( s # "solver_t" ->ₛ "qtail") # Int |-> ms_qtail M **
  &( s # "solver_t" ->ₛ "wlists")   # Ptr |-> wl **
  &( s # "solver_t" ->ₛ "activity") # Ptr |-> act **
  &( s # "solver_t" ->ₛ "assigns")  # Ptr |-> asg **
  &( s # "solver_t" ->ₛ "orderpos") # Ptr |-> opos **
  &( s # "solver_t" ->ₛ "reasons")  # Ptr |-> rsn **
  &( s # "solver_t" ->ₛ "levels")   # Ptr |-> lvl **
  &( s # "solver_t" ->ₛ "trail")    # Ptr |-> trl **
  &( s # "solver_t" ->ₛ "tags")     # Ptr |-> tgs **
  DoubleArray.seg act 0 sz (ms_activity M) **
  DoubleArray.undef_seg act sz (ms_cap M) **
  CharArray.seg asg 0 sz (mt_assigns (ms_core M)) **
  CharArray.undef_seg asg sz (ms_cap M) **
  IntArray.seg opos 0 sz (ms_orderpos M) **
  IntArray.undef_seg opos sz (ms_cap M) **
  PtrArray.seg rsn 0 sz (ms_reason_words M) **
  PtrArray.undef_seg rsn sz (ms_cap M) **
  IntArray.seg lvl 0 sz (mt_levels (ms_core M)) **
  IntArray.undef_seg lvl sz (ms_cap M) **
  CharArray.seg tgs 0 sz (ms_tags M) **
  CharArray.undef_seg tgs sz (ms_cap M) **
  IntArray.seg trl 0 (ms_qtail M) (mt_trail (ms_core M)) **
  IntArray.undef_seg trl (ms_qtail M) (ms_cap M) **
  wlists_rep wl sz (ms_wm M) (ms_wcaps M) **
  wlists_undef wl (2 * sz) (2 * ms_cap M).

(** [setnvars_open_at] is [size ** cap ** setnvars_arrays_at (ms_size M)
    ** order]; this is the [setnvars_open] shape restated over the bundle for
    [solver_setnvars_which_implies_wit_1]. *)
Lemma setnvars_open_arrays : forall s Mg,
  solver_rep_growable s Mg
  |-- EX wl act asg opos rsn lvl trl tgs : Z,
        “ solver_shape Mg ” &&
        (&( s # "solver_t" ->ₛ "size") # Int |-> ms_size Mg **
         &( s # "solver_t" ->ₛ "cap")  # Int |-> ms_cap Mg **
         setnvars_arrays_at s Mg (ms_size Mg) wl act asg opos rsn lvl trl tgs **
         veci_rep &( s # "solver_t" ->ₛ "order") (ms_order Mg) (ms_order_cap Mg) **
         setnvars_frame_at s Mg).
Proof.
  intros s Mg. sep_apply setnvars_open.
  Intros wl act asg opos rsn lvl trl tgs.
  Exists wl act asg opos rsn lvl trl tgs.
  unfold setnvars_open_at, setnvars_arrays_at, solver_trail_array_rep.
  msat_entailer_with lia.
Qed.

Definition setnvars_core_equiv (M0 M : msolver) : Prop :=
  mt_qhead (ms_core M) = mt_qhead (ms_core M0) /\
  mt_lim   (ms_core M) = mt_lim   (ms_core M0) /\
  ms_qtail M = ms_qtail M0 /\
  ms_capacity_pending_qhead M = ms_capacity_pending_qhead M0 /\
  ms_capacity_root_propagation_pending M =
    ms_capacity_root_propagation_pending M0 /\
  ms_root_level M = ms_root_level M0 /\
  ms_prob M = ms_prob M0 /\ ms_learnt M = ms_learnt M0 /\
  ms_prob_cap M = ms_prob_cap M0 /\ ms_learnt_cap M = ms_learnt_cap M0 /\
  ms_binary M = ms_binary M0 /\ ms_binary_lits M = ms_binary_lits M0 /\
  ms_lim_cap M = ms_lim_cap M0 /\
  ms_model M = ms_model M0 /\ ms_model_cap M = ms_model_cap M0 /\
  ms_tagged M = ms_tagged M0 /\ ms_tagged_cap M = ms_tagged_cap M0 /\
  ms_stack M = ms_stack M0 /\ ms_stack_cap M = ms_stack_cap M0 /\
  ms_var_inc M = ms_var_inc M0 /\ ms_var_decay M = ms_var_decay M0 /\
  ms_cla_inc M = ms_cla_inc M0 /\ ms_cla_decay M = ms_cla_decay M0 /\
  ms_random_seed M = ms_random_seed M0 /\ ms_progress M = ms_progress M0 /\
  ms_simpdb_assigns M = ms_simpdb_assigns M0 /\
  ms_simpdb_props M = ms_simpdb_props M0 /\
  ms_verbosity M = ms_verbosity M0 /\ ms_stats M = ms_stats M0.

(** [solver_setnvars]' whole Ensure, as one predicate -- the
    [clause_new_post_at] idiom.

    The success arm is NOT [ms_size M = n]: the growth loop is
    [for (var = s->size; var < n; var++)], so when [n <= ms_size M0] it never
    runs and the size is unchanged. The two alternatives below express
    exactly [ms_size M = Z.max (ms_size M0) n], excluding an arbitrary
    increase in the number of variables.

    [2 * ms_cap M <= INT_MAX] is carried because the watcher table is indexed
    [2*var] / [2*var+1] and the wlists realloc computes its element count as
    [new_cap * 2] in *int* arithmetic. *)

Definition setnvars_post_at (s n : Z) (M0 : msolver) (F : cnf)
    (A_arr A_inst : list literal) (logical_root ret : Z) : Assertion :=
  EX M : msolver,
    “ ((ret = 1 /\ n <= ms_size M /\
        (ms_size M = n \/ ms_size M = ms_size M0)) \/
       (ret = -2 /\ ms_size M <= n)) /\
      ms_size M0 <= ms_size M /\
      ms_cap  M0 <= ms_cap  M /\
      2 * ms_cap M <= INT_MAX /\
      ((Zlength (mt_lim (ms_core M0)) = 0 /\
        ms_capacity_root_propagation_pending M0 = 0 /\
        msolver_seed_shadow M0) ->
       (Zlength (mt_lim (ms_core M)) = 0 /\
        ms_capacity_root_propagation_pending M = 0 /\
        msolver_seed_shadow M)) /\
      ms_root_level M = ms_root_level M0 /\
      solver_support_inv (ms_size M) F A_arr A_inst logical_root M /\
      (minisat_watch_completed M0 -> minisat_watch_completed M) ” &&
    solver_rep_growable s M.

Lemma setnvars_frame_at_congr : forall s M0 M,
  setnvars_core_equiv M0 M ->
  setnvars_frame_at s M = setnvars_frame_at s M0.
Proof.
  intros s M0 M H. unfold setnvars_core_equiv in H.
  unfold setnvars_frame_at.
  destruct H as (Hqh & Hlm & Hqt & Hcp & Hcr & Hrl & Hpb & Hlr & Hpc & Hlc
                 & Hbi & Hbl & Hlim & Hmo & Hmc & Htg & Htc & Hst & Hsc
                 & Hvi & Hvd & Hci & Hcd & Hrs & Hpr & Hsa & Hsp & Hvb & Hstats).
  rewrite ?Hqh, ?Hlm, ?Hqt, ?Hcp, ?Hcr, ?Hrl, ?Hpb, ?Hlr, ?Hpc, ?Hlc,
          ?Hbi, ?Hbl, ?Hlim, ?Hmo, ?Hmc, ?Htg, ?Htc, ?Hst, ?Hsc, ?Hvi, ?Hvd,
          ?Hci, ?Hcd, ?Hrs, ?Hpr, ?Hsa, ?Hsp, ?Hvb, ?Hstats.
  reflexivity.
Qed.

(* ==================================================================== *)
(* Glue: the frame survives every step solver_setnvars takes.           *)
(* ==================================================================== *)

Lemma setnvars_core_equiv_refl : forall M, setnvars_core_equiv M M.
Proof. intros M. unfold setnvars_core_equiv. repeat split; reflexivity. Qed.

Lemma setnvars_core_equiv_trans : forall M0 M1 M2,
  setnvars_core_equiv M0 M1 -> setnvars_core_equiv M1 M2 ->
  setnvars_core_equiv M0 M2.
Proof.
  intros M0 M1 M2 H01 H12. unfold setnvars_core_equiv in *.
  repeat match goal with H : _ /\ _ |- _ => destruct H end.
  repeat split; etransitivity; eassumption.
Qed.

(** The capacity half touches no frame field. *)

Lemma setnvars_core_equiv_set_cap : forall M c,
  setnvars_core_equiv M (msolver_set_cap M c).
Proof.
  intros M c. unfold setnvars_core_equiv, msolver_set_cap, msolver_propagation_update.
  repeat split; reflexivity.
Qed.

(** The variable-append half touches no frame field either.  [mtrail_add_var]
    only appends to [mt_assigns] / [mt_levels], so the two
    [ms_core]-derived reads in the frame -- [mt_qhead] and [mt_lim] -- both
    survive, and [msolver_heap_project] rewrites only orderpos/order/order_cap. *)

Lemma setnvars_core_equiv_add_var_sift : forall M order_cap a0 orderpos1 order1 oc,
  setnvars_core_equiv M
    (msolver_heap_project (msolver_add_var M order_cap a0) orderpos1 order1 oc).
Proof.
  intros M order_cap a0 orderpos1 order1 oc.
  unfold setnvars_core_equiv, msolver_heap_project, msolver_core_heap_update,
         msolver_add_var, mtrail_add_var.
  repeat split; reflexivity.
Qed.

(** Consequently the residual frame is literally the same assertion before and
    after a growth step -- this is what closes the loop cut. *)

Lemma setnvars_frame_at_add_var_sift : forall s M order_cap a0 orderpos1 order1 oc,
  setnvars_frame_at s
    (msolver_heap_project (msolver_add_var M order_cap a0) orderpos1 order1 oc)
  = setnvars_frame_at s M.
Proof.
  intros. apply setnvars_frame_at_congr.
  apply setnvars_core_equiv_add_var_sift.
Qed.

Lemma setnvars_frame_at_set_cap : forall s M c,
  setnvars_frame_at s (msolver_set_cap M c) = setnvars_frame_at s M.
Proof.
  intros. apply setnvars_frame_at_congr. apply setnvars_core_equiv_set_cap.
Qed.

(** [order_update]'s Require, at the state the growth loop reaches it: the heap
    already holds the freshly pushed variable and [orderpos] its slot.  All three
    conjuncts come out of the post-append invariant -- [msw_heap_wf] IS
    [order_heap_wf] on those two lists, definitionally, because
    [msolver_heap M = {| mh_heap := ms_order M; mh_orderpos := ms_orderpos M |}]. *)

Lemma order_update_pre_add_var : forall n F A_arr A_inst M,
  msolver_inv n F A_arr A_inst M ->
  ms_size M < ms_cap M ->
  2 * (n + 1) <= INT_MAX ->
  order_update_pre (n + 1) (ms_size M)
    (ms_order M ++ (ms_size M :: nil))
    (ms_orderpos M ++ (Zlength (ms_order M) :: nil)).
Proof.
  intros n F A_arr A_inst M HI Hcap Hint.
  (* the witnesses are irrelevant to the conclusion; pick the state's own. *)
  set (order_cap := ms_order_cap M). set (a0 := Z_to_fp64 0).
  pose proof (msi_size HI) as Hsize.
  pose proof (msw_shape (msi_weak HI)) as Hsh.
  unfold solver_shape in Hsh.
  repeat match goal with H : _ /\ _ |- _ => destruct H end.
  assert (Hopl : Zlength (ms_orderpos M) = ms_size M) by assumption.
  pose proof (msolver_inv_add_var _ _ _ _ _ order_cap a0 HI Hcap Hint) as HI1.
  pose proof (msw_heap_wf (msi_weak HI1)) as Hwf.
  unfold order_update_pre. split; [ | split ].
  - exact Hwf.
  - lia.
  - rewrite app_Znth2 by lia. rewrite Hopl.
    replace (ms_size M - ms_size M) with 0 by lia.
    cbn. pose proof (Zlength_nonneg (ms_order M)). lia.
Qed.

(** The growth loop's boundary fact.

    [var] starts at [ms_size sn_M], which may ALREADY exceed [n]: a call asking
    for fewer variables than exist is a legal no-op.  So [var <= n] is not
    inductive at entry -- stating it emitted two FALSE entry obligations
    (entail_wit_3_1 / 3_2, each requiring [ms_size sn_M <= n_pre] with nothing
    to prove it from).  This disjunction IS inductive, and at exit it is exactly
    the case split [setnvars_post_at]'s success arm needs.

    It is an opaque Coq Prop on purpose: a bare `||` inside a C assertion is a
    PATH SPLIT in QCP, which would double the rest of the proof. *)

Definition setnvars_bound (n0 var n : Z) : Prop := var = n0 \/ var <= n.

Lemma setnvars_bound_entry : forall n0 n, setnvars_bound n0 n0 n.
Proof. intros. left. reflexivity. Qed.

Lemma setnvars_bound_step : forall n0 var n,
  var < n -> setnvars_bound n0 (var + 1) n.
Proof. intros n0 var n H. right. lia. Qed.

(** At exit ([var >= n]) the disjunction collapses to exactly the two arms the
    postcondition offers: the loop ran to [n], or it never ran. *)

Lemma setnvars_bound_exit : forall n0 var n,
  setnvars_bound n0 var n -> n <= var -> var = n \/ var = n0.
Proof. intros n0 var n [H | H] Hge; [ right | left ]; lia. Qed.

(** Appending one element to a DoubleArray prefix.  [seg_unfold] in ArrayLibCore
    is CONS-shaped, so the snoc direction is built from [seg_single] +
    [seg_merge_to_seg].  Only [DoubleArray] needs it: `.strategies` carries
    Int/Ptr/Char undef_seg rules that rejoin their written cell automatically,
    and there is no DoubleArray rule. *)

Lemma dseg_snoc : forall (l : list fp64) p lo n v,
  lo <= n ->
  DoubleArray.seg p lo n l ** (p + n * sizeof ( DOUBLE )) # Double |-> v
  |-- DoubleArray.seg p lo (n + 1) (l ++ (v :: nil)).
Proof.
  intros l p lo n v H.
  sep_apply (DoubleArray.seg_single p n v).
  sep_apply (DoubleArray.seg_merge_to_seg p lo n (n + 1) l (v :: nil)
               ltac:(lia)).
  msat_entailer_with lia.
Qed.

(* ==================================================================== *)
(* Projection tables for the two growth operations.                     *)
(*                                                                      *)
(* QCP's matcher is SYNTACTIC -- there is no congruence closure -- so    *)
(* once a loop-invariant witness is instantiated with a CONSTRUCTED      *)
(* model the right-hand side reads [ms_activity (msolver_set_cap M c)]   *)
(* while the heap still reads [ms_activity M], and nothing cancels.      *)
(* Both models are record literals, so every entry below is             *)
(* [reflexivity]; stating them is what turns that reduction into a       *)
(* rewrite the entailer can drive.                                      *)
(* ==================================================================== *)

Lemma msolver_set_cap_qtail : forall M c,
  ms_qtail (msolver_set_cap M c) = ms_qtail M.
Proof. reflexivity. Qed.

Lemma msolver_set_cap_activity : forall M c,
  ms_activity (msolver_set_cap M c) = ms_activity M.
Proof. reflexivity. Qed.

Lemma msolver_set_cap_tags : forall M c,
  ms_tags (msolver_set_cap M c) = ms_tags M.
Proof. reflexivity. Qed.

Lemma msolver_set_cap_reason_words : forall M c,
  ms_reason_words (msolver_set_cap M c) = ms_reason_words M.
Proof. reflexivity. Qed.

Lemma msolver_set_cap_orderpos : forall M c,
  ms_orderpos (msolver_set_cap M c) = ms_orderpos M.
Proof. reflexivity. Qed.

Lemma msolver_set_cap_order : forall M c,
  ms_order (msolver_set_cap M c) = ms_order M.
Proof. reflexivity. Qed.

Lemma msolver_set_cap_order_cap : forall M c,
  ms_order_cap (msolver_set_cap M c) = ms_order_cap M.
Proof. reflexivity. Qed.

Lemma msolver_set_cap_wm : forall M c,
  ms_wm (msolver_set_cap M c) = ms_wm M.
Proof. reflexivity. Qed.

Lemma msolver_set_cap_wcaps : forall M c,
  ms_wcaps (msolver_set_cap M c) = ms_wcaps M.
Proof. reflexivity. Qed.

(* ---- the growth step: append one variable, then re-point the heap ---- *)

Lemma mt_assigns_add_var : forall t,
  mt_assigns (mtrail_add_var t) = mt_assigns t ++ (0 :: nil).
Proof. reflexivity. Qed.

Lemma mt_levels_add_var : forall t,
  mt_levels (mtrail_add_var t) = mt_levels t ++ (0 :: nil).
Proof. reflexivity. Qed.

Lemma mt_trail_add_var : forall t,
  mt_trail (mtrail_add_var t) = mt_trail t.
Proof. reflexivity. Qed.

Lemma msolver_sift_size : forall M oc a0 op o1 oc2,
  ms_size (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2)
  = ms_size M + 1.
Proof. reflexivity. Qed.

Lemma msolver_sift_cap : forall M oc a0 op o1 oc2,
  ms_cap (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2) = ms_cap M.
Proof. reflexivity. Qed.

Lemma msolver_sift_qtail : forall M oc a0 op o1 oc2,
  ms_qtail (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2)
  = ms_qtail M.
Proof. reflexivity. Qed.

Lemma msolver_sift_core : forall M oc a0 op o1 oc2,
  ms_core (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2)
  = mtrail_add_var (ms_core M).
Proof. reflexivity. Qed.

Lemma msolver_sift_reason_words : forall M oc a0 op o1 oc2,
  ms_reason_words (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2)
  = ms_reason_words M ++ (0 :: nil).
Proof. reflexivity. Qed.

Lemma msolver_sift_tags : forall M oc a0 op o1 oc2,
  ms_tags (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2)
  = ms_tags M ++ (0 :: nil).
Proof. reflexivity. Qed.

Lemma msolver_sift_activity : forall M oc a0 op o1 oc2,
  ms_activity (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2)
  = ms_activity M ++ (a0 :: nil).
Proof. reflexivity. Qed.

Lemma msolver_sift_wm : forall M oc a0 op o1 oc2,
  ms_wm (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2)
  = ms_wm M ++ (nil :: nil :: nil).
Proof. reflexivity. Qed.

Lemma msolver_sift_wcaps : forall M oc a0 op o1 oc2,
  ms_wcaps (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2)
  = ms_wcaps M ++ (4 :: 4 :: nil).
Proof. reflexivity. Qed.

Lemma msolver_sift_orderpos : forall M oc a0 op o1 oc2,
  ms_orderpos (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2) = op.
Proof. reflexivity. Qed.

Lemma msolver_sift_order : forall M oc a0 op o1 oc2,
  ms_order (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2) = o1.
Proof. reflexivity. Qed.

Lemma msolver_sift_order_cap : forall M oc a0 op o1 oc2,
  ms_order_cap (msolver_heap_project (msolver_add_var M oc a0) op o1 oc2) = oc2.
Proof. reflexivity. Qed.

(** [wlists_rep_add_var] is stated over [vecp_rep], but at the point the growth
    loop reaches it the two fresh slots are still the five raw cells
    [vecp_new] left behind -- QCP cancels a struct field at a time, it does not
    re-fold a predicate.  Folding them here keeps the fold out of the VC proof,
    where the [vecp_slot] / [vecp_*_addr] indirection would have to be unfolded
    on the goal instead. *)

Lemma vecp_rep_new_intro : forall v r,
  vecp_size_addr v # Int |-> 0 **
  vecp_cap_addr  v # Int |-> 4 **
  vecp_ptr_addr  v # Ptr |-> r **
  PtrArray.seg r 0 0 nil ** PtrArray.undef_seg r 0 4
  |-- vecp_rep v nil 4.
Proof.
  intros v r.
  unfold vecp_rep, vecp_rep_at, vecp_size_addr, vecp_cap_addr, vecp_ptr_addr.
  Exists r. rewrite Zlength_nil. msat_entailer_with lia.
Qed.

(** The LHS is written as a FLAT, right-nested [**] chain on purpose.
    [sep_apply] lifts the lemma's atoms to the front of the goal one at a time
    and then [rewrite]s -- so it tolerates any ORDER in the goal, but the
    lemma's own bracketing has to match the flat shape lifting produces.  An
    inner [( .. ** .. )] group here makes the final rewrite fail with
    "Found no subterm matching". *)

Lemma wlists_rep_add_var_cells : forall base n wm caps p q,
  0 <= n ->
  wlists_rep base n wm caps **
  vecp_size_addr (vecp_slot base (2 * n)) # Int |-> 0 **
  vecp_cap_addr  (vecp_slot base (2 * n)) # Int |-> 4 **
  vecp_ptr_addr  (vecp_slot base (2 * n)) # Ptr |-> p **
  PtrArray.seg p 0 0 nil ** PtrArray.undef_seg p 0 4 **
  vecp_size_addr (vecp_slot base (2 * n + 1)) # Int |-> 0 **
  vecp_cap_addr  (vecp_slot base (2 * n + 1)) # Int |-> 4 **
  vecp_ptr_addr  (vecp_slot base (2 * n + 1)) # Ptr |-> q **
  PtrArray.seg q 0 0 nil ** PtrArray.undef_seg q 0 4
  |-- wlists_rep base (n + 1) (wm ++ (nil :: nil :: nil))
                              (caps ++ (4 :: 4 :: nil)).
Proof.
  intros base n wm caps p q Hn.
  sep_apply (vecp_rep_new_intro (vecp_slot base (2 * n)) p).
  sep_apply (vecp_rep_new_intro (vecp_slot base (2 * n + 1)) q).
  sep_apply (wlists_rep_add_var base n wm caps Hn).
  msat_entailer_with lia.
Qed.

(** The capacity-exhausted exit reaches [return -2] with the order vector
    FULL -- that is exactly the condition [veci_reserve] failed on -- so
    [Zlength l = cap] and a strategy rule has already collapsed the empty
    undefined tail to [emp].  The corpus fold
    [solver_nested_veci_from_cells__canceluntil_cap] cannot
    be used there: [sep_apply] lifts its atoms one at a time and its fifth,
    [IntArray.undef_seg p (Zlength l) cap], is no longer in the goal to lift. *)

Lemma solver_nested_veci_full_from_cells : forall s field p l cap,
  Zlength l = cap -> 0 < cap <= INT_MAX ->
  &( s # "solver_t" ->ₛ field .ₛ "size") # Int |-> Zlength l **
  &( s # "solver_t" ->ₛ field .ₛ "cap") # Int |-> cap **
  &( s # "solver_t" ->ₛ field .ₛ "ptr") # Ptr |-> p **
  IntArray.seg p 0 (Zlength l) l
  |-- veci_rep &( s # "solver_t" ->ₛ field) l cap.
Proof.
  intros s field p l cap Hfull Hcap.
  (* csimpl reconciliation, as in the [solver_dot_addr] address-bridge
     block: the address bridge is paid on a BARE equality, not on the whole
     entailment, which is where a blind whole-goal [csimpl] gets expensive. *)
  assert (Hsz : veci_size_addr &( s # "solver_t" ->ₛ field)
              = &( s # "solver_t" ->ₛ field .ₛ "size"))
    by (unfold veci_size_addr; csimpl; reflexivity).
  assert (Hcp : veci_cap_addr &( s # "solver_t" ->ₛ field)
              = &( s # "solver_t" ->ₛ field .ₛ "cap"))
    by (unfold veci_cap_addr; csimpl; reflexivity).
  assert (Hpt : veci_ptr_addr &( s # "solver_t" ->ₛ field)
              = &( s # "solver_t" ->ₛ field .ₛ "ptr"))
    by (unfold veci_ptr_addr; csimpl; reflexivity).
  unfold veci_rep. Exists p.
  unfold veci_rep_at. rewrite Hsz, Hcp, Hpt.
  rewrite Hfull, (IntArray.undef_seg_empty p cap).
  msat_entailer_with lia.
Qed.

(* The clause object's header word is learnt-dependent: solver_qcp.c writes
   [(size << 1) | learnt].  The Assert spells the value arithmetically as
   [size*2 + cn_sel]; [MiniSatClause.rep] spells it as [clause_hdr_word].
   This is the bridge between the two, and it is where the else-arm of
   [if (learnt)] stops being a false goal.
   Unreferenced elsewhere in the proof; retained as a checked-but-unused
   correspondence statement. *)
Lemma clause_hdr_word_sel : forall sel sz,
  0 <= sel <= 1 ->
  clause_hdr_word (solver_selected_is_learnt sel) sz = sz * 2 + sel.
Proof.
  intros sel sz H.
  unfold clause_hdr_word.
  assert (sel = 0 \/ sel = 1) as [-> | ->] by lia;
    [ rewrite sel_learnt_prob | rewrite sel_learnt_learnt ];
    cbv iota; lia.
Qed.

(** Installed clause transaction before the final solver representation fold.
    The two watch entries are clause pointers or binary tagged literals; callers
    supply the representation selected by the actual clause length. *)
Definition clause_new_transaction_installed_at_gen
    (s wl lvl c : Z) (M : msolver) (words : list Z)
    (sel entry0 entry1 : Z) : Assertion :=
  let i0 := lit_neg_c (Znth 0 words 0) in
  let i1 := lit_neg_c (Znth 1 words 0) in
  vecp_rep (solver_selected_vec s sel)
    (db_words (solver_selected_db sel M) ++ (c :: nil))
    (solver_selected_cap sel M) **
  vecp_rep (vecp_slot wl i0)
    (Znth i0 (ms_wm M) nil ++ (entry0 :: nil)) (Znth i0 (ms_wcaps M) 1) **
  vecp_rep (vecp_slot wl i1)
    (Znth i1 (ms_wm M) nil ++ (entry1 :: nil)) (Znth i1 (ms_wcaps M) 1) **
  MiniSatClause.rep c (solver_selected_is_learnt sel) words **
  clause_db_rep (solver_selected_db sel M) **
  clause_new_transaction_rest_at_gen s wl i0 i1 M lvl sel **
  &(s # "solver_t" ->ₛ "size") # Int |-> ms_size M.

(* Checked-but-unused correspondence statement: the generalised predicate at
   the learnt selector IS the shipped one.  Unreferenced elsewhere in the
   proof; retained as audit evidence. *)
Lemma solver_capacity_exhausted_gen_learnt : forall M,
  solver_capacity_exhausted_gen M 1 = solver_capacity_exhausted M.
Proof. reflexivity. Qed.

(* The watch-list disjunct is index-independent, so the shipped introduction
   rule carries over verbatim. *)
Lemma solver_capacity_exhausted_watch_gen : forall M i sel,
  0 <= i < Zlength (ms_wm M) ->
  vector_capacity_exhausted
    (Zlength (Znth i (ms_wm M) (@nil Z))) (Znth i (ms_wcaps M) 0) ->
  solver_capacity_exhausted_gen M sel.
Proof. intros M i sel Hi Hcap. right. exists i. auto. Qed.

(* Checked-but-unused correspondence statement, as above: the generalised
   readiness predicate at the learnt selector IS the shipped one.  Retained as
   audit evidence. *)
Lemma solver_internal_capacity_ready_gen_learnt : forall n F A_arr A_inst M,
  solver_internal_capacity_ready_gen n F A_arr A_inst M 1 =
  solver_internal_capacity_ready n F A_arr A_inst M.
Proof. reflexivity. Qed.

(* Checked-but-unused correspondence statement, as above: the learnt arm of the
   install certificate IS the record certificate.  Retained as audit evidence. *)
Lemma clause_install_pending_cert_learnt : forall n F M words,
  clause_install_pending_cert n F M words true = record_clause_cert n F M words.
Proof. reflexivity. Qed.

Lemma problem_clause_cert_pending : forall n F M words,
  problem_clause_cert n F M words -> problem_clause_pending_cert n F M words.
Proof.
  intros n F M words H. unfold problem_clause_cert in H.
  unfold problem_clause_pending_cert. tauto.
Qed.

(* Crossing back: after the install the formula has grown by exactly this
   clause, so the membership conjunct the full cert wants is immediate. *)
Lemma clause_install_cert_of_pending : forall n F M words sel,
  0 <= sel <= 1 ->
  clause_install_pending_cert n F M words (solver_selected_is_learnt sel) ->
  clause_install_cert n (cn_F F words sel) M words (solver_selected_is_learnt sel).
Proof.
  intros n F M words sel Hb H.
  assert (sel = 0 \/ sel = 1) as [-> | ->] by lia.
  - rewrite sel_learnt_prob in *. rewrite cn_F_prob.
    unfold clause_install_cert, clause_install_pending_cert in *; cbv iota in *.
    unfold problem_clause_pending_cert in H. unfold problem_clause_cert.
    destruct H as (H1 & H2 & H3 & H4).
    repeat split; try assumption.
    apply in_or_app. right. left. reflexivity.
  - rewrite sel_learnt_learnt in *. rewrite cn_F_learnt.
    unfold clause_install_cert, clause_install_pending_cert in *; cbv iota in *.
    exact H.
Qed.

(* Both arms of the entry certificate open with the same three well-formedness
   facts, so a proof that only needs those never has to case-split on sel. *)
Lemma clause_install_pending_cert_wf : forall n F M words b,
  clause_install_pending_cert n F M words b ->
  1 <= Zlength words /\ Forall (lit_wf_c n) words /\ NoDup (map lit_var_c words).
Proof.
  intros n F M words b H. unfold clause_install_pending_cert in H. destruct b.
  - unfold record_clause_cert, record_ready_cert in H. tauto.
  - unfold problem_clause_pending_cert in H.
    destruct H as (H1 & H2 & H3 & _). split; [ | split ]; [lia | assumption | assumption].
Qed.

