(* Helper lemmas.  Of the 14 the shipped clause_new proofs use, 7 name a   *)
(* learnt-pinned spelling or an indexed carrier; the other 7 carry over.   *)
(* Only the sel = 0 arm is new work -- at sel = 1 the generalised statement*)
(* is definitionally the shipped one, so the shipped lemma applies.        *)
(* The two install refolds are NOT here: they need the install operation   *)
(* itself generalised (msolver_install_clause .. true).                   *)
(* ==================================================================== *)

(* Generalized from [clause_new_stage_rep_at_refold__act_clause_bump_spec]. *)
(** ===== group: act_clause_bump_gen ===== *)
(* Same refold-contract note as above [clause_new_stage_rep_at_refold__act_clause_bump_spec]. *)
Definition clause_new_stage_rep_at_refold__act_clause_bump_gen_spec
    (level_rep : Z -> msolver -> Z -> Z -> Assertion) : Prop :=
  forall s begin clause_out database watch0 watch1 wl lvl M words sel,
  (sel = 0 \/ sel = 1) ->
  solver_shape M ->
  0 <= lit_neg_c (Znth 0 words 0) < Zlength (ms_wm M) ->
  0 <= lit_neg_c (Znth 1 words 0) < Zlength (ms_wm M) ->
  clause_new_stage_rep_at_gen
    s begin clause_out database watch0 watch1 wl lvl M words sel
  |-- level_rep s M wl lvl **
      IntArray.seg begin 0 (Zlength words) words **
      clause_out # Ptr |-> 0.

(* Generalized from [clause_new_full_db_stage_refold__act_clause_bump_spec]. *)
(* Same refold-contract note as above [clause_new_stage_rep_at_refold__act_clause_bump_spec]. *)
Definition clause_new_full_db_stage_refold__act_clause_bump_gen_spec
    (level_rep : Z -> msolver -> Z -> Z -> Assertion) : Prop :=
  forall s begin clause_out database watch0 watch1 wl lvl M words p sel,
  (sel = 0 \/ sel = 1) ->
  solver_shape M ->
  database = (solver_selected_vec s sel) ->
  watch0 = vecp_slot wl (lit_neg_c (Znth 0 words 0)) ->
  watch1 = vecp_slot wl (lit_neg_c (Znth 1 words 0)) ->
  lit_neg_c (Znth 0 words 0) <> lit_neg_c (Znth 1 words 0) ->
  Zlength (db_words ((solver_selected_db sel M))) = (solver_selected_cap sel M) ->
  0 < (solver_selected_cap sel M) <= INT_MAX ->
  0 <= lit_neg_c (Znth 0 words 0) < Zlength (ms_wm M) ->
  0 <= lit_neg_c (Znth 1 words 0) < Zlength (ms_wm M) ->
  &( database # "vecp_t" ->ₛ "size")
    # Int |-> Zlength (db_words ((solver_selected_db sel M))) **
  &( database # "vecp_t" ->ₛ "cap") # Int |-> (solver_selected_cap sel M) **
  &( database # "vecp_t" ->ₛ "ptr") # Ptr |-> p **
  PtrArray.seg p 0 (Zlength (db_words ((solver_selected_db sel M))))
    (db_words ((solver_selected_db sel M))) **
  vecp_rep watch0
    (Znth (lit_neg_c (Znth 0 words 0)) (ms_wm M) nil)
    (Znth (lit_neg_c (Znth 0 words 0)) (ms_wcaps M) 1) **
  vecp_rep watch1
    (Znth (lit_neg_c (Znth 1 words 0)) (ms_wm M) nil)
    (Znth (lit_neg_c (Znth 1 words 0)) (ms_wcaps M) 1) **
  clause_db_rep ((solver_selected_db sel M)) **
  clause_new_transaction_rest_at_gen s wl
    (lit_neg_c (Znth 0 words 0)) (lit_neg_c (Znth 1 words 0))
    M lvl sel **
  &( s # "solver_t" ->ₛ "size") # Int |-> ms_size M **
  IntArray.seg begin 0 (Zlength words) words **
  clause_out # Ptr |-> 0
  |-- level_rep s M wl lvl **
      IntArray.seg begin 0 (Zlength words) words **
      clause_out # Ptr |-> 0.

(* generalised from lib.v (shipped: msolver_inv_with_clause_caps_current__act_clause_bump) *)
Lemma msolver_inv_with_clause_caps_current__act_clause_bump_gen :
  forall n F A_arr A_inst M learnt_cap wcaps sel,
  (sel = 0 \/ sel = 1) ->
  msolver_inv n F A_arr A_inst M ->
  Zlength wcaps = Zlength (ms_wcaps M) ->
  msolver_inv n F A_arr A_inst
    (msolver_with_clause_caps_gen M learnt_cap wcaps sel).
Proof.
  intros n F A_arr A_inst M learnt_cap wcaps sel Hselector_case Hinv Hlen.
  destruct Hselector_case as [-> | ->].
  {
  destruct Hinv as [Hweak Hprop Hfront Hheap Hreason].
  constructor; simpl.
  - destruct Hweak; constructor; simpl in *; try assumption.
    unfold solver_shape in *. simpl in *.
    rewrite Hlen. tauto.
  - exact Hprop.
  - exact Hfront.
  - exact Hheap.
  - unfold current_reasonless_earliest in *; simpl in *.
  cn_at_prob.
    exact Hreason. }
  { cn_at_learnt. apply msolver_inv_with_clause_caps_current__act_clause_bump; try assumption; try lia. }
Qed.

(* generalised from lib.v (shipped: clause_new_transaction_rest_at_replace_i__act_clause_bump) *)
Lemma clause_new_txn_rest_at_replace_i__act_clause_bump_gen :
  forall s wl i j M learnt_cap caps lvl cap sel,
  (sel = 0 \/ sel = 1) ->
  Zlength (ms_wm M) = Zlength caps ->
  0 <= i < Zlength (ms_wm M) ->
  0 <= j < Zlength (ms_wm M) ->
  i <> j ->
  clause_new_transaction_rest_at_gen s wl i j
    (msolver_with_clause_caps_gen M learnt_cap caps sel) lvl sel
  |-- clause_new_transaction_rest_at_gen s wl i j
    (msolver_with_clause_caps_gen M learnt_cap (replace_Znth i cap caps) sel) lvl sel.
Proof.
