(* ===================================================================== *)
(* The stats block must survive at a NAMED wl.                           *)
(*                                                                        *)
(* solver_addclause's closing `which implies' hands out the eleven        *)
(* s->stats.* cells so `s->stats.clauses++' can run.  Today it names      *)
(* [solver_rep_levels_at], which re-hides wl -- exactly what this lane    *)
(* must not lose.  [stats_rep] is the LAST conjunct of                    *)
(* [solver_nonlevel_rep_at] in [solver_qcp_model.v], so the                *)
(* frame is that definition minus its final conjunct, with wl free; it    *)
(* is written out from that definition rather than retyped by hand.       *)
(* ===================================================================== *)

Lemma solver_rep_growable_to_wl : forall s M,
  solver_rep_growable s M
  |-- EX wl : Z, EX lvl : Z, solver_rep_levels_wl_at s M wl lvl **
      wlists_undef wl (2 * ms_size M) (2 * ms_cap M).
Proof.
  intros s M. unfold solver_rep_levels_wl_at, solver_rep_growable, solver_rep_at.
  Intros wl act asg opos rsn lvl trl tgs.
  Exists wl lvl. entailer_with lia.
  Exists act asg opos rsn trl tgs. msat_entailer_with lia.
Qed.


