Lemma solver_assuming_weak_zero_stable__api_reentry : forall n F A M,
  msolver_inv_assuming n F A A M ->
  Zlength (mt_lim (ms_core M)) = 0 -> ms_root_level M = 0 ->
  msolver_inv_weak n F A [] M.
Proof.
  intros n F A M Hweak Hdepth Hroot.
  pose proof (msolver_inv_ctx_root_empty__canceluntil_cap
    n F A (PropagationAssuming A) M Hweak Hdepth) as Hempty.
  assert (Heq : msolver_set_root M 0 = M).
  { rewrite <- Hroot. destruct M. reflexivity. }
  rewrite Heq in Hempty.
  pose proof (msa_A_wf Hweak) as HAwf.
  pose proof (msa_proc_sat Hweak) as Hsat. rewrite Hdepth in Hsat.
  destruct Hempty. constructor; try assumption.
  - intros a Hin. inversion Hin.
  - rewrite Hroot. exact Hsat.
Qed.

Lemma solver_assuming_propagation_zero_stable__api_reentry : forall n F A M,
  solver_propagation_inv n F A (PropagationAssuming A) M ->
  Zlength (mt_lim (ms_core M)) = 0 -> ms_root_level M = 0 ->
  solver_propagation_inv n F A (PropagationStable []) M.
Proof.
  intros n F A M [Hpending Hprop] Hdepth Hroot.
  split; [exact Hpending|].
  destruct Hprop as [Hweak Hlevel Hfront Hheap Hreason]. constructor.
  - eapply solver_assuming_weak_zero_stable__api_reentry; eassumption.
  - exact Hlevel.
  - exact Hfront.
  - exact Hheap.
  - exact Hreason.
