Lemma clause_new_caps_progress_root__api_reentry : forall entry words M sel,
  clause_new_caps_progress_gen entry words M sel ->
  ms_root_level M = ms_root_level entry.
Proof.
  intros entry words M sel H. unfold clause_new_caps_progress_gen in H.
  repeat match goal with
  | H : _ \/ _ |- _ => destruct H
  | H : exists _, _ |- _ => destruct H
  end; subst; reflexivity.
Qed.


Lemma clause_new_success_physical__api_reentry :
  forall n F A_arr A_inst entry words c sel M,
    clause_new_success_transition_root n F A_arr A_inst entry words c sel
      (ms_root_level entry) M ->
    clause_new_success_transition_gen n F A_arr A_inst entry words c sel M.
Proof.
  intros n F A_arr A_inst entry words c sel M
    (Mcaps & Hprogress & Hfresh & Hinstall & Hinv & Hpending & Hseed & Hcert).
  pose proof (clause_new_caps_progress_root__api_reentry _ _ _ _ Hprogress) as Hroot.
  assert (HrootM : ms_root_level M = ms_root_level entry).
  { rewrite Hinstall. change (ms_root_level Mcaps = ms_root_level entry).
    exact Hroot. }
  unfold solver_support_inv in Hinv.
  rewrite <- HrootM, msolver_set_root_self__api_reentry in Hinv, Hcert.
  exists Mcaps. split; [exact Hprogress |]. split; [exact Hfresh |].
  split; [exact Hinstall |]. split; [exact Hinv |].
  split; [exact Hpending |]. split; assumption.
Qed.


Lemma clause_new_capacity_physical__api_reentry :
  forall n F A_arr A_inst entry M words sel,
    clause_new_capacity_failure_root n F A_arr A_inst entry M words sel
      (ms_root_level entry) ->
    clause_new_capacity_failure_gen n F A_arr A_inst entry M words sel.
Proof.
  intros n F A_arr A_inst entry M words sel [Hprogress Hready].
  pose proof (clause_new_caps_progress_root__api_reentry _ _ _ _ Hprogress) as Hroot.
  rewrite <- Hroot, msolver_set_root_self__api_reentry in Hready.
  split; assumption.
Qed.


Lemma clause_new_post_physical__api_reentry :
  forall s begin clause_out lvl n F A_arr A_inst entry words ret sel wl,
    clause_new_post_at_root s begin clause_out lvl n F A_arr A_inst
      entry words ret sel wl (ms_root_level entry) |--
    clause_new_post_at_gen s begin clause_out lvl n F A_arr A_inst
      entry words ret sel wl.
Proof.
  intros. unfold clause_new_post_at_root, clause_new_post_at_gen.
  apply derivable1_orp_elim.
  - rewrite <- derivable1_orp_intros1. Intros M c. Exists M c.
    entailer_with ltac:(eapply clause_new_success_physical__api_reentry; eassumption).
  - rewrite <- derivable1_orp_intros2. Intros M. Exists M.
    entailer_with ltac:(eapply clause_new_capacity_physical__api_reentry; eassumption).
Qed.


Definition addclause_support_transition
    (n : Z) (F : cnf) (A_arr A_inst : list literal)
    (entry : msolver) (input : list Z) (ret : Z)
    (M : msolver) (current : list Z) (F' : cnf) : Prop :=
  addclause_transition n F A_arr A_inst (msolver_set_root entry 0)
    input ret (msolver_set_root M 0) current F' /\
  (minisat_watch_completed entry -> minisat_watch_completed M).


Definition addclause_support_post_at
    (s begin n : Z) (F : cnf) (A_arr A_inst : list literal)
    (entry : msolver) (input : list Z) (ret : Z) : Assertion :=
  EX M : msolver, EX current : list Z, EX F' : cnf,
    “ addclause_support_transition n F A_arr A_inst entry input ret
        M current F' ” &&
    (solver_rep_growable s M **
     IntArray.seg begin 0 (Zlength input) current).


