  &( s # "solver_t" ->ₛ "orderpos") # Ptr |->_ **
  &( s # "solver_t" ->ₛ "reasons") # Ptr |->_ **
  &( s # "solver_t" ->ₛ "levels") # Ptr |->_ **
  &( s # "solver_t" ->ₛ "trail") # Ptr |->_ **
  &( s # "solver_t" ->ₛ "binary") # Ptr |->_ **
