  &( s # "solver_t" ->ₛ "order" .ₛ "cap") # Int |->_ **
  &( s # "solver_t" ->ₛ "order" .ₛ "ptr") # Ptr |->_ **
  &( s # "solver_t" ->ₛ "trail_lim" .ₛ "size") # Int |->_ **
  &( s # "solver_t" ->ₛ "trail_lim" .ₛ "cap") # Int |->_ **
  &( s # "solver_t" ->ₛ "trail_lim" .ₛ "ptr") # Ptr |->_ **
  &( s # "solver_t" ->ₛ "tagged" .ₛ "size") # Int |->_ **
  &( s # "solver_t" ->ₛ "tagged" .ₛ "cap") # Int |->_ **
  &( s # "solver_t" ->ₛ "tagged" .ₛ "ptr") # Ptr |->_ **
